local dialogues = {}
dialogues.npcs = {
    ["Jack Oval"] = {
        ["You need to make things. Leather. Pottery. Every piece you make will increase your skill."] = "Necesitas hacer cosas. Cuero. Cerámica. Cada pieza que hagas aumentará tu habilidad.",
        ["Select an Option"] = "Selecciona una opción",
        ["I need Crafting supplies."] = "Necesito suministros Crafting.",
        ["Tell me about Crafting and other artisan skills."] = "Cuéntame sobre Crafting y otras habilidades artesanales.",
        ["Crafting is the most versatile skill by far. You can make leather armour, pottery, jewellery and even glasswork."] = "Crafting es, con diferencia, la habilidad más versátil. Puedes fabricar armaduras de cuero, cerámica, joyas e incluso cristalería.",
        ["If you ever get as good as me, you'll be able to perform extraordinary feats like making armour from the hides of dragons!"] = "¡Si alguna vez llegas a ser tan bueno como yo, podrás realizar hazañas extraordinarias como hacer armaduras con pieles de dragones!",
        ["Tell me about Fletching."] = "Háblame de Fletching.",
        ["Fletching is about making bows and arrows. The better you are at it, and the better the quality of your materials, the better the result."] = "Fletching se trata de hacer arcos y flechas. Cuanto mejor lo hagas y mejor sea la calidad de tus materiales, mejor será el resultado.",
        ["Every bow and every arrow you make will increase your skill."] = "Cada arco y cada flecha que hagas aumentará tu habilidad.",
        ["If you expect to spend any time as an archer you'll want to ensure you have the arrows you need."] = "Si esperas pasar algún tiempo como arquero, querrás asegurarte de tener las flechas que necesitas.",
        ["Most people have no appreciation for how many arrows an army goes through every day. We could really use your help re-supplying them."] = "La mayoría de la gente no aprecia cuántas flechas atraviesa un ejército cada día. Realmente nos vendría bien su ayuda para reabastecerlos.",
        ["Tell me about Smithing."] = "Háblame de Smithing.",
        ["Smithing is all about making weapons. And armour! The better you are at smithing, the higher the quality of the metal you can work with and the better the resulting items are."] = "Smithing se trata de fabricar armas. ¡Y armadura! Cuanto mejor seas forjando, mayor será la calidad del metal con el que podrás trabajar y mejores serán los elementos resultantes.",
        ["Every bar of metal you smelt and every metal item you smith will improve your abilities."] = "Cada barra de metal que fundes y cada objeto de metal que forjas mejorará tus habilidades.",
        ["As well as being able to make gear directly, some of the most powerful ancient relics need an expert smith to reassemble their fragmented parts."] = "Además de poder fabricar equipo directamente, algunas de las reliquias antiguas más poderosas necesitan un herrero experto para volver a ensamblar sus partes fragmentadas.",
        ["Burthorpe's militia need to be kept well supplied with arms and armour. It falls to smiths to meet that need."] = "La milicia de Burthorpe necesita estar bien provista de armas y armaduras. Corresponde a los herreros satisfacer esa necesidad.",
        ["(back)"] = "(atrás)",
        ["Tell me about the skills menu."] = "Cuéntame sobre el menú de habilidades.",
        ["You have many skills you can train. The more you practice a skill, the better it gets. Higher skill levels unlock new activities: equipment to craft, locations to explore, quests to complete, and much more."] = "Tienes muchas habilidades que puedes entrenar. Cuanto más practicas una habilidad, mejor se vuelve. Los skill levels superiores desbloquean nuevas actividades: equipos para crear, lugares para explorar, misiones para completar y mucho más.",
        ["Perform actions associated with a skill to earn experience points (XP) in that skill. Earn enough XP and you'll gain a level in that skill."] = "Realiza acciones asociadas con una habilidad para ganar puntos de experiencia (XP) en esa habilidad. Gana suficiente XP y ganarás un nivel en esa habilidad.",
        ["Most skills start at level 1, and you unlock all their benefits by leveling the skill to 99. (Some skills have unlocks up to level 120.)"] = "La mayoría de las habilidades comienzan en el nivel 1 y desbloqueas todos sus beneficios al subir la habilidad al nivel 99. (Algunas habilidades se pueden desbloquear hasta el nivel 120).",
        ["The bottom number next to a skill icon is your base level in that skill (un-modified by buffs or debuffs). It is used for most requirement checks."] = "El número inferior al lado del ícono de una habilidad es tu nivel base en esa habilidad (sin modificar por ventajas o desventajas). Se utiliza para la mayoría de las comprobaciones de requisitos.",
        ["The top number is your modified skill level (temporarily boosted or drained by skill buffs and debuffs - such as potions or spells). It is used for most skill checks."] = "El número superior es tu skill level modificado (impulsado o agotado temporalmente por mejoras y desventajas de habilidades, como pociones o hechizos). Se utiliza para la mayoría de las pruebas de habilidades.",
        ["Achieve 99 in all your skills to earn the coveted Max Cape!"] = "¡Consigue 99 en todas tus habilidades para ganar la codiciada capa Max!",
        ["Farewell."] = "Adiós.",
    },
    ["Jack Sails"] = {
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["Hello."] = "Hola.",
        ["Hello to you too."] = "Hola a ti también.",
        ["Yar!<br> We be pirates, yar! <br>Avast, ye scurvy land-lubbing lychee!"] = "¡Sí! <br> ¡Seremos piratas, sí! <br>Avast, ¡lichi que lubrica la tierra con escorbuto!",
        ["Please don't talk like that, it is extremely irritating."] = "Por favor, no hables así, es extremadamente irritante.",
        ["Also, please don't call me a lychee, whatever that may be."] = "Además, por favor no me llames lichi, sea lo que sea.",
        ["Oh.<br> Okay. <br>Sorry."] = "Oh.<br> Está bien. <br>Lo siento.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["So...<br>You're a pirate, huh?"] = "Entonces...<br>Eres un pirata, ¿eh?",
        ["It's what it says on my pay-packet at the end of the month."] = "Es lo que pone en mi nómina a final de mes.",
        ["How's that working out for you?"] = "¿Qué te parece?",
        ["Pretty good so far. <br>All the grog and loot that we can plunder, plus full medical including dental."] = "Bastante bien hasta ahora. <br>Todo el grog y el botín que podamos saquear, además de asistencia médica completa, incluido dental.",
        ["You mean you have insurance?"] = "¿Quieres decir que tienes seguro?",
        ["Not as such. <br>If any of us get sick we kidnap a doctor and don't let him go until we're better."] = "No como tal. <br>Si alguno de nosotros se enferma, secuestramos a un médico y no lo dejamos ir hasta que estemos mejor.",
        ["You'd be surprised what an incentive for expert health care that is."] = "Te sorprendería el incentivo que supone para la atención sanitaria experta.",
        ["I can imagine."] = "Me lo imagino.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Sorry, can't stop, the Captain will have my guts for garters if he catches me slacking off talking to the stowaway."] = "Lo siento, no puedo parar, el Capitán me tomará las tripas como ligas si me pilla holgazaneando hablando con el polizón.",
        ["I'm not a stowaway! <br>I was invited aboard!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo!",
        ["Yeah, whatever [guy/lady], it doesn't really matter who you are I'll get in trouble!"] = "Sí, sea lo que sea [guy/lady], realmente no importa quién seas, ¡me meteré en problemas!",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["You know, I've always wondered what life as a pirate actually entails."] = "Sabes, siempre me he preguntado qué implica realmente la vida como pirata.",
        ["Well, at the moment it mostly involves being asked random questions by a stowaway."] = "Bueno, por el momento se trata principalmente de que un polizón te haga preguntas aleatorias.",
        ["I'm not a stowaway! <br>I was invited aboard! <br>By Lokar! <br>Ask him!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo! <br>Por Lokar! <br>¡Pregúntale!",
        ["Hey, whatever [pal/love]. <br>Just make sure the captain doesn't catch you, pirates don't like stowaways much."] = "Oye, lo que sea [pal/love]. <br>Solo asegúrate de que el capitán no te atrape, a los piratas no les gustan mucho los polizones.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Ah, good day to you [sirrah/milady]! <br>Your face is unfamiliar, did you perhaps join us aboard the ship at Lunar Isle?"] = "¡Ah, buenos días para ti [sirrah/milady]! <br>Tu cara no te resulta familiar, ¿quizás te uniste a nosotros a bordo del barco en Lunar Isle?",
        ["No, Lokar offered me a lift in Rellekka actually."] = "No, Lokar me ofreció llevarme en Rellekka en realidad.",
        ["Oh, really? <br>You don't look like a Fremennik to me!"] = "Oh, ¿en serio? <br>¡No me pareces un Fremennik!",
        ["Well...<br> I kind of am, and I kind of aren't. <br>It's a long story."] = "Bueno... <br> En cierto modo lo soy y en cierto modo no. <br>Es una larga historia.",
        ["Sorry I don't have time to hear it then! <br>See you around young fremennik-who-is-not-really-a-fremennik!"] = "¡Lo siento, entonces no tengo tiempo para escucharlo! <br>¡Nos vemos por aquí, joven fremennik-que-no-es-realmente-un-fremennik!",
        ["Bye."] = "Adiós.",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Brrrr! <br>Its cold up here!"] = "¡Brrrr! <br>¡Hace frío aquí arriba!",
        ["You think this is cold? <br>Up by Acheron it gets so cold that when you talk you see the words freeze in the air in front of you!"] = "¿Crees que esto hace frío? <br>Up de Acheron ¡Hace tanto frío que cuando hablas ves las palabras congelarse en el aire frente a ti!",
        ["REALLY?"] = "¿EN SERIO?",
        ["Nah, not really. <br>I was exaggerating for humourous effect. It is very very cold though!"] = "No, en realidad no. <br>I estaba exagerando para lograr un efecto humorístico. ¡Aunque hace mucho, mucho frío!",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["ARGH! <br>SOUND THE ALARM! <br>STOWAWAY ON BOARD! <br>STOWAWAY ON BOARD!"] = "¡ARGH! <br>¡SUENA LA ALARMA! <br> ¡PILOTO A BORDO! <br>STOWAWAY ¡A BORDO!",
        ["No! <br>I'm not a stowaway! <br>Honest! I was invited here!"] = "¡No! <br>¡No soy un polizón! <br>¡Honesto! ¡Me invitaron aquí!",
        ["Oh, sorry, my mistake then."] = "Oh, lo siento, entonces fue mi error.",
        ["You must admit you do look a lot like a stowaway though."] = "Aunque debes admitir que te pareces mucho a un polizón.",
        ["Why, what do they usually look like?"] = "¿Cómo son normalmente?",
        ["Erm... <br>I've never actually met one..."] = "Erm... <br>I nunca he conocido a uno...",
        ["Okay then..."] = "Bueno, entonces...",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Aren't you a little short for a pirate?"] = "¿No eres un poco bajo para ser un pirata?",
        ["My mother was a gnome. <br>Apparently it was a very painful birth."] = "Mi madre era un gnomo. <br>Al parecer fue un parto muy doloroso.",
        ["More info than I wanted, thanks!"] = "Más información de la que quería, ¡gracias!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["Hello there. <br>So what brings you aboard the Lady Zay?"] = "Hola. <br> Entonces, ¿qué te trae a bordo del Lady Zay?",
        ["Well, I was planning on visiting the Moon Clan, but I have to say your ship is very impressive."] = "Bueno, estaba planeando visitar el Clan de la Luna, pero debo decir que tu barco es muy impresionante.",
        ["Aye, she's a beauty alright! <br>The Lady Zay has been my home for many hard months, through storm and sun, and she always gets us to here we were headed!"] = "¡Sí, ella es una belleza! <br>La Lady Zay ha sido mi hogar durante muchos meses difíciles, a través de tormentas y sol, ¡y siempre nos lleva hacia donde nos dirigimos!",
        ["Yes, she's certainly one of the finest boats I've seen on my travels!"] = "Sí, ¡sin duda es uno de los mejores barcos que he visto en mis viajes!",
        ["That she is [lad/lass], that she is."] = "Que ella es [lad/lass], que ella es.",
        ["*Dialogue 10:*"] = "*Diálogo 10:*",
        ["So how's life as a pirate?"] = "Entonces, ¿cómo es la vida como pirata?",
        ["What kind of question is that? <br>How's life as a... <br>I dunno. <br>Whatever it is that you do for a living."] = "¿Qué tipo de pregunta es esa? <br>Cómo es la vida como... <br>No lo sé. <br>Sea lo que sea a lo que te dedicas.",
        ["I'm a freelance troubleshooter."] = "Soy un solucionador de problemas independiente.",
        ["What does that entail then?"] = "¿Qué implica eso entonces?",
        ["Mostly killing things for money and delivering items around the planet for people."] = "Principalmente matando cosas por dinero y entregando artículos en todo el planeta para las personas.",
        ["I collect stuff."] = "Colecciono cosas.",
        ["So how's that life?"] = "Entonces, ¿cómo es esa vida?",
        ["Can't complain, can't complain..."] = "No me puedo quejar, no me puedo quejar...",
        ["Well, there you go."] = "Bueno, ahí lo tienes.",
    },
    ["Jack Seagull"] = {
        ["Arrr, matey!"] = "¡Arrr, amigo!",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["I'm looking for Redbeard Frank."] = "Estoy buscando a Redbeard Frank.",
        ["Redbeard Frank ye say? He be outside. Says he likes the feel of the wind on his cheeks."] = "Redbeard Frank ¿dices? Él estará afuera. Dice que le gusta sentir el viento en sus mejillas.",
        ["Thanks."] = "Gracias.",
        ["What are you doing here?"] = "¿Qué haces aquí?",
        ["Drinking."] = "Bebiendo.",
        ["Fair enough."] = "Muy bien.",
        ["Have you got any quests I could do?"] = "¿Tienes alguna misión que pueda hacer?",
        ["Nay, but the barkeep hears most of the news around here. Or Redbeard Frank, he's often spoken of buried treasure. Perhaps ye should be asking them for quests."] = "No, pero el camarero se entera de la mayoría de las noticias por aquí. O Redbeard Frank, a menudo se habla de tesoro enterrado. Quizás deberías pedirles misiones.",
        ["Nay, but the barkeep hears most of the news around here. Perhaps ye should be asking him for a quest."] = "No, pero el camarero se entera de la mayoría de las noticias por aquí. Quizás deberías pedirle una misión.",
        ["Nay, but Redbeard Frank has often spoken of buried treasure. Perhaps ye should be asking him for a quest."] = "No, pero Redbeard Frank ha hablado a menudo de tesoros enterrados. Quizás deberías pedirle una misión.",
        ["Nay, I've got nothing for ye to do. But I hear there's an old landlubber in Draynor Village who's always a-looking for a lively [lad/lass] to do him a favour."] = "No, no tengo nada que hacer. Pero he oído que hay un viejo marinero de agua dulce en Draynor Village que siempre está buscando un [lad/lass] animado que le haga un favor.",
        ["Yo ho ho!"] = "¡Ho, ho, ho!",
        ["So are you pirates?"] = "Entonces, ¿sois piratas?",
