    },
    ["Jacquelyn"] = {
        ["Ello, and what are you after then?"] = "Hola, ¿y qué buscas entonces?",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm an apprentice Slayer Master."] = "Soy aprendiz de Slayer Master.",
        ["What's a slayer?"] = "¿Qué es un cazador?",
        ["Oh dear, what do they teach you in school?"] = "Dios mío, ¿qué te enseñan en la escuela?",
        ["Well...er..."] = "Bueno... ejem...",
        ["I suppose I'll have to educate you then. A slayer is someone who is trained to fight specific creatures. They know that creatures every weakness and strength. As you can guess it makes killing them a lot easier."] = "Supongo que tendré que educarte entonces. Un asesino es alguien que está entrenado para luchar contra criaturas específicas. Saben que las criaturas tienen todas sus debilidades y fortalezas. Como puedes adivinar, hace que matarlos sea mucho más fácil.",
        ["Wow, can you teach me?"] = "Vaya, ¿puedes enseñarme?",
        ["Sounds useless to me."] = "Me parece inútil.",
        ["Never heard of you."] = "Nunca había oído hablar de ti.",
        ["That's because my foe never lives to tell of me. We slayers are a dangerous bunch."] = "Eso es porque mi enemigo nunca vive para hablar de mí. Los cazadores somos un grupo peligroso.",
        ["Hmmm, well, I'm not so sure..."] = "Hmmm, bueno, no estoy tan seguro...",
        ["Pleeeaasssse!"] = "¡Por favor!",
        ["Oh, okay then, you twisted my arm. You'll have to train against specific groups of creatures."] = "Oh, está bien, entonces, torciste a my arm. Tendrás que entrenar contra grupos específicos de criaturas.",
        ["Ok then, what's first?"] = "Bueno, entonces, ¿qué es lo primero?",
        ["Change your assigned Slayer Task?"] = "¿Cambiar su tarea Slayer asignada?",
        ["[First task] (default)"] = "[First task] (predeterminado)",
        ["Modify your assigned Slayer Task?"] = "¿Modificar su tarea Slayer asignada?",
        ["[Number] [monster's name] (default)"] = "[número] [monster's name] (predeterminado)",
        ["[Number] [monster's name] (min)"] = "[número] [monster's name] (min)",
        ["[Number] [monster's name] (max)"] = "[número] [monster's name] (máx.)",
        ["We'll start you off hunting [monster]. You'll need to kill [number] of them."] = "Empezaremos cazando [monster]. Tendrás que matar a [número] de ellos.",
        ["You'll also need this enchanted gem, it allows Slayer Masters like myself to contact you and update you on your progress. Don't worry if you lose it; you can buy another from any Slayer Master."] = "También necesitarás esta gema encantada, le permite a Slayer Masters, como a mí, contactarte y actualizarte sobre tu progreso. No te preocupes si lo pierdes; puedes comprar otro en cualquier Slayer Master.",
        ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
        ["Ok great!"] = "Ok genial!",
        ["Okay, great!"] = "¡Vale, genial!",
        ["Good luck! Don't forget to come back when you need a new assignment."] = "¡Buena suerte! No olvides volver cuando necesites una nueva tarea.",
        ["Suit yourself."] = "Haz lo que quieras.",
        ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
        ["I have a wide selection of Slayer equipment; take a look!"] = "Tengo una amplia selección de equipos Slayer; ¡eche un vistazo!",
        ["Er...nothing..."] = "Eh... nada...",
        ["I need another assignment."] = "Necesito otra tarea.",
        ["You are still hunting [assigned creatures]; come back when you've finished your task."] = "Aún estás buscando a [assigned creatures]; Vuelve cuando hayas terminado tu tarea.",
        ["Do you have anything to trade?"] = "¿Tienes algo para intercambiar?",
        ["I am here to discuss any rewards I might be eligible for."] = "Estoy aquí para discutir cualquier recompensa para la que pueda ser elegible.",
        ["View rewards."] = "Ver recompensas.",
        ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
        ["You'll gain co-op reward points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on the task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos de recompensa cooperativa si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estés trabajando en la tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
        ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
        ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
        ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
        ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado a matar a [assigned creatures]; sólo faltan X más.",
        ["Where are you?"] = "¿Dónde estás?",
        ["That's all thanks."] = "Eso es todo, gracias.",
        ["My name is Jacquelyn; I'm a Slayer Master."] = "Mi nombre es Jacquelyn; Soy un Slayer Master.",
        ["You'll find me in Lumbridge. I'll be here when you need a new task."] = "Me encontrarás en Lumbridge. Estaré aquí cuando necesites una nueva tarea.",
        ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
        ["Nothing really."] = "Nada realmente.",
        ["Hello?"] = "¿Hola?",
        ["Ello, who's that?"] = "Hola, ¿quién es ese?",
        ["I'm Player. I'm using magic to communicate with you."] = "Soy Player. Estoy usando magia para comunicarme contigo.",
        ["Amazing! Wat can I do for you?"] = "¡Increíble! ¿Qué puedo hacer por ti?",
        ["Bats are rarely found on the ground, so you'll have to fight them while they're airborne. You can find some flying around in the Lumbridge Catacombs."] = "Los murciélagos rara vez se encuentran en el suelo, por lo que tendrás que luchar contra ellos mientras están en el aire. Puedes encontrar algunos volando en las Catacumbas Lumbridge.",
        ["Birds aren't the most intelligent of creatures, but watch out for their sharp, stabbing beaks. Even the chickens in Lumbridge are after your blood, so get them before they get you."] = "Los pájaros no son las criaturas más inteligentes, pero ten cuidado con sus picos afilados y punzantes. Incluso las gallinas en Lumbridge buscan tu sangre, así que consíguelas antes de que te atrapen a ti.",
        ["Cave bugs are like cave crawlers, except smaller and easier to squish; although, they still have a fondness for plants. They lurk in the dark beneath Lumbridge Swamp."] = "Los insectos de las cavernas son como rastreadores de cuevas, excepto que son más pequeños y más fáciles de aplastar; aunque todavía sienten afición por las plantas. Acechan en la oscuridad debajo del pantano Lumbridge.",
        ["Cave slimes are the lesser cousins of jellies. Don't be fooled, though: they can still be dangerous, as they're often poisonous. Killing the ones beneath Lumbridge Swamp might be a good start."] = "Los limos de las cavernas son los primos menores de las jaleas. Pero no te dejes engañar: aún así pueden ser peligrosos, ya que a menudo son venenosos. Matar a los que están debajo del pantano Lumbridge podría ser un buen comienzo.",
        ["Cows are bigger than you, and they'll often hit hard but react fairly slowly. You can slaughter the ones in Lumbridge - I bet they are up to no good."] = "Las vacas son más grandes que tú y, a menudo, golpean fuerte pero reaccionan con bastante lentitud. Puedes masacrar a los de Lumbridge. Apuesto a que no traman nada bueno.",
        ["Frogs will attack and move faster than the average human, but on the whole an experienced warrior can deal with a lot of them quite quickly. You can find them in the swamp to the south."] = "Las ranas atacarán y se moverán más rápido que el humano promedio, pero en general un guerrero experimentado puede lidiar con muchas de ellas con bastante rapidez. Puedes encontrarlos en el pantano del sur.",
        ["The last Ghost I killed I found thrown weapons took them down effectively."] = "El último fantasma que maté lo encontré con armas arrojadizas que los derribaron de manera efectiva.",
        ["Ghosts are undead, so not the easiest thing to find in populated areas. Try looking in the abandoned Draynor Manor."] = "Los fantasmas son muertos vivientes, por lo que no es lo más fácil de encontrar en zonas pobladas. Intenta buscar en el Draynor Manor abandonado.",
        ["Goblins are mostly just annoying, but they can be vicious. Watch out for the weapons they sometimes carry. You can find them on the east side of the river here in Lumbridge."] = "Los duendes en su mayoría son simplemente molestos, pero pueden ser crueles. Cuidado con las armas que a veces portan. Puedes encontrarlos en el lado este del río aquí en Lumbridge.",
        ["Rats come in different sizes if you want a challenge or not. You can find the normal variety lurking around the castle grounds or head south into the swamp for giant rats."] = "Las ratas vienen en diferentes tamaños si quieres un desafío o no. Puedes encontrar la variedad normal acechando en los terrenos del castillo o dirigirte hacia el sur, hacia el pantano, en busca de ratas gigantes.",
        ["Skeletons are undead, so Magic is your best bet against them. Skeletons can be found in the Lumbridge Catacombs."] = "Los esqueletos son muertos vivientes, por lo que Magic es tu mejor opción contra ellos. Los esqueletos se pueden encontrar en las catacumbas de Lumbridge.",
        ["Spiders are often venomous and many varieties are camouflaged, too. I've seen plenty to the south-west of Lumbridge."] = "Las arañas suelen ser venenosas y muchas variedades también se camuflan. He visto muchos al suroeste de Lumbridge.",
        ["Zombies are undead, so be careful. You can find a variety of corpse fighters in the Lumbridge Catacombs or zombies in the sewers under Draynor village."] = "Los zombis son muertos vivientes, así que ten cuidado. Puedes encontrar una variedad de luchadores de cadáveres en las catacumbas de Lumbridge o zombis en las alcantarillas en Draynor village.",
    },
