        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
        ["I'd like to check my PIN settings."] = "Me gustaría comprobar la configuración de mi PIN.",
        ["*(Bank Pin Settings interface opens)*"] = "*(Se abre la interfaz de configuración de PIN bancario)*",
        ["I'd like to see my Collection box."] = "Me gustaría ver mi cuadro de Colección.",
