    ["Janus"] = {
        ["Who are you?"] = "¿Quién eres?",
        ["Do you not know who I am? I am the future, I am the conduit of Sliske's might; I am Janus!"] = "¿No sabes quién soy? Soy el futuro, soy el conducto del poder de Sliske; ¡Soy Janus!",
        ["Yeah, but really, who are you?"] = "Sí, pero en realidad, ¿quién eres?",
        ["I'm a mage of great power, come to bring forth change to the world of Gielinor."] = "Soy un mago de gran poder, vengo a traer cambios al mundo de Gielinor.",
        ["Ah, so you're a mage. Are you part of the Zamorak Magical Institute?"] = "Ah, entonces eres un mago. ¿Eres parte del Instituto Mágico Zamorak?",
        ["The ZMI is full of shortsighted fools, I am doing work far greater than anything they will ever accomplish. I am glad that I am no longer part of them, they were holding me back."] = "El ZMI está lleno de tontos miopes. Estoy haciendo un trabajo mucho mayor que cualquier cosa que ellos puedan lograr. Me alegro de no ser más parte de ellos, me estaban frenando.",
        ["What happened with the ZMI?"] = "¿Qué pasó con el ZMI?",
        ["They thought that they knew better than me, my mentor tried to interfere with my learnings! She tried to stop a magical experiment that I was conducting and was badly burned by the spells that I had cast. It was her own fault, she knows the dangers of magic, but no, she had to step in. They told me to leave the ZMI because of it, yet she was allowed to stay. They will see what a mistake they have made when they see the results of my endeavours."] = "Pensaban que sabían más que yo, ¡mi mentor intentó interferir con mis aprendizajes! Intentó detener un experimento mágico que yo estaba realizando y resultó gravemente quemada por los hechizos que le había lanzado. Fue culpa suya, conoce los peligros de la magia, pero no, tuvo que intervenir. Me dijeron que dejara el ZMI por eso, pero a ella le permitieron quedarse. Verán el error que han cometido cuando vean los resultados de mis esfuerzos.",
        ["What are you planning on doing?"] = "¿Qué planeas hacer?",
        ["Works beyond your understanding. I am furthering the cause of the majestic Sliske. These rifts will further his journey towards being the greatest god of them all, and I am a pivotal part of that plan."] = "Funciona más allá de tu comprensión. Estoy promoviendo la causa del majestuoso Sliske. Estas divisiones impulsarán su viaje hacia convertirse en el dios más grande de todos, y yo soy una parte fundamental de ese plan.",
        ["Nevermind."] = "No importa.",
        ["*Dialogue terminates.*"] = "*El diálogo termina.*",
        ["Though this scheme has been thwarted Sliske's overall strategy cannot be stopped. He will be successful. This was just one plan of many, each reaching towards the same final plan, and I will stand by him as he succeeds."] = "Aunque este plan se ha visto frustrado, la estrategia general de Sliske no se puede detener. Tendrá éxito. Este fue sólo un plan entre muchos, cada uno de los cuales apuntaba hacia el mismo plan final, y lo apoyaré en su éxito.",
    },
    ["Jaraah"] = {
        ["Hi!"] = "¡Hola!",
        ["What? Can't you see I'm busy?"] = "¿Qué? ¿No ves que estoy ocupado?",
        ["Select an Option"] = "Selecciona una opción",
        ["Can you heal me?"] = "¿Puedes curarme?",
        ["Okay. This will hurt you more than it will me."] = "Está bien. Esto te hará más daño a ti que a mí.",
        ["These facilities aren't ideal for a hospital, but I can make them work."] = "Estas instalaciones no son ideales para un hospital, pero puedo hacer que funcionen.",
        ["Okay. This will hurt you more than it will hurt me."] = "Está bien. Esto te dolerá más a ti que a mí.",
        ["*If at full health:*"] = "*Si está en plena salud:*",
        ["You look healthy to me!"] = "¡Me pareces saludable!",
        ["*If not at full health:*"] = "*Si no está en plena salud:*",
        ["You feel a little better."] = "Te sientes un poco mejor.",
        ["You must see some gruesome things."] = "Debes ver algunas cosas espantosas.",
        ["It's a gruesome business, and, with the tools they give me, it gets more gruesome before it gets better."] = "Es un negocio espantoso y, con las herramientas que me dan, se vuelve más espantoso antes de mejorar.",
        ["You must have seen some gruesome things."] = "Debes haber visto algunas cosas espantosas.",
        ["In my time at the Duel Arena? Certainly, it was a gruesome business."] = "¿En mi tiempo en Duel Arena? Ciertamente, fue un asunto espantoso.",
        ["But now that the arena has sunk back into the desert, things are a little bit better."] = "Pero ahora que la arena se ha hundido nuevamente en el desierto, las cosas están un poco mejor.",
        ["Why do they call you 'The Butcher'?"] = "¿Por qué te llaman 'El Carnicero'?",
        ["The Butcher'?"] = "¿'El Carnicero'?",
        ["Ha!"] = "¡Ja!",
        ["Would you like me to demonstrate?"] = "¿Quieres que te lo demuestre?",
        ["Er... I'll give it a miss, thanks."] = "Er... Lo dejaré pasar, gracias.",
        ["Er...I'll give it a miss, thanks."] = "Er... Lo dejaré pasar, gracias.",
        ["Here! Now, I have work to do!"] = "¡Aquí! ¡Ahora tengo trabajo que hacer!",
        ["[Jaraah has given you another clue scroll!]"] = "[¡Jaraah te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    },
    ["Jari"] = {
        ["Good day, [sir/madam]."] = "Buenos días, [sir/madam].",
        ["Select an Option"] = "Selecciona una opción",
        ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
        ["I'm waiting to work on the digging."] = "Estoy esperando trabajar en la excavación.",
        ["It's the first excavation I've worked on, and I'm looking forward to it."] = "Es la primera excavación en la que trabajo y estoy deseando que llegue.",
        ["Good day."] = "Buenos días.",
    },
    ["Jarvald"] = {
        ["What do you want from me outerlander? It is our policy not to associate with those not of our tribe."] = "¿Qué quieres de mí, outsider? Es nuestra política no asociarnos con personas que no sean de nuestra tribu.",
        ["What would you like to ask about?"] = "¿Sobre qué te gustaría preguntar?",
        ["Where is your chieftain?"] = "¿Dónde está tu jefe?",
        ["Where is your chieftain? I find it highly discriminatory to refuse to talk to someone on the grounds that they are not part of your tribe."] = "¿Dónde está tu jefe? Considero muy discriminatorio negarse a hablar con alguien alegando que no forma parte de su tribu.",
        ["I don't rightly understand your speech outerlander, but my loyalty is with Chieftain Brundt. He resides in our long hall; it is the large building over there, you should speak to him for he speaks for us all."] = "No entiendo bien tu discurso externo, pero mi lealtad está con el cacique Brundt. Él reside en nuestro largo salón; es el gran edificio de allí, deberías hablar con él porque él habla por todos nosotros.",
        ["What Jarvald is doing."] = "Qué está haciendo Jarvald.",
        ["So what are you doing here?"] = "Entonces, ¿qué estás haciendo aquí?",
        ["This should not concern you, outerlander. I am awaiting other Fremenniks to join me on an expedition to Waterbirth Island."] = "Esto no debería preocuparte, extranjero. Estoy esperando que otros Fremenniks se unan a mí en una expedición a la Isla Waterbirth.",
        ["Select an Option"] = "Selecciona una opción",
        ["Waterbirth Island?"] = "¿Isla del nacimiento del agua?",
        ["It is a small crescent-shaped island just north-west of here, outerlander. We have many legends about it, such as the tale of the broken sky, and the day of the green seas. The reason I am travelling there is more serious Fremennik business, however. I doubt an outerlander would be interested."] = "Es una pequeña isla en forma de media luna justo al noroeste de aquí, outsider. Tenemos muchas leyendas al respecto, como el cuento del cielo roto y el día de los mares verdes. Sin embargo, el motivo por el que viajo allí es un asunto más serio de Fremennik. Dudo que un extranjero esté interesado.",
        ["Can I come?"] = "¿Puedo ir?",
        ["Hey, scary barbarian type guy, think I can join you on this expedition?"] = "Oye, tipo bárbaro aterrador, ¿crees que puedo unirme a ti en esta expedición?",
        ["An outerlander join us on an honoured hunt??? Well.... I guess... I might be able to allow you to join us, although it is a breach of many of our customs..."] = "¿¿Un extranjero se une a nosotros en una cacería honorable??? Bueno... supongo... que podría permitirte unirte a nosotros, aunque es una violación de muchas de nuestras costumbres...",
        ["Oh, pleeeeease? I really LOVE killing stuff!"] = "Oh, ¿por favor? ¡Realmente AMO matar cosas!",
        ["Well... I remain unconvinced that it would be wise to allow an outerlander to join us in such dangerous battle, but your enthusiasm seems genuine enough... I will allow you to escort us, but you must pay me a sum of money first."] = "Bueno... Sigo sin estar convencido de que sería prudente permitir que un extranjero se una a nosotros en una batalla tan peligrosa, pero tu entusiasmo parece bastante genuino... Te permitiré escoltarnos, pero primero debes pagarme una suma de dinero.",
        ["What? That's outrageous, why charge me money? And, uh, how much does it cost me?"] = "¿Qué? Eso es indignante, ¿por qué cobrarme dinero? ¿Y cuánto me cuesta?",
        ["Ah, the outerlanders have stolen from my people for many years, in this way you can help my community with a small amount of money... Let us say... 1000 coins. Payable in advance, of course. For this I will take you to Waterbirth Island on my boat, and will bring you back here when you have had your fill of the hunt. Assuming you are still alive to wish to leave, of course."] = "Ah, los extranjeros le han robado a mi gente durante muchos años, de esta manera puedes ayudar a mi comunidad con una pequeña cantidad de dinero... Digamos... 1000 coins. A pagar por adelantado, por supuesto. Para ello, te llevaré a la isla Waterbirth en mi barco y te traeré de regreso aquí cuando te hayas saciado de la caza. Suponiendo que todavía estés vivo para desear irte, por supuesto.",
        ["YES"] = "SI",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["Ah, outerlander... I go beyond my duty to allow you to accompany me, and you attempt to swindle me out of a reasonable fee? This is no way even for an outerlander to behave..."] = "Ah, extranjero... Voy más allá de mi deber al permitirte que me acompañes, ¿y tú intentas estafarme con una tarifa razonable? Esta no es forma de comportarse ni siquiera para un extranjero...",
        ["I suggest you head to the cave with some urgency outerlander, the cold air out here might be too much for the likes of you..."] = "Te sugiero que te dirijas a la cueva con cierta urgencia, extranjero, el aire frío aquí afuera podría ser demasiado para personas como tú...",
        ["I would head straight for the cave and not tarry too long [Fremennik name], the cold winds on this island can cut right through you should you spend too long in them."] = "Me dirigiría directamente a la cueva y no me demoraría demasiado [Fremennik name], los vientos fríos de esta isla pueden atravesarte si pasas demasiado tiempo en ellos.",
        ["As you wish. Come and see me when your bloodlust needs sating."] = "Como desees. Ven a verme cuando tu sed de sangre necesite saciar.",
        ["Nice hat!"] = "¡Bonito sombrero!",
        ["Hey, I have to say, that's a fine looking hat you are wearing there."] = "Oye, tengo que decir que el sombrero que llevas ahí luce muy bien.",
        ["It is actually a helm, outerlander, but the sentiment is appreciated nonetheless."] = "En realidad es un timón, outsider, pero de todos modos se agradece el sentimiento.",
        ["Ok, 'bye."] = "Vale, adiós.",
        ["Nothing"] = "nada",
        ["No, outerlander I am not taking you there."] = "No, extranjero, no te llevaré allí.",
        ["Ah, you live yet, outerlander! Have you had your fill of the hunt and wish to return, or are you still feeling the joy of the cull?"] = "¡Ah, aún vives, extranjero! ¿Se ha hartado de la caza y desea volver, o todavía siente la alegría del sacrificio?",
        ["Yes"] = "si",
        ["Then let us away; There will be death to bring here another day!"] = "Entonces déjanos ir; ¡Habrá muerte que traerá aquí otro día!",
        ["Ha Ha Ha! A true huntsman at heart!"] = "¡Ja, ja, ja! ¡Un verdadero cazador de corazón!",
        ["I myself have killed over a hundred of the daggermouths, and did not think it too many!"] = "Yo mismo he matado a más de cien bocas de daga, ¡y no pensé que fueran demasiados!",
        ["Greetings, [Fremennik name]!"] = "¡Saludos, [Fremennik name]!",
        ["Ah, and what a glorious name that is! Worthy of only the finest warriors!"] = "¡Ah, y qué nombre tan glorioso es ese! ¡Digno sólo de los mejores guerreros!",
        ["Heh. Yup, you're right there."] = "Je. Sí, tienes razón.",
        ["So what brings you back to fair Rellekka? It has been too long since you have drunk in the long hall with us and sang of your battles!"] = "Entonces, ¿qué te trae de vuelta a la feria Rellekka? ¡Ha pasado demasiado tiempo desde que bebiste en el gran salón con nosotros y cantaste sobre tus batallas!",
        ["You have not heard, [Fremennik name]? I am leading an expedition to Waterbirth Island!"] = "¿No te has enterado, [Fremennik name]? ¡Estoy liderando una expedición a la isla Waterbirth!",
        ["You have not ever travelled to Waterbirth Island, [Fremennik name]? I am surprised, it is a place of outstanding natural beauty."] = "¿Nunca has viajado a Waterbirth Island, [Fremennik name]? Me sorprende, es un lugar de una belleza natural excepcional.",
        ["Or at least it used to be! But things have now changed..."] = "¡O al menos así era! Pero ahora las cosas han cambiado...",
        ["Changed? How do you mean, changed?"] = "¿Cambiado? ¿Qué quieres decir con cambiado?",
        ["It seems as though the sea-beasts known to us as the daggermouths have begun their hatching once again... And there may be others of their ilk there too."] = "Parece que las bestias marinas que conocemos como bocas de daga han comenzado a eclosionar una vez más... Y puede que haya otras de su calaña allí también.",
        ["Daggermouths?"] = "¿Bocas de daga?",
        ["Aye, the daggermouths! The vile creatures lived near here once, but we had thought them all driven back to the ocean depths many moons past."] = "¡Sí, los bocas de daga! Estas viles criaturas vivieron cerca de aquí una vez, pero pensábamos que todas habían sido expulsadas a las profundidades del océano hace muchas lunas.",
        ["I can only imagine a daggermouth queen has nested somewhere nearby, and spawned her foul brood under the sea once more, and some of them have migrated to fair Waterbirth Island."] = "Solo puedo imaginar que una reina boca de daga haya anidado en algún lugar cercano y haya engendrado su loque bajo el mar una vez más, y algunas de ellas hayan migrado a la hermosa Isla Waterbirth.",
        ["So you're scared they might attack Rellekka?"] = "¿Entonces tienes miedo de que ataquen a Rellekka?",
        ["Scared? Ha ha ha!"] = "¿Asustado? ¡Ja, ja, ja!",
        ["You wound us with your questioning, [Fremennik name]!"] = "¡Nos hieres con tu interrogatorio, [Fremennik name]!",
        ["We are glad the daggermouths have returned to these shores, for it means we will get the chance to hunt them once again as our ancestors did!"] = "¡Nos alegra que los boca de daga hayan regresado a estas costas, porque eso significa que tendremos la oportunidad de cazarlos una vez más como lo hicieron nuestros antepasados!",
        ["When treated in the correct manner, the creatures' remains can be used to make fine battleworthy armour!"] = "¡Cuando se tratan de la manera correcta, los restos de las criaturas se pueden usar para fabricar excelentes armaduras dignas de batalla!",
        ["Of course, [Fremennik name]! Your presence is more than welcome on this cull! You wish to leave now?"] = "¡Por supuesto, [Fremennik name]! ¡Su presencia es más que bienvenida en este sacrificio! ¿Quieres irte ahora?",
        ["Aye, that it is [Fremennik name]! Skulgrimen fashioned it for me from the carcass of one of the monsters on Waterbirth Island after our last hunt! I hope to kill enough creatures to fashion some fine armour as well when next we leave!"] = "¡Sí, que es [Fremennik name]! ¡Skulgrimen lo creó para mí a partir del cadáver de uno de los monstruos de la isla Waterbirth después de nuestra última cacería! ¡Espero matar suficientes criaturas para crear algunas armaduras finas la próxima vez que nos vayamos!",
        ["Ah, [Fremennik name]! Such glorious battle makes you feel glad of life, does it not?"] = "¡Ah, [Fremennik name]! Una batalla tan gloriosa te hace sentir feliz por la vida, ¿no es así?",
        ["So what say you, stay here for the hunt, or return home to sweet Rellekka to feast and drink with your tribe?"] = "Entonces, ¿qué te parece, quedarte aquí para cazar o regresar a casa, al dulce Rellekka, para darte un festín y beber con tu tribu?",
    },
    ["Jasim the Camel"] = {
        ["*Jasim the Camel and the player say one of the following at random:*"] = "*Jasim the Camel y el player dicen uno de los siguientes al azar:*",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["I'm not going to pet that! I might get fleas or something else that nasty creature might have."] = "¡No voy a acariciar eso! Podría contraer pulgas o cualquier otra cosa que esa criatura desagradable pudiera tener.",
        ["You're fairly nasty yourself, human. Poking and prodding me like a lump of meat."] = "Tú también eres bastante desagradable, humano. Empujándome y pinchándome como si fuera un trozo de carne.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["I'm not going to pet that! It will probably bite my hand off, that filthy beast."] = "¡No voy a acariciar eso! Probablemente me arrancará la mano de un mordisco, esa bestia inmunda.",
        ["Watch who you're calling a filthy beast, human."] = "Mira a quién llamas bestia inmunda, humano.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["That beast would probably bite my fingers off if I tried to pet it."] = "Esa bestia probablemente me arrancaría los dedos de un mordisco si intentara acariciarla.",
        ["If you want me to bite your fingers off, you're going the right way about it."] = "Si quieres que te arranque los dedos de un mordisco, estás yendo por el camino correcto.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["Mmmm... Won't you make the nicest kebab?"] = "Mmmm... ¿No harías el mejor kebab?",
        ["How would you like it if you were destined for the kebab shop when you finally keeled over?"] = "¿Qué te parecería si estuvieras destinado a la tienda de kebab cuando finalmente te desplomaras?",
    },
    ["Jatix"] = {
        ["Are you here to practice your herblore?"] = "¿Estás aquí para practicar tu herbolaria?",
        ["Select an Option"] = "Selecciona una opción",
        ["I need herblore supplies."] = "Necesito suministros de herblore.",
        ["Tell me more about Herblore."] = "Cuéntame más sobre Herblore.",
        ["Every natural plant has powers locked within. Herblore is the art of unlocking these powers through potion-making."] = "Cada planta natural tiene poderes encerrados en su interior. Herblore es el arte de desbloquear estos poderes mediante la elaboración de pociones.",
        ["You'll be able to brew potions to do just about anything. Most significantly, you can restore yourself when you feel depleted."] = "Podrás preparar pociones para hacer casi cualquier cosa. Lo más importante es que puedes recuperarte cuando te sientas agotado.",
        ["Every stage in the brewing of a potion will give you a little practise. You can also start out by cleaning herbs for use."] = "Cada etapa de la elaboración de una poción te dará un poco de práctica. También puedes empezar limpiando las hierbas para su uso.",
        ["Tell me about the skills menu."] = "Cuéntame sobre el menú de habilidades.",
        ["You have many skills you can train. The more you practice a skill, the better it gets. Higher skill levels unlock new activities: equipment to craft, locations to explore, quests to complete, and much more."] = "Tienes muchas habilidades que puedes entrenar. Cuanto más practicas una habilidad, mejor se vuelve. Los skill levels superiores desbloquean nuevas actividades: equipos para crear, lugares para explorar, misiones para completar y mucho más.",
        ["Perform actions associated with a skill to earn experience points (XP) in that skill. Earn enough XP and you'll gain a level in that skill."] = "Realiza acciones asociadas con una habilidad para ganar puntos de experiencia (XP) en esa habilidad. Gana suficiente XP y ganarás un nivel en esa habilidad.",
        ["Most skills start at level 1, and you unlock all their benefits by leveling the skill to 99. (Some skills have unlocks up to level 120.)"] = "La mayoría de las habilidades comienzan en el nivel 1 y desbloqueas todos sus beneficios al subir la habilidad al nivel 99. (Algunas habilidades se pueden desbloquear hasta el nivel 120).",
        ["The bottom number next to a skill icon is your base level in that skill (un-modified by buffs or debuffs). It is used for most requirement checks."] = "El número inferior al lado del ícono de una habilidad es tu nivel base en esa habilidad (sin modificar por ventajas o desventajas). Se utiliza para la mayoría de las comprobaciones de requisitos.",
        ["The top number is your modified skill level (temporarily boosted or drained by skill buffs and debuffs - such as potions or spells). It is used for most skill checks."] = "El número superior es tu skill level modificado (impulsado o agotado temporalmente por mejoras y desventajas de habilidades, como pociones o hechizos). Se utiliza para la mayoría de las pruebas de habilidades.",
        ["Achieve 99 in all your skills to earn the coveted Max Cape!"] = "¡Consigue 99 en todas tus habilidades para ganar la codiciada capa Max!",
        ["Farewell."] = "Adiós.",
        ["Hello, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["What are you selling?"] = "¿Qué estás vendiendo?",
        ["You can't; I'm beyond help."] = "No puedes; No tengo ayuda.",
        ["I'm okay, thank you."] = "Estoy bien, gracias.",
    },
    ["Jay'uu"] = {
        ["You hear the spiritual warrior's voice in your head: \"Gal'Son."] = "Escuchas la voz del guerrero espiritual en tu cabeza: \"Gal'Son\".",
        ["*(The player responds with one of the following, at random, and then the dialogue ends.)*"] = "*(el player responde con una de las siguientes opciones, al azar, y luego finaliza el diálogo.)*",
        ["Hello?"] = "¿Hola?",
        ["I beg your pardon?"] = "¿Perdón?",
        ["Sorry, what?"] = "Lo siento, ¿qué?",
        ["What does that mean?"] = "¿Qué significa eso?",
    },
    ["Jeb"] = {
        ["Hello there."] = "Hola.",
        ["I understand that you can take me to the Fishing Platform."] = "Entiendo que puedes llevarme a la Plataforma Fishing.",
        ["Yes, we can do that. Board the boat and we shall depart."] = "Sí, podemos hacerlo. Sube al barco y partiremos.",
        ["Hey, Jeb."] = "Hola, Jeb.",
        ["Business here is complete. Do you wish to return to the dry land?"] = "El negocio aquí está completo. ¿Quieres volver a tierra firme?",
        ["Select an Option"] = "Selecciona una opción",
        ["Okay, let's go back."] = "Bien, volvamos.",
        ["Then board the rowing boat."] = "Luego sube al bote de remos.",
        ["No, I'm going to stay a while."] = "No, me quedaré un rato.",
        ["Then stay if that is your wish."] = "Entonces quédate si ese es tu deseo.",
        ["Hello there. You seem familiar somehow."] = "Hola. Pareces familiar de alguna manera.",
        ["Uh, I get that a lot."] = "Uh, lo entiendo mucho.",
    },
    ["Jeed"] = {
        ["Hi!"] = "¡Hola!",
        ["*Jeed may say one of the following at random:*"] = "*Jeed puede decir una de las siguientes palabras al azar:*",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["A fight over love and money would be a duel purpose."] = "Una pelea por amor y dinero sería un duelo.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["What did the skeleton say before it ate?"] = "¿Qué dijo el esqueleto antes de comer?",
        ["I don't know."] = "No lo sé.",
        ["Bone appétit."] = "Apetito de huesos.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["My favourite fighter is Mubariz."] = "Mi luchador favorito es Mubariz.",
        ["The guy at the information kiosk?"] = "¿El chico del quiosco de información?",
        ["Yeah! He rocks!"] = "¡Sí! ¡Él es genial!",
        ["Takes all sorts, I guess."] = "Supongo que se aceptan de todo tipo.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["Did you know, they think this place dates back to the Second Age."] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
        ["Really?"] = "¿En serio?",
        ["Yeah, the guy at the information kiosk was telling me."] = "Sí, me lo estaba diciendo el chico del quiosco de información.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Why do giants lose all their duels against vampires?"] = "¿Por qué los gigantes pierden todos sus duelos contra vampiros?",
        ["I don't know - why?"] = "No lo sé, ¿por qué?",
        ["The stakes are always too high!"] = "¡Siempre hay mucho en juego!",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Ooh, this is exciting."] = "Oh, esto es emocionante.",
        ["Yup!"] = "¡Sí!",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Well, this beats doing the shopping."] = "Bueno, esto es mejor que hacer compras.",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Can't you see I'm watching the duels?"] = "¿No ves que estoy viendo los duelos?",
        ["Sorry!"] = "¡Lo siento!",
        ["*Dialogue 9:*"] = "*Diálogo 9:*",
        ["*Dialogue 10:*"] = "*Diálogo 10:*",
        ["Aww, come on, keep fighting. It's just a flesh wound!"] = "Oh, vamos, sigue luchando. ¡Es sólo una herida superficial!",
