        ["He ripped his opponent in half."] = "Partió a su oponente por la mitad.",
        ["That's gotta hurt."] = "Eso tiene que doler.",
        ["He's only 15!"] = "¡Solo tiene 15 años!",
        ["You gotta start 'em young."] = "Tienes que empezarlos jóvenes.",
        ["*Dialogue 12:*"] = "*Diálogo 12:*",
        ["I wouldn't want to be the poor guy who has to clean up after the duels."] = "No me gustaría ser el pobre que tiene que limpiar después de los duelos.",
        ["Me neither."] = "Yo tampoco.",
        ["*Dialogue 13:*"] = "*Diálogo 13:*",
        ["Hi! I'm here to watch the duels."] = "¡Hola! Estoy aquí para ver los duelos.",
        ["Me too!"] = "¡Yo también!",
        ["*Dialogue 14:*"] = "*Diálogo 14:*",
        ["*Dialogue 15:*"] = "*Diálogo 15:*",
        ["I once duelled a man from Entrana,"] = "Una vez me batí en duelo con un hombre de Entrana,",
        ["Who wielded a mighty katana,"] = "Quien empuñaba una poderosa katana,",
        ["It caused me a fright, but it lost him the fight,"] = "Me dio un susto, pero le hizo perder la pelea,",
        ["It was made, not from steel, but banana!"] = "¡No estaba hecho de acero, sino de plátano!",
        ["*Dialogue 16:*"] = "*Diálogo 16:*",
        ["How many duellists does it take to kill a vampyre?"] = "¿Cuántos duelistas se necesitan para matar a un vampyre?",
        ["Uh, wait: I can do this. You would need thousands, because they'd all be too busy arguing ovr who gets the stake!"] = "Uh, espera: puedo hacer esto. ¡Necesitarías miles, porque estarían todos demasiado ocupados discutiendo sobre quién se queda con la apuesta!",
        ["What? No, we've got a vampyre problem back home. I was thinking of recruiting fighters."] = "¿Qué? No, tenemos un problema con vampyre en casa. Estaba pensando en reclutar combatientes.",
        ["Oh, I thought it was a joke."] = "Oh, pensé que era una broma.",
        ["Can't you see I'm watching the crocodiles?"] = "¿No ves que estoy mirando a los cocodrilos?",
        ["Did you know, they think this place dates back to the Second Age?"] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
        ["Yeah, an archaeologist was telling me."] = "Sí, me lo decía un arqueólogo.",
        ["I do miss the fighting sometimes."] = "A veces extraño las peleas.",
        ["I think I prefer the cool water across the oasis to the mass murder."] = "Creo que prefiero el agua fresca del oasis al asesinato en masa.",
        ["I miss the duels."] = "Extraño los duelos.",
        ["The view's quite pleasant really."] = "La vista es realmente agradable.",
        ["Congratulations! You have come to the right place."] = "¡Felicitaciones! Has venido al lugar correcto.",
    },
    ["Jeffery"] = {
        ["Keep it quick. What do you want?"] = "Que sea rápido. ¿Qué deseas?",
        ["Choose an option:"] = "Elige una opción:",
        ["*(After Gunnar's Ground)* Who was that love poem for?"] = "*(Después de Gunnar's Ground)* ¿Para quién era ese poema de amor?",
        ["It, er, it didn't work out well. I don't want to talk about it! Leave me alone!"] = "Eso, ejem, no funcionó bien. ¡No quiero hablar de eso! ¡Déjame en paz!",
        ["I want to use the furnace."] = "Quiero usar el horno.",
        ["You want to use my furnace? No one can use my furnace! Only I can use my furnace!"] = "¿Quieres usar mi horno? ¡Nadie puede usar mi horno! ¡Solo yo puedo usar mi horno!",
        ["You want to use my furnace? I only let exceptional people use my furnace. You don't look exceptional to me."] = "¿Quieres usar mi horno? Sólo dejo que personas excepcionales utilicen mi horno. No me pareces excepcional.",
        ["How do I become exceptional?"] = "¿Cómo puedo llegar a ser excepcional?",
        ["Exceptional people have earned exceptional items; earning Varrock armour would impress me."] = "Personas excepcionales han obtenido artículos excepcionales; ganarme la armadura Varrock me impresionaría.",
        ["Alright!"] = "¡Muy bien!",
        ["You seem exceptional enough. Go ahead."] = "Pareces bastante excepcional. Adelante.",
        ["What can I make here, exactly?"] = "¿Qué puedo hacer aquí exactamente?",
        ["Well, depending on your skill as a blacksmith, you can use this furnace to smelt ore into metal bars."] = "Bueno, dependiendo de tu habilidad como herrero, puedes usar este horno para fundir mineral y convertirlo en barras de metal.",
        ["Oh, I see. What's so special about this furnace, then?"] = "Ah, ya veo. Entonces, ¿qué tiene de especial este horno?",
        ["If you smelt at this furnace while wearing your Varrock armour the enchantment on the armour will give you a small chance of smelting two bars instead of one."] = "Si fundes en este horno mientras usas tu armadura Varrock, el encantamiento de la armadura te dará una pequeña posibilidad de fundir dos barras en lugar de una.",
        ["I see. So, which metal will I be able to obtain more of when smelting with the armour I'm wearing?"] = "Ya veo. Entonces, ¿de qué metal podré obtener más al fundir con la armadura que llevo puesta?",
        ["While wearing the Varrock armour, you will have a chance of smelting an extra bar of any metal up to, and including, adamant."] = "Mientras uses la armadura Varrock, tendrás la posibilidad de fundir una barra adicional de cualquier metal, incluido el adamant.",
        ["Oh, that's useful. That should save me a fair bit of time. Thanks very much."] = "Oh, eso es útil. Eso debería ahorrarme bastante tiempo. Muchas gracias.",
        ["Stay exceptional!"] = "¡Mantente excepcional!",
        ["Try coming back when you're actually wearing your Varrock armour."] = "Intenta regresar cuando estés usando tu armadura Varrock.",
        ["Oh, right. Yes, I see. Okay, thanks."] = "Ah, claro. Sí, ya veo. Bien, gracias.",
        ["Er, nothing."] = "Er, nada.",
        ["Keep away from that! It's dangerous!"] = "¡Manténgase alejado de eso! ¡Es peligroso!",
    },
