        ["I can imagine."] = "Me lo imagino.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["Sorry, can't stop, the Captain will have my guts for garters if he catches me slacking off talking to the stowaway."] = "Lo siento, no puedo parar, el Capitán me tomará las tripas como ligas si me pilla holgazaneando hablando con el polizón.",
        ["I'm not a stowaway! <br>I was invited aboard!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo!",
