        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Jess the human"] = {
        ["Oh dear, oh dear. I'm sorry, but I have to get going!"] = "Dios mío, Dios mío. ¡Lo siento, pero tengo que irme!",
    },
    ["Jessika"] = {
        ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["What do you want to say?"] = "¿Qué quieres decir?",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Jessika. I'm a mage from the Wizards' Tower, doing research on pests."] = "Soy Jessika. Soy un mago de Wizards' Tower y estoy investigando plagas.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is the Void Knight Outpost. For some reason there is a disturbance in these islands and pests come through portals. I'm studying those portals. You should talk to one of the Void Knights if you want to know more."] = "Este es el puesto avanzado Void Knight. Por alguna razón hay una perturbación en estas islas y las plagas entran por los portales. Estoy estudiando esos portales. Deberías hablar con uno de los Void Knights si quieres saber más.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
    },
    ["Jethick"] = {
        ["Hello. We don't get many newcomers around here."] = "Hola. No recibimos muchos recién llegados por aquí.",
        ["Hello. I've been seeing more newcomers around here since the revolution. I don't miss the plague...but it would be good to have more peace and quiet."] = "Hola. He estado viendo más recién llegados por aquí desde la revolución. No extraño la plaga... pero sería bueno tener más paz y tranquilidad.",
    },
    ["Jex"] = {
        ["Hello."] = "Hola.",
        ["Greetings, non-believer. May the blessings of Icthlarin rest on your tired shoulders and may they set you at ease during interesting times."] = "Saludos, no creyente. Que las bendiciones de Icthlarin descansen sobre tus hombros cansados ​​y que te tranquilicen en momentos interesantes.",
        ["Hello, Jex."] = "Hola, Jex.",
        ["Hello, Player."] = "Hola, Player.",
        ["Jex rubs his head tenderly."] = "Jex se frota la cabeza con ternura.",
        ["Select an Option"] = "Seleccione una opción",
        ["Are you okay?"] = "¿Estás bien?",
        ["Some degenerate clubbed me and gave me a lump the size of an egg on the back of my head."] = "Un degenerado me golpeó y me hizo un bulto del tamaño de un huevo en la nuca.",
        ["I'll keep my eyes peeled for suspicious characters."] = "Estaré atento a personajes sospechosos.",
        ["I have a fairly good idea who did it."] = "Tengo una idea bastante clara de quién lo hizo.",
        ["Who?"] = "¿Quién?",
        ["That linen merchant, Siamun; she's never liked me."] = "Ese comerciante de ropa blanca, Siamun; A ella nunca le agrado.",
        ["I'll keep an eye out for her."] = "Estaré atento a ella.",
        ["Could you tell me more about the minor gods?"] = "¿Podrías contarme más sobre los dioses menores?",
        ["Could you tell me more about Scabaras?"] = "¿Podrías contarme más sobre Scabaras?",
        ["I think you'll have gathered most of the relevant details from elsewhere, but general knowledge isn't always the most accurate."] = "Creo que habrás recopilado la mayoría de los detalles relevantes de otros lugares, pero el conocimiento general no siempre es el más preciso.",
        ["Are you claiming I've been misinformed?"] = "¿Estás afirmando que me han informado mal?",
        ["Not really; there are simply details of Scabaras's fall from grace that are only known to we priests."] = "En realidad no; simplemente hay detalles de la caída en desgracia de Scabaras que sólo conocemos los sacerdotes.",
        ["Such as?"] = "¿Por ejemplo?",
        ["Some of his supposed faults can be forgiven. I just can't explain why at the moment."] = "Algunas de sus supuestas faltas pueden ser perdonadas. Simplemente no puedo explicar por qué en este momento.",
        ["I'm not sure whether I should thank you for that bit of confusion or add to that bump on your head."] = "No estoy seguro de si debería agradecerte por ese poco de confusión o aumentar ese chichón en tu cabeza.",
        ["Could you tell me more about Het?"] = "¿Podrías contarme más sobre Het?",
        ["Het is the least strange looking of our deities to foreign eyes; he looks just like us. I suspect this is why his shrines are particularly targeted by the infamous Templeton."] = "Es el aspecto menos extraño de nuestras deidades a ojos extranjeros; se parece a nosotros. Sospecho que es por eso que sus santuarios son particularmente atacados por el infame Templeton.",
        ["What does his patronage cover?"] = "¿Qué cubre su patrocinio?",
        ["He is the very incarnation of health and strength in both mind and body."] = "Él es la encarnación misma de la salud y la fuerza tanto en la mente como en el cuerpo.",
        ["Could you tell me more about Het's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Het en el desierto?",
        ["When I was young, I thought of Het as a strong virtuous knight: brave, daring, and, perhaps, just a little dim."] = "Cuando era joven, pensaba en Het como un caballero fuerte y virtuoso: valiente, atrevido y, tal vez, un poco tonto.",
        ["Sounds like every knight I've ever known."] = "Suena como todos los caballeros que he conocido.",
        ["But, as I grow older, I'm not so sure. It is clear that Het's influence is felt all over the desert; his strength can be felt on the serrated edges of the Menaphites' blades. His nerve is in the tip of every spear wielded by the soldiers of Al Kharid."] = "Pero, a medida que crezco, no estoy tan seguro. Está claro que la influencia de Het se siente en todo el desierto; su fuerza se puede sentir en los bordes dentados de las espadas de los menafitas. Su valor está en la punta de cada lanza que empuñan los soldados de Al Kharid.",
        ["He fortifies each steel cuff that constrains a slave. He is the very tug in the river Elid that drags many to their deaths."] = "Fortalece cada esposa de acero que restringe a un esclavo. Él es el mismo remolcador del río Elid que arrastra a muchos a la muerte.",
        ["Yet, we have enfeebled slaves and weakened villages. Even in this very city there is a plague sapping us of our strength."] = "Sin embargo, hemos debilitado a los esclavos y a las aldeas. Incluso en esta misma ciudad hay una plaga que nos está quitando nuestras fuerzas.",
        ["So, you feel that Het has turned his back on your people?"] = "Entonces, ¿sientes que Het le ha dado la espalda a tu gente?",
        ["No, I wouldn't say that. We mortals are too quick to blame our problems on the gods. Without weakness there is no strength, after all."] = "No, yo no diría eso. Nosotros, los mortales, nos apresuramos a culpar a los dioses de nuestros problemas. Después de todo, sin debilidad no hay fuerza.",
        ["Could you tell me more about Het's followers?"] = "¿Podrías contarme más sobre los seguidores de Het?",
        ["Het originated in the north, so he is worshipped fervently by the people of Al Kharid; however, he is a popular god across the desert - his powerful image of strength and health make him a popular god amongst soldiers and leaders."] = "Het se originó en el norte, por lo que la gente de Al Kharid lo adora fervientemente; sin embargo, es un dios popular en todo el desierto: su poderosa imagen de fuerza y ​​salud lo convierte en un dios popular entre soldados y líderes.",
        ["Could you tell me more about Crondis?"] = "¿Podrías contarme más sobre Crondis?",
        ["Crondis is a ferocious lady with the head of a mighty crocodile."] = "Crondis es una dama feroz con cabeza de un poderoso cocodrilo.",
        ["That must be awkward when buying helmets."] = "Eso debe ser incómodo a la hora de comprar cascos.",
        ["Enough flippancy: remember she is a deity, and this is her place of power."] = "Basta de ligereza: recuerda que ella es una deidad y este es su lugar de poder.",
        ["What kind of people follow her?"] = "¿Qué tipo de gente la sigue?",
        ["She embodies modesty, diligence and resourcefulness, so Crondis is worshipped by the desert's subsistence farmers and hunters. Conversely, she proves unpopular amongst society's elite."] = "Ella encarna la modestia, la diligencia y el ingenio, por eso Crondis es adorada por los agricultores y cazadores de subsistencia del desierto. Por el contrario, resulta impopular entre la élite de la sociedad.",
        ["How so?"] = "¿Cómo es eso?",
        ["Crondis teaches that people should take no more than they need and make do with little, which, as you can imagine, conflicts with the values of many in the richer echelons of society."] = "Crondis enseña que las personas no deben tomar más de lo que necesitan y arreglárselas con poco, lo cual, como puedes imaginar, entra en conflicto con los valores de muchos en los niveles más ricos de la sociedad.",
        ["In Menaphos, she is particularly frowned upon, although that is hardly surprising."] = "En Menaphos, ella está particularmente mal vista, aunque eso no es sorprendente.",
        ["Why?"] = "¿Por qué?",
        ["The Pharaoh of Menaphos is a greedy, cruel man whose lack of restraint is beyond even Crondis's help."] = "El faraón de Menaphos es un hombre codicioso y cruel cuya falta de control está más allá incluso de la ayuda de Crondis.",
        ["Excuse me, I should not have spoken that way. It is unwise to speak ill of one's betters."] = "Disculpe, no debería haber hablado de esa manera. No es prudente hablar mal de los mejores.",
        ["Could you tell me more about Crondis's connection with crocodiles?"] = "¿Podrías contarme más sobre la conexión de Crondis con los cocodrilos?",
        ["Crondis was once a crocodile. Many people believe that those that hunt in the waters of the River Elid embody her very spirit. They were her most beloved supporters."] = "Crondis fue una vez un cocodrilo. Mucha gente cree que quienes cazan en las aguas del río Elid encarnan su espíritu. Eran sus seguidores más queridos.",
        ["When I was young, people were wary of them, revered them even, but were not afraid of them. With the recent crocodile attacks, that has changed."] = "Cuando era joven, la gente desconfiaba de ellos, incluso los veneraban, pero no les tenían miedo. Con los recientes ataques de cocodrilos, eso ha cambiado.",
        ["I'm afraid that the growing lack of restraint of the crocodiles along the River Elid is only further proof that not all is well with Crondis."] = "Me temo que la creciente falta de control de los cocodrilos a lo largo del río Elid es sólo una prueba más de que no todo va bien con Crondis.",
        ["Could you tell me more about Crondis's followers?"] = "¿Podrías contarme más sobre los seguidores de Crondis?",
        ["Crondis is worshipped by those who rely upon their ingenuity to survive: sailors, engineers and rogues hold her in high regard."] = "Crondis es adorada por aquellos que dependen de su ingenio para sobrevivir: marineros, ingenieros y pícaros la tienen en alta estima.",
        ["Due to her popularity amongst seafarers, word of Crondis has spread far and wide and her followers can be found in a great number of exotic places."] = "Debido a su popularidad entre la gente de mar, la palabra sobre Crondis se ha extendido por todas partes y sus seguidores se pueden encontrar en una gran cantidad de lugares exóticos.",
        ["Could you tell me more about Crondis's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Crondis sobre el desierto?",
        ["Could you tell me more about Crondis's influence?"] = "¿Podrías contarme más sobre la influencia de Crondis?",
        ["Crondis hopes to inspire resourcefulness and unassuming modesty. While this has always been her goal, her methods vary more than most."] = "Crondis espera inspirar ingenio y modestia sin pretensiones. Si bien este siempre ha sido su objetivo, sus métodos varían más que la mayoría.",
        ["I'm confused. What do you mean?"] = "Estoy confundido. ¿Qué quieres decir?",
        ["Crondis may save a struggling harvest by bursting the clouds, or she might set swarms of locusts upon a bountiful crop to stop complacency."] = "Crondis puede salvar una cosecha difícil haciendo estallar las nubes, o puede lanzar enjambres de langostas sobre una cosecha abundante para detener la complacencia.",
        ["Could you tell me more about Apmeken?"] = "¿Podrías contarme más sobre Apmeken?",
        ["Something tells me that you might know more than I. I've sensed a change in the heavens, albeit a small one, and I can't help thinking it has something to do with you."] = "Algo me dice que quizás sepas más que yo. He sentido un cambio en los cielos, aunque sea pequeño, y no puedo evitar pensar que tiene algo que ver contigo.",
        ["What makes you think that?"] = "¿Qué te hace pensar eso?",
        ["Not many people come here, and, of those few that do, only a few care to mention Apmeken. I feel her sunny smile shining upon the desert, and I am convinced you are responsible for that. I thank you."] = "No viene mucha gente aquí y, de los pocos que lo hacen, solo unos pocos se preocupan por mencionar Apmeken. Siento su sonrisa soleada brillando sobre el desierto y estoy convencido de que tú eres el responsable de ello. Te lo agradezco.",
        ["Apmeken was the most mischievous, playful and unpredictable of the minor deities. My personal favourite, in fact."] = "Apmeken era la más traviesa, juguetona e impredecible de las deidades menores. Mi favorito personal, de hecho.",
        ["I'm guessing I shouldn't trust you, then?"] = "Supongo que no debería confiar en ti, ¿entonces?",
        ["While Apmeken was mischievous, she was also a goddess of friendship. Like her, I may trip you, but I'd catch you before you fell."] = "Si bien Apmeken era traviesa, también era una diosa de la amistad. Como ella, puedo hacerte tropezar, pero te atraparé antes de que caigas.",
        ["Well, that's good to know. I presume she looks slightly inhuman?"] = "Bueno, es bueno saberlo. ¿Supongo que parece un poco inhumana?",
        ["She had the head of a monkey, ape or baboon, depending on the nature she was displaying at the time. The monkey was skilful, the ape was wise and the baboon was comical."] = "Tenía cabeza de mono, simio o babuino, dependiendo de la naturaleza que mostrara en ese momento. El mono era hábil, el simio sabio y el babuino cómico.",
        ["I see. Jex, I can't help notice that you're speaking in the past tense."] = "Ya veo. Jex, no puedo evitar notar que estás hablando en tiempo pasado.",
        ["Ah, sorry, yes. I'm of the opinion - and it's an opinion not shared by many, I should add - that Apmeken has moved on from these lands."] = "Ah, lo siento, sí. Soy de la opinión -y es una opinión que no comparten muchos, debo añadir- que Apmeken ha abandonado estas tierras.",
        ["I've read reams of scripture detailing Apmeken, and heard endless tales of her deeds. I can't believe that the desert would be such a warring, sombre, plague-filled place if she was still felt here."] = "He leído montones de escrituras que detallan a Apmeken y he escuchado infinitas historias sobre sus hazañas. No puedo creer que el desierto sería un lugar tan guerrero, sombrío y lleno de plagas si todavía se sintiera aquí.",
        ["That's interesting, Jex; can I ask you some more questions about her?"] = "Eso es interesante, Jex; ¿Puedo hacerte más preguntas sobre ella?",
        ["Of course."] = "Por supuesto.",
        ["Could you tell me more about Apmeken's connection with monkeys?"] = "¿Podrías contarme más sobre la conexión de Apmeken con los monos?",
        ["Apmeken was once a monkey. Many people believe that the native monkeys embodied her very spirit. They were her most beloved supporters. There hasn't been any wild monkeys in the desert for a long time - not since I was a child."] = "Apmeken alguna vez fue un mono. Mucha gente cree que los monos nativos encarnaban su espíritu. Eran sus seguidores más queridos. Hace mucho tiempo que no hay monos salvajes en el desierto, desde que yo era niño.",
        ["I'm afraid that the lack of monkeys living here is only further proof that Apmeken has indeed moved on."] = "Me temo que la falta de monos viviendo aquí es sólo una prueba más de que Apmeken realmente ha seguido adelante.",
        ["Could you tell me more about Apmeken's followers?"] = "¿Podrías contarme más sobre los seguidores de Apmeken?",
        ["Apmeken is worshipped by those who value the community and friendship above everything else: mothers, priests and even politicians."] = "Apmeken es adorado por quienes valoran la comunidad y la amistad por encima de todo: madres, sacerdotes e incluso políticos.",
        ["Apmeken originated in the west, in the space between two warring tribes, and it is there she found most of her support."] = "Apmeken se originó en el oeste, en el espacio entre dos tribus en guerra, y es allí donde encontró la mayor parte de su apoyo.",
        ["Could you tell me more about Apmeken's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Apmeken sobre el desierto?",
        ["Apmeken's influence was subtle but incredible, she was an infectious laugh, a jaunty jig, a joke you've heard a hundred times before, but still chuckle at."] = "La influencia de Apmeken fue sutil pero increíble, ella era una risa contagiosa, una jiga alegre, una broma que has escuchado cientos de veces antes, pero de la que aún te ríes.",
        ["It may not sound like much, but these subtleties have been known to avert wars and make enemies set aside their differences."] = "Puede que no parezca mucho, pero se sabe que estas sutilezas evitan guerras y hacen que los enemigos dejen de lado sus diferencias.",
        ["Goodbye, Jex."] = "Adiós, Jex.",
        ["Goodbye. May the gods be with you."] = "Adiós. Que los dioses estén contigo.",
        ["Why is your temple still in such a state?"] = "¿Por qué tu templo sigue en ese estado?",
        ["The minor gods aren't particularly revered in our fine city. Icthlarin holds sway here and, although a fine deity indeed, he's not the most jolly of sorts."] = "Los dioses menores no son particularmente venerados en nuestra hermosa ciudad. Icthlarin domina aquí y, aunque es una excelente deidad, no es el más alegre.",
        ["I thought you were a priest of Icthlarin?"] = "¿Pensé que eras un sacerdote de Icthlarin?",
        ["Well, yes and no. I am primarily a priest of Icthlarin, certainly, but I have been trained in the rites of the minor gods as well."] = "Bueno, sí y no. Ciertamente soy principalmente un sacerdote de Icthlarin, pero también he sido entrenado en los ritos de los dioses menores.",
        ["What would it take to repair this temple, then? Money? Materials? Manpower?"] = "¿Qué se necesitaría entonces para reparar este templo? ¿Dinero? ¿Materiales? ¿Mano de obra?",
        ["I'm not really sure, to be honest. Most of the natural worshippers are in Menaphos; of course, and the local economy is rather depressed. In addition, that Templeton rogue made off with some of the damaged stonework. We should hunt him down like the jackal he is."] = "Para ser honesto, no estoy muy seguro. La mayoría de los adoradores naturales están en Menaphos; Por supuesto, y la economía local está bastante deprimida. Además, ese pícaro de Templeton se llevó parte de la mampostería dañada. Deberíamos cazarlo como el chacal que es.",
        ["I'm sure you'll think of something; you'll be able to count on me when you do."] = "Estoy seguro de que se te ocurrirá algo; Podrás contar conmigo cuando lo hagas.",
    },
    ["Jhonatan"] = {
        ["You are welcome in our home."] = "Eres bienvenido a nuestra casa.",
        ["Greetings. Do you have a moment to spare? I need some help."] = "Saludos. ¿Tienes un momento libre? Necesito ayuda.",
        ["Would you like to help?"] = "¿Quieres ayudar?",
        ["Yes."] = "Sí.",
        ["My appreciation."] = "Mi agradecimiento.",
        ["Not right now."] = "No ahora mismo.",
        ["Nevermind."] = "No importa.",
        ["I am exhausted because my children are unable to sleep at night."] = "Estoy exhausto porque mis hijos no pueden dormir por la noche.",
        ["Oh, that's awful, how come they cannot sleep?"] = "Oh, eso es horrible, ¿por qué no pueden dormir?",
        ["My oldest son is too afraid to sleep because of the [monster]."] = "Mi hijo mayor tiene demasiado miedo para dormir debido al [monster].",
        ["Would you be able to go and find some [monster] and thin their numbers?"] = "¿Podrías ir a buscar algunos [monster] y reducir sus números?",
        ["Seems a little excessive... How many would I need to deal with?"] = "Parece un poco excesivo... ¿Con cuántos tendría que lidiar?",
        ["Could you kill [number] [monster] for me?"] = "¿Podrías matar a [número] [monster] por mí?",
        ["Select an option"] = "Selecciona una opción",
        ["Where could I find [monster]?"] = "¿Dónde puedo encontrar [monster]?",
        ["They were exiled. Rumour has it they've set themselves up in Pollnivneach. That's what I've heard."] = "Fueron exiliados. Se rumorea que se han instalado en Pollnivneach. Eso es lo que he oído.",
        ["The mining camp is somewhere out in the desert to the north. That's what I've heard."] = "El campamento minero está en algún lugar del desierto, al norte. Eso es lo que he oído.",
        ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
        ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
        ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
        ["Talk about your current task."] = "Hable sobre su tarea actual.",
        ["Did you deal with the [number] [monster]? ([number] remaining)"] = "¿Se ocuparon del [número] [monster]? ([número] restantes)",
        ["Not yet. Where could I find [monster] again?"] = "Todavía no. ¿Dónde podría encontrar [monster] nuevamente?",
        ["They were exiled. Rumour has it they've set themselves up in Pollnivneach."] = "Fueron exiliados. Se rumorea que se han instalado en Pollnivneach.",
        ["The mining camp is somewhere out in the desert to the north."] = "El campamento minero está en algún lugar del desierto, al norte.",
        ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
        ["Yeah, the [monster] won't be scaring your son again anytime soon."] = "Sí, el [monster] no volverá a asustar a tu hijo en el corto plazo.",
        ["Thank you. As excessive as it may have seemed, it was necessary!"] = "Gracias. Por excesivo que pareciera, ¡era necesario!",
        ["Now that he can sleep peacefully, let us talk about my daughter."] = "Ahora que puede dormir tranquilo, hablemos de mi hija.",
        ["Ever since she was a little baby, she has been unable to sleep without [item]."] = "Desde que era pequeña, no puede dormir sin [item].",
        ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
        ["Yes, I know it's a bit strange, but [item] were the only thing that would help her drift off."] = "Sí, sé que es un poco extraño, pero [item] era lo único que la ayudaría a quedarse dormida.",
        ["So, please, if you could get [number] [item] I would greatly appreciate it."] = "Entonces, por favor, si pudieras conseguir [número] [item], te lo agradecería mucho.",
        ["Alright."] = "Muy bien.",
        ["Do you know where I could get [item]?"] = "¿Sabes dónde puedo conseguir [item]?",
        ["Copper ore can be found south-east of Varrock."] = "El mineral de cobre se puede encontrar al sureste de Varrock.",
        ["No, sorry."] = "No, lo siento.",
        ["Have you found [number] [item] yet? ([number] remaining)"] = "¿Ya has encontrado [número] [item]? ([número] restantes)",
        ["Nope, where should I be looking for the [item]?"] = "No, ¿dónde debería buscar el [item]?",
        ["Number of [item] given to Jhonatan ([number]/[number])"] = "Número de [item] dado a Jhonatan ([número]/[número])",
        ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
        ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
        ["Great. Thank you."] = "Genial. Gracias.",
        ["I have the [item]."] = "Tengo el [item].",
        ["Excellent, my daughter will be able to sleep like a baby once again!"] = "¡Excelente, mi hija podrá volver a dormir como un bebé!",
        ["Now, my youngest son, he recently lost his teddy bear."] = "Ahora, mi hijo menor, recientemente perdió su osito de peluche.",
        ["You want me to find him a new teddy bear?"] = "¿Quieres que le busque un nuevo osito de peluche?",
        ["No, no. I may not look like it, but I am quite skilled in crafting. I plan to make him a new one if you could get me the materials."] = "No, no. Puede que no lo parezca, pero soy bastante hábil en la elaboración. Planeo hacerle uno nuevo si pudieras conseguirme los materiales.",
        ["What do you need?"] = "¿Qué necesitas?",
        ["I need [number] [item] to make it out of."] = "Necesito [número] [item] para salir.",
        ["So, could you get [number] [item] for me?"] = "Entonces, ¿podrías conseguirme [número] [item]?",
        ["Sure."] = "Claro.",
        ["What do you know about [item]?"] = "¿Qué sabes sobre [item]?",
        ["I hear there is a renowned candlemaker in Catherby."] = "He oído que hay un fabricante de velas de renombre en Catherby.",
        ["Nope."] = "No.",
        ["Did you bring [number] [item]? This teddy bear won't build itself! ([number] remaining)"] = "¿Trajiste [número] [item]? ¡Este osito de peluche no se construirá solo! ([número] restantes)",
        ["Not yet. Could you point me in the direction of some [item]?"] = "Todavía no. ¿Podrías indicarme la dirección de algún [item]?",
        ["Yes, I have brought the [item]."] = "Sí, he traído el [item].",
        ["So how do you make a teddy bear from..."] = "Entonces, ¿cómo se hace un osito de peluche con...?",
        ["No. I think it's better to not know."] = "No. Creo que es mejor no saberlo.",
        ["Excellent! I'll get right to work!"] = "¡Excelente! ¡Me pondré manos a la obra!",
        ["So, my other son..."] = "Entonces, mi otro hijo...",
        ["Uh... Bye."] = "Eh... Adiós.",
        ["The magnificent Crondis has been angered by [monster]. She requires a blood sacrifice and a tribute."] = "El magnífico Crondis se ha enfadado con [monster]. Requiere un sacrificio de sangre y un tributo.",
        ["First, go and kill [number] [monster]."] = "Primero, ve y mata a [número] [monster].",
        ["What have the [monster] done to anger the almighty Crondis?"] = "¿Qué han hecho los [monster] para enojar al todopoderoso Crondis?",
        ["You don't need to know. Will you go to kill them?"] = "No necesitas saberlo. ¿Irás a matarlos?",
        ["Have you vanquished the [number] [monster] for Lady Crondis? ([number] remaining)"] = "¿Has vencido al [número] [monster] para Lady Crondis? ([número] restantes)",
        ["I've been tasked to procure supplies for the war effort."] = "Me han encomendado la tarea de conseguir suministros para el esfuerzo bélico.",
        ["Who are we- Who are YOU at war with?"] = "¿Quiénes somos? ¿Con quién estás en guerra TÚ?",
        ["All will be revealed. First up I need [number] [items]. Can I rely on you?"] = "Todo será revelado. Primero necesito [número] [items]. ¿Puedo confiar en ti?",
        ["Affirmative."] = "Afirmativo.",
        ["Negative."] = "Negativo.",
        ["Do you have the [number] [item] at hand, soldier? ([number] remaining)"] = "¿Tienes el [número] [item] a mano, soldado? ([número] restantes)",
        ["Yes, I have the [item]."] = "Sí, tengo el [item].",
        ["Good work, soldier!"] = "¡Buen trabajo, soldado!",
        ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
        ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
        ["Have you ever tried to fight a war without [item]? I didn't think so."] = "¿Alguna vez has intentado pelear una guerra sin [item]? No lo creo.",
        ["The war effort requires [number] [item]. I assume I can trust you to obtain the [item]?"] = "El esfuerzo de guerra requiere [número] [item]. ¿Asumo que puedo confiar en usted para obtener el [item]?",
        ["You sure can."] = "Seguro que puedes.",
        ["Do you have the supplies, soldier? This war won't fund itself! We need [number] [item]! ([number] remaining)"] = "¿Tienes los suministros, soldado? ¡Esta guerra no se financiará sola! ¡Necesitamos [número] [item]! ([número] restantes)",
        ["Great! Now we are ready to drive the offensive home!"] = "¡Genial! ¡Ahora estamos listos para llevar la ofensiva a casa!",
        ["Can I ask why you're talking like this?"] = "¿Puedo preguntar por qué hablas así?",
        ["Whatever do you mean, soldier?"] = "¿Qué quieres decir, soldado?",
        ["You're talking like an imperial general. It's a bit off-putting."] = "Estás hablando como un general imperial. Es un poco desagradable.",
        ["The guards are always watching. I have to keep up appearances."] = "Los guardias siempre están mirando. Tengo que guardar las apariencias.",
        ["Right...fair enough. What else do...we...need for the war effort?"] = "Cierto... bastante justo. ¿Qué más... nosotros... necesitamos para el esfuerzo bélico?",
        ["Now is the time you have been waiting for, soldier! The killing!"] = "¡Ahora es el momento que estabas esperando, soldado! ¡La matanza!",
        ["We will finally vanquish our dreaded enemy, the [monster]!"] = "¡Finalmente venceremos a nuestro temido enemigo, el [monster]!",
        ["What?"] = "¿Qué?",
        ["Yes, kill [number] [monster] in the name of the Pharaoh himself!"] = "¡Sí, mata a [número] [monster] en nombre del propio Faraón!",
        ["Okay."] = "Está bien.",
        ["Have you killed [number] [monster]? They're usually sliming around Sophanem. We might win this war yet! ([number] remaining)"] = "¿Has matado a [número] [monster]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! ([número] restantes)",
        ["Have you killed [number] [monster]? They're usually sliming around Sophanem. We might win this war yet! (0 remaining)"] = "¿Has matado a [número] [monster]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! (0 restante)",
        ["Yes, I have killed the [monster]."] = "Sí, he matado al [monster].",
        ["Have you danced, as they say, in the blood of your enemies? Have you sent the souls of [number] [monster] to the Underworld?"] = "¿Has bailado, como dicen, en la sangre de tus enemigos? ¿Has enviado las almas de [número] [monster] al Inframundo?",
        ["Not that those [monster] have souls, I believe they are truly beyond help."] = "No es que esos [monster] tengan alma, creo que realmente no pueden recibir ayuda.",
        ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
        ["I fear you still need a lot more help."] = "Me temo que todavía necesitas mucha más ayuda.",
        ["Sorry, what?"] = "Lo siento, ¿qué?",
        ["Nothing. It was my pleasure."] = "Nada. Fue un placer.",
    },
    ["Jim"] = {
        ["Hi Jim!"] = "¡Hola Jim!",
        ["What do you think you're doing? You'll blow your cover. Let me get you out of that suit."] = "¿Qué crees que estás haciendo? Vas a arruinar tu tapadera. Déjame sacarte ese traje.",
        ["Do you want to get out of the penguin suit?"] = "¿Quieres quitarte el traje de pingüino?",
        ["Yes"] = "si",
        ["I don't have enough room to store my penguin suit in my pack. I'll have to make room first."] = "No tengo suficiente espacio para guardar mi traje de pingüino en mi mochila. Primero tendré que hacer espacio.",
        ["The spell wears off as you climb out of the suit, growing back to normal size."] = "El hechizo desaparece cuando te quitas el traje y vuelve a crecer hasta su tamaño normal.",
        ["No, thanks."] = "No, gracias.",
        ["Select an Option"] = "Selecciona una opción",
        ["Tuxedo-time."] = "Hora del esmoquin.",
        ["You will need your hands free to operate the suit."] = "Necesitará tener las manos libres para operar el traje.",
        ["You can't wear a cape inside the suit, it might get caught."] = "No puedes usar una capa dentro del traje, podría quedar atrapada.",
        ["You shrink and walk in to the penguin suit."] = "Te encoges y te pones el traje de pingüino.",
        ["Ask about hunting ground."] = "Preguntar por cotos de caza.",
        ["Pssst."] = "Psst.",
        ["Oh, so you can talk now?"] = "Oh, ¿entonces puedes hablar ahora?",
        ["I could always talk. But I didn't want to reveal myself to the enemy."] = "Siempre podría hablar. Pero no quería revelarme al enemigo.",
        ["Well, what do you want?"] = "Bueno, ¿qué quieres?",
        ["I have heard of Larry's capture. I am sorry for your loss. Larry is very brave."] = "He oído hablar de la captura de Larry. Lamento tu pérdida. Larry es muy valiente.",
        ["Yeah. I hope he's okay. Where ever he is."] = "Sí. Espero que esté bien. Dondequiera que esté.",
        ["That is why I wish to speak to you. I have been instructed to assist you in infiltrating the penguins and training for future assignments."] = "Por eso deseo hablar contigo. Me han ordenado que le ayude a infiltrarse entre los pingüinos y a entrenar para futuras asignaciones.",
        ["What? What future assignments?"] = "¿Qué? ¿Qué futuras asignaciones?",
        ["When you go to rescue Larry, of course. It is not a task to be approached unprepared."] = "Cuando vayas a rescatar a Larry, claro. No es una tarea que deba abordarse sin estar preparado.",
        ["So what exactly am I supposed to do?"] = "Entonces, ¿qué se supone que debo hacer exactamente?",
        ["Should you wish to infiltrate the penguins, I have been granted access to the spell that puts you in your penguin suit."] = "Si deseas infiltrarte entre los pingüinos, se me ha concedido acceso al hechizo que te pone tu traje de pingüino.",
        ["There is more than that, though. A new iceberg has floated down from the north, bringing with it reinforcements for the Penguin Outpost."] = "Pero hay más que eso. Un nuevo iceberg ha descendido flotando desde el norte, trayendo consigo refuerzos para Penguin Outpost.",
        ["To prepare you for the times ahead, we have provided some equipment for you to practise hunting and tracking penguins."] = "Para prepararte para los tiempos venideros, te proporcionamos algunos equipos para que practiques la caza y el rastreo de pingüinos.",
        ["In exchange for the experience you gain, we only ask that you hand over the captured KGP agents to us."] = "A cambio de la experiencia que ganes, solo te pedimos que nos entregues a los agentes de KGP capturados.",
        ["Simply jump across the ice floes here."] = "Simplemente salta sobre los témpanos de hielo aquí.",
        ["Why KGP agents? What will you do with them?"] = "¿Por qué agentes de KGP? ¿Qué harás con ellos?",
        ["That is classified. You do not need to know."] = "Eso está clasificado. No necesitas saberlo.",
        ["What do you want to do?"] = "¿Qué quieres hacer?",
        ["Press him further."] = "Presiónelo más.",
        ["That's not good enough? I'm tired of just taking orders. What will you do with the captured penguins?"] = "¿Eso no es suficiente? Estoy cansado de sólo recibir órdenes. ¿Qué harás con los pingüinos capturados?",
        ["Very well, if you insist on knowing. We will interrogate them and keep them imprisoned. They may reveal valuable information about Larry's location. That is why we only want KGP agents, the other penguins know nothing of"] = "Muy bien, si insistes en saberlo. Los interrogaremos y los mantendremos encarcelados. Pueden revelar información valiosa sobre la ubicación de Larry. Por eso solo queremos agentes del KGP, los otros pingüinos no saben nada de ello.",
        ["interest."] = "interés.",
        ["Ignorance is bliss."] = "La ignorancia es felicidad.",
        ["Fine, I don't want to know."] = "Bien, no quiero saberlo.",
        ["It is for the best."] = "Es lo mejor.",
        ["Do you have any captured KGP agents you would like to hand over?"] = "¿Tiene algún agente de KGP capturado que le gustaría entregar?",
        ["Yes."] = "Sí.",
        ["Yes, I do have some."] = "Sí, tengo algunos.",
        ["Very good. Let me take a look."] = "Muy bien. Déjame echar un vistazo.",
        ["You don't appear to have any with you."] = "Parece que no tienes ninguno contigo.",
        ["The PBJ thanks you for your help."] = "La PBJ te agradece tu ayuda.",
        ["No, I don't have any for you right now."] = "No, no tengo ninguno para ti en este momento.",
        ["You tickle the polar bear."] = "Le haces cosquillas al oso polar.",
        ["You do not have enough space in your inventory to get out of the suit."] = "No tienes suficiente espacio en tu inventario para quitarte el traje.",
    },
    ["Jiminua"] = {
        ["Welcome to Jiminua's Jungle Store. Can I help you at all?"] = "Bienvenido a la tienda Jungle Store de Jiminua. ¿Puedo ayudarte en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
        ["Take a good look."] = "Míralo bien.",
        ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
        ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
        ["Can you un-note any of my items?"] = "¿Puedes anular la nota de alguno de mis artículos?",
        ["I can un-note pure essence, but nothing else. Just give me the notes you wish to exchange."] = "Puedo eliminar la esencia pura, pero nada más. Sólo dame las notas que deseas intercambiar.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Jimmy Dazzler"] = {
        ["What is your name and what is your business here?"] = "¿Cuál es tu nombre y cuál es tu negocio aquí?",
        ["My name is Player, and I have a couple of questions for you."] = "Mi nombre es Player y tengo un par de preguntas para usted.",
        ["What do you mean by no?"] = "¿Qué quieres decir con no?",
        ["That just isn't the ticket. I don't know you nor will I answer any questions. Now begone from here, you'll attract unwanted attention to me."] = "Ese no es el billete. No te conozco ni responderé ninguna pregunta. Ahora vete de aquí, atraerás atención no deseada hacia mí.",
        ["As if those 'clothes' you're wearing wouldn't do that already."] = "Como si esa 'ropa' que llevas puesta no hiciera eso ya.",
        ["Ah, Player, aren't you just the ticket?"] = "Ah, Player, ¿no eres sólo el billete?",
        ["Can you tell me where I could find..."] = "¿Puedes decirme dónde puedo encontrar...?",
        ["Grimesquit and Phingspet"] = "Grimesquit y Phingspet",
        ["Can you tell me where I could find Phingspet and Grimesquit?"] = "¿Puedes decirme dónde puedo encontrar Phingspet y Grimesquit?",
        ["You can find those vile harpies in the sewers of Varrock."] = "Puedes encontrar esas viles arpías en las alcantarillas de Varrock.",
        ["~ Jimmy shudders when he thinks of them. ~"] = "~ Jimmy se estremece cuando piensa en ellos. ~",
        ["If you ask me, it's too good a place for them."] = "Si me preguntas, es un lugar demasiado bueno para ellos.",
        ["Can you tell me where I could find Hooknosed Jack?"] = "¿Puedes decirme dónde puedo encontrar Hooknosed Jack?",
        ["He should be in the roughest area of Varrock, knowing him. He likes a good scrap does Jack."] = "Debería estar en la zona más dura de Varrock, conociéndolo. A Jack le gusta una buena pelea.",
        ["Can you tell me where I could find Smokin' Joe?"] = "¿Puedes decirme dónde puedo encontrar Smokin' Joe?",
        ["You won't find him around here. They wouldn't let a filthy old dwarf like him into a civilised town like this."] = "No lo encontrarás por aquí. No dejarían que un viejo y asqueroso enano como él entrara en una ciudad civilizada como ésta.",
        ["Well, if he's not here, where would I find him?"] = "Bueno, si no está aquí, ¿dónde lo encontraría?",
        ["If the old rascal's lungs haven't given up yet, you should find him in Keldagrim, the city of dwarves."] = "Si los pulmones del viejo sinvergüenza aún no se han rendido, deberías encontrarlo en Keldagrim, la ciudad de los enanos.",
        ["Can you tell me where I could find 'The Face'?"] = "¿Puedes decirme dónde puedo encontrar 'The Face'?",
        ["Old Pugly? My oh my, she got her comeuppance alright!"] = "¿Viejo Pugly? ¡Dios mío, ella recibió su merecido!",
        ["Old Pugly?"] = "¿Viejo Pugly?",
        ["Pug ugly."] = "Pug feo.",
        ["That's really nasty."] = "Eso es realmente desagradable.",
        ["Believe me, she deserves everything she gets!"] = "Créeme, ¡ella se merece todo lo que recibe!",
        ["What did she do?"] = "¿Qué hizo ella?",
        ["I couldn't possibly tell you, but be careful around her."] = "No podría decírtelo, pero ten cuidado con ella.",
        ["Will you please tell me where I could find her?"] = "¿Podrías decirme dónde puedo encontrarla?",
        ["She'll be in or around Port Sarim I reckon."] = "Supongo que estará en Port Sarim o sus alrededores.",
        ["Can you tell me where I would find Felkrash?"] = "¿Puedes decirme dónde encontraría Felkrash?",
        ["The Boss? You'll find her in Port Sarim."] = "¿El jefe? La encontrarás en Port Sarim.",
        ["She's your boss?"] = "¿Ella es tu jefa?",
        ["Well, sort of. She's the unofficial head of the rat catchers."] = "Bueno, más o menos. Ella es la jefa no oficial de los cazadores de ratas.",
        ["Nothing, thanks."] = "Nada, gracias.",
    },
    ["Jimmy the Chisel"] = {
        ["Hello mate!"] = "¡Hola amigo!",
    },
    ["Jimmy"] = {
        ["Ello there."] = "Hola.",
        ["Select an Option"] = "Selecciona una opción",
        ["Tell me about this room."] = "Háblame de esta habitación.",
        ["Tell me about this room?"] = "¿Cuéntame sobre esta habitación?",
        ["Well... s'like thish... Thish here'sh a shtore room right?"] = "Bueno... es así... Aquí hay un trastero, ¿verdad?",
        ["A store roorr. you mean?"] = "Una tienda. ¿te refieres a?",
        ["That'sh what I shaid! *HIC* A shtore room.... Now technic'ly shpeaking, I should be outshide guarding it..."] = "¡Eso es lo que dije! *HIC* Un almacén... Ahora, técnicamente hablando, debería estar afuera cuidándolo...",
        ["But you just nipped in to have a quick drink?"] = "¿Pero viniste a tomar un trago rápido?",
        ["Yep... and to practish."] = "Sí... y a practicar.",
        ["Practish? I mean.. practise what?"] = "¿Practicar? Quiero decir... ¿practicar qué?",
        ["Keg balancin. I'm the besht."] = "Equilibrio del barril. Soy el mejor.",
        ["Tell me how to balance kegs."] = "Dime cómo equilibrar barriles.",
        ["Tell me how to balance kegs?"] = "¿Dime cómo equilibrar los barriles?",
        ["Yer very very shtrange. But.... you pick the keg up, and balance it on yer head, then you pick another keg up and put that on top. S'really very eashy."] = "Eres muy, muy extraño. Pero... levantas el barril y lo equilibras sobre tu cabeza, luego tomas otro barril y lo pones encima. Es realmente muy fácil.",
        ["Eashy?"] = "¿Tranquilo?",
        ["Yesh. Eashy."] = "Sí. Fácil.",
        ["But you couldn't ever balansh ash many ash meee!"] = "¡Pero nunca podrías equilibrar ash muchos ash meee!",
        ["That sounds like a challenge, I'll show you!"] = "Eso suena como un desafío, ¡te lo mostraré!",
        ["What's with the multicoloured furniture?"] = "¿Qué pasa con el furniture multicolor?",
        ["Keg tag. S'my invenshun."] = "Etiqueta de barril. Es mi invención.",
        ["Keg tag? How does that work?"] = "¿Etiqueta de barril? ¿Cómo funciona eso?",
        ["Eashy. Balance kegsh on yer head, then shee if you can tag the coloured shtuff in order, before you loshe control of yer kegsh."] = "Tranquilo. Equilibra el barril sobre tu cabeza y luego comprueba si puedes etiquetar las cosas de colores en orden, antes de que pierdas el control del barril.",
        ["So, I put some kegs on my head, then go around tagging each of the coloured furniture in order. Sounds easy! What do I get?"] = "Entonces, me pongo algunos barriles en la cabeza y luego voy etiquetando cada uno de los furniture de colores en orden. ¡Suena fácil! ¿Qué obtengo?",
        ["Well...I could teash yer shumfin' abou' strength."] = "Bueno... podría molestarte sobre la fuerza.",
        ["Knowledge in strength. Hmm, could be useful."] = "Conocimiento en fuerza. Mmmm, podría ser útil.",
        ["Bye!"] = "¡Adiós!",
        ["Shure you wouldn't like an ickle drinkie fore yer go?"] = "¿Seguro que no te gustaría tomar un trago antes de irte?",
        ["No thanks, got things to do, people to see, tokens to earn..."] = "No, gracias, tengo cosas que hacer, gente que ver, fichas que ganar...",
    },
    ["Joe (City of Um)"] = {
        ["That's another year in Um been and gone..."] = "Ese es otro año en el que Um ha estado y se ha ido...",
    },
    ["Joe"] = {
        ["Hi, I'm Joe, door guard for Lady Keli."] = "Hola, soy Joe, guardia de puerta de Lady Keli.",
        ["Hi, who are you guarding here?"] = "Hola, ¿a quién estás protegiendo aquí?",
        ["Can't say, all very secret. You should get out of here. I am not supposed to talk while I guard."] = "No puedo decirlo, todo es muy secreto. Deberías salir de aquí. Se supone que no debo hablar mientras estoy en guardia.",
        ["Hey, chill out, I won't cause you trouble. I was just wondering what you do to relax."] = "Oye, relájate, no te causaré problemas. Me preguntaba qué haces para relajarte.",
        ["You never relax with these people, but it's a good career for a young man and some of the shouting I rather like."] = "Nunca te relajas con esta gente, pero es una buena carrera para un joven y algunos de los gritos me gustan bastante.",
        ["RESISTANCE IS USELESS!"] = "¡LA RESISTENCIA ES INÚTIL!",
        ["So what do you buy with these great wages?"] = "Entonces, ¿qué compras con estos fantásticos salarios?",
        ["Really, after working here, there's only time for a drink or three. All us guards go to the same bar and drink ourselves stupid."] = "Realmente, después de trabajar aquí, solo hay tiempo para tomar una copa o tres. Todos los guardias vamos al mismo bar y bebemos hasta quedar estupefactos.",
        ["It's what I enjoy these days, that fade into unconsciousness. I can't resist the sight of a really cold beer."] = "Es lo que disfruto estos días, lo que se desvanece en la inconsciencia. No puedo resistirme a ver una cerveza bien fría.",
        ["Would you be interested in making a little more money?"] = "¿Estarías interesado en ganar un poco más de dinero?",
        ["WHAT?! Are you trying to bribe me? I may not be a great guard, but I am loyal. How DARE you try to bribe me!"] = "¡¿QUÉ?! ¿Estás intentando sobornarme? Puede que no sea un gran guardia, pero soy leal. ¡Cómo te ATREVES a intentar sobornarme!",
        ["No, no, you got the wrong idea, totally. I just wondered if you wanted some part-time bodyguard work."] = "No, no, tienes una idea totalmente equivocada. Sólo me preguntaba si querías un trabajo de guardaespaldas a tiempo parcial.",
        ["Oh. Sorry. No, I don't need money. As long as you were not offering me a bribe."] = "Ah. Lo siento. No, no necesito dinero. Siempre y cuando no me ofrecieras un soborno.",
        ["Tell me about the life of a guard."] = "Cuéntame sobre la vida de un guardia.",
        ["Well, the hours are good....."] = "Bueno, el horario es bueno.....",
        [".... But most of those hours are a drag. If only I had spent more time in Knight school when I was a young boy. Maybe I wouldn't be here now, scared of Keli."] = ".... Pero la mayoría de esas horas son un fastidio. Si tan solo hubiera pasado más tiempo en la escuela Knight cuando era un niño. Quizás no estaría aquí ahora, asustada de Keli.",
        ["What did you want to be when you were a boy?"] = "¿Qué querías ser cuando eras niño?",
        ["Well, I loved to sit by the lake, with my toes in the water and shoot the fish with my bow and arrow."] = "Bueno, me encantaba sentarme junto al lago, con los dedos de los pies en el agua y disparar a los peces con mi arco y flecha.",
        ["That was a strange hobby for a little boy."] = "Ese era un pasatiempo extraño para un niño pequeño.",
        ["It kept us from goblin hunting, which was what most boys did. What are you here for?"] = "Nos impedía cazar duendes, que era lo que hacían la mayoría de los niños. ¿Para qué estás aquí?",
        ["I had better leave, I don't want trouble."] = "Será mejor que me vaya, no quiero problemas.",
        ["Thanks, I appreciate that. Talking on duty can be punishable by having your mouth stitched up. These are tough people, no mistake."] = "Gracias, lo aprecio. Hablar durante el servicio puede ser castigado con que le cosen la boca. Son personas duras, no hay duda.",
    },
    ["Joe (Harpoon)"] = {
        ["Hello!"] = "¡Hola!",
        ["Arr? Be ye wantin' te go on account with our gang o' fillibusters?"] = "¿Llegó? ¿Quieres ir a cuenta con nuestra banda de filibusteros?",
        ["The powder monkey be takin' a caulk after gettin' rowdy on bumboo, so there be plenty of room for ye."] = "El mono de la pólvora se va a poner masilla después de ponerse alborotado en bumboo, así que habrá mucho espacio para ti.",
        ["Riiiiight..."] = "Correcto...",
        ["I'll just be over here if you need me."] = "Estaré aquí si me necesitas.",
        ["Whadda ya want?"] = "¿Qué quieres?",
        ["Select an Option"] = "Selecciona una opción",
        ["Whadda ya got?"] = "¿Qué tienes?",
        ["We gots grog and we gots food. Here, take a look."] = "Tenemos grog y comida. Aquí, echa un vistazo.",
        ["Nothing! Honest!"] = "¡Nada! ¡Honesto!",
        ["Then stop takin' up me floor space!"] = "¡Entonces deja de ocuparme espacio!",
        ["I wanted to know where you got that harpoon hand."] = "Quería saber de dónde sacaste esa mano de arpón.",
        ["Yer new in town aintcha?"] = "¿Eres nuevo en la ciudad?",
        ["Newish certainly."] = "Nuevo, sin duda.",
        ["Well, if ye wants te hear the story, here goes."] = "Bueno, si quieres escuchar la historia, aquí va.",
        ["See, I was walkin' along the docks one day, and this fierce storm blew up."] = "Mira, un día estaba caminando por los muelles y estalló una tormenta feroz.",
        ["All of a sudden I turn an there, bearin' down on me is this albatross..."] = "De repente me giro y allí, acercándose a mí, está este albatros...",
        ["Sorry to interrupt, but I would just like to clear something up."] = "Perdón por interrumpir, pero me gustaría aclarar algo.",
        ["What? I was just gettin' to the good bit."] = "¿Qué? Estaba llegando a la parte buena.",
        ["When I said 'I wanted to know where you got that harpoon hand', I meant where did you get it made, or buy it from?"] = "Cuando dije 'Quería saber de dónde sacaste esa mano de arpón', quise decir ¿dónde la hiciste o dónde la compraste?",
        ["If ye don't wants to hear the story then I ain't gonna tell ye!"] = "¡Si no quieres escuchar la historia entonces no te la contaré!",
        ["What'll it be?"] = "¿Qué será?",
        ["A Long Drop."] = "Una caída larga.",
        ["Ye sure?"] = "¿Estás seguro?",
        ["Aye, drop me..."] = "Sí, déjame...",
        ["Take a seat."] = "Toma asiento.",
        ["Er, nothing?"] = "Er, ¿nada?",
        ["Then stop tryin' te take up me table space!"] = "¡Entonces deja de intentar ocupar mi espacio en la mesa!",
        ["Sorry, lad, I think you've had enough of those. I'm cutting you off."] = "Lo siento, muchacho, creo que ya has tenido suficiente de eso. Te estoy interrumpiendo.",
    },
    ["Joey"] = {
        ["*(If the player has tokens to hand in:)*"] = "*(Si el player tiene fichas para entregar:)*",
        ["Handing in event currency will increase your progress and unlock unique rewards. This will remove all currency from your bags and pouch."] = "Entregar moneda del evento aumentará tu progreso y desbloqueará recompensas únicas. Esto eliminará todo el dinero de sus bolsos y carteras.",
        ["Do you wish to continue?"] = "¿Quieres continuar?",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["Yes"] = "si",
        ["*(If a cloak is rewarded, repeated for possible multiples:)*"] = "*(Si se recompensa una capa, se repite para posibles múltiplos:)*",
        ["Congratulations, you have unlocked the [cloak] Override in the wardrobe."] = "Felicitaciones, has desbloqueado la anulación [cloak] en el armario.",
        ["*(If the player reaches a new level:)*"] = "*(Si el player alcanza un nuevo nivel:)*",
        ["*(If a mystery box would be rewarded but there is not enough space in backpack for it:)*"] = "*(Si se recompensa una caja misteriosa pero no hay suficiente espacio en backpack para ella:)*",
        ["Please ensure you have at least 2 free spaces in your inventory."] = "Asegúrese de tener al menos 2 espacios libres en su inventario.",
        ["*(Continues with chat, without tokens being handed in.)*"] = "*(Continúa con el chat, sin entrega de tokens.)*",
        ["*(If big event mystery boxes are rewarded:)*"] = "*(Si se recompensan las cajas misteriosas del gran evento:)*",
        ["Congratulations, you received Big event mystery box x [amount]."] = "Felicitaciones, recibió la caja misteriosa del gran evento x [amount].",
        ["*(If event mystery boxes are rewarded:)*"] = "*(Si se recompensan las cajas misteriosas del evento:)*",
        ["Congratulations, you received Event mystery box x [amount]."] = "Felicitaciones, recibió la caja misteriosa del evento x [amount].",
        ["Congratulations, you have levelled up to Level [level]"] = "Felicitaciones, has subido de nivel al nivel [level].",
        ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
        ["Greetings! Allow me to introduce myself. I am Joey the renowned cape designer and this is my cape festival, Rune Capers! I also like Piña Coladas and getting caught in the rain. Gonna be honest though, not really into yoga, it's just not my sort of thing."] = "¡Saludos! Permítanme presentarme. Soy Joey, el renombrado diseñador de capas, y este es mi festival de capas, ¡Rune Capers! También me gustan las piñas coladas y que me pille la lluvia. Pero voy a ser honesto, no me gusta mucho el yoga, simplemente no es mi tipo de cosas.",
        ["Nice to meet you Joey!"] = "¡Encantado de conocerte Joey!",
        ["*(Only after the first time:)*"] = "*(Sólo después de la primera vez:)*",
        ["What can I do for you today?"] = "¿Qué puedo hacer por ti hoy?",
        ["Select an option"] = "Seleccione una opción",
        ["*(Only if not asked last and it's not the first time:)*"] = "*(Solo si no se te preguntó la última vez y no es la primera vez :)*",
        ["Who are you?"] = "¿Quién eres?",
        ["Allow me to introduce myself. I am Joey the renowned cape designer and this is my cape festival, Rune Capers! I also like Piña Coladas and getting caught in the rain. Gonna be honest though, not really into yoga, it's just not my sort of thing."] = "Permítanme presentarme. Soy Joey, el renombrado diseñador de capas, y este es mi festival de capas, ¡Rune Capers! También me gustan las piñas coladas y que me pille la lluvia. Pero voy a ser honesto, no me gusta mucho el yoga, simplemente no es mi tipo de cosas.",
        ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
        ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
        ["Tell me about the event!"] = "¡Cuéntame sobre el evento!",
        ["It's really simple, I just want you to prove to me that you are worthy of wearing my ostentatious designs! If you want to wear my Cloak of Might design you're gonna have to go out and get you hands dirty, doesn't matter what combat style you're using, just give me the Tokens of Might that you find. Or if you're feeling a bit more passive and want to wear my Cloak of Talents design... head on out and get to skilling! Gathering, artisan, whatever you like, just bring me the Tokens of Talent that you find along the way! Then for the truly dedicated, if you manage to get enough tokens for both of my designs you'll be deemed worthy to wear my finest creation, The Cloak of Proficiency!"] = "Es muy simple, ¡solo quiero que me demuestres que eres digno de lucir mis ostentosos diseños! Si quieres usar mi diseño de Capa de Poder tendrás que salir y ensuciarte las manos, no importa qué estilo de combate estés usando, solo dame las Fichas de Poder que encuentres. O si te sientes un poco más pasivo y quieres usar mi diseño de Capa de Talentos... ¡sal y empieza a desarrollar habilidades! Recolector, artesano, lo que quieras, ¡tráeme las Fichas de Talento que encuentres en el camino! Luego, para los verdaderamente dedicados, si logran obtener suficientes fichas para mis dos diseños, serán considerados dignos de usar mi mejor creación, ¡La Capa de la Competencia!",
        ["What makes your capes so special?"] = "¿Qué hace que tus capas sean tan especiales?",
        ["Did you really just ask that question?! Have you not heard of Joey, King of fashion capes? Winner of the Gielinor Cape Designs of the Year Award four out of the past five years!?"] = "¡¿De verdad acabas de hacer esa pregunta?! ¿No has oído hablar de Joey, el rey de las capas de moda? ¿¡Ganador del premio Gielinor Cape Designs of the Year en cuatro de los últimos cinco años!?",
        ["Only four out of five?"] = "¿Sólo cuatro de cinco?",
        ["Yeah... we don't talk about the Great S Cape fiasco."] = "Sí... no hablamos del fiasco de Great S Cape.",
        ["Goodbye."] = "Adiós.",
        ["Take care!"] = "¡Cuídate!",
        ["Well, that was another successful Cape Festival, I hope you enjoyed our Es-cape-ades!"] = "Bueno, ese fue otro Festival del Cabo exitoso. ¡Espero que hayas disfrutado de nuestros Es-cape-ades!",
        ["... Well, I'm going to go on ahead."] = "... Bueno, voy a seguir adelante.",
        ["... Like a hat."] = "... Como un sombrero.",
        ["HAHAHAHAHAHAHAHAHAHAHAHAHA!"] = "¡HAHAHAHAHAHAHAHAHAHAHAHAHA!",
        ["OHOHOHOHOHOHOHOHO!"] = "¡OHOHOHOHOHOHOHOHO!",
        ["Ha...ha...Oh..."] = "Ja... ja... Oh...",
        ["Doug! Write that one down! I have an idea for a new festival!"] = "¡Doug! ¡Escribe eso! ¡Tengo una idea para un nuevo festival!",
        ["Hahaha..."] = "Jajaja...",
        ["You take this opportunity to slowly back away and take your leave."] = "Aprovechas esta oportunidad para retroceder lentamente y despedirte.",
        ["Get it away from me! Don't let it get on my cape!"] = "¡Aléjamelo de mí! ¡No dejes que se manche mi capa!",
        ["Joey, are you o... What happened to your hair!?"] = "Joey, ¿estás... ¿¡Qué le pasó a tu cabello!?",
        ["It was so dark... I never thought I'd get out... I had to eat my cape to survive."] = "Estaba tan oscuro... Nunca pensé que saldría... Tuve que comerme mi capa para sobrevivir.",
        ["You ate your cape? ... How was it?"] = "¿Te comiste tu capa? ... ¿Cómo fue?",
        ["Expensive."] = "Caro.",
        ["Hey Joey!"] = "¡Hola Joey!",
        ["*(After first time:)*"] = "*(Después de la primera vez:)*",
        ["How's it going??"] = "¿Cómo te va?",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["I'm having hair troubles! That's what's going on!"] = "¡Tengo problemas con el cabello! ¡Eso es lo que está pasando!",
        ["Sorry Joey, I meant what's going on with the event?"] = "Lo siento Joey, quise decir ¿qué está pasando con el evento?",
        ["Don't worry about it."] = "No te preocupes por eso.",
        ["I've decided to kill two birds with one stone and win this competition by concocting a potion which will bring back my luscious locks."] = "He decidido matar dos pájaros de un tiro y ganar este concurso preparando una poción que me devolverá mis deliciosos mechones.",
        ["Is this potion safe?"] = "¿Es segura esta poción?",
        ["You'll be the one making it so that's up to you."] = "Tú serás quien lo haga, así que eso depende de ti.",
        ["I'm not sure I'm comfortable risking your life over this..."] = "No estoy seguro de sentirme cómodo arriesgando tu vida por esto...",
        ["You'll be able to earn some Herblore XP while you do so!"] = "¡Podrás ganar algo de XP Herblore mientras lo haces!",
        ["I think I can help."] = "Creo que puedo ayudar.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["Why did you enter the Summer Skill Off?"] = "¿Por qué participaste en el Summer Skill Off?",
        ["People just aren't interested in my capes anymore."] = "La gente ya no está interesada en mis capas.",
        ["I think it's time for a change in the business, time to branch out into other outfits!"] = "Creo que es hora de un cambio en el negocio, ¡es hora de expandirse hacia otras marcas!",
        ["But I can't do that without some serious money!"] = "¡Pero no puedo hacer eso sin mucho dinero!",
        ["What sort of of outfits are you thinking of?{{Sic}}"] = "¿En qué tipo de ropa estás pensando?{{Sic}}",
        ["You tell me!"] = "¡Dímelo tú!",
        ["What kind of outfits would you like to see?"] = "¿Qué tipo de outfits te gustaría ver?",
        ["Regular clothes."] = "Ropa normal.",
        ["Light or leather armour."] = "Armadura ligera o de cuero.",
        ["Robes and magical gear."] = "Túnicas y equipo mágico.",
        ["Goofy armour."] = "Armadura tonta.",
        ["Heavy and bulky armour."] = "Armadura pesada y voluminosa.",
        ["That's a great idea, I'll keep that in mind when I'm designing my next outfit!"] = "¡Es una gran idea, la tendré en cuenta cuando diseñe mi próximo conjunto!",
        ["Thanks Joey!"] = "¡Gracias Joey!",
        ["Question?"] = "¿Pregunta?",
        ["Can I ask you an important question?"] = "¿Puedo hacerte una pregunta importante?",
        ["Of course!"] = "¡Por supuesto!",
        ["What happened down that well?"] = "¿Qué pasó en ese pozo?",
        ["It was horrible..."] = "Fue horrible...",
        ["Horrors you can't even imagine..."] = "Horrores que ni siquiera puedes imaginar...",
        ["I still hear the 'Gloop gloop gloop' every night..."] = "Todavía escucho el 'Gloop gloop gloop' todas las noches...",
        ["Hope to hear from you again soon!"] = "¡Espero volver a tener noticias tuyas pronto!",
        ["What did you say about my hair!?"] = "¿¡Qué dijiste sobre mi cabello!?",
        ["You slink away from the angry man."] = "Te alejas del hombre enojado.",
        ["Hi Player..."] = "Hola Player...",
        ["While he wasn't the winner of the Summer Skill Off, he certainly was the baldest."] = "Si bien no fue el ganador del Summer Skill Off, ciertamente fue el más calvo.",
        ["Welcome back..."] = "Bienvenido de nuevo...",
        ["What do I need to do here?"] = "¿Qué necesito hacer aquí?",
        ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
        ["Well... I guess you just have to toss stuff into the cauldron and hope it brings my hair back."] = "Bueno... Supongo que solo tienes que tirar cosas al caldero y esperar que me devuelva el cabello.",
        ["Using the cauldron Joey is at will grant increased XP while skilling at this location!"] = "¡Usar el caldero en el que se encuentra Joey otorgará más XP mientras practicas en esta ubicación!",
        ["I'll do my best to get your hair back Joey!"] = "¡Haré todo lo posible para recuperar tu cabello Joey!",
        ["Thank you."] = "Gracias.",
        ["Why did you enter the Winter Chill Off?"] = "¿Por qué participaste en el Winter Chill Off?",
        ["What brings you back to the Chill Off?"] = "¿Qué te trae de vuelta al Chill Off?",
        ["What if I never get my hair back?"] = "¿Qué pasa si nunca recupero mi cabello?",
        ["It's not so bad, just think of all the money you will save on shampoo!"] = "No es tan malo, ¡solo piensa en todo el dinero que ahorrarás en champú!",
        ["I guess..."] = "Supongo...",
        ["Why do you need your hair back so badly?"] = "¿Por qué necesitas tanto recuperar tu cabello?",
        ["I'm just not good enough without it..."] = "Simplemente no soy lo suficientemente bueno sin él...",
        ["Joey, you're a wonderful person, don't let anyone make you think otherwise."] = "Joey, eres una persona maravillosa, no dejes que nadie te haga pensar lo contrario.",
        ["It's not about the hair on your head, it's about the hair in your heart."] = "No se trata del pelo de tu cabeza, se trata del pelo de tu corazón.",
        ["And you have the hairiest heart I've ever seen."] = "Y tienes el corazón más peludo que he visto en mi vida.",
        ["That may be the strangest thing I've ever said."] = "Eso puede ser lo más extraño que he dicho en mi vida.",
        ["Who's winning?"] = "¿Quién está ganando?",
        ["Joey appears to be in a daze."] = "Joey parece estar aturdido.",
        ["Joey, I think you might be the second best fashion designes on Gielinor."] = "Joey, creo que podrías ser el segundo mejor diseño de moda en Gielinor.",
        ["The second best fashion designer..."] = "El segundo mejor diseñador de moda...",
        ["Second best..."] = "Segundo mejor...",
        ["He's not responding."] = "Él no responde.",
        ["Oh Joey, if only you had hair like mine, then maybe you wouldn't just be the second best fashion designer!"] = "¡Oh, Joey, si tan solo tuvieras el cabello como el mío, entonces tal vez no serías el segundo mejor diseñador de moda!",
        ["Bloomin' bananas!"] = "¡Plátanos florecientes!",
        ["Don't bother with him, he's only the second best fashion designer!"] = "¡No te molestes con él, es solo el segundo mejor diseñador de moda!",
        ["Hahaha!"] = "¡Jajaja!",
        ["Hehehe!"] = "¡Jejeje!",
        ["Hohoho!"] = "¡Hohoho!",
        ["What a loser!"] = "¡Qué perdedor!",
        ["Hm..."] = "Mmm...",
        ["Maybe you should leave him be for now."] = "Quizás deberías dejarlo en paz por ahora.",
        ["Goodbye!"] = "¡Adiós!",
        ["Bye..."] = "Adiós...",
    },
    ["Jofridr Mordstatter"] = {
        ["Hello there. Would you like to see the goods I have for sale?"] = "Hola. ¿Quieres ver los productos que tengo a la venta?",
        ["Select an option"] = "Selecciona una opción",
        ["Yes please, Jofridr"] = "Si por favor, Jofridr",
        ["Yes please, Jofridr."] = "Sí, por favor, Jofridr.",
        ["No thank you, Jofridr"] = "No, gracias Jofridr.",
        ["No thank you, Jofridr."] = "No, gracias, Jofridr.",
        ["Fair thee well."] = "Que te vaya bien.",
        ["Why do you have so much wool in your store?"] = "¿Por qué tienes tanta lana en tu tienda?",
        ["Why do you have so much wool in your store? I haven't seen any sheep anywhere."] = "¿Por qué tienes tanta lana en tu tienda? No he visto ninguna oveja por ningún lado.",
        ["Ah, I have contacts on the mainland. I have a sailor friend who brings me crates of wool on a regular basis."] = "Ah, tengo contactos en el continente. Tengo un amigo marinero que me trae cajas de lana con regularidad.",
        ["What do you trade for it?"] = "¿Qué cambias por él?",
        ["Rope of course! What else can we sell? Fish would go off before it got so far south."] = "¡Cuerda, por supuesto! ¿Qué más podemos vender? Los peces se lanzarían antes de llegar tan al sur.",
        ["Where does all this rope go?"] = "¿A dónde va toda esta cuerda?",
        ["Err, I don't remember the name of the place very well. Dreinna? Drennor? Something like that."] = "Err, no recuerdo muy bien el nombre del lugar. ¿Dreinna? ¿Drennor? Algo así.",
        ["That's very interesting. Thanks Jofridr."] = "Eso es muy interesante. Gracias Jofridr.",
    },
    ["Johanhus Ulsbrecht"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What kind of organisation is this?"] = "¿Qué tipo de organización es esta?",
        ["We're a proactive organisation working towards the cessation of monsters in normal civilised human society. There seems to be no backbone in this land so we're stepping up to the challenge."] = "Somos una organización proactiva que trabaja para el cese de los monstruos en la sociedad humana civilizada normal. Parece que no hay columna vertebral en esta tierra, por lo que estamos asumiendo el desafío.",
        ["Hmm, how do you propose to do that? I mean, I see people every day killing goblins around here!"] = "Hmm, ¿cómo propones hacer eso? Quiero decir, ¡veo gente todos los días matando duendes por aquí!",
        ["We're mobilising people and we're starting our own society...cleaning out the caves once inhabited by these foul creatures and defending them so that they can never again shelter sub-human species."] = "Estamos movilizando gente y estamos iniciando nuestra propia sociedad... limpiando las cuevas que alguna vez estuvieron habitadas por estas repugnantes criaturas y defendiéndolas para que nunca más puedan albergar especies subhumanas.",
        ["That sounds kind of strange, but, hey, it's your choice."] = "Eso suena un poco extraño, pero bueno, es tu elección.",
        ["Who are you and what do you do here?"] = "¿Quién eres y qué haces aquí?",
        ["My name is Johanhus and I lead these glorious people on a courageous mission called 'Humans Against Monsters'. We mean to make this land free of monsters, so that we can all live in peace."] = "Mi nombre es Johanhus y dirijo a estas gloriosas personas en una valiente misión llamada 'Humanos contra monstruos'. Queremos hacer que esta tierra esté libre de monstruos, para que todos podamos vivir en paz.",
        ["Okay, thanks."] = "Está bien, gracias.",
        ["Sad news, brother. Sigmund’s group has been destroyed by a goblin attack."] = "Triste noticia, hermano. El grupo de Sigmund ha sido destruido por un ataque de duendes.",
        ["This just goes to show the danger of taking action directly… All that Sigmund’s attacks achieved was getting some good humans killed."] = "Esto sólo sirve para mostrar el peligro de tomar medidas directamente... Todo lo que lograron los ataques de Sigmund fue matar a algunos buenos humanos.",
        ["Besides, the cave goblins aren’t much of a threat. They may not be human, but they’re no worse than the dwarves or gnomes. From now on, we’ll leave them alone, and focus on occupying caves and lobbying the government."] = "Además, los duendes de las cavernas no son una gran amenaza. Puede que no sean humanos, pero no son peores que los enanos o los gnomos. De ahora en adelante, los dejaremos en paz y nos concentraremos en ocupar cuevas y presionar al gobierno.",
    },
    ["Johanna"] = {
        ["Barrel making is just the thing for all you smithies."] = "La fabricación de barriles es ideal para todos los herreros.",
        ["Do you have the stomach for our race course?"] = "¿Tienes estómago para nuestro circuito de carreras?",
        ["Join our dancers and learn some new moves."] = "Únete a nuestros bailarines y aprende algunos movimientos nuevos.",
        ["NovtumberFest is open! It is time for revelry and sausages!"] = "¡NovtumberFest está abierto! ¡Es hora de juerga y salchichas!",
        ["Practice your glass blowing by making steins."] = "Practica cómo soplar vidrio haciendo jarras.",
        ["Take part in the Bar Crawl to earn prismatic lamps."] = "Participa en el Bar Crawl para ganar lámparas prismáticas.",
        ["Talk to me if you haven't yet got your Bar Crawl card."] = "Habla conmigo si aún no tienes tu tarjeta Bar Crawl.",
        ["Test your aim at the Archery Targets."] = "Pon a prueba tu puntería en los objetivos de tiro con arco.",
        ["Try hopping into an open portal for instant travel."] = "Intente ingresar a un portal abierto para viajar instantáneamente.",
        ["Welcome to NovtumberFest!"] = "¡Bienvenido a NovtumberFest!",
        ["You are missing a Bar Crawl card. Would you like a new one?"] = "Te falta una tarjeta de rastreo de bares. ¿Quieres uno nuevo?",
        ["Yes."] = "Sí.",
        ["A bar crawl card has been added to your inventory."] = "Se ha agregado una tarjeta de rastreo de bares a su inventario.",
        ["You do not have any space for a bar crawl card at the moment."] = "No tienes espacio para una tarjeta de rastreo de bares en este momento.",
        ["Select an option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["Hello there, I'm Johanna, head of this merry rabble of people who have come to celebrate NovtumberFest!"] = "Hola, soy Johanna, jefe de esta alegre chusma de personas que han venido a celebrar NovtumberFest.",
        ["What is NovtumberFest?"] = "¿Qué es NovtumberFest?",
        ["It's a celebration! A chance for people to come together and just relax and have a good time."] = "¡Es una celebración! Una oportunidad para que la gente se reúna, se relaje y pase un buen rato.",
        ["So it's a place to talk and unwind?"] = "Entonces, ¿es un lugar para hablar y relajarse?",
        ["Well, we know that's not everyone's idea of fun, so we've added a few games and such for you to try while you are here."] = "Bueno, sabemos que esa no es la idea de diversión que todos tienen, por eso hemos agregado algunos juegos y cosas así para que los pruebes mientras estás aquí.",
        ["There are all sorts of things for you to try your hand at."] = "Hay todo tipo de cosas que puedes probar.",
        ["Just roll up to an activity and give it a go!"] = "¡Simplemente acércate a una actividad y pruébala!",
        ["How long will you be here for?"] = "¿Cuánto tiempo estarás aquí?",
        ["We're going to be here for about 4 weeks, so plenty of time to have a go at everything."] = "Estaremos aquí aproximadamente 4 semanas, así que tendremos tiempo de sobra para probarlo todo.",
        ["What is there to do at NovtumberFest?"] = "¿Qué se puede hacer en NovtumberFest?",
        ["Roaming events."] = "Eventos itinerantes.",
        ["We've sent out our cart to travel around Gielinor to spread word of our little get-together."] = "Hemos enviado nuestro carrito para viajar por Gielinor para difundir nuestra pequeña reunión.",
        ["However, the driver is known to get into the occasional spot of trouble."] = "Sin embargo, se sabe que el conductor se mete en problemas ocasionales.",
        ["If you see him out and about could you check on him and make sure he's safe?"] = "Si lo ves por ahí, ¿podrías controlarlo y asegurarte de que está a salvo?",
        ["And if he's not, help him out of whatever trouble he's got in to."] = "Y si no es así, ayúdalo a salir de cualquier problema en el que se haya metido.",
        ["So you want me to take care of him?"] = "¿Entonces quieres que lo cuide?",
        ["Oh, he's not that bad, but he does sometimes need a nudge in the right direction."] = "Oh, no es tan malo, pero a veces necesita un empujón en la dirección correcta.",
        ["He's always generous to those who help him out, though."] = "Sin embargo, siempre es generoso con quienes lo ayudan.",
        ["Cooking sausages."] = "Salchichas Cooking.",
        ["The perfect thing to go with a cold drink is a nice meaty sausage."] = "Lo perfecto para acompañar una bebida fría es una rica salchicha con carne.",
        ["We have only the best sausages at NovtumberFest. Jakob is very particular."] = "Solo tenemos las mejores salchichas en NovtumberFest. Jakob es muy particular.",
        ["Have a go at cooking some for yourself on the grills."] = "Intenta cocinar algo tú mismo en las parrillas.",
        ["Just follow your nose and you'll find your way there."] = "Simplemente sigue tu olfato y encontrarás el camino hasta allí.",
        ["A little more intensive this one."] = "Este es un poco más intensivo.",
        ["You too can experience what it is like to be a bar person on a very, very busy shift."] = "Tú también puedes experimentar lo que es ser un bar en un turno muy, muy ocupado.",
        ["Try to serve all of the customers that you can and get rewarded for your hard work."] = "Intente atender a todos los clientes que pueda y obtenga recompensas por su arduo trabajo.",
        ["I'll warn you - it won't be easy, but it should be fun."] = "Te lo advierto: no será fácil, pero debería ser divertido.",
        ["More."] = "Más.",
        ["Archery targets."] = "Dianas de tiro con arco.",
        ["Test your aim! Nice and simple this one."] = "¡Pon a prueba tu puntería! Bonito y sencillo este.",
        ["Just pick your target and fire away at it with arrows."] = "Simplemente elige tu objetivo y dispárale con flechas.",
        ["Just imagine the target is someone you don't like - always cheers me up no end."] = "Imagínate que el objetivo es alguien que no te agrada; siempre me alegra muchísimo.",
        ["NovtumberFest racing."] = "Carreras del NovtumberFest.",
        ["A lovely little racetrack inside our freezer-tent."] = "Una pequeña y encantadora pista de carreras dentro de nuestra tienda congeladora.",
        ["It's a bit slippery, but that makes it all the more fun."] = "Es un poco resbaladizo, pero eso lo hace aún más divertido.",
        ["Just try to stay up on your feet!"] = "¡Intenta mantenerte de pie!",
        ["Gathering hops."] = "Recogiendo lúpulo.",
        ["To keep the drink flowing we need a good supply of hops."] = "Para que la bebida siga fluyendo necesitamos un buen suministro de lúpulo.",
        ["You should be able to find lots of hops growing around the crater."] = "Deberías poder encontrar muchos lúpulos creciendo alrededor del cráter.",
        ["If you want to help you can harvest some and then deposit them in the hops crate, over by the glassblowing area."] = "Si quieres ayudar, puedes cosechar un poco y luego depositarlos en la caja de lúpulo, junto al área de soplado de vidrio.",
        ["Crafting steins."] = "Jarras Crafting.",
        ["Moritz is our man in charge of keeping our supply of steins up for our drinks."] = "Moritz es nuestro hombre a cargo de mantener nuestro suministro de jarras para nuestras bebidas.",
        ["A remarkable amount of them get broken during the festivities."] = "Una cantidad notable de ellos se rompen durante las festividades.",
        ["If you head over to the furnace he'll set you up with the equipment you need."] = "Si te diriges al horno, él te proporcionará el equipo que necesitas.",
        ["Making barrels."] = "Fabricación de barriles.",
        ["We can never have too many barrels. We always keep losing some."] = "Nunca podemos tener demasiados barriles. Siempre seguimos perdiendo algo.",
        ["I know the driver keeps taking some out and about round Gielinor, but he never seems to return with a full cart-full."] = "Sé que el conductor sigue sacando algo alrededor de Gielinor, pero parece que nunca regresa con el carrito lleno.",
        ["If you want to help out with making us more go talk to Lukas by his workbench."] = "Si quieres ayudarnos a hacer más, habla con Lukas junto a su mesa de trabajo.",
        ["Deedit's wolpertinger experiment."] = "El experimento Wolpertinger de Deedit.",
        ["Ah, yes. The wizard. He came to us and asked if we would mind helping him out."] = "Ah, sí. El mago. Vino a nosotros y nos preguntó si nos importaría ayudarlo.",
        ["I didn't expect it to cause such a big disturbance though."] = "Sin embargo, no esperaba que causara tal alboroto.",
        ["Oh well, he seems to be keeping things under control, just about."] = "Oh, bueno, parece estar manteniendo las cosas bajo control, más o menos.",
        ["Probably best to go talk to Wizard Deedit yourself for more information on the experiment though."] = "Probablemente sea mejor hablar con Wizard Deedit usted mismo para obtener más información sobre el experimento.",
        ["Dancing."] = "Bailando.",
        ["There is no more lovely a way to display your joy at the world around you than with a dance."] = "No hay manera más hermosa de mostrar tu alegría al mundo que te rodea que con un baile.",
        ["Join Mila and Elias on the tables and show everyone how happy you are."] = "Únete a Mila y Elias en las mesas y muestra a todos lo feliz que eres.",
        ["Carousel."] = "Carrusel.",
        ["The centrepiece of our little celebration."] = "La pieza central de nuestra pequeña celebración.",
        ["Isn't it delightful? I could just watch it go round and round for hours."] = "¿No es delicioso? Podría verlo girar y girar durante horas.",
        ["Hop on and give it a whirl, it is so much fun."] = "Súbete y pruébalo, es muy divertido.",
        ["Bar Crawl."] = "Rastreo de bares.",
        ["Linus' shop."] = "Tienda Linus.",
        ["The lovely Linus. He's the person to go for any cosmetics you might be looking for."] = "La encantadora Linus. Es la persona indicada para cualquier cosmético que estés buscando.",
        ["All of the cosmetics for sale in Linus' shop are also available as drops from doing the activities."] = "Todos los cosméticos a la venta en la tienda de Linus también están disponibles como obsequios al realizar las actividades.",
        ["Portals."] = "Portales.",
        ["Portals seem to be all the rage at these kinds of gatherings, so we made sure that we had some too."] = "Los portales parecen estar de moda en este tipo de reuniones, así que nos aseguramos de tener algunos también.",
        ["They're really handy for zipping around the world."] = "Son muy útiles para viajar por el mundo.",
        ["Leni will be able to keep you up to date with which portals are active."] = "Leni podrá mantenerlo actualizado sobre qué portales están activos.",
        ["Of course, they light up when they can be used, so you could just look out for the lights."] = "Por supuesto, se iluminan cuando se pueden usar, así que puedes simplemente estar atento a las luces.",
        ["Ask about something else."] = "Pregunta por otra cosa.",
        ["Tell me about the bar crawl."] = "Cuéntame sobre el recorrido por los bares.",
        ["We've set up a little bar crawl around the world to help celebrate this NovtumberFest."] = "Hemos organizado un pequeño recorrido por bares por todo el mundo para ayudar a celebrar este NovtumberFest.",
        ["I can give you a card with a list of bars on and what drink to purchase at each."] = "Puedo darte una tarjeta con una lista de bares y qué bebida comprar en cada uno.",
        ["There are 18 different tasks to complete. One will be unlocked for each of the first 18 days of NovtumberFest."] = "Hay 18 tareas diferentes para completar. Se desbloqueará uno para cada uno de los primeros 18 días de NovtumberFest.",
        ["This leaves you with the remaining time to collect all of the drinks on your card."] = "Esto te deja el tiempo restante para recoger todas las bebidas de tu tarjeta.",
        ["Ok, that makes sense. What do I get for doing the tasks?"] = "Ok, eso tiene sentido. ¿Qué obtengo por realizar las tareas?",
        ["You will get a lamp for completing each task, and then two lamps for completing the entire card."] = "Recibirás una lámpara por completar cada tarea y luego dos lámparas por completar la tarjeta completa.",
        ["There are two different cards. One is the standard card, and then we have an advanced version."] = "Hay dos cartas diferentes. Una es la tarjeta estándar y luego tenemos una versión avanzada.",
        ["The standard card only covers bars that are in the F2P world. The rewards for this are small lamps for each task and two medium lamps on card completion."] = "La tarjeta estándar solo cubre bares que están en el mundo F2P. La recompensa por esto son lámparas pequeñas por cada tarea y dos lámparas medianas al completar la tarjeta.",
        ["The advanced card covers members-only bars and some of those will require certain quests to be completed. The rewards for this card are small lamps for each task and two large lamps on card completion."] = "La tarjeta avanzada cubre barras exclusivas para miembros y algunas de ellas requerirán que se completen ciertas misiones. Las recompensas por esta tarjeta son lámparas pequeñas por cada tarea y dos lámparas grandes al completar la tarjeta.",
        ["Once you choose which card you would like you will NOT be able to change your mind."] = "Una vez que elijas qué tarjeta quieres, NO podrás cambiar de opinión.",
        ["As long as you complete the card before NovtumberFest finishes it doesn't matter when you start your card."] = "Siempre que complete la tarjeta antes de que finalice NovtumberFest, no importa cuándo comience su tarjeta.",
        ["You can wait until all of the tasks are revealed before choosing which type of card to take."] = "Puedes esperar hasta que se revelen todas las tareas antes de elegir qué tipo de tarjeta tomar.",
        ["What kind of card would you like?"] = "¿Qué tipo de tarjeta te gustaría?",
        ["Standard."] = "Estándar.",
        ["Advanced."] = "Avanzado.",
        ["An advanced bar crawl card has been added to your inventory."] = "Se ha agregado una tarjeta de rastreo de bares avanzado a su inventario.",
        ["I'll make my mind up later."] = "Me decidiré más tarde.",
        ["Now you have your bar crawl card a different task will be unlocked each day.{{Sic}}"] = "Ahora que tienes tu tarjeta de rastreo de bares, se desbloqueará una tarea diferente cada día.{{Sic}}",
        ["You have from the day that is is unlocked until the end of NovtumberFest to complete the task."] = "Tienes desde el día en que se desbloquea hasta el final de NovtumberFest para completar la tarea.",
        ["This will give you an XP lamp per task completed."] = "Esto te dará una lámpara de XP por cada tarea completada.",
        ["This means you can wait until all tasks are unlocked before starting your crawl, and do it all in one go."] = "Esto significa que puedes esperar hasta que todas las tareas estén desbloqueadas antes de comenzar a rastrear y hacerlo todo de una vez.",
        ["You must complete the task before the end of the NovtumberFest though!"] = "¡Debes completar la tarea antes de que finalice el NovtumberFest!",
        ["If you complete the whole card you will receive an addition two XP lamps as reward."] = "Si completas la tarjeta completa, recibirás dos lámparas XP adicionales como recompensa.",
        ["Well done on completing the bar crawl. May all of your future journeys around Gielinor be as fun!"] = "Enhorabuena por completar el rastreo de bares. ¡Que todos tus viajes futuros por Gielinor sean igual de divertidos!",
        ["Bye."] = "Adiós.",
        ["To your health!"] = "¡A tu salud!",
        ["You need to complete one task on the bar crawl."] = "Debes completar una tarea en el rastreo de barras.",
        ["You need to throw some sausages on the grills."] = "Hay que echar unas salchichas a las parrillas.",
        ["You need to craft a stein."] = "Necesitas elaborar una jarra.",
        ["You need to help create barrels for the festival."] = "Necesitas ayudar a crear barriles para el festival.",
        ["You need to take part in a round of kegger."] = "Necesitas participar en una ronda de barril.",
        ["You need to take your shot over at the Archery area."] = "Debes disparar en el área de tiro con arco.",
        ["You need to gather some hops from around the crater."] = "Necesitas recolectar algunos saltos alrededor del cráter.",
        ["You need to help Wizard Deedit with his wolpertinger issues."] = "Necesitas ayudar a Wizard Deedit con sus problemas con el wolpertinger.",
        ["You need to talk to Jakob, who is manning the cooking grills."] = "Debes hablar con Jakob, quien se encarga de las parrillas.",
        ["You need to talk to Friedrich, over by the Archery area."] = "Necesitas hablar con Friedrich, cerca del área de tiro con arco.",
        ["You need to talk to Klara, stood by the portal for the racing arena."] = "Necesitas hablar con Klara, que se encuentra junto al portal del campo de carreras.",
        ["You need to talk to Marta, probably next to one of the crops of hops around the crater."] = "Necesitas hablar con Marta, probablemente al lado de uno de los cultivos de lúpulo alrededor del cráter.",
        ["You need to talk to Moritz, follow the smell of molten glass to the stein making area."] = "Necesitas hablar con Moritz, sigue el olor a vidrio fundido hasta el área de fabricación de jarras.",
        ["You need to talk to Lukas, he'll be busy making barrels."] = "Necesitas hablar con Lukas, estará ocupado fabricando barriles.",
        ["You need to talk to Elias, one of our spectacular dancers."] = "Necesitas hablar con Elias, uno de nuestros espectaculares bailarines.",
        ["You need to talk to Mila, one of our spectacular dancers."] = "Necesitas hablar con Mila, uno de nuestros espectaculares bailarines.",
        ["You need to talk to Jonas, the host of the kegger area."] = "Necesitas hablar con Jonas, el anfitrión del área de barriles.",
        ["You need to talk to Linus, the resident vendor for NovtumberFest."] = "Debes hablar con Linus, el proveedor residente de NovtumberFest.",
        ["You need to talk to Leni, who will be keeping the portals in check."] = "Debes hablar con Leni, quien mantendrá los portales bajo control.",
        ["You have already unlocked the NovtumberFest title."] = "Ya has desbloqueado el título NovtumberFest.",
    },
    ["John (Slime is of the Essence)"] = {
        ["Where did it come from?"] = "¿De dónde vino?",
        ["I hear it came from the well. Hey, that's a cute dog! Does he have a name?"] = "He oído que vino del pozo. ¡Oye, qué lindo perro! ¿Tiene un nombre?",
        ["... Okay."] = "... Está bien.",
        ["<nowiki>*</nowiki>Dog is barking beside the well<nowiki>*</nowiki>"] = "<nowiki>*</nowiki>El perro ladra junto al pozo<nowiki>*</nowiki>",
        ["What's that boy? Joey fell down the well!?"] = "¿Qué es ese chico? ¿¡Joey se cayó al pozo!?",
        ["... How on Gielinor did that happen?"] = "... ¿Cómo fue que Gielinor sucedió eso?",
        ["He probably lost his glasses. And without them he just didn't see well."] = "Probablemente perdió sus gafas. Y sin ellos simplemente no veía bien.",
        ["Dog. Stay."] = "Perro. Permanecer.",
        ["Well, that's it over."] = "Bueno, se acabó.",
        ["It sure is!"] = "¡Seguro que lo es!",
        ["John looks down to Dog"] = "John mira hacia abajo a Perro",
        ["It's okay. Let's go home."] = "Está bien. Vámonos a casa.",
        ["Dog barks happily"] = "perro ladra alegremente",
    },
    ["John"] = {
        ["Where did it come from?"] = "¿De dónde vino?",
        ["I hear it came from the well. Hey, that's a cute dog! Does he have a name?"] = "He oído que vino del pozo. ¡Oye, qué lindo perro! ¿Tiene un nombre?",
        ["... Okay."] = "... Está bien.",
        ["<nowiki>*</nowiki>Dog is barking beside the well<nowiki>*</nowiki>"] = "<nowiki>*</nowiki>El perro ladra junto al pozo<nowiki>*</nowiki>",
        ["What's that boy? Joey fell down the well!?"] = "¿Qué es ese chico? ¿¡Joey se cayó al pozo!?",
        ["... How on Gielinor did that happen?"] = "... ¿Cómo fue que Gielinor sucedió eso?",
        ["He probably lost his glasses. And without them he just didn't see well."] = "Probablemente perdió sus gafas. Y sin ellos simplemente no veía bien.",
        ["Dog. Stay."] = "Perro. Permanecer.",
        ["Well, that's it over."] = "Bueno, se acabó.",
        ["It sure is!"] = "¡Seguro que lo es!",
        ["John looks down to Dog"] = "John mira hacia abajo a Perro",
        ["It's okay. Let's go home."] = "Está bien. Vámonos a casa.",
        ["Dog barks happily"] = "perro ladra alegremente",
    },
    ["John Wyrd"] = {
        ["*When speaking to John Wyrd in Draynor Village.*"] = "*Al hablar con John Wyrd en Draynor Village.*",
        ["What are you doing?"] = "¿Qué estás haciendo?",
        ["Practicing my form. I'm having trouble gathering memories and Orla said this might help."] = "Practicando mi forma. Tengo problemas para reunir recuerdos y Orla dijo que esto podría ayudar.",
        ["I see."] = "Ya veo.",
        ["If you're new to divination you should speak to Orla. I still have a lot to learn."] = "Si eres nuevo en la adivinación, deberías hablar con Orla. Todavía tengo mucho que aprender.",
    },
    ["Johnathon"] = {
        ["I am so very tired... Leave me be... to rest..."] = "Estoy muy cansada... Déjame en paz... para descansar...",
        ["Hello again. My family now considers you a hero."] = "Hola de nuevo. Mi familia ahora te considera un héroe.",
        ["Your father tells me you can improve these gauntlets for me..."] = "Tu padre me dice que puedes mejorar estos guanteletes para mí...",
        ["And right he is at that. Although my skill with Death Rune magiks was not great enough to defeat Chronozon, I am adequately skilled at Chaos Rune magiks. If you give me your gauntlets I will bestow upon them some of my power, and make any bolt spells you wish to cast more effective."] = "Y tiene razón en eso. Aunque mi habilidad con las magias de las Runas de la Muerte no fue lo suficientemente grande como para derrotar a Chronozon, tengo habilidades adecuadas con las magias de las Runas del Caos. Si me das tus guanteletes, les otorgaré parte de mi poder y haré que cualquier hechizo de rayo que desees lanzar sea más efectivo.",
        ["Select an option"] = "Seleccione una opción",
        ["That sounds good to me."] = "Eso me suena bien.",
        ["That sounds good to me!"] = "¡Eso me parece bien!",
        ["Johnathon takes your gauntlets from you, and begins a low chant over them. You see them begin to glow and sparkle, before he returns them to you."] = "Johnathon te quita los guanteletes y comienza un canto bajo sobre ellos. Los ves comenzar a brillar y brillar, antes de que él te los devuelva.",
        ["I shall see what options your brothers can offer me first."] = "Primero veré qué opciones pueden ofrecerme tus hermanos.",
        ["I think I'll check my other options with your brothers before committing myself."] = "Creo que comprobaré mis otras opciones con tus hermanos antes de comprometerme.",
        ["I doubt they will offer anything as useful as my magical boost, but as you wish."] = "Dudo que ofrezcan algo tan útil como mi impulso mágico, pero como desees.",
        ["Maybe because… I am."] = "Quizás porque… lo soy.",
        ["Yes well... Is there anything I can help you with?"] = "Sí, bueno... ¿Hay algo en lo que pueda ayudarte?",
        ["Can you change my gauntlets for me?"] = "¿Puedes cambiar mis guanteletes por mí?",
        ["Can you change my gauntlets for me? {{anchor|change-gauntlets}}"] = "¿Puedes cambiarme los guanteletes? {{anchor|change-gauntlets}}",
        ["*(If the player has no gauntlets:)*"] = "*(Si el player no tiene guanteletes:)*",
        ["You don't have any gauntlets I can imbue."] = "No tienes ningún guantelete que pueda imbuirte.",
        ["*(If the player currently has chaos gauntlets in inventory:)*"] = "*(Si el player actualmente tiene guanteletes del caos en su inventario:)*",
        ["Your gauntlets are already imbued with my powers. You don't have any gauntlets I can imbue."] = "Tus guanteletes ya están imbuidos de mis poderes. No tienes ningún guantelete que pueda imbuirte.",
        ["*(If the player has the gauntlets:)*"] = "*(Si el player tiene los guanteletes:)*",
        ["Yes certainly, though it will cost you 25,000 coins?"] = "Sí, claro, aunque te costará 25.000 coins.",
        ["Great thanks!"] = "¡Muchas gracias!",
        ["*(If the player has at least 25,000 coins:)*"] = "*(Si el player tiene al menos 25,000 coins:)*",
        ["Your gauntlets are already imbued with my powers."] = "Tus guanteletes ya están imbuidos de mis poderes.",
        ["*(If the player has less than 25,000 coins:)*"] = "*(Si el player tiene menos de 25,000 coins:)*",
        ["Unfortunately you don't have enough coins on you, come back with 25,000 and I'll change those gauntlets for you."] = "Desafortunadamente no tienes suficiente coins contigo, regresa con 25,000 y te cambiaré esos guanteletes.",
        ["No that's ok thanks."] = "No, está bien, gracias.",
        ["*(After having the family gauntlets enchanted for the first time:)*"] = "*(Después de encantar los guanteletes familiares por primera vez :)*",
        ["Does your family own any more gauntlets?"] = "¿Tu familia posee más guanteletes?",
        ["Does your family own any more gauntlets? I really appreciate the skill and effort you and your brothers have put into those gauntlets, and to prove it, I would like to own one of each pair."] = "¿Tu familia posee más guanteletes? Realmente aprecio la habilidad y el esfuerzo que tú y tus hermanos habéis puesto en esos guanteletes y, para demostrarlo, me gustaría tener uno de cada par.",
        ["I own a pair my father gave me, but they are a family heirloom and I’m not supposed to part with them. However if my dad saw fit to give you his, I could be convinced."] = "Tengo un par que me regaló mi padre, pero son una reliquia familiar y se supone que no debo separarme de ellos. Sin embargo, si mi padre considerara oportuno darte el suyo, podría convencerme.",
        ["How much would you want for them?"] = "¿Cuánto pedirías por ellos?",
        ["1 million coins."] = "1 millón de coins.",
        ["I would like to buy them for 1 million."] = "Me gustaría comprarlos por 1 millón.",
        ["Are you sure? That's a lot of money!"] = "¿Estás seguro? ¡Eso es mucho dinero!",
        ["Yes!"] = "¡Sí!",
        ["I suppose not."] = "Supongo que no.",
        ["I suppose you had better keep them."] = "Supongo que será mejor que los guardes.",
        ["Thank you!"] = "¡Gracias!",
        ["No thanks."] = "No, gracias.",
    },
    ["Jokul"] = {
        ["Don't bother me."] = "No me molestes.",
        ["You are unusually helpful for an outerlander, [Fremennik name]."] = "Eres inusualmente útil para un extranjero, [Fremennik name].",
        ["Ehm, thanks... I guess."] = "Ehm, gracias... Supongo.",
    },
    ["Jonas"] = {
        ["Welcome to Kegger!"] = "¡Bienvenido a Kegger!",
        ["This is a game of skill. Can you keep up?"] = "Este es un juego de habilidad. ¿Puedes seguir el ritmo?",
        ["All you have to do is click on the taps to send drinks to the customers."] = "Todo lo que tienes que hacer es hacer clic en los grifos para enviar bebidas a los clientes.",
        ["You need to keep &nbsp;{{Sic}}your customers happy. If they get to the line without a drink they are going to get upset."] = "Debes mantener contentos a  {{Sic}}tus clientes. Si llegan a la fila sin beber, se enojarán.",
        ["Look out for faster customers as you get slicker with your serving."] = "Esté atento a los clientes más rápidos a medida que se vuelve más hábil con su servicio.",
        ["Click the entrance sign to Kegger to begin a game."] = "Haga clic en la señal de entrada a Kegger para comenzar un juego.",
    },
    ["Jones"] = {
        ["Hi, Jones."] = "Hola, Jones.",
        ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["Select an Option"] = "Selecciona una opción",
        ["Can we hunt the Thalassus again?"] = "¿Podremos volver a cazar el Thalassus?",
        ["Certainly. Let's go!"] = "Por supuesto. ¡Vamos!",
        ["Hold on a second, you can't take your follower with you."] = "Espera un segundo, no puedes llevarte a tu seguidor contigo.",
        ["It doesn't seem so. The Thalassus seems to have fled to another part of the sea; doubt we'll ever see it again. Luckily, no one seems to have realised, so I can keep selling my Miracle Thalassus Protection Cream."] = "No lo parece. El Talaso parece haber huido a otra parte del mar; Dudo que lo volvamos a ver. Por suerte, nadie parece haberse dado cuenta, así que puedo seguir vendiendo mi Crema Protectora Miracle Thalassus.",
        ["Those cast nets sound good!"] = "¡Esas redes suenan bien!",
        ["They are! Which type would you like?"] = "¡Lo son! ¿Qué tipo te gustaría?",
        ["Both, please!"] = "¡Ambos, por favor!",
        ["[Jones hands you the two cast nets.]"] = "[Jones te entrega las dos atarrayas.]",
        ["Use them wisely!"] = "¡Úsalos sabiamente!",
        ["Small, please!"] = "¡Pequeño, por favor!",
        ["[Jones hands you a small cast net.]"] = "[Jones te entrega una pequeña atarraya.]",
        ["Use it wisely!"] = "¡Úsalo sabiamente!",
        ["Big, please!"] = "¡Grande, por favor!",
        ["[Jones hands you a big cast net.]"] = "[Jones te entrega una gran atarraya.]",
        ["Actually, I changed my mind."] = "En realidad, cambié de opinión.",
        ["You said something about deposit boxes?"] = "¿Dijiste algo sobre las cajas de depósito?",
        ["Yes, they're all around the coastline. There's one near Eagles' Peak; in Tirannwn; down at Ape Atoll; near Brimhaven; a couple around the settlements in the Kharidian Desert; on Harmony Island; and along the River Salve."] = "Sí, están por toda la costa. Hay uno cerca de Eagles' Peak; en Tirannwn; abajo en Ape Atoll; cerca de Brimhaven; una pareja por los asentamientos en Kharidian Desert; en la isla Armonía; y a lo largo del río Salve.",
        ["You seem to get around a bit?"] = "¿Parece que te mueves un poco?",
        ["Around the coastlines I do. There's some good fishing to be done around the world."] = "Alrededor de las costas lo hago. Hay buena pesca que hacer en todo el mundo.",
        ["What's your cousin's real name?"] = "¿Cuál es el verdadero nombre de tu prima?",
        ["You mean what's 'The Guns' really called?"] = "¿Te refieres a cómo se llama realmente 'The Guns'?",
        ["Yeah, he wouldn't tell me."] = "Sí, no me lo dijo.",
        ["Listen closely; it's..."] = "Escuche atentamente; es...",
        ["Julian."] = "Julián.",
        ["Interesting..."] = "Interesante...",
        ["Actually, nothing."] = "En realidad, nada.",
        ["Fair enough!"] = "¡Es justo!",
    },
    ["Jonny the beard"] = {
        ["Jonny the beard is not interested in talking."] = "Jonny the beard no está interesado en hablar.",
        ["I'd give my left arm to join your band."] = "Daría mi brazo izquierdo por unirme a tu banda.",
        ["Pong, he's back again."] = "Pong, ha vuelto.",
        ["Tell him we don't want groupies."] = "Dile que no queremos groupies.",
        ["I just want to be Jonny the Bard! <br>I play a mean flute!"] = "¡Solo quiero ser Jonny el Bardo! <br>I ¡toco una flauta mala!",
        ["My dreams of being Jonny the Bard are over. <br> You can't play a flute wit' one arm."] = "Mis sueños de ser Jonny el Bardo se acabaron. <br> No puedes tocar la flauta con un solo brazo.",
        ["Jonny the Bard?"] = "¿Jonny el Bardo?",
        ["All my life - and zombie life - I been dreamin' of playing in taverns."] = "Toda mi vida, y mi vida zombie, he soñado con jugar en tabernas.",
        ["I were gonna play the flute like a demon, I tells ya. <br>Ne'er mind. Back to a life of crime..."] = "Iba a tocar la flauta como un demonio, te lo dije. <br>No importa. De vuelta a una vida de crimen...",
        ["A pox on Katrine and her recruitment process.<br>One of her Black Arm initiates beat me up and stole my arm."] = "Una viruela en Katrine y su proceso de reclutamiento.<br>Uno de sus iniciados de Black Arm me golpeó y robó my arm.",
    },
    ["Jorral"] = {
        ["Why is it that whenever that enchanted key re-appears, you soon come visiting?"] = "¿Por qué cada vez que esa llave encantada reaparece, pronto vienes de visita?",
        ["Select an option"] = "Selecciona una opción",
        ["How's the archaeology going?"] = "¿Cómo va la arqueología?",
        ["Good. I'm looking more into the background of that enchanted key; hopefully, we'll be able to time travel with it again in future."] = "Bien. Estoy investigando más el trasfondo de esa llave encantada; Con suerte, podremos viajar en el tiempo con él nuevamente en el futuro.",
        ["Don't you mean the past?"] = "¿No te refieres al pasado?",
        ["Yes, travel to the past, in our future. I hadn't even considered trying to travel into the future!"] = "Sí, viajar al pasado, a nuestro futuro. ¡Ni siquiera había considerado intentar viajar al futuro!",
        ["Could I have the key back?"] = "¿Me podrían devolver la llave?",
        ["Sure, but it'll cost you! 6,000 coins!"] = "Claro, ¡pero te costará! ¡6.000 coins!",
        ["6,000? Seems fair!"] = "¿6.000? ¡Parece justo!",
        ["Here you go then."] = "Aquí tienes entonces.",
        ["I'm not that interested."] = "No estoy tan interesado.",
        ["I suppose you'll be needing this."] = "Supongo que necesitarás esto.",
        ["The key? But how...what...why?"] = "¿La clave? Pero ¿cómo... qué... por qué?",
        ["I think you should take better care of it in the future."] = "Creo que deberías cuidarlo mejor en el futuro.",
    },
    ["Jorzik"] = {
        ["*When speaking to Jorzik at the Blast Furnace in Keldagrim.*"] = "*Al hablar con Jorzik en el Alto Horno en Keldagrim.*",
        ["Do you want to trade?"] = "¿Quieres comerciar?",
        ["Select an option"] = "Seleccione una opción",
        ["What are you selling?"] = "¿Qué estás vendiendo?",
        ["The finest smiths from all over Gielinor come here to work, and I buy the fruit of their craft. Armour made from the strongest metals!"] = "Los mejores herreros de todo Gielinor vienen aquí a trabajar y yo compro el fruto de su oficio. ¡Armadura hecha de los metales más fuertes!",
        ["Let's have a look, then."] = "Entonces, echemos un vistazo.",
        ["No, thanks."] = "No, gracias.",
        ["You just don't appreciate the beauty of fine metalwork."] = "Simplemente no se aprecia la belleza del trabajo en metal fino.",
    },
    ["Joseph"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Joshua"] = {
        ["Yeah? What you want?"] = "¿Sí? ¿Lo que quieras?",
        ["Um... nothing really..."] = "Um... nada realmente...",
        ["Quit bugging me then, [dude/doll]! I got me some fish to catch!"] = "¡Entonces deja de molestarme, [dude/doll]! ¡Tengo algo de pescado para pescar!",
        ["Can I fish here instead of you?"] = "¿Puedo pescar aquí en lugar de ti?",
        ["Nuh uh [dude/doll]. Less talk, more fishing!"] = "No, eh, [dude/doll]. ¡Menos charla, más pesca!",
        ["Do you have any tips for me?"] = "¿Tienes algún consejo para mí?",
        ["[Dude/Doll]! Why should I help you? You like, might beat me! I'm not giving away my secrets like that dude Grampa Jack does!"] = "¡[Dude/Doll]! ¿Por qué debería ayudarte? ¡Si te gusta, podrías vencerme! ¡No voy a revelar mis secretos como lo hace ese tipo, el abuelo Jack!",
        ["Who's Grampa Jack?"] = "¿Quién es el abuelo Jack?",
        ["Who's Grampa Jack [he/she] says! He won this competition four years in a row! He lives in the house just outside the gate."] = "¿Quién es el abuelo Jack [he/she]? ¡Ganó esta competencia cuatro años seguidos! Vive en la casa justo afuera de la puerta.",
    },
    ["Jossik"] = {
        ["Hello again adventurer. What brings you this way?"] = "Hola de nuevo aventurero. ¿Qué te trae por este camino?",
        ["Choose an option:"] = "Elige una opción:",
        ["Can I see your wares?"] = "¿Puedo ver tus productos?",
        ["Sure thing! I think you'll agree, my prices are remarkable."] = "¡Claro! Creo que estarás de acuerdo, mis precios son notables.",
        ["Have you found any new prayer books?"] = "¿Has encontrado algún libro de oraciones nuevo?",
        ["cond=If the Blood Runs Deep quest has been completed:"] = "cond=Si la misión Blood Runs Deep se ha completado:",
        ["I think I may have found your uncle."] = "Creo que pude haber encontrado a tu tío.",
        ["Really? Where is he? How is he?"] = "¿En serio? ¿Dónde está? ¿Cómo está él?",
        ["Well, he was being looked after by the mages in Lunar Isle but, when he got better, he wanted to leave, so they had to let him go."] = "Bueno, los magos de Lunar Isle lo estaban cuidando pero, cuando mejoró, quiso irse, así que tuvieron que dejarlo ir.",
        ["He just left? Oh my... Well, now I'll never find him."] = "¿Se acaba de ir? Oh Dios... Bueno, ahora nunca lo encontraré.",
        ["At least we know he's alive and well. I'm sure he'll show up sooner or later."] = "Al menos sabemos que está vivo y bien. Estoy seguro de que aparecerá tarde o temprano.",
        ["Funnily enough I have! I found these [number] books in caskets just the other day! I'll sell one to you for 5000 coins: what do you say?"] = "¡Curiosamente sí! ¡Encontré estos libros [número] en ataúdes el otro día! Te vendo uno por 5000 coins: ¿qué dices?",
        ["Select an option"] = "Selecciona una opción",
        ["Buy a book"] = "comprar un libro",
        ["Here you go!"] = "¡Aquí tienes!",
        ["Don't buy anything"] = "no compres nada",
        ["No thanks."] = "No, gracias.",
        ["Okay! Suit yourself."] = "¡Está bien! Haz lo que quieras.",
        ["Nope. Sorry, adventurer, I guess you've found them all! I'll let you know if any new ones show up, though."] = "No. Lo siento, aventurero, ¡supongo que los has encontrado todos! Sin embargo, te avisaré si aparece alguno nuevo.",
        ["As a matter of fact, I did! This book washed up on the beach not so long ago, I recognised it as yours immediately! Here you go!"] = "¡De hecho, lo hice! Este libro apareció en la playa no hace mucho, ¡lo reconocí como tuyo inmediatamente! ¡Aquí tienes!",
    },
    ["Jukat"] = {
        ["*When speaking to Jukat at the Zanaris marketplace.*"] = "*Al hablar con Jukat en el mercado Zanaris.*",
        ["Dragon swords! Here, dragon swords! Straight from Frenaskrae!"] = "¡Espadas de dragón! ¡Aquí, espadas de dragón! ¡Directamente desde Frenaskrae!",
        ["Select an option"] = "Seleccione una opción",
        ["Yes, please."] = "Sí, por favor.",
        ["Yes, please!"] = "¡Sí, por favor!",
        ["No thanks, I'm just browsing."] = "No, gracias, solo estoy navegando.",
    },
    ["Julienne, Emissary of Saradomin"] = {
        ["I am Julienne. I have been a priestess of Saradomin for several years, and I am here to act as his emissary. I would be happy to help you understand the wisdom of Saradomin, if you have questions. Also, you can declare your allegiance to Saradomin. If you do so, I may have some work for your."] = "Soy Juliana. He sido sacerdotisa de Saradomin durante varios años y estoy aquí para actuar como su emisaria. Estaré encantado de ayudarle a comprender la sabiduría de Saradomin, si tiene preguntas. Además, puedes declarar tu lealtad a Saradomin. Si lo haces, puede que tenga algo de trabajo para ti.",
        ["*Can you tell me about Saradomin?*"] = "*¿Puedes contarme sobre Saradomin?*",
        ["Can you tell me about Saradomin?"] = "¿Puedes hablarme de Saradomin?",
        ["What do you want to know about Sardomin?"] = "¿Qué quieres saber sobre Sardomin?",
        ["*Who is Saradomin?*"] = "*¿Quién es Saradomin?*",
        ["**Player: :** Who is Saradomin?"] = "**Player: :** ¿Quién es Saradomin?",
        ["Saradomin is the great protector - the god of light and order. He is first among the gods. Saradomin has more followers than any other god on Gielinor, and he has returned to protect us from evil and chaos."] = "Saradomin es el gran protector, el dios de la luz y el orden. Es el primero entre los dioses. Saradomin tiene más seguidores que cualquier otro dios en Gielinor y ha regresado para protegernos del mal y el caos.",
        ["*Why should I follow Saradomin?*"] = "*¿Por qué debería seguir a Saradomin?*",
        ["**Player: :** Why should I follow Saradomin?"] = "**Player: :** ¿Por qué debería seguir a Saradomin?",
        ["Saradomin is the guardian of us all. Under his protection, you need never fear chaos or evil. Through the grace of Saradomin, we will all achieve peace and security."] = "Saradomin es el guardián de todos nosotros. Bajo su protección, nunca deberás temer al caos ni al mal. Gracias a Saradomin, todos lograremos la paz y la seguridad.",
        ["*What does Saradomin want?*"] = "*¿Qué quiere Saradomin?*",
        ["**Player: :** What does Saradomin want?"] = "**Player: :** ¿Qué quiere Saradomin?",
        ["Saradomin is the one true god. This is his world, and he will watch over us all. He wants us to be safe. He will banish all other gods, so we can live on his world in peace - and in his glory!"] = "Saradomin es el único dios verdadero. Este es su mundo y él velará por todos nosotros. Él quiere que estemos a salvo. Él desterrará a todos los demás dioses, para que podamos vivir en su mundo en paz... ¡y en su gloria!",
        ["*I want to declare my support for Saradomin!*"] = "*¡Quiero declarar mi apoyo a Saradomin!*",
        ["That’s wonderful! On behalf of Saradomin’s followers, I welcome you. Please, take this banner to show your support. I have a gift for you: a book of stories regarding the gods. Please, read it. Even in the misguided tenets of others, there is something to be learned through comparison. The book is not yet complete, however. When you complete some jobs I will give you more pages."] = "¡Eso es maravilloso! En nombre de los seguidores de Saradomin, les doy la bienvenida. Por favor, lleve este banner para mostrar su apoyo. Tengo un regalo para ti: un libro de historias sobre los dioses. Por favor, léelo. Incluso en los principios equivocados de otros, hay algo que aprender a través de la comparación. Sin embargo, el libro aún no está completo. Cuando completes algunos trabajos te daré más páginas.",
        ["Category:God Emissaries"] = "Categoría:God Emissaries",
    },
    ["Juna"] = {
        ["After completing the Tears of Guthix quest, players have the option to collect tears once a week. To do so, players must first tell Juna a story of their travels and adventures. Each story can be linked to a quest done in the past."] = "Después de completar la misión Tears of Guthix, los jugadores tienen la opción de recolectar lágrimas una vez a la semana. Para hacerlo, los jugadores primero deben contarle a Juna una historia de sus viajes y aventuras. Cada historia se puede vincular a una misión realizada en el pasado.",
        ["Note that these dialogues can be story or non-story related. Story-related dialogues are listed under the List of stories section, while the ones below are for dialogues not related to the stories."] = "Tenga en cuenta que estos diálogos pueden estar relacionados con una historia o no. Los diálogos relacionados con las historias se enumeran en la sección Lista de historias, mientras que los que aparecen a continuación son para diálogos no relacionados con las historias.",
        ["Tell me... a story..."] = "Cuéntame... una historia...",
        ["Choose an option"] = "Elige una opción:",
        ["Okay..."] = "Está bien...",
        ["You tell Juna some stories of your adventures."] = "Le cuentas a Juna algunas historias de tus aventuras.",
        ["*See the List of stories section below*"] = "*Consulta la sección Lista de historias a continuación*",
        ["Your stories have entertained me. I will let you into the cave for a short time."] = "Tus historias me han entretenido. Te dejaré entrar a la cueva por un corto tiempo.",
        ["I see you are not currently enlightened, but you have a light creature summoned, as well as a scroll it can use in your inventory."] = "Veo que actualmente no estás iluminado, pero tienes una criatura de luz invocada, así como un pergamino que puedes usar en tu inventario.",
        ["I see you are not currently enlightened, but you have a light creature summoned, and the light creature is holding a scroll it can use."] = "Veo que actualmente no estás iluminado, pero tienes una criatura de luz convocada y la criatura de luz sostiene un pergamino que puede usar.",
        ["I see you are not currently enlightened, but you have a both a light creature pouch, and a scroll it can use, in your inventory."] = "Veo que actualmente no estás iluminado, pero tienes en tu inventario una bolsa de criatura ligera y un pergamino que puedes usar.",
        ["Do you wish to collect the tears anyway?"] = "¿Quieres recoger las lágrimas de todos modos?",
        ["Yes, I understand that none of the tears I collect will be doubled."] = "Sí, entiendo que ninguna de las lágrimas que recoja se duplicará.",
        ["No thank you, I would like to cast enlightenment first."] = "No, gracias. Primero me gustaría transmitir la iluminación.",
        ["As you wish, Player."] = "Como desees, Player.",
        ["Collect as much as you can from the blue streams. If you let in water from the green streams, it will take away from the blue. For Guthix is god of balance, and balance lies in the juxtaposition of opposites."] = "Recoge todo lo que puedas de las corrientes azules. Si dejas entrar agua de los arroyos verdes, se la quitará a los azules. Porque Guthix es el dios del equilibrio, y el equilibrio reside en la yuxtaposición de los opuestos.",
        ["Your stories have entertained me. But I will not permit any adventurer to access the tears more than once a week. Come back in # days."] = "Tus historias me han entretenido. Pero no permitiré que ningún aventurero acceda a las lágrimas más de una vez por semana. Vuelve en # días.",
        ["Your stories have entertained me, but the creation of Armadyl that follows you will not enter my cave. Dismiss it and return to me."] = "Tus historias me han entretenido, pero la creación de Armadyl que te sigue no entrará en mi cueva. Deséchalo y regresa a mí.",
        ["How do I make the improved bowl?"] = "¿Cómo hago el cuenco mejorado?",
        ["A story?"] = "¿Una historia?",
        ["I have been waiting here for three thousand years, guarding the Tears of Guthix. I serve my master faithfully, but I am bored."] = "He estado esperando aquí durante tres mil años, guardando las Lágrimas de Guthix. Sirvo fielmente a mi amo, pero estoy aburrido.",
        ["An adventurer such as yourself must have many tales to tell. If you can entertain me, I will let you in the cave for a time."] = "Un aventurero como tú debe tener muchas historias que contar. Si puedes entretenerme, te dejaré entrar a la cueva por un tiempo.",
        ["The more I enjoy your story, the more time I will give you in the cave."] = "Cuanto más disfrute tu historia, más tiempo te daré en la cueva.",
        ["Then you can drink the power of balance, which will make you stronger in whatever area you are weakest."] = "Entonces podrás beber el poder del equilibrio, que te hará más fuerte en cualquier área en la que estés más débil.",
        ["Okay... (see the top)"] = "Está bien... (ver arriba)",
        ["Not now."] = "Ahora no.",
        ["What are the Tears of Guthix?"] = "¿Qué son las Lágrimas de Guthix?",
        ["The Third Age of the world was a time of great conflict, of destruction never seen before or since, when all the gods save Guthix warred for control."] = "La Tercera Edad del mundo fue una época de gran conflicto, de destrucción nunca vista antes ni después, cuando todos los dioses, excepto Guthix, lucharon por el control.",
        ["The colossal wyrms, of whom today's dragons are a pale reflection, turned all the sky to fire, while on the ground armies of foot soldiers - goblins and trolls and humans - filled the valleys and plains with blood."] = "Los colosales wyrms, de los cuales los dragones de hoy son un pálido reflejo, convirtieron todo el cielo en fuego, mientras que en tierra ejércitos de soldados de infantería (duendes, trolls y humanos) llenaron de sangre los valles y llanuras.",
        ["In the time the noise of the conflict woke Guthix from His deep slumber, and He rose and stood in the centre of the battlefield so the splendour of His wrath filled the world, and He called for the conflict to cease!"] = "En el momento en que el ruido del conflicto despertó a Guthix de Su profundo sueño, se levantó y se paró en el centro del campo de batalla para que el esplendor de Su ira llenara el mundo, ¡y pidió que cesara el conflicto!",
        ["Silence fell, for the gods knew that none could challenge the power of the mighty Guthix; for His power is that of nature itself, to which all other things are subject, in the end."] = "Se hizo el silencio, porque los dioses sabían que nadie podía desafiar el poder del poderoso Guthix; porque su poder es el de la naturaleza misma, a la que, en última instancia, están sujetas todas las demás cosas.",
        ["Guthix reclaimed that which had been stolen from Him, and went back underground to His sleep and continue to draw the world's power into Himself."] = "Guthix reclamó lo que le había sido robado, volvió a dormir bajo tierra y continuó atrayendo el poder del mundo hacia sí mismo.",
        ["But on His way into the depths of the earth He sat and rested in this cave; and, thinking of the battle-scarred desert that now streched from one side of His world to the other, He wept."] = "Pero en Su camino hacia las profundidades de la tierra, se sentó y descansó en esta cueva; y, pensando en el desierto marcado por la batalla que ahora se extendía de un lado a otro de Su mundo, lloró.",
        ["And so great was His sorrow, and so great was His life-giving power, that the rocks themselves began to weep with Him."] = "Y tan grande era Su dolor, y tan grande era Su poder vivificante, que las rocas mismas comenzaron a llorar con Él.",
        ["Later, Guthix noticed that the rocks continued to weep, and that their tears was infused with a small part of His power."] = "Más tarde, Guthix notó que las rocas seguían llorando y que sus lágrimas estaban impregnadas de una pequeña parte de Su poder.",
        ["So He set me, His servant, to guard the cave, and He entrusted me the task of judging who was and was not worthy to access the tears."] = "Entonces Él me puso a mí, Su sirviente, para custodiar la cueva, y me confió la tarea de juzgar quién era y quién no era digno de acceder a las lágrimas.",
        ["You tell me a story."] = "Cuéntame una historia.",
        ["Tell me about the Tears of Guthix. (see above)"] = "Háblame de las Lágrimas de Guthix. (ver arriba)",
        ["Tell me a new story."] = "Cuéntame una nueva historia.",
        ["I will tell you the story of the light-creatures."] = "Te contaré la historia de las criaturas de luz.",
        ["Myriad and beautiful were the creatures and civilizations of the early ages of the world. Gielinor was a work of art, shaped lovingly over the millennia by the creative mind of Guthix."] = "Innumerables y hermosas fueron las criaturas y civilizaciones de las primeras edades del mundo. Gielinor fue una obra de arte, moldeada con amor a lo largo de milenios por la mente creativa de Guthix.",
        ["Only the sturdiest races survived the God Wars, and even then by only abandoning their high culture and gearing the societies towards war. Of the more delicate races there is now no trace, and almost no memory."] = "Sólo las razas más resistentes sobrevivieron a las Guerras de Dios, e incluso entonces abandonaron su alta cultura y orientaron a las sociedades hacia la guerra. De las razas más delicadas ya no queda rastro, y casi ningún recuerdo.",
        ["One such race had bodies as fragile as snowflakes, yet they built crystal cities that stood for a thousand years."] = "Una de esas razas tenía cuerpos tan frágiles como los copos de nieve, pero construyeron ciudades de cristal que duraron mil años.",
        ["The wind would whisper through the spires and fill them with street harmonies, and the rising sun would shine through the precious gems that studded the towers and create inter plays of light as if rainbows were dancing."] = "El viento susurraría a través de las agujas y las llenaría con armonías callejeras, y el sol naciente brillaría a través de las gemas preciosas que tachonaban las torres y crearía juegos de luces como si los arcoíris estuvieran bailando.",
        ["Indeed, so marvellous was this light-show at it's height that the patterns of light themselves became alive, and the great flocks of luminous creatures rode along the gem-cast beams, each drawn to its own colour."] = "De hecho, tan maravilloso fue este espectáculo de luces en su apogeo que los propios patrones de luz cobraron vida, y las grandes bandadas de criaturas luminosas cabalgaban a lo largo de los rayos de gemas, cada una atraída por su propio color.",
        ["The creatures you see floating in this chasm are the last sorry remnants of that age. I do not know how they made their way here and survived to this time, but I am grateful for their company."] = "Las criaturas que ves flotando en este abismo son los últimos restos lamentables de esa época. No sé cómo llegaron hasta aquí y sobrevivieron hasta este momento, pero estoy agradecido por su compañía.",
        ["Not after the start of my vigil a party of goblins happened on my cave. They were the ugly brutes of the gods' armies, but their armour bore a faded patch where the symbol of a god had been removed."] = "No después del comienzo de mi vigilia, apareció un grupo de duendes en mi cueva. Eran los feos brutos de los ejércitos de los dioses, pero sus armaduras tenían un parche descolorido donde se había eliminado el símbolo de un dios.",
        ["They looked around hesitantly, squinting in the light of crude torches, but as soon as they saw me they raised their spears and charged."] = "Miraron a su alrededor vacilantes, entrecerrando los ojos a la luz de toscas antorchas, pero tan pronto como me vieron levantaron sus lanzas y cargaron.",
        ["No one may access the Tears of Guthix by force. I sent them tumbling into the chasm."] = "Nadie puede acceder a las Lágrimas de Guthix por la fuerza. Los envié al abismo.",
        ["Two hundred years later, another goblin found me. This one was unarmed, and although she was very wary I succeeded in engaging her in conversation."] = "Doscientos años después, otro duende me encontró. Esta estaba desarmada y, aunque estaba muy cautelosa, logré entablar conversación con ella.",
        ["Since then I have had many more visits from the descendants of those lost warriors, and over the centuries I have seen them change."] = "Desde entonces he recibido muchas más visitas de los descendientes de esos guerreros perdidos y, a lo largo de los siglos, los he visto cambiar.",
        ["They have become timid rather than aggressive, and I have seen the light of intelligence grow in their bulging eyes."] = "Se han vuelto más tímidos que agresivos, y he visto crecer la luz de la inteligencia en sus ojos saltones.",
        ["Their stories are repetitive and grim, of scraping a living out of the harsh rock through ingenuity and toil shaping it into a home."] = "Sus historias son repetitivas y sombrías, sobre cómo ganarse la vida a partir de la dura roca a través del ingenio y el trabajo duro para convertirla en un hogar.",
        ["I have followed the progress of their race, but their individual stories hold little interest for me."] = "He seguido el progreso de su carrera, pero sus historias individuales tienen poco interés para mí.",
        ["Tell me a...wait one moment."] = "Dime... espera un momento.",
        ["What's the matter?"] = "¿Qué pasa?",
        ["I feel that you possess great skill; great enough to gain the full power of the tears."] = "Siento que posees una gran habilidad; lo suficientemente grande como para obtener todo el poder de las lágrimas.",
        ["Use your great skill to make a more ornate bowl. The pattern will come to you as you work."] = "Usa tu gran habilidad para hacer un cuenco más adornado. El patrón te llegará a medida que trabajes.",
        ["Bring the bowl to me, and you can use it to collect the tears to gain the full power they hold."] = "Tráeme el cuenco y podrás usarlo para recoger las lágrimas y obtener todo el poder que contienen.",
        ["Now, tell me...a story..."] = "Ahora, cuéntame... una historia...",
        ["Select an Option"] = "Selecciona una opción",
        ["Leave to make the bowl."] = "Dejar hacer el bol.",
        ["Very well. Return soon..."] = "Muy bien. Vuelve pronto...",
        ["Keep talking."] = "Sigue hablando.",
        ["You have the bowl for me?"] = "¿Tienes el cuenco para mí?",
        ["I have it here."] = "Lo tengo aquí.",
        ["Very good. With this larger bowl you will gain ever greater benefit from the tears."] = "Muy bien. Con este cuenco más grande obtendrás un beneficio cada vez mayor de las lágrimas.",
        ["I will keep this bowl with me, and you may use it from now on to drink deeply of the tears."] = "Guardaré este cuenco conmigo y podrás usarlo de ahora en adelante para beber profundamente de las lágrimas.",
        ["Now, tell me a story..."] = "Ahora, cuéntame una historia...",
        ["I would like to talk about Guthix's death."] = "Me gustaría hablar sobre la muerte de Guthix.",
        ["I cannot say it is something I wish to think about."] = "No puedo decir que sea algo en lo que desee pensar.",
        ["Sorry Juna, but we cannot ignore it. I just wanted to ask some questions."] = "Lo siento Juna, pero no podemos ignorarlo. Sólo quería hacer algunas preguntas.",
        ["I'd like some advice about being a Guardian of Guthix."] = "Me gustaría recibir algún consejo sobre cómo ser un guardián de Guthix.",
        ["Guthix chose you as a Guardian because he could already see it in you."] = "Guthix te eligió como Guardián porque ya podía verlo en ti.",
        ["You were chosen to be one of us because you showed not only a great talent, but also an understanding of balance, and the potential to be much more."] = "Fuiste elegido para ser uno de nosotros porque demostraste no solo un gran talento, sino también una comprensión del equilibrio y el potencial para ser mucho más.",
        ["With Guthix's death, and the knowledge he imparted to you, he clearly intends us to become an army against the young gods."] = "Con la muerte de Guthix y el conocimiento que te impartió, claramente tiene la intención de que nos convirtamos en un ejército contra los dioses jóvenes.",
        ["You should think on what he told you; remember his intentions when giving you his power. He wants you to lead the defence of this world."] = "Deberías pensar en lo que te dijo; Recuerda sus intenciones al darte su poder. Él quiere que lideres la defensa de este mundo.",
        ["Surely the other Guardians can help? Where did they go?"] = "¿Seguramente los otros Guardianes pueden ayudar? ¿A dónde fueron?",
        ["Of course. We will be by your side whenever you need us, but in the mean time we must all continue our previous duties. I cannot leave these caves unattended, Death cannot abandon his role... Guthix may be gone, but that does not mean we should abandon our posts."] = "Por supuesto. Estaremos a tu lado siempre que nos necesites, pero mientras tanto todos debemos continuar con nuestras funciones anteriores. No puedo dejar estas cuevas desatendidas, la Muerte no puede abandonar su papel... Puede que Guthix se haya ido, pero eso no significa que debamos abandonar nuestros puestos.",
        ["What do you think will happen now?"] = "¿Qué crees que pasará ahora?",
        ["We have already seen it begin. Saradomin has already returned."] = "Ya lo hemos visto comenzar. Saradomin ya ha regresado.",
        ["The others will come. Nothing has changed, Player, they will be as determined and greedy as they were thousands of years ago."] = "Los demás vendrán. Nada ha cambiado, Player, serán tan decididos y codiciosos como lo fueron hace miles de años.",
        ["We are on the brink of another God Wars. If we do not act, the world will be ravaged. Guthix is not here to stop them, this time. It is up to us."] = "Estamos al borde de otra Guerra de Dioses. Si no actuamos, el mundo quedará devastado. Guthix no está aquí para detenerlos esta vez. Depende de nosotros.",
        ["How are you feeling?"] = "¿Cómo te sientes?",
        ["It is very difficult to speak about. I can't believe..."] = "Es muy difícil hablar de ello. No puedo creer...",
        ["I'm sorry, I'm not ready to discuss this with anyone. It's too painful."] = "Lo siento, no estoy listo para discutir esto con nadie. Es demasiado doloroso.",
        ["We have already seen it begin. Saradomin and Zamorak have already returned. Armadyl and Bandos have clashed, and the new God War has claimed its first divine victim."] = "Ya lo hemos visto comenzar. Saradomin y Zamorak ya regresaron. Armadyl y Bandos se han enfrentado y el nuevo Dios War ha reclamado su primera víctima divina.",
        ["More yet will come. Nothing has changed, player. They will be as determined and greedy as they were thousands of years ago."] = "Vendrán más. Nada ha cambiado, jugador. Serán tan decididos y codiciosos como lo fueron hace miles de años.",
        ["Select an option"] = "Selecciona una opción",
        ["I want to talk about Zanik and Bandos."] = "Quiero hablar sobre Zanik y Bandos.",
        ["My feelings on this matter have changed. Do you wish to know how I felt at the time, or how I feel in the light of the death of my lord Guthix?"] = "Mis sentimientos sobre este asunto han cambiado. ¿Quieres saber cómo me sentí en ese momento o cómo me siento ante la muerte de mi señor Guthix?",
        ["I want to know how you felt then."] = "Quiero saber cómo te sentiste entonces.",
        ["Player, I hope you realise the magnitude of your actions. In helping Zanik to drive off Bandos you have betrayed all the gods."] = "Player, espero que te des cuenta de la magnitud de tus acciones. Al ayudar a Zanik a expulsar a Bandos, has traicionado a todos los dioses.",
        ["I thought you and Zanik were friends."] = "Pensé que tú y Zanik eran amigos.",
        ["We were, but no more. I will never deal with that blasphemer again. She has done more than betray her god - she has betrayed all the gods."] = "Lo estábamos, pero ya no. Nunca volveré a tratar con ese blasfemo. Ha hecho más que traicionar a su dios: ha traicionado a todos los dioses.",
        ["What do you mean, betrayed all the gods?"] = "¿Qué quieres decir con traicionar a todos los dioses?",
        ["You betrayed the principle of the gods' sovereignty! Bandos brought the goblins to Gielinor, and so they are his rightful property. They have no more right to defy him than your own weapon has to strike at you. That was why Guthix allowed Zanik to be raised from the dead. It was not only Bandos's{{Sic}} interests at stake. In defying him you stood against all the gods."] = "¡Traicionaste el principio de la soberanía de los dioses! Bandos trajo los duendes a Gielinor, por lo que son su propiedad legítima. No tienen más derecho a desafiarlo que el que tu propia arma tiene a atacarte. Por eso Guthix permitió que Zanik resucitara de entre los muertos. No sólo estaban en juego los intereses de Bandos, {{Sic}}. Al desafiarlo te enfrentaste a todos los dioses.",
        ["It was still the right thing to do."] = "Aún así era lo correcto.",
        ["The will of the gods is the measure of what is right."] = "La voluntad de los dioses es la medida de lo que es correcto.",
        ["So I'm an enemy of the gods now?"] = "¿Entonces ahora soy un enemigo de los dioses?",
        ["No. I do not sense that about you. For whatever reason, Guthix does not wish to punish you. Perhaps he senses that you will serve the gods well in the future."] = "No. No siento eso en ti. Por alguna razón, Guthix no desea castigarte. Quizás sienta que servirás bien a los dioses en el futuro.",
        ["I don't like the sound of that."] = "No me gusta cómo suena eso.",
        ["What you want or do not want is of no consequence to the gods. In any case, Guthix still wishes me to deal with you. Will you tell me a story?"] = "Lo que quieras o no quieras no tiene importancia para los dioses. En cualquier caso, Guthix todavía desea que me ocupe de usted. ¿Me contarás una historia?",
        ["That's a relief."] = "Eso es un alivio.",
        ["I am glad to hear that you are still on the right path. In any case, Guthix still wishes me to deal with you. Will you tell me a story?"] = "Me alegra saber que todavía estás en el camino correcto. En cualquier caso, Guthix todavía desea que me ocupe de usted. ¿Me contarás una historia?",
        ["I want to know how you feel now."] = "Quiero saber cómo te sientes ahora.",
        ["I served Guthix for longer than most mortal dynasties exist. I spent most of that time alone, patiently fulfilling the task to which he assigned me. In that time, my thoughts and feelings became...twisted."] = "Serví a Guthix durante más tiempo del que existe la mayoría de las dinastías mortales. Pasé la mayor parte de ese tiempo solo, cumpliendo pacientemente la tarea que me asignó. En ese momento, mis pensamientos y sentimientos se volvieron... retorcidos.",
        ["For centuries, my only thought was love for my lord Guthix. I longed for him to return and bless me with his divine gaze, to tell me that I had been a good and faithful servant. I loved Guthix not because he was the most powerful or benevolent god - although he was both those things - but because he was my god and he had chosen me to be his servant."] = "Durante siglos, mi único pensamiento fue el amor por mi señor Guthix. Anhelaba que regresara y me bendijera con su mirada divina, para decirme que había sido un buen y fiel servidor. Amaba a Guthix no porque fuera el dios más poderoso o benévolo (aunque era ambas cosas), sino porque era mi dios y me había elegido para ser su sirviente.",
        ["When I saw that Zanik had been chosen by her god to be his servant, and that she refused, that seemed to me to be the greatest possible blasphemy. I see now that, in my isolation, I had constructed a false idol in my mind and no longer worshipped the real Guthix. In defying the war god, Zanik followed the true path of Guthix, and in opposing her...I was wrong."] = "Cuando vi que Zanik había sido elegida por su dios para ser su sirvienta, y que ella se negó, eso me pareció la mayor blasfemia posible. Ahora veo que, en mi aislamiento, había construido un ídolo falso en mi mente y ya no adoraba al verdadero Guthix. Al desafiar al dios de la guerra, Zanik siguió el verdadero camino de Guthix, y al oponerme a ella... me equivoqué.",
        ["I have not had news of Zanik since Guthix died. Perhaps if I saw her again, she could forgive me...but I do not know where she is or what her place will be in this new age."] = "No he tenido noticias de Zanik desde que murió Guthix. Quizás si la volviera a ver podría perdonarme... pero no sé dónde está ni cuál será su lugar en esta nueva era.",
        ["I do not wish to think of this any more... Will you tell me a story?"] = "No deseo pensar más en esto... ¿Me cuentas una historia?",
        ["{| class=\"wikitable"] = "{| clase=\"wikitabla",
        ["! Quest"] = "! Búsqueda",
        ["! Story ending"] = "! final de la historia",
        ["! Juna's reply"] = "! La respuesta de Juna",
        ["| Aftermath"] = "| Secuelas",
        ["| \"I defeated Zamorak, and said farewell to the gods before they were banished from Gielinor."] = "| \"Derroté a Zamorak y me despedí de los dioses antes de que fueran desterrados de Gielinor\".",
        ["| All Fired Up"] = "| Todo encendido",
        ["| \"...And that was how I learned to maintain King Roald's watchtower beacons."] = "| \"...Y así fue como aprendí a mantener las balizas de vigilancia de King Roald\".",
        ["| Alpha vs Omega"] = "| Alfa vs Omega",
        ["| \"I finally felt ready to face Rasial in immortal combat and destroyed his physical body. At least he was true to his word, and freed his army of enthralled souls back to Um."] = "| \"Finalmente me sentí listo para enfrentarme a Rasial en un combate inmortal y destruí su cuerpo físico. Al menos cumplió su palabra y liberó a su ejército de almas cautivadas de regreso a Um\".",
        ["| Ancient Awakening"] = "| Antiguo despertar",
        ["| \"I led an expedition to the island of Ungael and witnessed Zemouregal reanimating the dragon Vorkath."] = "| \"Dirigí una expedición a la isla de Ungael y fui testigo de cómo Zemouregal reanimaba al dragón Vorkath\".",
        ["| Animal Magnetism"] = "| Magnetismo animal",
        ["| \"...and so the attractor works using an undead chicken and a magnet."] = "| \"...y así el atractor funciona usando un pollo no-muerto y un imán.",
        ["| \"How odd."] = "| \"Qué extraño.",
        ["| Another Slice of H.A.M."] = "| Otra rebanada de H.A.M.",
        ["| \"...so I rescued Zanik from Sigmund and the railway was opened."] = "| \"... así que rescaté a Zanik de Sigmund y se abrió el ferrocarril\".",
        ["|(Before The Chosen Commander)"] = "|(Ante el Comandante Elegido)",
        ["| As a First Resort"] = "| Como primer recurso",
        ["| \"...So now the Oo'glog spa is open!"] = "| \"...¡Así que ahora el spa Oo'glog está abierto!",
        ["| Back to my Roots"] = "| De vuelta a mis raíces",
        ["| \"...So I defeated the wild vine and learned how to care for my own Jade Vine."] = "| \"... Así que derroté a la vid salvaje y aprendí a cuidar mi propia Jade Vine\".",
        ["| \"The care of nature is important, but wild plants are creatures of Guthix just as much as cultivated ones."] = "| \"El cuidado de la naturaleza es importante, pero las plantas silvestres son criaturas de Guthix tanto como las cultivadas.",
        ["| Back to the Freezer"] = "| De vuelta al congelador",
        ["| \"...And I stopped the Penguins from sending Gielinor into an Ice Age."] = "| \"...Y evité que los pingüinos enviaran a Gielinor a una Edad de Hielo\".",
        ["| \"A truly mammoth feat! Those penguins could one day become more powerful than we could possibly imagine!"] = "| \"¡Una hazaña verdaderamente gigantesca! ¡Esos pingüinos algún día podrían volverse más poderosos de lo que podríamos imaginar!",
        ["| Battle of Forinthry"] = "| Batalla de Forinthry",
        ["| \"I defended Fort Forinthry against an invasion from Zemouregal and Vorkath."] = "| \"Defendí Fort Forinthry contra una invasión de Zemouregal y Vorkath.",
        ["| Bar Crawl (miniquest)"] = "| Rastreo de bares (minimisión)",
        ["| \"I completed my bar crawl card and earned access to the Barbarian Outpost agility course."] = "| \"Completé mi tarjeta de rastreo de bares y obtuve acceso al curso de agilidad de Barbarian Outpost\".",
        ["| Battle of the Monolith"] = "| Batalla del monolito",
        ["| \"I fought in the Battle of the Monolith."] = "| \"Luché en la Batalla del Monolito\".",
        ["| Beneath Cursed Tides"] = "| Debajo de las mareas malditas",
        ["| \"I discovered the true fate of Tutorial Island and helped break the curse that had been put upon the tutors."] = "| \"Descubrí el verdadero destino de Tutorial Island y ayudé a romper la maldición que habían caído sobre los tutores\".",
        ["| Beneath Scabaras' Sands"] = "| Debajo de las arenas de Scabaras",
        ["| \"I located the god Scabaras and watched as Osman's plot to kill him was foiled."] = "| \"Localicé al dios Scabaras y vi cómo se frustraba el plan de Osman para matarlo\".",
        ["| Benedict's World Tour (miniquest)"] = "| Gira mundial de Benedict (minimisión)",
        ["| \"I visited all the locations in Benedict Encumberyak's scrapbook."] = "| \"Visité todos los lugares del álbum de recortes de Benedict Encumberyak\".",
        ["| Between a Rock..."] = "| Entre una roca...",
        ["| \"...I had to be shot out of a cannon into a rock! But, finally, I banished the spirit of the rock and Dondakan could mine his gold."] = "| \"...¡Tuve que ser disparado desde un cañón hacia una roca! Pero, finalmente, desterré el espíritu de la roca y Dondakan pudo extraer su oro\".",
        ["| Big Chompy Bird Hunting"] = "| Gran caza Chompy Bird",
        ["| \"...poor Rantz was so clumsy he couldn't shoot anything, but I managed to kill the Chompy bird."] = "| \"...el pobre Rantz era tan torpe que no podía disparar a nada, pero logré matar al Chompy bird\".",
        ["| \"...it turned out there was no plague after all!"] = "| \"... ¡Resultó que después de todo no había ninguna plaga!",
        ["| \"Deception of the people by their rulers is a terrible thing."] = "| \"El engaño del pueblo por parte de sus gobernantes es algo terrible\".",
        ["| Birthright of the Dwarves"] = "| Patrimonio de los enanos",
        ["| \"...and that was how we finally defeated the Red Axe."] = "| \"...y así fue como finalmente derrotamos al Hacha Roja.",
        ["| \"The spectre of chaos dwarves has loomed over all dwarves since the Third Age. I am glad you stopped those who sought to create more of those abominations."] = "| \"El espectro de los enanos del caos se ha cernido sobre todos los enanos desde la Tercera Edad. Me alegra que hayas detenido a aquellos que buscaban crear más de esas abominaciones\".",
        ["| Black Knights' Fortress (Removed)"] = "| Fortaleza de Black Knights (eliminada)",
        ["| \"...in the end the Black Knights were defeated by a cabbage!"] = "| \"...¡al final los Black Knights fueron derrotados por un repollo!",
        ["| \"One should never underestimate the vegetables of Guthix."] = "| \"Nunca se deben subestimar las verduras de Guthix.",
        ["| The Blood Pact"] = "| El pacto de sangre",
        ["| \"...so I rescued the prisoner, but the last cultist's death completed the ritual. Dragith Nurn's tomb broke open to reveal a staircase to the lower level of the catacombs."] = "| \"... así que rescaté al prisionero, pero la muerte del último cultista completó el ritual. La tumba de Dragith Nurn se abrió para revelar una escalera al nivel inferior de las catacumbas\".",
        ["| Blood Runs Deep"] = "| La sangre corre profunda",
        ["| \"After sealing away the dagganoth mother, we held a funeral for Prince Brand and Princess Astrid."] = "| \"Después de sellar a la madre dagganoth, celebramos un funeral para Prince Brand y Princess Astrid\".",
        ["| \"Death is a natural part of life. Celebrate it that as much mourn it."] = "| \"La muerte es una parte natural de la vida. Celebrenla tanto como la lloren.",
        ["| Boric's Task I (miniquest)"] = "| Tarea I de Boric (minimisión)",
        ["| \"I completed another Mining task for Boric."] = "| \"Completé otra tarea Mining para Boric\".",
        ["| Boric's Task II (miniquest)"] = "| Tarea II de Boric (minimisión)",
        ["| Boric's Task III (miniquest)"] = "| Tarea III de Boric (minimisión)",
        ["| The Branches of Darkmeyer"] = "| Las ramas de Darkmeyer",
        ["| \"...and, when I went back to Veliaf, he said I'd just put the Myreque in more danger."] = "| \"...y, cuando volví con Veliaf, me dijo que simplemente pondría al Myreque en mayor peligro\".",
        ["We do not yet know what will happen due to your actions. You had good intentions and therefore, good may still come of it."] = "Aún no sabemos qué sucederá debido a tus acciones. Tenías buenas intenciones y, por lo tanto, aún puede salir algo bueno de ello\".",
        ["| Bringing Home the Bacon"] = "| Llevar el tocino a casa",
        ["| \"...and that is how I managed to help preserve the pig population."] = "| \"...y así es como logré ayudar a preservar la población porcina.",
        ["| \"Such a balance would be pleasing Guthix. I cannot help but wonder what happened to those bacon addicts, though. I hope they too found balance."] = "| \"Un equilibrio así agradaría a Guthix. Sin embargo, no puedo evitar preguntarme qué pasó con esos adictos al tocino. Espero que ellos también encuentren el equilibrio\".",
        ["| The Brink of Extinction"] = "| El borde de la extinción",
        ["| \"...And so the TzHaar declared me their great champion. After I beat TokHaar-Hok into submission, he withdrew to the Elder Kiln to recover."] = "| \"...Y entonces TzHaar me declaró su gran campeón. Después de que vencí a TokHaar-Hok hasta someterlo, se retiró al Elder Kiln para recuperarse\".",
        ["| \"It saddens me that the TokHaar would resort to an act of genocide to purify their ancient race. You have established a precarious balance between the TokHaar and their TzHaar brethren."] = "| \"Me entristece que los TokHaar recurran a un acto de genocidio para purificar su antigua raza. Habéis establecido un equilibrio precario entre los TokHaar y sus hermanos TzHaar\".",
        ["| Broken Home"] = "| Hogar roto",
        ["| \"...and that's how I broke the curse on Senecianus and put the ghost of Ormod Gulvas to rest."] = "| \"...y así fue como rompí la maldición sobre Senecianus y puse a descansar al fantasma de Ormod Gulvas\".",
        ["| \"A tale of madness and troubled men. How very sad. I am relieved you've restored balance to the world, hero."] = "| \"Una historia de locura y hombres con problemas. Qué triste. Me alivia que hayas restaurado el equilibrio del mundo, héroe\".",
        ["| Buyers and Cellars"] = "| Compradores y bodegas",
        ["| \"With stealth and misdirection, I secured the funds to get the Thieves' Guild of Lumbridge up and running."] = "| \"Con sigilo y desvío, conseguí los fondos para poner en funcionamiento el Gremio de Ladrones de Lumbridge\".",
        ["| Cabin Fever"] = "| Fiebre de cabina",
        ["| \"...so I holed the enemy ship with another cannon shot, and the Adventurous sailed triumphantly into Mos Le'Harmless!"] = "| \"...así que agujereé el barco enemigo con otro disparo de cañón, ¡y el Adventurous navegó triunfalmente hacia Mos Le'Harmless!",
        ["| Call of the Ancestors"] = "| Llamado de los Ancestros",
        ["| \"I discovered a truly ancient Goebie, and helped three young goebs harness the powers of Mazcab."] = "| \"Descubrí un Goebie verdaderamente antiguo y ayudé a tres jóvenes goebs a aprovechar los poderes de Mazcab\".",
        ["| Carnillean Rising"] = "| Levantamiento carnilleano",
        ["| \"...so Philipe Carnilean now travels the world, seeking out adventure!"] = "| \"... ¡Así que ahora Philipe Carnilean viaja por el mundo en busca de aventuras!",
        ["| \"A worthy career, indeed. It is good that the boy has taken charge of his own life instead of living in his parents' shadow."] = "| \"Una carrera digna, por cierto. Es bueno que el niño se haya hecho cargo de su propia vida en lugar de vivir a la sombra de sus padres\".",
        ["| Catapult Construction"] = "| Catapulta Construction",
        ["| \"...And that was how I repaired the catapult in the Tyras camp."] = "| \"...Y así fue como reparé la catapulta en el campamento de Tyras.",
        ["| \"Catapults are terrible devices. They move rocks from their proper Guthix-assigned positions."] = "| \"Las catapultas son dispositivos terribles. Mueven rocas desde las posiciones apropiadas asignadas por Guthix\".",
        ["| Chef's Assistant"] = "| asistente de chef",
        ["| \"I followed the Head Chef's instructions and learned how to make cheesecake."] = "| \"Seguí las instrucciones de Head Chef y aprendí a hacer tarta de queso\".",
        ["| Children of Mah"] = "| hijos de mah",
        ["| \"...And that is how Mah came to pass and the mahjarrat were freed from their rituals."] = "| \"...Y así es como Mah sucedió y los mahjarrat fueron liberados de sus rituales\".",
        ["| \"A grand tale! I only hope that they will treat Gielinor with respect now that they are free of their curse."] = "| \"¡Una gran historia! Sólo espero que traten a Gielinor con respeto ahora que están libres de su maldición\".",
        ["| The Chosen Commander"] = "| El comandante elegido",
        ["| \"...so Zanik and I defeated the Bandos Avatar!"] = "| \"...¡Así que Zanik y yo derrotamos al Avatar Bandos!",
        ["| \"I know what happened. Your actions were an affront to the authority of the gods. You may redeem yourself in the eyes of Guthix, but Zanik is no longer welcome here."] = "| \"Sé lo que pasó. Tus acciones fueron una afrenta a la autoridad de los dioses. Puedes redimirte ante los ojos de Guthix, pero Zanik ya no es bienvenido aquí\".",
        ["| City of Senntisten"] = "| Ciudad de Senntisten",
        ["| \"I worked with Azzanadra to reclaim and secure Senntisten's cathedral in preparation for our defence against the elder gods."] = "| \"Trabajé con Azzanadra para recuperar y asegurar la catedral de Senntisten en preparación para nuestra defensa contra los dioses mayores\".",
        ["| Clock Tower"] = "| Torre del Reloj",
        ["| \"...so, it was I who repaired the clock tower."] = "| \"... entonces, fui yo quien reparó la torre del reloj\".",
        ["| A Clockwork Syringe"] = "| Una jeringa mecánica",
        ["| \"...and then I sank the fleet of zomboats, and protected Mos Le'Harmless from Annihilation."] = "| \"...y luego hundí la flota de zombos y protegí a Mos Le'Harmless de la aniquilación\".",
        ["| \"Undead pirates enhanced by machinery? If ever a more abominable affront to balance existed.."] = "| \"¿Piratas no muertos mejorados por maquinaria? Si alguna vez existiera una afrenta más abominable al equilibrio...",
        ["| Cold War"] = "| Frío War",
        ["| \"...It was a close call, but I managed to discover the penguins' plans and escape from their base."] = "| \"...Estuve cerca, pero logré descubrir los planes de los pingüinos y escapar de su base\".",
        ["| \"Penguins? Those creatures are not to be underestimated."] = "| \"¿Pingüinos? Esas criaturas no deben subestimarse.",
        ["| Contact!"] = "| ¡Contacto!",
        ["| \"...And when I emerged from the temple I found the place hugely changed. The deserted food stalls and empty streets were replaced with a healthy city filled with life, colour and commerce."] = "| \"...Y cuando salí del templo encontré el lugar enormemente cambiado. Los puestos de comida desiertos y las calles vacías fueron reemplazadas por una ciudad saludable llena de vida, color y comercio\".",
        ["| \"...And, in the end, I found all the ingredients, so the Duke of Lumbridge had a birthday cake after all."] = "| \"...Y, al final, encontré todos los ingredientes, así que, después de todo, el duque de Lumbridge tenía un pastel de cumpleaños\".",
        ["| \"Ah, a happy ending. It would not be good for such an anniversary to go unmarked."] = "| \"Ah, un final feliz. No sería bueno que un aniversario así quedara sin marcar\".",
        ["| Creature of Fenkenstrain"] = "| Criatura de Fenkenstrain",
        ["| \"...But in the end I stopped Fenkenstrain from continuing his horrible experiments."] = "| \"...Pero al final impidí que Fenkenstrain continuara con sus horribles experimentos\".",
        ["| Crocodile Tears"] = "| Crocodile Lágrimas",
        ["| \"...so I kept telling her no, and she spat up her corruption in the form of a crocodile demon, which I dealt with."] = "| \"... así que seguí diciéndole que no, y ella escupió su corrupción en la forma de un demonio cocodrilo, con el cual me ocupé\".",
        ["| \"Restoring Crondis is but a tilt of the scales in bringing balance to the desert. Still, it is a tilt in the right direction."] = "| \"Restaurar Crondis no es más que una inclinación de la balanza para traer equilibrio al desierto. Aún así, es una inclinación en la dirección correcta\".",
        ["| The Curse of Arrav"] = "| La maldición de Arrav",
        ["| \"...And so I escaped with the heart of Arrav."] = "| \"...Y así escapé con el corazón de Arrav.",
        ["| \"This separation of heart from man is not natural. It is good you are looking to resolve such matters."] = "| \"Esta separación del corazón del hombre no es natural. Es bueno que busquen resolver estos asuntos\".",
        ["| Curse of the Black Stone"] = "| Maldición de la Piedra Negra",
        ["| \"I defeated the Ambassador and saved Gielinor from a horrific hidden presence."] = "| \"Derroté a the Ambassador y salvé a Gielinor de una horrible presencia oculta\".",
        ["| Curse of the Empty Lord (miniquest)"] = "| La maldición del Señor Vacío (minimisión)",
        ["| \"I communed with six spirits, and learned more of an ancient entity whose name I probably shouldn't speak aloud. I also acquired ghostly robes."] = "| \"Me comuniqué con seis espíritus y aprendí más sobre una entidad antigua cuyo nombre probablemente no debería pronunciar en voz alta. También adquirí túnicas fantasmales\".",
        ["| Damage Control (miniquest)"] = "| Control de daños (minimisión)",
        ["| \"I salvaged materials from the island of Goshima to repair the Sarim's Revenge."] = "| \"Rescaté materiales de la isla de Goshima para reparar el Sarim's Revenge\".",
        ["| The Darkness of Hallowvale"] = "| La oscuridad de Hallowvale",
        ["| \"...I gave Safalaan the book on haemalchemy, and he recommended me for a position in the Myreque."] = "| \"...Le di a Safalaan el libro sobre hemalquimia y él me recomendó para un puesto en el Myreque\".",
        ["| \"I'm sure you will have many more adventures on behalf of the Myreque. Then, perhaps, you will have even more stories to tell me."] = "| \"Estoy seguro de que tendrás muchas más aventuras en nombre del Myreque. Entonces, tal vez, tendrás aún más historias que contarme\".",
        ["| Daughter of Chaos"] = "| hija del caos",
        ["| \"I tracked Moia through the Wilderness and witnessed the turning point of the Zamorakian Civil War."] = "| \"Seguí a Moia a través de Wilderness y fui testigo del punto de inflexión del War civil de Zamorak\".",
        ["| Dead and Buried"] = "| Muerto y enterrado",
        ["| \"The Raptor and I delved deeper into the crypt north of Fort Forinthry and discovered Zemouregal's nefarious plot."] = "| \"The Raptor y yo profundizamos en la cripta al norte de Fort Forinthry y descubrimos el nefasto complot de Zemouregal\".",
        ["| Deadliest Catch"] = "| Captura más mortal",
        ["| \"...and we returned to the Fishing Guild where Jones set up shop selling his own Miracle Thalassus Protection Cream."] = "| \"...y regresamos al Gremio Fishing donde Jones instaló una tienda vendiendo su propia Crema Protectora Miracle Thalassus\".",
        ["| \"It's a small blessing that the creature can continue to exist."] = "| \"Es una pequeña bendición que la criatura pueda seguir existiendo\".",
        ["| Dealing with Scabaras"] = "| Lidiando con Scabaras",
        ["| \"...And that was how I dealt with the High Priest of Scabaras."] = "| \"...Y así fue como lidié con el High Priest of Scabaras\".",
        ["| \"The desert gods are strange, but you must be sure to pay them the proper respect."] = "| \"Los dioses del desierto son extraños, pero debes asegurarte de mostrarles el debido respeto\".",
        ["| The Death of Chivalry"] = "| La muerte de la caballería",
        ["| \"...Saradomin brought Sir Owen back to life, but the resurrected knight's sword arm was corrupted and skeletal."] = "| \"...Saradomin devolvió la vida a Sir Owen, pero el brazo espada del caballero resucitado estaba corrupto y esquelético\".",
        ["| \" I hope now you appreciate the power the gods seek to wield, at any cost."] = "| \"Espero que ahora aprecies el poder que los dioses buscan ejercer, a cualquier precio\".",
        ["| Death Plateau"] = "| Meseta de la muerte",
        ["| \"...So, from then on, the Imperial Guard was able to access Death Plateau safely and take the trolls by surprise."] = "| \"... Entonces, a partir de ese momento, la Guardia Imperial pudo acceder a la Meseta de la Muerte de manera segura y tomar a los trolls por sorpresa\".",
        ["| Death to the Dorgeshuun"] = "| Muerte al Dorgeshuun",
        ["| \"...Sigmund escaped again, but Zanik and I destroyed the machine and Dorgesh-Kaan was saved!"] = "| \"...¡Sigmund escapó de nuevo, pero Zanik y yo destruimos la máquina y Dorgesh-Kaan se salvó!",
        ["|(Before The Chosen Commander) \"Zanik still has her destiny to fulfil, and I have a feeling you will have a part in that."] = "|(Antes de The Chosen Commander) \"Zanik todavía tiene su destino que cumplir, y tengo la sensación de que tú tendrás parte en eso\".",
        ["| Defender of Varrock"] = "| Defensor de Varrock",
        ["| \"...The Shield of Arrav glowed with lightning, and Dimintheis used it to defeat the zombie army."] = "| \"...El Escudo de Arrav brillaba con un rayo, y Dimintheis lo usó para derrotar al ejército zombie\".",
        ["| Demon Slayer"] = "| Demonio Slayer",
        ["| \"...so I destroyed the demon Delrith and saved Varrock!"] = "| \"... ¡así que destruí al demonio Delrith y salvé a Varrock!",
        ["| \"I remember Delrith. A most unpleasant character; I am glad he has been dispatched."] = "| \"Recuerdo a Delrith. Un personaje muy desagradable; me alegro de que lo hayan enviado\".",
        ["| Desert Slayer Dungeon (miniquest)"] = "| Mazmorra del Desierto Slayer (minimisión)",
        ["| \"In the Pollnivneach Slayer Dungeon, I defeated a monstrous cave crawler, basilisk boss, mightiest turoth and kurask overlord."] = "| \"En la mazmorra Pollnivneach Slayer, derroté a un monstruoso rastreador de cuevas, al jefe basilisco, al turoth más poderoso y al señor supremo kurask\".",
        ["| \"...In the pyramid I discovered a whole new set of magic spells!"] = "| \"...¡En la pirámide descubrí un conjunto completamente nuevo de hechizos mágicos!",
        ["| \"I suggest you think about the origin of those spells. Ancient magicks are not to be toyed with."] = "| \"Te sugiero que pienses en el origen de esos hechizos. No se debe jugar con la magia antigua\".",
        ["| Desperate Measures"] = "| Medidas desesperadas",
        ["| \"I tracked down Kerapac and foiled his plot to destroy Gielinor. He's now fallen back under Jas's control, bound to the Needle this time."] = "| \"Rastreé a Kerapac y frustré su plan para destruir Gielinor. Ahora ha vuelto a caer bajo el control de Jas, esta vez atado a la Aguja\".",
        ["| Desperate Times"] = "| Tiempos desesperados",
        ["| \"I may have accidentally helped a dragonkin take control of an elder artefact, endangering all life on Gielinor. Oops."] = "| \"Es posible que accidentalmente haya ayudado a un dragonante a tomar el control de un artefacto antiguo, poniendo en peligro toda la vida en Gielinor. Ups\".",
        ["| Devious Minds"] = "| Mentes tortuosas",
        ["| \"...it was I who accidentally brought a teleport beacon onto Entrana! But the Temple Knights are investigating, so it should be all right."] = "| \"... ¡Fui yo quien accidentalmente trajo una baliza de teletransporte a Entrana! Pero los Caballeros del Templo están investigando, así que todo debería estar bien\".",
        ["| Diamond in the Rough"] = "| Diamante en bruto",
        ["| \"So it turned out Lady Keli was really the desert goddess Amascut in disguise! She escaped with the heart, and left Ozan and I to defeat her bodyguards."] = "| \"¡Resultó que Lady Keli era en realidad la diosa del desierto Amascut disfrazada! Ella escapó con el corazón y nos dejó a Ozan y a mí para derrotar a sus guardaespaldas\".",
        ["| \"It is good that the prince was safely returned home to retain the balance of peace, but the cost may prove to be high."] = "| \"Es bueno que el príncipe haya regresado sano y salvo a casa para mantener el equilibrio de la paz, pero el coste puede resultar elevado\".",
        ["| The Dig Site"] = "| El sitio de excavación",
        ["| \"...And the examiner was very impressed that I had discovered an ancient altar of Zaros."] = "| \"...Y el examinador quedó muy impresionado de que hubiera descubierto un antiguo altar de Zaros\".",
        ["| \"Zaros? I had not heard that name for a thousand years, even before the start of my sojourn here."] = "| \"¿Zaros? No había oído ese nombre en mil años, incluso antes del comienzo de mi estancia aquí.",
        ["| Dimension of Disaster"] = "| Dimensión del desastre",
        ["| \"...and so I returned to Varrock, the hero of two worlds."] = "| \"...y así regresé a Varrock, el héroe de dos mundos\".",
        ["| \"Fascinating. A city of villains, in a world where Guthix still sleeps. Your tale intrigues me."] = "| \"Fascinante. Una ciudad de villanos, en un mundo donde Guthix todavía duerme. Tu historia me intriga\".",
        ["| Dimension of Disaster: Coin of the Realm"] = "| Dimensión del desastre: moneda del reino",
        ["| \"I opened the way to New Varrock."] = "| \"Abrí el camino hacia el nuevo Varrock\".",
        ["| Dimension of Disaster: Curse of Arrav"] = "| Dimensión del desastre: La maldición de Arrav",
        ["| \"I defeated Zemouregal in New Varrock."] = "| \"Derroté a Zemouregal en New Varrock\".",
        ["| Dimension of Disaster: Shield of Arrav"] = "| Dimensión del Desastre: Escudo de Arrav",
        ["| \"I returned the Shield of Arrav to New Varrock museum."] = "| \"Devolví el escudo de Arrav al nuevo museo Varrock\".",
        ["| Dimension of Disaster: Defender of Varrock"] = "| Dimensión del desastre: Defensor de Varrock",
        ["| \"I weakened Zemouregal's control over Arrav in New Varrock."] = "| \"Debilité el control de Zemouregal sobre Arrav en New Varrock\".",
        ["| Dimension of Disaster: Demon Slayer"] = "| Dimensión del desastre: Demonio Slayer",
        ["| \"I defeated the demons Delrith and Agrith Naar in New Varrock."] = "| \"Derroté a los demonios Delrith y Agrith Naar en New Varrock\".",
        ["| Dishonour among Thieves (siding with Zamorak)"] = "| Deshonra entre ladrones (del lado de Zamorak)",
        ["| \"...and then Zamorak and I simultaneously blasted Sliske, delivering a blow that forced him to withdraw to the Shadow Realm with the Stone of Jas!"] = "| \"... ¡y luego Zamorak y yo atacamos simultáneamente a Sliske, dándole un golpe que lo obligó a retirarse al Reino de las Sombras con la Piedra de Jas!",
        ["| \"Another step closer to all out God Wars. Guthix would weep at the anarchy that is sweeping Gielinor, the other Guardians and I must do everything within our power to prevent it."] = "| \"Otro paso más hacia God Wars. Guthix lloraría ante la anarquía que está arrasando Gielinor, los otros Guardianes y yo debemos hacer todo lo que esté a nuestro alcance para evitarlo.",
        ["| Dishonour among Thieves (neutral)"] = "| Deshonra entre ladrones (neutral)",
        ["| \"...and after drawing power from the Stone of Jas, Zamorak blasted Sliske, forcing him to withdraw to the Shadow Realm with the stone."] = "| \"...y después de extraer poder de la Piedra de Jas, Zamorak atacó a Sliske, obligándolo a retirarse al Reino de las Sombras con la piedra.",
        ["| Dishonour among Thieves (siding with Sliske)"] = "| Deshonra entre ladrones (del lado de Sliske)",
        ["| \"...then I channeled  the Stone of Jas and blasted Zamorak to save Sliske, giving him enough time to shift both of us into the Shadow Realm along with the Stone!"] = "| \"...luego canalicé la Piedra de Jas y lancé a Zamorak para salvar a Sliske, ¡dándole tiempo suficiente para trasladarnos a ambos al Reino de las Sombras junto con la Piedra!",
        ["| Do No Evil"] = "| No hacer el mal",
        ["| \"...and so the monkey colony prospers and Apmeken is restored."] = "| \"...y así la colonia de monos prospera y Apmeken se restablece.",
        ["| \"Restoring Apmeken is but a tilt of the scales in bringing balance to the desert. Still, it is a tilt in the right direction."] = "| \"Restaurar Apmeken no es más que una inclinación de la balanza para lograr el equilibrio en el desierto. Aún así, es una inclinación en la dirección correcta\".",
        ["| Doric's Task I (miniquest)"] = "| Tarea I de Doric (minimisión)",
        ["| \"I completed another Smithing task for Doric."] = "| \"Completé otra tarea Smithing para Doric\".",
        ["| Doric's Task II (miniquest)"] = "| Tarea II de Doric (minimisión)",
        ["| Doric's Task III (miniquest)"] = "| Tarea III de Doric (minimisión)",
        ["| Doric's Task IV (miniquest)"] = "| Tarea IV de Doric (minimisión)",
        ["| Doric's Task V (miniquest)"] = "| Tarea V de Doric (minimisión)",
        ["| Doric's Task VI (miniquest)"] = "| Tarea VI de Doric (minimisión)",
        ["| Doric's Task VII (miniquest)"] = "| Tarea VII de Doric (minimisión)",
        ["| Doric's Task VIII (miniquest)"] = "| Tarea VIII de Doric (minimisión)",
        ["| Doric's Quest (Removed)"] = "| La misión de Doric (eliminada)",
        ["| \"...so once I had got all the ores he wanted, Doric let me use his anvils."] = "| \"... así que una vez que obtuve todos los minerales que quería, Doric me dejó usar sus yunques\".",
        ["| \"Such a small task hardly seems worthy of the term 'quest'."] = "| \"Una tarea tan pequeña difícilmente merece el término 'búsqueda'.",
        ["| \"...so with Elvarg the dragon dead, the master of the Champions' Guild let me in, and I was able to wear rune plate armour!"] = "| \"... así que con Elvarg el dragón muerto, el maestro de Champions' Guild me dejó entrar y ¡pude usar una armadura de placas rúnicas!",
        ["| Dream Mentor"] = "| Mentor de sueños",
        ["| \"...So in the end I travelled into Cyrisus's Dreamland and defeated his fear of combat."] = "| \"... Así que al final viajé al País de los Sueños de Cyrisus y derroté su miedo al combate\".",
        ["| Druidic Ritual"] = "| Ritual druídico",
        ["| \"...so Kaqemeex taught me how to use the Herblore skill."] = "| \"... entonces Kaqemeex me enseñó cómo usar la habilidad Herblore\".",
        ["| \"A generous reward indeed."] = "| \"Una recompensa generosa en verdad.",
        ["| Duck Quest"] = "| Búsqueda del pato",
        ["| \"I helped reunite a lost duckling with her family, and learnt the philosophy of the duck along the way."] = "| \"Ayudé a reunir a un patito perdido con su familia y, en el camino, aprendí la filosofía del pato\".",
        ["| Dwarf Cannon"] = "| Cañón enano",
        ["| \"...and that was how I fixed the dwarf multicannon."] = "| \"...y así fue como arreglé el multicañón enano.",
        ["| \"So, war still rages in the world above? Will you never tire of creating machines of destruction?"] = "| \"Entonces, ¿la guerra todavía hace estragos en el mundo de arriba? ¿Nunca te cansarás de crear máquinas de destrucción?",
        ["| Eadgar's Ruse"] = "| La artimaña de Eadgar",
        ["| \"...Eadgar's ruse was absurd, but it worked! The trolls ate a fake human, and I got the herb for the druids' ritual."] = "| \"... ¡La artimaña de Eadgar fue absurda, pero funcionó! Los trolls se comieron a un humano falso y yo conseguí la hierba para el ritual de los druidas\".",
        ["| Eagles' Peak"] = "| Pico de las Águilas",
        ["| \"...in the end I had to dress up as an eagle in order to get the zoo a new ferret!"] = "| \"...¡al final tuve que disfrazarme de águila para conseguirle al zoológico un nuevo hurón!",
        ["| \"You should not make light of your tampering with the balance of nature. Always treat the natural world with respect."] = "| \"No debes tomar a la ligera tu alteración del equilibrio de la naturaleza. Trata siempre el mundo natural con respeto\".",
        ["| \"...and that's how I reunited the demigods of the desert pantheon, stopped Amascut's destruction, and saved Menaphos!"] = "| \"... ¡y así fue como reuní a los semidioses del panteón del desierto, detuve la destrucción de Amascut y salvé a Menaphos!",
        ["| \"You were wise not to end Amascut's life. With her returned from the brink, balance has been restored to the desert."] = "| \"Hiciste bien en no acabar con la vida de Amascut. Con su regreso del borde del abismo, se ha restablecido el equilibrio en el desierto\".",
        ["| The Elder Kiln"] = "| El horno mayor",
        ["| \"...Ga'al-Xox left without another word, I can't help but think that the memories of the dead TzHaar champion weigh heavily on his mind."] = "| \"...Ga'al-Xox se fue sin decir una palabra más, no puedo evitar pensar que los recuerdos del campeón TzHaar muerto pesan mucho en su mente.",
        ["| \"The dead's memories are sacred. To channel them through the living is an affront to Guthix. The TzHaar should have steered clear of that kiln."] = "| \"Los recuerdos de los muertos son sagrados. Canalizarlos a través de los vivos es una afrenta para Guthix. Los TzHaar deberían haberse mantenido alejados de ese horno\".",
        ["| Elemental Workshop I"] = "| Taller Elemental I",
        ["| \"...once I had repaired the Elemental Workshop, I was able to make an elemental shield."] = "| \"...una vez que reparé el Taller Elemental, pude hacer un escudo elemental\".",
        ["| Elemental Workshop II"] = "| Taller Elemental II",
        ["| \"...so I instilled the power of my mind into the primed bar and smithed it into an elemental mind helm!"] = "| \"...¡así que inculqué el poder de mi mente en la barra preparada y la forjé en un yelmo mental elemental!",
        ["| \"You should be careful about meddling with your own head."] = "| \"Debes tener cuidado de no entrometerte en tu propia cabeza\".",
        ["| Elemental Workshop III"] = "| Taller Elemental III",
        ["| \"...pressing the button powered the elemental bar. I was then able to make a body body."] = "| \"...al presionar el botón se encendió la barra elemental. Entonces pude crear un cuerpo\".",
        ["| \"Sounds like an arduous task."] = "| \"Suena como una tarea ardua\".",
        ["| Elemental Workshop IV"] = "| Taller Elemental IV",
        ["| \"...pressing the button powered the elemental bar. I was then able to make some chaos boots."] = "| \"...al presionar el botón se encendió la barra elemental. Luego pude hacer algunas botas del caos\".",
        ["| \"This workshop sounds complex."] = "| \"Este taller suena complejo\".",
        ["| Enakhra's Lament"] = "| El lamento de Enakhra",
        ["| \"...then Akthanakos and Enakhra went away to the north to continue fighting."] = "| \"...entonces Akthanakos y Enakhra se fueron al norte para seguir luchando.",
        ["| \"A battle between two such powerful beings will take much time and unleash much energy. I hope that the natural world is not damaged in this conflict!"] = "| \"Una batalla entre dos seres tan poderosos llevará mucho tiempo y liberará mucha energía. ¡Espero que el mundo natural no resulte dañado en este conflicto!",
        ["| Enlightened Journey"] = "| Viaje iluminado",
        ["| \"...we landed the balloon in Taverley and Auguste thanked me for helping him get his idea off the ground."] = "| \"...aterrizamos el globo en Taverley y Auguste me agradeció por ayudarlo a hacer despegar su idea\".",
        ["| Enter the Abyss (miniquest)"] = "| Entra en el abismo (minimisión)",
        ["| \"I gained access to the Abyss."] = "| \"Obtuve acceso al Abismo\".",
        ["| Ernest the Chicken"] = "| Ernesto el Chicken",
        ["| \"...So, once I had found all the parts for the machine, poor Ernest could be himself once more."] = "| \"...Así que, una vez que encontré todas las piezas de la máquina, el pobre Ernest pudo volver a ser él mismo.",
        ["| \"That was a good deed. It is a terrible thing to be locked out of one's natural form."] = "| \"Esa fue una buena acción. Es algo terrible que uno se quede fuera de su forma natural\".",
        ["| Evil Dave's Big Day Out"] = "| El gran día de Evil Dave",
        ["| \"I somehow switched bodies with Evil Dave and survived enough chores and shouting from Doris to find a way to swap back."] = "| \"De alguna manera cambié de cuerpo con Evil Dave y sobreviví suficientes tareas y gritos de Doris para encontrar una manera de volver a cambiar\".",
        ["| Extinction"] = "| extinción",
        ["| \"...and that's how I prevented the Elder Gods from destroying Gielinor, once and for all!"] = "| \"... ¡y así es como evité que los Dioses Mayores destruyeran Gielinor, de una vez por todas!",
        ["| \"Guthix knew the Elders were the greatest threat Gielinor could ever face. He saw that this day would come...and that you would rise to meet it. Mourn the fate of Iaia, World Guardian. The greatest victories require the greatest sacrifices."] = "| \"Guthix sabía que los Ancianos eran la mayor amenaza que Gielinor podría enfrentar. Vio que este día llegaría... y que tú te levantarías para enfrentarlo. Llora el destino de Iaia, Guardiana Mundial. Las mayores victorias requieren los mayores sacrificios\".",
        ["| Eye for an Eye (miniquest)"] = "| Ojo por ojo (minimisión)",
        ["| \"I assisted the one-eyed inhabitants of Cyclosis, and dispatched undead Jed."] = "| \"Ayudé a los habitantes tuertos de Cyclosis y envié a Jed no-muertos\".",
        ["| Eye of Het I"] = "| Ojo de Het I",
        ["| \"I helped Icthlarin recover a priceless relic following the Duel Arena's destruction."] = "| \"Ayudé a Icthlarin a recuperar una reliquia de valor incalculable tras la destrucción del Duel Arena\".",
        ["| Eye of Het II"] = "| Ojo de Het II",
        ["| \"I solved the mystery of the Duel Arena's destruction."] = "| \"Resolví el misterio de la destrucción del Duel Arena\".",
        ["| The Eyes of Glouphrie"] = "| Los ojos de Gloufrie",
        ["| \"...the machine revealed that the cute creatures were actually Arposandran spies! I destroyed them, and King Narnode gave me a crystal seed that belonged to Oaknock the Engineer."] = "| \"... ¡la máquina reveló que las lindas criaturas eran en realidad espías arposandranos! Los destruí y el rey Narnode me dio una semilla de cristal que pertenecía a Oaknock el Ingeniero\".",
        ["| A Fairy Tale I - Growing Pains"] = "| Un cuento de Fairy I - Dolores de crecimiento",
        ["| \"...so I defeated the tanglefoot and returned the Fairy Queen's enchanted secateurs to the Fairy Godfather."] = "| \"... así que derroté al pie enredado y devolví las tijeras de podar encantadas de Fairy Queen al Padrino de Fairy\".",
        ["| \"These fairies seem to be well-versed in the powers of nature."] = "| \"Estas hadas parecen conocer bien los poderes de la naturaleza.",
        ["| A Fairy Tale II - Cure a Queen"] = "| A Fairy Tale II - Cura a una reina",
        ["| \"...the Fairy Queen awoke, and we realized that the Godfather had betrayed her!"] = "| \"...¡la Fairy Queen despertó y nos dimos cuenta de que el Padrino la había traicionado!",
        ["| \"Politics is never straightforward."] = "| \"La política nunca es sencilla\".",
        ["| A Fairy Tale III - Battle at Ork's Rift"] = "| A Fairy Tale III - Batalla en Ork's Rift",
        ["| \"...and as the Fairy Godfather got sucked into the rift, his power grew so immense that the rift exploded and destroyed an entire area of Zanaris. Cursed Ivory orks now roam that area, continually regrowing from the cursed farming patches!"] = "| \"...y cuando el Padrino de Fairy fue absorbido por la grieta, su poder creció tan inmenso que la grieta explotó y destruyó un área entera de Zanaris. ¡Los orkos de Marfil Malditos ahora deambulan por esa área, rebrotando continuamente de las parcelas agrícolas malditas!",
        ["That is indeed troubling, Player."] = "Eso es realmente preocupante, Player\".",
        ["To which you reply: \"However, the Fairy Queen has now been returned to her rightful throne, and the Fairy Godfather won't be around to bother anyone again!"] = "A lo que usted responde: \"Sin embargo, la Fairy Queen ha vuelto a ocupar el trono que le corresponde, ¡y el padrino de Fairy no volverá a molestar a nadie!\".",
        ["To which Juna replies: \"It seems you truly are a force for good, Player. Guthix himself would approve of you returning balance to the realm of Zanaris."] = "A lo que Juna responde: \"Parece que realmente eres una fuerza para el bien, Player. El propio Guthix aprobaría que devuelvas el equilibrio al reino de Zanaris\".",
        ["| Family Crest"] = "| Escudo familiar",
        ["| \"...So all three parts of the family crest were reunited."] = "| \"...Así que las tres partes del escudo familiar se reunieron\".",
        ["| Fate of the Gods (returning Zaros at full strength)"] = "| Destino de los Dioses (regresando Zaros con toda su fuerza)",
        ["| \"...And so Zaros has returned to Gielinor at full strength, and he intends to become an elder god! "] = "| \"... ¡Y entonces Zaros ha regresado a Gielinor con toda su fuerza, y tiene la intención de convertirse en un dios anciano! ",
        ["| \"While his intentions may seem noble, his methods are questionable and his history tarnished. Whatever he might be, he is not Guthix."] = "| \"Si bien sus intenciones pueden parecer nobles, sus métodos son cuestionables y su historia está empañada. Sea lo que sea, no es Guthix.",
        ["| Fate of the Gods (sabotaging Zaros)"] = "| Destino de los dioses (saboteando a Zaros)",
        ["| \"...and so Zaros has returned to Gielinor in a weakened state, but he still intends to become an elder god!"] = "| \"...y entonces Zaros ha regresado a Gielinor en un estado debilitado, ¡pero todavía tiene la intención de convertirse en un dios mayor!",
        ["| Father and Son (miniquest)"] = "| Padre e hijo (minimisión)",
        ["| \"I passed on a message to Sigli from Irwinsson and gave Irwinsson a bow created by his father."] = "| \"Le pasé un mensaje a Sigli de Irwinsson y le di a Irwinsson un arco creado por su padre.",
        ["| \"...So despite the failure of my original task, Ali Morrisane was very happy about his nephew's fortunes."] = "| \"... Entonces, a pesar del fracaso de mi tarea original, Ali Morrisane estaba muy contento con la suerte de su sobrino\".",
        ["| Fight Arena"] = "| Arena de lucha",
        ["| \"...I beat General Khazard in his own arena and won the Servils their freedom!"] = "| \"... ¡Vencí a General Khazard en su propia arena y le gané a los Servils su libertad!",
        ["| Final Destination (miniquest)"] = "| Destino final (minimisión)",
        ["| \"I defeated Captain Cora and eased the khan of Goshima's passage to her final destination."] = "| \"Derroté al Capitán Cora y facilité el paso del Khan de Goshima hasta su destino final\".",
        ["| The Firemaker's Curse"] = "| La maldición del bombero",
        ["| \"...so Char is still there, supposedly planning for Zaros's return."] = "| \"...así que Char todavía está allí, supuestamente planeando el regreso de Zaros.",
        ["| \"Zaros's return is not something I can look on kindly, but we must admire Char's devotion. It takes strength to stay loyal for so many centuries."] = "| \"El regreso de Zaros no es algo que pueda ver con buenos ojos, pero debemos admirar la devoción de Char. Se necesita fuerza para permanecer leal durante tantos siglos\".",
        ["| Fishing Contest"] = "| Concurso Fishing",
        ["| \"...And after I had won the fishing contest, the Dwarves let me go under White Wolf Mountain."] = "| \"...Y después de ganar el concurso de pesca, los enanos me dejaron ir bajo la Montaña del Lobo Blanco\".",
        ["| \"Fishing? A strange test of worthiness to pass through an underground tunnel!"] = "| \"¿Fishing? ¡Una extraña prueba de dignidad para pasar por un túnel subterráneo!",
        ["| Flag Fall (miniquest)"] = "| Caída de bandera (minimisión)",
        ["| \"I learned how to travel to uncharted islands and claimed an island of my own."] = "| \"Aprendí a viajar a islas inexploradas y reclamé una isla propia\".",
        ["| Forgettable Tale of a Drunken Dwarf"] = "| Historia olvidable de un Drunken Dwarf",
        ["| \"...I think I did something with a drunken dwarf, but I can't remember what."] = "| \"...Creo que hice algo con drunken dwarf, pero no recuerdo qué.",
        ["| \"You must be careful not to let drink muddle your brain!"] = "| \"¡Debes tener cuidado de no dejar que la bebida enturbie tu cerebro!",
        ["| Forgiveness of a Chaos Dwarf"] = "| El perdón de un enano del caos",
        ["| \"...And it turned out that Hilda had been the chaos dwarf we killed in the tower. Veldaban was devestated."] = "| \"...Y resultó que Hilda había sido el enano del caos que matamos en la torre. Veldaban estaba devastado\".",
        ["| \"Losing one's identity is worse than death."] = "| \"Perder la identidad es peor que la muerte\".",
        ["| The Fremennik Isles"] = "| Las islas Fremennik",
        ["| \"...I slew many trolls and brought the Troll King's head back to Neitiznot as a trophy."] = "| \"... Maté a muchos trolls y traje la cabeza del Rey Troll a Neitiznot como trofeo\".",
        ["| The Fremennik Trials"] = "| Los juicios de Fremennik",
        ["| \" ...And that was how I became an honourary member of the Fremennik, and was given my Fremennik name, <small>*(player's Fremennik name)*</small>."] = "| \"...Y así fue como me convertí en miembro honorario del Fremennik, y me dieron mi nombre de Fremennik, <small>*(nombre de Fremennik del jugador)*</small>\".",
        ["| From Tiny Acorns (miniquest)"] = "| De Tiny Acorns (minimisión)",
        ["| \"I completed another caper for the Lumbridge Thieves' Guild."] = "| \"Completé otra travesura para el gremio de ladrones Lumbridge\".",
        ["| Fur 'n Seek"] = "| Fur 'n buscar",
        ["| \"...So, I fetched all the furs the Odd Old Man wanted and he gave me a reward!"] = "| \"... Entonces, ¡busqué todas las pieles que quería el Odd Old Man y él me dio una recompensa!",
        ["| \"This Odd Old Man has some puzzling requests. I wonder about the motivations of his actions."] = "| \"Este Odd Old Man tiene algunas solicitudes desconcertantes. Me pregunto cuáles son las motivaciones de sus acciones\".",
        ["| Garden of Tranquillity"] = "| Jardín de la Tranquilidad",
        ["| \"...so the garden at Varrock palace is all my work!"] = "| \"... ¡así que el jardín del palacio Varrock es todo mi trabajo!",
        ["| \"It is good that you can take time from slaying and adventuring to grow a beautiful garden."] = "| \"Es bueno que puedas tomarte el tiempo de matar y aventurarte para cultivar un hermoso jardín\".",
        ["| The General's Shadow (miniquest)"] = "| La sombra del general (minimisión)",
        ["| \"I peered into the shadow realm and encountered General Khazard. I completed his assignment and earned the shadow sword."] = "| \"Miré hacia el reino de las sombras y me encontré con General Khazard. Completé su tarea y obtuve la espada de las sombras.",
        ["| Gertrude's Cat"] = "| El gato de Gertrude",
        ["| \"...I returned Fluffs safely to Gertrude and she gave me a cat of my own!"] = "| \"... ¡Devolví Fluffs sano y salvo a Gertrude y ella me dio mi propio gato!",
        ["| \"Cats are one of the most mysterious creatures of Guthix. I hope you take your responsibility seriously."] = "| \"Los gatos son una de las criaturas más misteriosas de Guthix. Espero que tomes en serio tu responsabilidad\".",
        ["| Ghosts Ahoy"] = "| Fantasmas a la vista",
        ["| \"...so the people of Port Phasmatys were finally able to rest."] = "| \"...así que la gente de Port Phasmatys finalmente pudo descansar.",
        ["| Ghosts from the Past (miniquest)"] = "| Fantasmas del pasado (minimisión)",
        ["| \"I visited the Islands That Once Were Turtles and discovered more than anyone would prefer to know about Quartermaster Gully's personal life."] = "| \"Visité las islas que alguna vez fueron tortugas y descubrí más de lo que nadie preferiría saber sobre la vida personal de Quartermaster Gully\".",
        ["| The Giant Dwarf"] = "| El enano gigante",
        ["| \"...the statue in Keldagrim was rebuilt and I witnessed a meeting of the Mining Consortium."] = "| \"...la estatua en Keldagrim fue reconstruida y fui testigo de una reunión del Consorcio Mining.",
        ["| \"I have a feeling that Keldagrim will be the setting of many great adventures for you."] = "| \"Tengo la sensación de que Keldagrim será el escenario de muchas grandes aventuras para ti\".",
        ["| Glorious Memories"] = "| Recuerdos gloriosos",
        ["| \"As soon as King Vargas had regained his human form, he set off on another adventure."] = "| \"Tan pronto como King Vargas recuperó su forma humana, se embarcó en otra aventura\".",
        ["| Goblin Diplomacy"] = "| Diplomacia duende",
        ["| \"...and so the goblins ended up wearing the armour colour they had to start off with!"] = "| \"...¡y así los goblins terminaron usando el color de armadura con el que tenían que empezar!",
        ["| \"Poor, silly goblins! Their race had such potential; if only they could rise above their petty squabbles."] = "| \"¡Pobres y tontos duendes! Su raza tenía mucho potencial; si tan solo pudieran superar sus pequeñas disputas.",
        ["| The Golem"] = "| El Golem",
        ["| \"...And I had to reprogram the golem before it would believe that the demon was dead."] = "| \"...Y tuve que reprogramar el golem antes de que creyera que el demonio estaba muerto.",
        ["| \"I remember well the battle of Uzer."] = "| \"Recuerdo bien la batalla de Uzer\".",
        ["| Gower Quest"] = "| Búsqueda de Gower",
        ["| \"...and that's how the Gowers repaired the life altar with my help and saved Behind the Scenes."] = "| \"...y así es como los Gowers repararon el altar de la vida con mi ayuda y salvaron Detrás de Escenas\".",
        ["| \"To believe such a place exists. I wonder if perhaps I will ever have chance  to visit."] = "| \"Creer que existe un lugar así. Me pregunto si quizás alguna vez tendré la oportunidad de visitarlo\".",
        ["| The Grand Tree"] = "| El gran árbol",
        ["| \"...Glough fled like the coward he really is, and the Grand Tree was saved!"] = "| \"...Glough huyó como el cobarde que realmente es, ¡y el Gran Árbol se salvó!",
        ["| The Great Brain Robbery"] = "| El gran robo de cerebros",
        ["| \"...but after the monks' brains had been restored, I had to fight an enormous abomination called Barrelchest!"] = "| \"...pero después de que los cerebros de los monjes fueron restaurados, ¡tuve que luchar contra una enorme abominación llamada Barrelchest!",
        ["| \"Zombies and brain-swapping? It is good that you stopped this disrespect for nature."] = "| \"¿Zombis e intercambio de cerebros? Es bueno que hayas puesto fin a esta falta de respeto por la naturaleza\".",
        ["| Grim Tales"] = "| Cuentos sombríos",
        ["| \"...so I found the golden goblin and cut down the beanstalk, and that was the end of that grim tale!"] = "| \"... así que encontré al duende dorado y corté el tallo de habichuelas, ¡y ese fue el final de esa sombría historia!",
        ["| A Guild of Our Own (miniquest)"] = "| Un gremio propio (minimisión)",
        ["| I completed another caper for the Lumbridge Thieves' Guild."] = "| Completé otra travesura para el gremio de ladrones Lumbridge.",
        ["| Gunnar's Ground"] = "| Tierra de Gunnar",
        ["| \"...and the chieftain agreed to settle on the land that his ancestors had won."] = "| \"...y el cacique accedió a establecerse en la tierra que sus antepasados ​​habían ganado.",
        ["| \"These militant Fremennik think they serve Guthix, but they serve only themselves."] = "| \"Estos militantes fremennik creen que sirven a Guthix, pero sólo se sirven a sí mismos\".",
        ["| The Hand in the Sand"] = "| La mano en la arena",
        ["| \"...so that was how I gave Bert a hand solving the murder and returned the wizard's head, solving the riddle of the ever-full sand pits!"] = "| \"... ¡Así fue como le di una mano a Bert para resolver el asesinato y le devolví la cabeza al mago, resolviendo el enigma de los siempre llenos pozos de arena!",
        ["| \"A victim dies and a murderer is punished - that is balance."] = "| \"La víctima muere y el asesino es castigado: eso es equilibrio.",
        ["| Harbinger (miniquest)"] = "| Heraldo (minimisión)",
        ["| \"I embarked on a voyage to the scholarly island of Tuai Leit. It didn't go entirely according to plan, and my ship was severely damaged by a mysterious new adversary."] = "| \"Me embarqué en un viaje a la erudita isla de Tuai Leit. No salió del todo según lo planeado y mi barco resultó gravemente dañado por un nuevo y misterioso adversario\".",
        ["| Haunted Mine"] = "| Mina embrujada",
        ["| \"...And from the legendary crystals I cut a salve shard to fight the undead."] = "| \"...Y de los cristales legendarios corté un fragmento de ungüento para luchar contra los no-muertos\".",
        ["| Hazeel Cult (Ceril's side)"] = "| Culto Hazeel (lado de Ceril)",
        ["| \"...that was how I foiled the cultists in their plan to resurrect Hazeel."] = "| \"...así fue como frustré a los cultistas en su plan de resucitar a Hazeel.",
        ["| \"The Mahjarrat are a vile race. You would do well to steer clear of them."] = "| \"Los Mahjarrat son una raza vil. Harías bien en mantenerte alejado de ellos\".",
        ["| Hazeel Cult (Hazeel's side)"] = "| Culto Hazeel (lado de Hazeel)",
        ["| \"...So that was how I helped return Hazeel to his followers."] = "| \"... Así fue como ayudé a que Hazeel regresara a sus seguidores\".",
        ["| Head of the Family (miniquest)"] = "| Jefe de familia (minimisión)",
        ["| \"I helped the moai of Waiko and Aminishi resolve their troubled long-distance relationship."] = "| \"Ayudé a los moai de Waiko y Aminishi a resolver su problemática relación a larga distancia\".",
        ["| \"...and as the prehistoric abyssal fell back into the portal, we learned that Xenia may have already started the elder gods re-awakening."] = "| \"...y cuando el abisal prehistórico volvió a caer en el portal, supimos que es posible que Xenia ya haya iniciado el despertar de los dioses mayores\".",
        ["| \"I am saddened that we have lost Xenia. She was a good woman in her own way. But perhaps you were right to stop her."] = "| \"Me entristece que hayamos perdido a Xenia. Ella era una buena mujer a su manera. Pero tal vez hiciste bien en detenerla\".",
        ["| Hearts of Sanguine"] = "| Corazones de sangre",
        ["| \"With the aid of a vampyre named Anya, I destroyed the sanguine heart near Wendlewick and saved the village from the blight it was spreading."] = "| \"Con la ayuda de un vampyre llamado Anya, destruí el corazón sanguíneo cerca de Wendlewick y salvé a la aldea de la plaga que se estaba propagando\".",
        ["| Heartstealer"] = "| ladrón de corazones",
        ["| \"We may not have stolen a priceless ruby, but I helped Annette steal Caelyn's heart."] = "| \"Puede que no hayamos robado un rubí de valor incalculable, pero ayudé a Annette a robar el corazón de Caelyn\".",
        ["| Heralds of Crimson"] = "| Heraldos de carmesí",
        ["| \"...and so we teamed up to defeat the Ghrazi Blood Knights! Unfortunately, one of them escaped and closed the portal, stranding Anya on Gielinor."] = "| \"... ¡y así nos unimos para derrotar a los Caballeros de Sangre Ghrazi! Desafortunadamente, uno de ellos escapó y cerró el portal, dejando varado a Anya en Gielinor\".",
        ["| \"You do make some questionable friends, but I am glad to hear Havenhythe is well protected."] = "| \"Haces algunos amigos cuestionables, pero me alegra saber que Havenhythe está bien protegida\".",
        ["| Hermit Permits"] = "| Permisos Hermit",
        ["| \"I helped the villagers of Wendlewick to solve their crab problem."] = "| \"Ayudé a los aldeanos de Wendlewick a resolver el problema de los cangrejos\".",
        ["| Helping Laniakea (miniquest)"] = "| Ayudando a Laniakea (minimisión)",
        ["| \"I helped Laniakea find a Fugu so she could make a very potent poison."] = "| \"Ayudé a Laniakea a encontrar un Fugu para que pudiera producir un veneno muy potente\".",
        ["| Hero's Welcome"] = "| Bienvenida del héroe",
        ["| \"...but in the end V is still dead, even though the  Tarshak paid the price."] = "| \"...pero al final V sigue muerto, a pesar de que Tarshak pagó el precio\".",
        ["| \"The world is safer for that monster's passing. I am sure V would be proud."] = "| \"El mundo es más seguro tras la muerte de ese monstruo. Estoy seguro de que V estaría orgulloso\".",
        ["| Heroes' Quest"] = "| Búsqueda de héroes",
        ["| \"...so, after I had retrieved all the items, I became a member of the Heroes' Guild!"] = "| \"...así que, después de haber recuperado todos los artículos, ¡me convertí en miembro de Heroes' Guild!",
        ["| Holy Grail"] = "| Santo Grial",
        ["| \"...and out of all the Knights of the Round Table, it was I who found the Holy Grail."] = "| \"...y de todos los Caballeros de la Mesa Redonda, fui yo quien encontró el Santo Grial.",
        ["| Hopespear's Will (miniquest)"] = "| Voluntad de Hopespear (minimisión)",
        ["| \"I buried five goblin priests for the ghost of Hopespear, laying their souls to rest."] = "| \"Enterré a cinco sacerdotes duendes para el fantasma de Hopespear, haciendo descansar sus almas\".",
        ["| Horror from the Deep"] = "| Terror desde las profundidades",
        ["| \"...And that was the end of the horror from the deep!"] = "| \"... ¡Y ese fue el fin del horror de las profundidades!",
        ["| Housing of Parliament"] = "| Vivienda del Parlamento",
        ["| \"I cleaned up the City of Um's owlery, and enticed some owls back to the city."] = "| \"Limpié la lechucería de City of Um y atraje a algunas lechuzas a la ciudad\".",
        ["| Hunt for Red Raktuber"] = "| Caza del Raktuber rojo",
        ["| \"...and then Larry was kidnapped by the penguins and I had to swim on a polar bear to get back to the mainland."] = "| \"...y luego Larry fue secuestrado por los pingüinos y tuve que nadar sobre un oso polar para regresar al continente\".",
        ["| \"Those penguins are shifty characters."] = "| \"Esos pingüinos son personajes astutos\".",
        ["| The Hunt for Surok (miniquest)"] = "| La caza de Surok (minimisión)",
        ["| \"I hunted down Surok Magis in the Chaos Tunnels, and encountered a big ork."] = "| \"Perseguí a Surok Magis en los Túneles del Caos y me encontré con un gran orko\".",
        ["| Icthlarin's Little Helper"] = "| El pequeño ayudante de Icthlarin",
        ["| \"...And, with the amulet I received, I could understand the language of cats!"] = "| \"... ¡Y con el amuleto que recibí, pude entender el lenguaje de los gatos!",
        ["| \"It is a rare privilege to understand the language of those beings. You should listen carefully to all they have to say - but not believe too much of it."] = "| \"Es un raro privilegio entender el lenguaje de esos seres. Hay que escuchar atentamente todo lo que tienen que decir, pero no creer demasiado en ello\".",
        ["| Imp Catcher"] = "| Cazador de diablillos",
        ["| \"...took some time, but I finally got all four beads back, and Mizgog gave me my reward."] = "| \"...me tomó algo de tiempo, pero finalmente recuperé las cuatro cuentas y Mizgog me dio mi recompensa\".",
        ["| \"Imps! I remember the age of great war, when armies of Zamorak's imps bloodied the ankles of the other gods' creatures."] = "| \"¡Diablillos! Recuerdo la época de las grandes guerras, cuando los ejércitos de diablillos de Zamorak ensangrentaban los tobillos de las criaturas de los otros dioses\".",
        ["| Impressing the Locals"] = "| Impresionando a los lugareños",
        ["| \"...and so now I'm the captain of the Sarim's Revenge, with a motley crew under my command."] = "| \"...y ahora soy el capitán del Sarim's Revenge, con una tripulación heterogénea bajo mi mando\".",
        ["| \"Guthix visited these Wushanko Isles when he first arrived, but he did not tell me much of his time there."] = "| \"Guthix visitó estas islas Wushanko cuando llegó por primera vez, pero no me contó mucho sobre su tiempo allí\".",
        ["| In Aid of the Myreque"] = "| En ayuda del Myreque",
        ["| \"...Veliaf was very impressed by the Rod of Ivandis, and I can use it to kill juves and the juvinates!"] = "| \"...Veliaf quedó muy impresionado con la Vara de Ivandis, ¡y puedo usarla para matar a los juves y a los juvinates!",
        ["| In Memory of the Myreque (miniquest)"] = "| En Memoria del Myreque (minimisión)",
        ["| \"I constructed a memorial to the Myreque."] = "| \"Construí un monumento al Myreque\".",
        ["| In Pyre Need"] = "| En necesidad de pira",
        ["| \"...And that was how I helped the phoenix to be reborn!"] = "| \"... ¡Y así fue como ayudé al fénix a renacer!",
        ["| \"You have performed a service to one of the creatures of Guthix, and for that I thank you."] = "| \"Has prestado un servicio a una de las criaturas de Guthix, y te lo agradezco\".",
        ["| In Search of the Myreque"] = "| En busca del Myreque",
        ["| \"...so, I suppose it was my fault that the young members of the Myreque were killed by Vanstrom."] = "| \"...entonces, supongo que fue mi culpa que los jóvenes miembros del Myreque fueran asesinados por Vanstrom.",
        ["| The Jack of Spades"] = "| La jota de espadas",
        ["| \"...but it was just Ozan in disguise, and he only wanted to meet away from watchful eyes and to show me the corruption in Menaphos."] = "| \"...pero era sólo Ozan disfrazado, y él sólo quería encontrarse lejos de miradas atentas y mostrarme la corrupción en Menaphos\".",
        ["| \"The souls of humans are so easily corrupted, especially of those who have no friends."] = "| \"Las almas de los humanos se corrompen muy fácilmente, especialmente las de aquellos que no tienen amigos.",
        ["| Jed Hunter (miniquest)"] = "| Jed Hunter (minimisión)",
        ["| \"I hunted down and defeated Jed, and claimed vengeance for the people of Port Sarim."] = "| \"Perseguí y derroté a Jed, y reclamé venganza para la gente de Port Sarim\".",
        ["| Jungle Potion"] = "| Poción de la selva",
        ["| \"...and once I had gathered all the herbs, Trufitus Shakaya was able to commune with his gods."] = "| \"...y una vez que reuní todas las hierbas, Trufitus Shakaya pudo comunicarse con sus dioses\".",
        ["| Kennith's Concerns"] = "| Preocupaciones de Kennith",
        ["| \"...And my last step was to bring Kennith his toy train."] = "| \"...Y mi último paso fue traerle a Kennith su tren de juguete\".",
        ["| Kili Row"] = "| Fila Kili",
        ["| \"I met the City of Um's blacksmith, and learned how to upgrade my necromancer's equipment."] = "| \"Conocí al herrero de City of Um y aprendí a mejorar mi equipo de nigromante\".",
        ["| Kindred Spirits"] = "| Espíritus afines",
        ["| \"I escaped Sliske's twisted game with the Barrows Brothers. Sadly Linza was turned into a wight in the process."] = "| \"Escapé del retorcido juego de Sliske con los hermanos Barrows. Lamentablemente, Linza se convirtió en un monstruo en el proceso\".",
        ["| King of the Dwarves"] = "| rey de los enanos",
        ["| \"...So now Veldaban is the king of the dwarves"] = "| \"...Así que ahora Veldaban es el rey de los enanos",
        ["| \"...You may have had noble motives, but you have robbed the rightful king of his throne. This action is not balanced."] = "| \"...Puede que hayas tenido motivos nobles, pero le has robado el trono al legítimo rey. Esta acción no es equilibrada\".",
        ["| King's Ransom"] = "| El rescate del rey",
        ["| \"...And after I had used the spell to free King Arthur, I disguised him as a guard so he could escape."] = "| \"...Y después de haber usado el hechizo para liberar a King Arthur, lo disfrazé de guardia para que pudiera escapar\".",
        ["| The Knight's Sword"] = "| La espada del caballero",
        ["| \"...that was how I found the Imcando Dwarves and got the knight a new sword."] = "| \"... así fue como encontré a los Enanos Imcando y le conseguí al caballero una nueva espada\".",
        ["| Koschei's Troubles (miniquest)"] = "| Los problemas de Koschei (minimisión)",
        ["| \"I discovered the mysterious origin of Koschei the Deathless."] = "| \"Descubrí el misterioso origen de Koschei el Inmortal.",
        ["| Lair of Tarn Razorlor (miniquest)"] = "| Guarida de Tarn Razorlor (minimisión)",
        ["| \"I defeated Tarn Razorlor and learned his secret knowledge by reading the diary in his living quarters."] = "| \"Derroté a Tarn Razorlor y aprendí su conocimiento secreto leyendo el diario en su vivienda\".",
        ["| Land of the Goblins"] = "| Tierra de los duendes",
        ["| \"...Oldak and I escaped from Yu'biusk before the portal closed, but Zanik was trapped in the box."] = "| \"...Oldak y yo escapamos de Yu'biusk antes de que se cerrara el portal, pero Zanik quedó atrapado en la caja\".",
        ["| (Before The Chosen Commander)"] = "| (Ante el comandante elegido)",
        ["| Legacy of Seergaze"] = "| El legado de la mirada vidente",
        ["| \"...I slew a Vyrewatch, as Safalaan had asked, and took the corpse to the Paterdomus Columbarium to cremate it. In gratitude the spirit left a key which allowed me to gain access to their worldly wealth. My first prize was a blood talisman!"] = "| \"... Maté un Vyrewatch, como me había pedido Safalaan, y llevé el cadáver al Columbario Paterdomus para cremarlo. En agradecimiento, el espíritu dejó una llave que me permitió acceder a sus riquezas mundanas. ¡Mi primer premio fue un talismán de sangre!",
        ["| \"With your mind so focused on material wealth, I worry whether the intrigues overshadowing your discoveries are being properly looked into. Drakan, I fear, is a whole world of trouble for which you are ill-prepared."] = "| \"Con tu mente tan concentrada en la riqueza material, me preocupa si las intrigas que ensombrecen tus descubrimientos están siendo investigadas adecuadamente. Me temo que Drakan es todo un mundo de problemas para los cuales no estás preparado\".",
        ["| Legends' Quest"] = "| Búsqueda de leyendas",
        ["| \"...and when I had completed all the tasks, I became a member of the Legends' Guild!"] = "| \"...y cuando hube completado todas las tareas, ¡me convertí en miembro de Legends' Guild!",
        ["| Let Them Eat Pie"] = "| Déjalos comer pastel",
        ["| \"...and in the end Rolo's food stores were given to the people of Burthorpe to enjoy."] = "| \"...y al final las tiendas de alimentos de Rolo fueron entregadas a la gente de Burthorpe para que las disfrutara\".",
        ["| \"So the hungry became fed and the overfed became...well, empty. Guthix might not approve of the methods used, but a balance has been struck."] = "| \"Así que los hambrientos se alimentaron y los sobrealimentados quedaron... bueno, vacíos. Puede que Guthix no apruebe los métodos utilizados, pero se ha logrado un equilibrio\".",
        ["| The Light Within"] = "| La luz interior",
        ["| \"I helped return the light of Seren to the world by reforging her body and soul."] = "| \"Ayudé a devolver la luz de Seren al mundo reformando su cuerpo y su alma\".",
        ["| The Lord of Vampyrium"] = "| El Señor del Vampyrium",
        ["| \"...so with most of the Myreque killed by Lord Drakan, Veliaf has given up hope, and Ivan has returned to Paterdomus. The Myreque are broken."] = "| \"... así que con la mayoría de los Myreque asesinados por Lord Drakan, Veliaf ha perdido la esperanza y Ivan ha regresado a Paterdomus. Los Myreque están rotos\".",
        ["| \"Even in death, the Myreque light the way for the people of Morytania. Anything is lost can be found again, even hope. Stay strong, Player."] = "| \"Incluso en la muerte, los Myreque iluminan el camino para la gente de Morytania. Todo lo que se pierde se puede encontrar de nuevo, incluso la esperanza. Mantente fuerte, Player\".",
        ["| Lost City"] = "| ciudad perdida",
        ["| \"...And when I entered the door carrying the Dramen Staff, I was transported to a whole new world - a world populated by magical fairies!"] = "| \"...Y cuando entré por la puerta llevando el Dramen Staff, fui transportado a un mundo completamente nuevo: ¡un mundo poblado por hadas mágicas!",
        ["| Lost Her Marbles (miniquest)"] = "| Perdió sus canicas (minimisión)",
        ["| The Lost Toys (miniquest)"] = "| Los juguetes perdidos (minimisión)",
        ["| \"I hunted down and hugged 13 vampyre plushies hidden throughout Morytania."] = "| \"Busqué y abracé 13 peluches de vampyre escondidos por todo Morytania\".",
        ["| The Lost Tribe"] = "| La tribu perdida",
        ["| \"...Sigmund was dismissed, and the duke and the ruler of the cave goblins signed a peace treaty."] = "| \"...Sigmund fue despedido, y el duque y el gobernante de los duendes de las cavernas firmaron un tratado de paz\".",
        ["| \"The Dorgueshuun goblins have been good neighbours during my vigil here. They are a timid race, but not cowardly, and I am glad they have the peace they desire."] = "| \"Los duendes Dorgueshuun han sido buenos vecinos durante mi vigilia aquí. Son una raza tímida, pero no cobarde, y me alegro de que tengan la paz que desean\".",
        ["| Love Story"] = "| Historia de amor",
        ["| \"...so the Wise Old Man and Zenevivia are living happily ever after, but they still wouldn't give me that hat!"] = "| \"...así que Wise Old Man y Zenevivia viven felices para siempre, ¡pero aun así no me dieron ese sombrero!",
        ["A hat is just a hat Player."] = "Un sombrero es sólo un sombrero Player.",
        ["To which you reply: \"Grr!"] = "A lo que respondes: \"¡Grr!",
        ["| Lunar Diplomacy"] = "| Diplomacia lunar",
        ["| \"...so I defeated my mirror image, won the respect of the Moon Clan and persuaded them to communicate with the Fremennik."] = "| \"... así que derroté a mi imagen reflejada, me gané el respeto del Clan de la Luna y los persuadí para que se comunicaran con los Fremennik\".",
        ["| \"The Moon Clan's reliance on magic is no more balanced than the Fremennik's hatred of it."] = "| \"La dependencia del Clan de la Luna en la magia no es más equilibrada que el odio de los Fremennik hacia ella.",
        ["| Making History"] = "| Haciendo historia",
        ["| \"...so the outpost became a museum."] = "| \"...así que el puesto de avanzada se convirtió en un museo\".",
        ["| \"History is the greatest story of all, and it is very good that you have helped to preserve it."] = "| \"La historia es la historia más grande de todas y es muy bueno que hayan ayudado a preservarla\".",
        ["| Mahjarrat Memories (miniquest)"] = "| Recuerdos de Mahjarrat (minimisión)",
        ["| \"I helped Kharshai the Mahjarrat recover 15 memories of his kin."] = "| \"Ayudé a Kharshai el Mahjarrat a recuperar 15 recuerdos de sus parientes\".",
        ["| Meeting History"] = "| Historial de reuniones",
        ["| \"...And that was how I travelled into the past and met the first family to arrive on Gielinor."] = "| \"...Y así fue como viajé al pasado y conocí a la primera familia que llegó a Gielinor\".",
        ["| \"You have been truly blessed by Guthix. I can only dream of such an honour."] = "| \"Has sido realmente bendecido por Guthix. Sólo puedo soñar con tal honor\".",
        ["| Merlin's Crystal"] = "| El cristal de Merlín",
        ["| \"...and when I told King Arthur that I had single-handedly freed Merlin from his crystal prison, he made me a knight of the Round Table!"] = "| \"...y cuando le dije a King Arthur que yo solo había liberado a Merlín de su prisión de cristal, ¡me nombró caballero de la Mesa Redonda!",
        ["| The Mighty Fall (sparing Zanik)"] = "| La poderosa caída (ahorrando a Zanik)",
        ["| \"...and then I defeated Graardor, and so Zanik became leader of the Bandosians. She led many of them away on an exodus into Yu'biusk, hoping to find either peace or death."] = "| \"...y luego derroté a Graardor, y así Zanik se convirtió en líder de los bandosianos. Ella condujo a muchos de ellos en un éxodo a Yu'biusk, con la esperanza de encontrar la paz o la muerte\".",
        ["| \"I will miss Zanik. I am shamed by my condemnation of her. In the end her heroism shone through. Between you, you have neutralised the remaining Bandosian imbalance."] = "| \"Extrañaré a Zanik. Me avergüenza haberla condenado. Al final, su heroísmo brilló. Entre ustedes, habéis neutralizado el desequilibrio bandosiano restante\".",
        ["| The Mighty Fall (killing Zanik)"] = "| La poderosa caída (matando a Zanik)",
        ["| \"...and then, uh, Zanik died, and so Graardor became leader of the Bandosians. Some of them returned to Gielinor and some remained on Yu'biusk"] = "| \"...y luego, eh, Zanik murió, y así Graardor se convirtió en líder de los bandosianos. Algunos de ellos regresaron a Gielinor y otros permanecieron en Yu'biusk",
        ["| \"I will miss Zanik. I am shamed by my condemnation of her. At least you seem to have neutralised the Bandosian imbalance. Graardor will not be much of a leader."] = "| \"Extrañaré a Zanik. Me avergüenza haberla condenado. Al menos parece que has neutralizado el desequilibrio bandosiano. Graardor no será un gran líder\".",
        ["| Missing My Mummy"] = "| Extrañando a mi mamá",
        ["| \"...So, I was able to restore the mummy enough to make sense of what she was saying."] = "| \"... Entonces, pude restaurar la momia lo suficiente como para darle sentido a lo que estaba diciendo\".",
        ["| \"To have your body, spirit and shadow scattered by time must be a terrible thing. It is good that you have helped ease the mummy's torment by restoring her."] = "| \"Tener tu cuerpo, espíritu y sombra esparcidos por el tiempo debe ser algo terrible. Es bueno que hayas ayudado a aliviar el tormento de la momia restaurándola\".",
        ["| Missing, Presumed Death"] = "| Desaparecido, presunta muerte",
        ["| \"...and that's how Icthlarin and I saved Death. But not before Sliske could deliver his challenge: that the person to kill the most gods would receive the Stone of Jas."] = "| \"...y así fue como Icthlarin y yo salvamos a la Muerte. Pero no antes de que Sliske pudiera cumplir su desafío: que la persona que matara a la mayor cantidad de dioses recibiría la Piedra de Jas\".",
        ["| \"I'm glad you found Death. He is a devoted Guardian of Guthix. Alas, it seems that with Guthix gone and his edicts no longer in place, another God Wars is on the horizon."] = "| \"Me alegro de que hayas encontrado a la Muerte. Es un devoto guardián de Guthix. Por desgracia, parece que con Guthix desaparecido y sus edictos ya no vigentes, otra Guerra de Dios está en el horizonte\".",
        ["| Monk's Friend"] = "| Amigo del monje",
        ["| \"...so the monks had a drunken party to celebrate the child's birthday."] = "| \"... entonces los monjes organizaron una fiesta de borracheras para celebrar el cumpleaños del niño\".",
        ["Mirth should not be taken to excess. These Saradominists have never understood the importance of balance."] = "La alegría no debe llevarse al exceso. Estos saradoministas nunca han entendido la importancia del equilibrio\".",
        ["To which you reply: \"Also, although they'd brought plenty of alcohol, I never saw them getting anything for the child to drink."] = "A lo que usted responde: \"Además, aunque habían traído mucho alcohol, nunca los vi trayendo nada para que bebiera el niño\".",
        ["| \"...So I defeated the Jungle Demon and stopped the Monkeys' plot to take over Karamja."] = "| \"... Así que derroté al Demonio de la Selva y detuve el complot de los Monos para apoderarse de Karamja\".",
        ["I see they couldn't make a monkey out of you!"] = "¡Veo que no podrían convertirte en un mono!",
        ["To which you reply: \"Well, actually, I was a monkey for a bit."] = "A lo que respondes: \"Bueno, en realidad, fui mono por un tiempo\".",
        ["| Mountain Daughter"] = "| Hija de la montaña",
        ["| \"...I was too late to save the chieftan's daughter, but at least I gave her a proper burial."] = "| \"... Llegué demasiado tarde para salvar a la hija del cacique, pero al menos le di un entierro adecuado\".",
        ["| \"Brief is life, but more precious if its passing is properly honoured."] = "| \"Breve es la vida, pero más preciosa si se honra adecuadamente su paso.",
        ["| Mourning's End Part I"] = "| Mourning's End Parte I",
        ["| \"...after I had told the Head Mourner I had poisoned the city, he told me about the lost temple in the mountains that they're searching for."] = "| \"...después de haberle dicho al Jefe Mourner que había envenenado la ciudad, él me habló del templo perdido en las montañas que estaban buscando\".",
        ["| Mourning's End Part II"] = "| Mourning's End Parte II",
        ["| \"...What kind of twisted mind would come up with the light-beam puzzle in that temple?"] = "| \"... ¿A qué clase de mente retorcida se le ocurriría el rompecabezas del rayo de luz en ese templo?",
        ["| Murder on the Border"] = "| Asesinato en la frontera",
        ["| \"I solved the mystery behind Duke Hoarse's murder, and unraveled a plot to assassinate King Roald."] = "| \"Resolví el misterio detrás del asesinato de Duke Hoarse y desentrañé un complot para asesinar a King Roald\".",
        ["| Murder Mystery"] = "| Misterio del asesinato",
        ["| \"...And that's how I solved the murder of Lord Sinclair."] = "| \"...Y así es como resolví el asesinato de Lord Sinclair.",
        ["| My Arm's Big Adventure"] = "| La gran aventura de My Arm",
        ["| \"...My Arm is still up on that rooftop, growing goutweed in his little farming patch!"] = "| \"...¡My Arm todavía está en esa azotea, cultivando gota en su pequeño huerto!",
        ["| \"it is good that a troll wishes to study the complex skill that is Farming."] = "| \"Es bueno que un troll desee estudiar la compleja habilidad que es Farming\".",
        ["| Myths of the White Lands"] = "| Mitos de las Tierras Blancas",
        ["| \"...I went through the snow imps' prank. Explorer Jack had no idea the 'riches' were really frozen yeti dung!"] = "| \"...Pasé por la broma de los diablillos de nieve. ¡Explorer Jack no tenía idea de que las 'riquezas' eran en realidad estiércol de yeti congelado!",
        ["| \"It is pleasant to hear that the snow imps are still up to their old tricks."] = "| \"Es agradable saber que los diablillos de las nieves siguen haciendo sus viejos trucos.",
        ["| \"I listened to Skaldrun's saga of Moia, the half-Mahjarrat daughter of Lucien, and her descent into Daemonheim."] = "| \"Escuché la saga de Skaldrun sobre Moia, la hija medio Mahjarrat de Lucien, y su descenso a Daemonheim\".",
        ["| Nature Spirit"] = "| Naturaleza Spirit",
        ["| \"...and that was how I helped Filliman Tarlock transform into a nature spirit."] = "| \"...y así fue como ayudé a Filliman Tarlock a transformarse en un espíritu de la naturaleza\".",
        ["| \"It is good that you helped a servant of Guthix to his rest."] = "| \"Es bueno que hayas ayudado a descansar a un sirviente de Guthix\".",
        ["| \"After being killed by an animated sword, and a quick visit to Death's office, Death took me to the City of Um. There we witnessed Rasial, the first necromancer, stealing all of its souls."] = "| \"Después de ser asesinado por una espada animada y de una rápida visita a la oficina de la Muerte, la Muerte me llevó al City of Um. Allí fuimos testigos de Rasial, the first necromancer, robando todas sus almas\".",
        ["| The Needle Skips"] = "| La aguja salta",
        ["| \"...and that was how I learned the secrets of the Needle and the impact on that poor family."] = "| \"...y así fue como aprendí los secretos de la Aguja y el impacto en esa pobre familia.",
        ["| \"Elder artefacts can be dangerous things, in more ways that the physical."] = "| \"Los artefactos antiguos pueden ser cosas peligrosas, en más formas que las físicas\".",
        ["| New Foundations"] = "| Nuevas fundaciones",
        ["| \"I helped King Roald establish a new Duchy in the Wilderness which I now manage."] = "| \"Ayudé a King Roald a establecer un nuevo Ducado en Wilderness que ahora administro\".",
        ["| Nomad's Elegy"] = "| Elegía del nómada",
        ["| \"...allowing the souls of the dead to move on without being stolen by Nomad."] = "| \"...permitiendo que las almas de los muertos sigan adelante sin ser robadas por Nomad.",
        ["| \"A noble goal. His false Guthix and wicked scheme brought great unbalance to the underworld."] = "| \"Un objetivo noble. Su falso Guthix y su perverso plan trajeron un gran desequilibrio al inframundo\".",
        ["| Nomad's Requiem"] = "| Réquiem del nómada",
        ["| \"...And, finally, Nomad fell before me."] = "| \"...Y, finalmente, Nomad cayó ante mí.",
        ["| \"Impressive...Most impressive."] = "| \"Impresionante...Muy impresionante.",
        ["| Observatory Quest"] = "| Búsqueda del Observatorio",
        ["| \"...and, when I had fixed the telescope, I looked through and saw the stars."] = "| \"...y, cuando hube arreglado el telescopio, miré a través de él y vi las estrellas.",
        ["| \"It is long since I have seen the stars."] = "| \"Hace mucho que no veo las estrellas.",
        ["| Ode of the Devourer"] = "| Oda del Devorador",
        ["| \"With the aid of Icthlarin and Zemouregal, I cleansed the Gate of Elidinis and saved Bill and the citizens of Al Kharid from Amascut's curse."] = "| \"Con la ayuda de Icthlarin y Zemouregal, limpié la Puerta de Elidinis y salvé a Bill y a los ciudadanos de Al Kharid de la maldición de Amascut\".",
        ["| Olaf's Quest"] = "| La búsqueda de Olaf",
        ["| \"...It wasn't easy, but I managed to convince Olaf's family that he was a good navigator."] = "| \"...No fue fácil, pero logré convencer a la familia de Olaf de que era un buen navegante\".",
        ["| Once Upon a Slime"] = "| Érase una vez un limo",
        ["| \"\"I helped Peter eliminate the King Slime threat.\";"] = "| \"\"Ayudé a Peter a eliminar la amenaza King Slime.\";",
        ["| Once Upon a Time in Gielinor"] = "| Érase una vez en Gielinor",
        ["| \"...and that's how Relomia went from being Sliske's emissary to a renowned heroic adventurer."] = "| \"...y así fue como Relomia pasó de ser el emisario de Sliske a un reconocido heroico aventurero\".",
        ["| \"It goes to show the transformative power of stories. Thank you for sharing this with me."] = "| \"Esto demuestra el poder transformador de las historias. Gracias por compartir esto conmigo\".",
        ["| One Foot in the Grave (miniquest)"] = "| Un pie en la tumba (minimisión)",
        ["| \"I lent the Yanille wizards' guild another hand by finding (most of) Clarence's remaining body parts. We managed to put all but one foot in the grave, and I had to hand it to the Yanille wizards...it was quite a touching funeral."] = "| \"Le presté otra mano al gremio de magos de Yanille al encontrar (la mayoría de) las partes restantes del cuerpo de Clarence. Logramos poner todos menos un pie en la tumba, y tuve que entregárselo a los magos de Yanille... fue un funeral bastante conmovedor\".",
        ["| One of a Kind (siding with Kerapac)"] = "| Único en su clase (del lado de Kerapac)",
        ["| \"...and after defeating the Echo of an Elder God, I encouraged Hannibus to return with Kerapac and endure stasis so that he had a chance to save his people."] = "| \"...y después de derrotar al Eco de un Dios Antiguo, animé a Hannibus a regresar con Kerapac y soportar la estasis para tener la oportunidad de salvar a su pueblo\".",
        ["| \"You fought the will of an Elder God and allowed the Dragonkin to experiment on the last of the Dragon Riders? I fear that there might be unforeseen repercussions Player."] = "| \"¿Luchaste contra la voluntad de un Dios anciano y permitiste que los Dragonkin experimentaran con el último de los Jinetes de Dragón? Me temo que podría haber repercusiones imprevistas Player\".",
        ["| One of a Kind (siding with Sharrigan)"] = "| Único en su clase (del lado de Sharrigan)",
        ["| \"...and after defeating the Echo of an Elder God, I encouraged Hannibus to return with his people and allow himself to rest amongst his own kind."] = "| \"...y después de derrotar al Eco de un Dios Antiguo, animé a Hannibus a regresar con su gente y permitirse descansar entre los de su propia especie\".",
        ["| \"The Ilujanka sound like a noble species, it is a shame that they are dying out. I wonder if this is the last we'll see of them however."] = "| \"Los Ilujanka parecen una especie noble, es una pena que estén desapareciendo. Sin embargo, me pregunto si será la última vez que los veremos.",
        ["| One Piercing Note"] = "| Una nota penetrante",
        ["| \"...and that's how I caught the Citharede Abbey murderer."] = "| \"...y así fue como atrapé al asesino de Citharede Abbey\".",
        ["| \"Of course, I worked out who the murderer was half way through your story."] = "| \"Por supuesto, descubrí quién era el asesino a mitad de tu historia\".",
        ["| One Small Favour"] = "| Un pequeño favor",
        ["| \"...I still can't believe how long that 'one small favour' took me!"] = "| \"...¡Todavía no puedo creer cuánto tiempo me tomó ese 'un pequeño favor'!",
        ["| Osseous Rex"] = "| Óseo Rex",
        ["| \"...and that's how I helped resurrect the old matriarch, Osseous."] = "| \"...y así fue como ayudé a resucitar a la vieja matriarca, Osseous\".",
        ["| \"A great being walks among us once more."] = "| \"Un gran ser camina entre nosotros una vez más.",
        ["| Our Man in the North"] = "| Nuestro hombre en el norte",
        ["| \"...and now everyone knows that Osman is the rightful ruler of Menaphos, but also has been exiled from Al Kharid."] = "| \"...y ahora todo el mundo sabe que Osman es el gobernante legítimo de Menaphos, pero también ha sido exiliado de Al Kharid\".",
        ["| \"While in some cultures blood might decree a right to rule, it rarely suggests ability or competence."] = "| \"Si bien en algunas culturas la sangre puede decretar el derecho a gobernar, rara vez sugiere capacidad o competencia\".",
        ["| The Path of Glouphrie"] = "| El camino de Gloufrie",
        ["| \"...The room filled up with gas and I nearly died, but Hazelmere came to my rescue."] = "| \"...La habitación se llenó de gas y casi muero, pero Hazelmere vino a rescatarme\".",
        ["| \"A truly exciting tale of failing and needing to be rescued."] = "| \"Una historia realmente emocionante sobre el fracaso y la necesidad de ser rescatados.",
        ["| Perils of Ice Mountain"] = "| Peligros de la montaña de hielo",
        ["| \"...So now Nurmof's pickaxe machine is powered by a windmill."] = "| \"... Así que ahora la máquina pico de Nurmof funciona con un molino de viento\".",
        ["| \"You acted as a true servant of Guthix in this matter."] = "| \"Actuaste como un verdadero servidor de Guthix en este asunto\".",
        ["| Pharaoh's Folly"] = "| La locura del faraón",
        ["| \"...and that's how I helped overthrow the Pharaoh of Menaphos. Again."] = "| \"...y así es como ayudé a derrocar al faraón de Menaphos. Otra vez\".",
        ["| \"We can hope that the cycle of destruction in Menaphos is broken."] = "| \"Podemos esperar que se rompa el ciclo de destrucción en Menaphos\".",
        ["| 'Phite Club"] = "| 'Club de Fito",
        ["| \"...and then I defeated the Pharoah  and ripped off his mask, revealing the corruption beneath."] = "| \"...y luego derroté al Faraón y le arranqué la máscara, revelando la corrupción que había debajo\".",
        ["| \"But the problem is that the corruption didn't end at the Pharaoh..."] = "| \"Pero el problema es que la corrupción no terminó en el faraón...",
        ["| Pieces of Hate"] = "| pedazos de odio",
        ["| \"...and then I plugged the portal. Literally."] = "| \"...y luego conecté el portal. Literalmente\".",
        ["| \"Unspeakable horror lies beyond but, at least for now, you won't be having kittens."] = "| \"Más allá se esconde un horror indescriptible, pero, al menos por ahora, no tendrás gatitos\".",
        ["| Pirate's Treasure"] = "| El tesoro de Pirate",
        ["| \"...And when I dug in the middle of the park in Falador, I found the pirate's treasure!"] = "| \"... ¡Y cuando cavé en medio del parque en Falador, encontré el tesoro del pirata!",
        ["| \"Such is ever the folly of pirates, to bury their loot in the ground so that another can dig it up."] = "| \"Esa es siempre la locura de los piratas: enterrar su botín en la tierra para que otro pueda desenterrarlo\".",
        ["| \"...And that was how I rescued Elena from West Ardougne."] = "| \"...Y así fue como rescaté a Elena de West Ardougne\".",
        ["| Plague's End"] = "| El fin de la plaga",
        ["| \"...so at last the Dark Lord was dead, Ardougne was free of the plague, and the elves could re-grow their city!"] = "| \"... ¡así que por fin el Señor Oscuro estaba muerto, Ardougne estaba libre de la plaga y los elfos podían volver a hacer crecer su ciudad!",
        ["That was the end of - perhaps - your most epic adventure, Player."] = "Ese fue el final de, quizás, tu aventura más épica, Player\".",
        ["What started as the rescue of one woman took you across the mountains, and had you take part in the fates of kingdoms."] = "Lo que comenzó como el rescate de una mujer te llevó a través de las montañas y te hizo participar en el destino de los reinos\".",
        ["I can only admire your perseverance."] = "Sólo puedo admirar tu perseverancia\".",
        ["| Priest in Peril"] = "| Sacerdote en peligro",
        ["| \"...but with Drezel's help I was able to purify the River Salve."] = "| \"...pero con la ayuda de Drezel pude purificar el río Salve.",
        ["| Prince Ali Rescue (Removed)"] = "| Rescate del Príncipe Ali (eliminado)",
        ["| \"...And I had to disguise Prince Ali as a woman in order to smuggle him out!"] = "| \"... ¡Y tuve que disfrazar al Príncipe Ali de mujer para poder sacarlo clandestinamente!",
        ["| Princess and the Pauper"] = "| La princesa y el mendigo",
        ["| \"I took Princess for a very eventful walk around Varrock."] = "| \"Llevé a Princess a dar un paseo lleno de acontecimientos por Varrock\".",
        ["| The Prisoner of Glouphrie"] = "| El prisionero de Glouphrie",
        ["| \"...and that's how Bolrie was reunited with his family."] = "| \"...y así fue como Bolrie se reunió con su familia.",
        ["| \"Bringing families back together is a noble cause; however, what you tell me of the city of Arposandra is a crime towards nature and balance, and it worries me greatly."] = "| \"Reunir a las familias es una causa noble; sin embargo, lo que me cuentas de la ciudad de Arposandra es un crimen contra la naturaleza y el equilibrio, y me preocupa mucho.",
        ["| Purple Cat (miniquest)"] = "| Gato Púrpura (minimisión)",
        ["| \"In exchange for helping Wendy the witch, and her best friend, Lottie, I learned how to permanently dye my pet cat purple."] = "| \"A cambio de ayudar a la bruja Wendy y a su mejor amiga, Lottie, aprendí a hacer dye permanentemente de color morado a mi gato\".",
        ["| Quiet Before the Swarm"] = "| Tranquilo ante el enjambre",
        ["| \"...and I unlocked Korasi's memories and learned what happened on the ship."] = "| \"...y desbloqueé los recuerdos de Korasi y supe lo que pasó en el barco\".",
        ["| \"The Void Knights walk a fine line as they seek balance."] = "| \"Los Caballeros del Vacío caminan sobre una delgada línea mientras buscan el equilibrio\".",
        ["| Rag and Bone Man"] = "| Hombre de trapo y hueso",
        ["| \"...I fetched all the bones the Odd Old Man wanted and he gave me a reward!"] = "| \"... ¡Conseguí todos los huesos que Odd Old Man quería y me dio una recompensa!",
        ["| \"What could that man have wanted all those bones for? Collecting that many bones cannot be a balanced activity."] = "| \"¿Para qué podría haber querido ese hombre todos esos huesos? Recolectar tantos huesos no puede ser una actividad equilibrada\".",
        ["| Rat Catchers"] = "| Cazadores de ratas",
        ["| \"...those rat-catchers are odd people, but, by the end of it, I had caught a huge number of rats all over RuneScape!"] = "| \"...esos cazadores de ratas son gente rara, pero, al final, ¡había atrapado una gran cantidad de ratas por todo RuneScape!",
        ["| \"Rats are a highly unbalanced creature and it is right that their numbers be controlled."] = "| \"Las ratas son criaturas muy desequilibradas y es correcto controlar su número\".",
        ["| Rebuilding Edgeville (miniquest)"] = "| Reconstrucción de Edgeville (minimisión)",
        ["| \"I assisted Mandrith in cleaning up Edgeville after it was attacked by the dragonkin."] = "| \"Ayudé a Mandrith a limpiar Edgeville después de que fuera atacado por los dragonantes\".",
        ["| \"...after I had freed all the dinner guests, I was finally able to face the Culinaromancer and put an end to his mad schemes!"] = "| \"...después de haber liberado a todos los invitados a la cena, ¡finalmente pude enfrentar al Culinaromancer y poner fin a sus locos planes!",
        ["| \"That evil wizard's time spells sent a ripple through the fabric of balance. I am glad he is no longer at large!"] = "| \"Los hechizos de tiempo de ese mago malvado enviaron una onda a través del tejido del equilibrio. ¡Me alegro de que ya no esté suelto!",
        ["| Recipe for Disaster: Another Cook's Quest"] = "| Recipe for Disaster: La búsqueda de otro cocinero",
        ["| \"I helped the Lumbridge cook prepare a centennial feast in the castle banquet hall. Aris froze the council members in time to stop an evil magician from the past. This gave me time to hunt down some special recipes to protect them."] = "| \"Ayudé al cocinero de Lumbridge a preparar un banquete centenario en el salón de banquetes del castillo. Aris congeló a los miembros del consejo a tiempo para detener a un mago malvado del pasado. Esto me dio tiempo para buscar algunas recetas especiales para protegerlos\".",
        ["| Recipe for Disaster: Defeating the Culinaromancer"] = "| Recipe for Disaster: Derrotando al Culinaromancer",
        ["| \"I gave the Culinaromancer his just desserts and the Duke's party can go on unhindered."] = "| \"Le di al Culinaromancer sus postres justos y la fiesta del Duque puede continuar sin obstáculos\".",
        ["| Recipe for Disaster: Freeing Evil Dave"] = "| Recipe for Disaster: Liberando Evil Dave",
        ["| \"I freed Evil Dave."] = "| \"Liberé a Evil Dave\".",
        ["| Recipe for Disaster: Freeing King Awowogei"] = "| Recipe for Disaster: Liberando al Rey Awowogei",
        ["| \"I freed King Awowogei."] = "| \"Liberé al rey Awowogei\".",
        ["| Recipe for Disaster: Freeing Pirate Pete"] = "| Recipe for Disaster: Liberando Pirate Pete",
        ["| \"I freed Pirate Pete."] = "| \"Liberé a Pirate Pete\".",
        ["| Recipe for Disaster: Freeing Sir Amik Varze"] = "| Recipe for Disaster: Liberando Sir Amik Varze",
        ["| \"I freed Sir Amik Varze."] = "| \"Liberé a Sir Amik Varze\".",
        ["| Recipe for Disaster: Freeing Skrach Uglogwee"] = "| Recipe for Disaster: Liberando a Skrach Uglogwee",
        ["| \"I freed Skrach Uglogwee."] = "| \"Liberé a Skrach Uglogwee\".",
        ["| Transcript:Recipe for Disaster: Freeing the Goblin Generals"] = "| Transcripción:Recipe for Disaster: Liberando el Goblin Generals",
        ["| \"I freed the Goblin generals."] = "| \"Liberé el Goblin generals\".",
        ["| Recipe for Disaster: Freeing the Lumbridge Sage"] = "| Recipe for Disaster: Liberando el Lumbridge Sage",
        ["| \"I freed the Lumbridge Sage."] = "| \"Liberé el Lumbridge Sage\".",
        ["| Recipe for Disaster: Freeing the Mountain Dwarf"] = "| Recipe for Disaster: Liberando al enano de la montaña",
        ["| \"I freed Vestri the Mountain dwarf."] = "| \"Liberé a Vestri, el enano de la montaña\".",
        ["| Recruitment Drive"] = "| Campaña de reclutamiento",
        ["| \"...So I figured out their weird puzzles, and the Temple Knights asked me to join as an initiate member!"] = "| \"... ¡Así que descubrí sus extraños acertijos y los Caballeros del Templo me pidieron que me uniera como miembro iniciado!",
        ["| \"I have heard tales of these 'Temple Knights' from many years past. Be wary, their motivations are not what they might lead you to believe."] = "| \"He oído historias sobre estos 'Caballeros del Templo' de muchos años atrás. Ten cuidado, sus motivaciones no son las que podrían hacerte creer\".",
        ["| \"...I returned to tell King Lathas that the assassination was successful, and he rewarded me."] = "| \"... Regresé para decirle a King Lathas que el asesinato fue un éxito y él me recompensó\".",
        ["| Remains of the Necrolord"] = "| Restos del Necroseñor",
        ["| \"I worked with a former student of Rasial's, the infamous Lord Yudura, and learned about how power can be consolidated from rituals."] = "| \"Trabajé con un antiguo alumno de Rasial, el infame Lord Yudura, y aprendí cómo se puede consolidar el poder a partir de los rituales\".",
        ["| The Restless Ghost"] = "| El Restless Ghost",
        ["| \"...and once I returned the skull, the ghost was able to rest."] = "| \"...y una vez que le devolví el cráneo, el fantasma pudo descansar.",
        ["| \"A strange attachment to an item that has no use after one's death."] = "| \"Un extraño apego a un objeto que no tiene utilidad después de la muerte.",
        ["| Requiem for a Dragon"] = "| Réquiem por un dragón",
        ["| \"I faced off against Vengeance and Bilrach. Although I failed to stop their ritual, I was able to save a portion of Vorkath's soul and lay him to rest."] = "| \"Me enfrenté a Vengeance y Bilrach. Aunque no pude detener su ritual, pude salvar una parte del alma de Vorkath y dejarlo descansar\".",
        ["| Ritual of the Mahjarrat"] = "| Ritual del Mahjarrat",
        ["| \"...and, after the dragonkin killed Lucien, we hid the Stone of Jas again."] = "| \"...y, después de que los dragonantes mataron a Lucien, escondimos la Piedra de Jas nuevamente\".",
        ["| \"It is good that the stone is once more hidden away, but the damage has been done. Lucien was dangerous, but these dragonkin could end up destroying everything."] = "| \"Es bueno que la piedra esté escondida una vez más, pero el daño ya está hecho. Lucien era peligroso, pero estos dragonantes podrían terminar destruyendo todo\".",
        ["| River of Blood"] = "| río de sangre",
        ["| \"...and so my adventure with the Myreque in Morytania has finally reached its titanic conclusion. Many have died, many more have suffered, but I emerged victorious from those dark lands."] = "| \"...y así mi aventura con el Myreque en Morytania finalmente ha llegado a su titánica conclusión. Muchos han muerto, muchos más han sufrido, pero yo salí victorioso de esas tierras oscuras.",
        ["| \"I can't help but notice that your journey ended as it began...with King Roald in Varrock. To think your humble search for a priest in peril could end at the brink of war between Misthalin and Morytania."] = "| \"No puedo evitar notar que tu viaje terminó como comenzó... con King Roald en Varrock. Pensar que tu humilde búsqueda de un sacerdote en peligro podría terminar al borde de la guerra entre Misthalin y Morytania\".",
        ["| Rocking Out"] = "| Rockeando",
        ["| \"...And that was how I heard the tale of the death of Rabid Jack the pirate."] = "| \"...Y así fue como escuché la historia de la muerte del pirata Rabid Jack.",
        ["| \"The lives of pirates often make for good tales."] = "| \"Las vidas de los piratas a menudo dan lugar a buenas historias.",
        ["| Romeo & Juliet (Removed)"] = "| Romeo y Julieta (eliminado)",
        ["| \"...I gave the message to Romeo, but he misunderstood, so they never were together."] = "| \"...Le di el mensaje a Romeo, pero él no lo entendió, así que nunca estuvieron juntos\".",
        ["| \"Never was there a story of more woe that this of Juliet and her Romeo."] = "| \"Nunca hubo una historia más triste que la de Juliet y su Romeo\".",
        ["| \"...and when I planted the shard it grew into a crystal tree!"] = "| \"...y cuando planté el fragmento, ¡se convirtió en un árbol de cristal!",
        ["| Royal Trouble"] = "| Problema real",
        ["| \"...I showed that the war was based on a misunderstanding, and now Miscellania and Etceteria are at peace again!"] = "| \"...Mostré que la guerra se basó en un malentendido, ¡y ahora Miscellania y Etceteria están en paz nuevamente!",
        ["War? What is it good for?"] = "¿War? ¿Para qué sirve?",
        ["To which you reply: \"Absolutely nothing."] = "A lo que usted responde: \"Absolutamente nada\".",
        ["| Rum Deal"] = "| Oferta de ron",
        ["| \"...so that was how I helped keep the zombie pirates drunk!"] = "| \"...¡Así fue como ayudé a mantener borrachos a los piratas zombies!",
        ["| \"Drunken zombie pirates? What is the world coming to?"] = "| \"¿Piratas zombis borrachos? ¿A dónde está llegando el mundo?",
        ["| Rune Mechanics"] = "| Mecánica de runas",
        ["| \"...So Clerval and I successfully made a Rune Guardian pet."] = "| \"...Así que Clerval y yo creamos con éxito una mascota Rune Guardian\".",
        ["| \"Hmm, be careful of such powers - they are better left with the gods."] = "| \"Hmm, ten cuidado con esos poderes; es mejor dejarlos en manos de los dioses\".",
        ["| Rune Memories"] = "| Recuerdos rúnicos",
        ["| Rune Mysteries"] = "| Misterios de runas",
        ["| \"...so Ariane and I trapped the anomalies in the ruins beneath the Wizards' Tower, but we didn't find out who had released them or what they were."] = "| \"... entonces Ariane y yo atrapamos las anomalías en las ruinas debajo del Wizards' Tower, pero no descubrimos quién las había liberado ni qué eran\".",
        ["| \"I fear that some things are best left in the past."] = "| \"Me temo que es mejor dejar algunas cosas en el pasado.",
        ["| Rune Mythos"] = "| Mitos de las runas",
        ["| \"I learned how to create impure essence, craft necrotic runes and to use necromancy incantations."] = "| \"Aprendí a crear esencias impuras, crear runas necróticas y utilizar encantamientos de nigromancia\".",
        ["| Rune Mysteries (historical) (Removed)"] = "| Rune Mysteries (histórico) (eliminado)",
        ["| \"...So, I brought Aubury's notes to Sedridor the head wizard and, from then on, I was able to mine rune essence."] = "| \"... Entonces, le llevé las notas de Aubury a Sedridor, el mago principal, y, a partir de ese momento, pude extraer esencia rúnica\".",
        ["| \"So, the mortals above have discovered magic once more? Very interesting."] = "| \"Entonces, ¿los mortales de arriba han descubierto la magia una vez más? Muy interesante\".",
        ["| Salt in the Wound"] = "| Sal en la herida",
        ["| \"...and, when I awoke, the queen was dead and the villagers of Witchaven were free."] = "| \"...y, cuando desperté, la reina estaba muerta y los aldeanos de Witchaven estaban libres\".",
        ["| \"This just goes to show the power of teamwork."] = "| \"Esto simplemente demuestra el poder del trabajo en equipo\".",
        ["| Scorpion Catcher"] = "| Cazador de escorpiones",
        ["| \"...I would never have thought that three scorpions would take that long to find!"] = "| \"... ¡Nunca hubiera pensado que tres escorpiones tomarían tanto tiempo para encontrarlos!",
        ["| Sea Slug"] = "| babosa de mar",
        ["| \"...and that was how I rescued Caroline's family from the sea slugs."] = "| \"...y así fue como rescaté a la familia de Caroline de las babosas marinas.",
        ["| Secrets of Amberfell"] = "| Secretos de Amberfell",
        ["| \"I met Inanna on Havenhythe and saved the village of Amberfell from the sanguine blight."] = "| \"Conocí a Inanna en Havenhythe y salvé al pueblo de Amberfell de la plaga sanguínea\".",
        ["| Shades of Mort'ton"] = "| Tonos de Mort'ton",
        ["| \"...so Mort'ton returned pretty much to normal and I was able to put the shades to rest."] = "| \"...así que Mort'ton volvió prácticamente a la normalidad y pude poner las cortinas en reposo\".",
        ["| Shadow of the Storm"] = "| Sombra de la tormenta",
        ["| \"...Denath was Agrith-Naar all along! But I managed to summon the demon again and slay him."] = "| \"... ¡Denath fue Agrith-Naar todo el tiempo! Pero logré convocar al demonio nuevamente y matarlo\".",
        ["| \"Agrith-Naar was one of the demons my master banished at the end of the great war. It seems he found a way to work around the ban on direct intervention."] = "| \"Agrith-Naar fue uno de los demonios que mi maestro desterró al final de la gran guerra. Parece que encontró una manera de evitar la prohibición de la intervención directa\".",
        ["| A Shadow over Ashdale"] = "| Una sombra sobre Ashdale",
        ["| \"...I defeated Agoroth, the crassians' leader, and freed the villagers."] = "| \"... Derroté a Agoroth, el líder de los crassianos, y liberé a los aldeanos\".",
        ["| \"There are many fell terrors sleeping beneath the surface of the world. The people of Ashdale are fortunate to have such a protector."] = "| \"Hay muchos terrores que duermen bajo la superficie del mundo. La gente de Ashdale tiene suerte de contar con un protector así\".",
        ["| Sheep Herder"] = "| Sheep Pastor",
        ["| \"...so the sheep were safely killed and incinerated."] = "| \"...así que las ovejas fueron sacrificadas e incineradas de forma segura\".",
        ["| Sheep Shearer (miniquest)"] = "| Sheep Esquilador (minimisión)",
        ["| \"Out of sheer hard work, I managed to shear some sheep for farmer Fred. Then I got in a spin and created some balls of wool."] = "| \"Con mucho trabajo logré esquilar algunas ovejas para el granjero Fred. Luego me puse a girar y creé algunos ovillos de lana\".",
        ["| Shield of Arrav"] = "| Escudo de Arrav",
        ["| \"...so that's how I helped return the Shield of Arrav."] = "| \"... así es como ayudé a devolver el Escudo de Arrav\".",
        ["| \"...so, what Rashiliyia wanted all along was to be reunited with her son in the afterlife."] = "| \"... entonces, lo que Rashiliyia siempre quiso fue reunirse con su hijo en el más allá\".",
        ["| \"...and that was how the Stone of Jas was destroyed and Sliske met his end."] = "| \"...y así fue como la Piedra de Jas fue destruida y Sliske encontró su fin\".",
        ["| \"As a Guardian I must remain on the side on balance, however I am not sad that Sliske is dead."] = "| \"Como guardián, debo permanecer al margen, sin embargo, no estoy triste de que Sliske esté muerto\".",
        ["| The Slug Menace"] = "| La amenaza de las babosas",
        ["| \"...when I told Sir Tiffy that I had accidentally freed the Mother Mallum, he promoted me to the rank of Proselyte within the Temple Knights."] = "| \"... cuando le dije a Sir Tiffy que había liberado accidentalmente a la Madre Mallum, él me ascendió al rango de Prosélito dentro de los Caballeros del Templo\".",
        ["| \"That was a strange response to such an unfortunate event. But the motives of the Temple Knights have always been incomprehensibly unbalanced."] = "| \"Esa fue una respuesta extraña a un acontecimiento tan desafortunado. Pero los motivos de los Caballeros del Templo siempre han estado incomprensiblemente desequilibrados\".",
        ["| Smoking Kills"] = "| Fumar mata",
        ["| \"...who would have thought there were so many monsters down the well in Pollnivneach?"] = "| \"... ¿quién hubiera pensado que había tantos monstruos en el pozo de Pollnivneach?",
        ["| \"You will find that monsters can hide in the most surprising of places. Indeed, those with friendly faces can be the closest things to a monster. Be most careful in your desert adventures."] = "| \"Descubrirás que los monstruos pueden esconderse en los lugares más sorprendentes. De hecho, aquellos con caras amigables pueden ser lo más parecido a un monstruo. Ten mucho cuidado en tus aventuras en el desierto\".",
        ["| Some Like it Cold"] = "| A algunos les gusta el frío",
        ["| \"...and then the egg hatched and a baby penguin came out. You should have seen the look on Larry's face."] = "| \"...y luego el huevo eclosionó y salió un pingüino bebé. Deberías haber visto la expresión en el rostro de Larry\".",
        ["| \"Larry's path was never an easy one, but this will complicate matters."] = "| \"El camino de Larry nunca fue fácil, pero esto complicará las cosas.",
        ["| Song from the Depths"] = "| Canción desde las profundidades",
        ["| \"...so the souls of the sleeping people were returned but Remora, the Siren, was killed by the Queen Black Dragon during our escape."] = "| \"... entonces las almas de las personas dormidas fueron devueltas, pero Remora, la Sirena, fue asesinada por la Reina Dragón Negro durante nuestro escape\".",
        ["| \"Well, at least her death will prevent the Queen from growing stronger stealing other people's souls."] = "| \"Bueno, al menos su muerte evitará que la Reina se haga más fuerte y robe las almas de otras personas\".",
        ["| A Soul's Bane"] = "| La pesadilla de un alma",
        ["| \"...so I defeated all of the monsters in Tolna's subconscious and he escaped from the rift."] = "| \"... así que derroté a todos los monstruos en el subconsciente de Tolna y él escapó de la grieta\".",
        ["| \"The most fearsome monsters are to be found in the darkness of our own minds."] = "| \"Los monstruos más temibles se encuentran en la oscuridad de nuestras propias mentes.",
        ["| Soul Searching"] = "| Búsqueda del alma",
        ["| \"I worked with Icthlarin to gain access to the Sanctum of Rebirth; a strange temple in the Underworld."] = "| \"Trabajé con Icthlarin para obtener acceso al Santuario del Renacimiento; un templo extraño en el inframundo\".",
        ["| Spirit of Summer"] = "| Spirit de Verano",
        ["| \"...I trapped the Spirit Beast and the family could talk again, but they said I had only made it more powerful."] = "| \"...Atrapé a la Bestia Spirit y la familia pudo volver a hablar, pero dijeron que solo la había hecho más poderosa\".",
        ["| \"I have heard of that Spirit Beast. You did very well to even survive your encounter with it."] = "| \"He oído hablar de esa Bestia Spirit. Lo hiciste muy bien incluso para sobrevivir a tu encuentro con ella\".",
        ["| The Spirit of War"] = "| El Spirit de War",
        ["| \"I tested myself against Hermod, the Spirit of War (and Rasial's phantom bodyguard). Despite winning, Rasial just regenerated Hermod. I have much left to learn."] = "| \"Me puse a prueba contra Hermod, the Spirit of War (y el guardaespaldas fantasma de Rasial). A pesar de ganar, Rasial acaba de regenerar a Hermod. Me queda mucho por aprender\".",
        ["| Spirits of the Elid"] = "| Espíritus de los Elid",
        ["| \"...so it turned out that the people of Nardah were dying of thirst because the spirits of the Elid had cursed them for turning away from their goddess."] = "| \"... entonces resultó que la gente de Nardah se estaba muriendo de sed porque los espíritus de los Elid los habían maldecido por alejarse de su diosa\".",
        ["| \"It is a terrible thing for people to turn away from their religion. I think the spirits taught the town a lesson."] = "| \"Es terrible que la gente se aparte de su religión. Creo que los espíritus le dieron una lección a la ciudad\".",
        ["| Spiritual Enlightenment (miniquest)"] = "| Iluminación espiritual (minimisión)",
        ["| \"I climbed the path to enlightenment on the island of Aminishi."] = "| \"Subí el camino hacia la iluminación en la isla de Aminishi\".",
        ["| Stellar Born"] = "| Nacido estelar",
        ["| \"I worked with some astromancers to help a star sprite get back to their home planet, and discovered what was draining their powers."] = "| \"Trabajé con algunos astromantes para ayudar a un star sprite a regresar a su planeta de origen y descubrí qué estaba agotando sus poderes\".",
        ["| Stolen Hearts"] = "| Corazones robados",
        ["| \"...but Ozan and I were caught trying to steal the diamond, and while we were trying to convice the emir to trade it for his son, his own heart gave out!"] = "| \"...pero Ozan y yo fuimos atrapados tratando de robar el diamante, y mientras intentábamos convencer al emir de que lo cambiara por su hijo, ¡su propio corazón se rindió!",
        ["| \"Life is full of little ironies, but do not presume such coincidences are without deliberate cause."] = "| \"La vida está llena de pequeñas ironías, pero no asumas que tales coincidencias no tienen una causa deliberada.",
        ["| Succession"] = "| Sucesión",
        ["| \"I teamed up with Adrasteia for one last adventure before her coronation. Together we tracked Bilrach deep into the Wilderness and ended his scheme."] = "| \"Me asocié con Adrasteia para una última aventura antes de su coronación. Juntos rastreamos a Bilrach hasta lo más profundo del Wilderness y terminamos su plan\".",
        ["| Summer's End"] = "| El fin del verano",
        ["| \"...and after I defeated the Spirit Beast, Summer and her family were finally able to die."] = "| \"...y después de que derroté a la Bestia Spirit, Summer y su familia finalmente pudieron morir\".",
        ["| \"The balance of life and death have been restored. It is good."] = "| \"Se ha restablecido el equilibrio entre la vida y la muerte. Es bueno\".",
        ["| Swan Song"] = "| Canción del cisne",
        ["| \"...so the Wise Old Man said it was time for him to retire, and he left the colony and went home. He taught me a lot, but he wouldn't let me have his hat!"] = "| \"... entonces el Wise Old Man dijo que era hora de que se retirara, dejó la colonia y se fue a casa. ¡Me enseñó mucho, pero no me dejó tener su sombrero!",
        ["A hat is just a hat, Player."] = "Un sombrero es sólo un sombrero, Player.",
        ["To which you reply: \"Grrr!"] = "A lo que respondes: \"¡Grrr!",
        ["| Swept Away"] = "| barrido",
        ["| \"...And that was how I helped the witches prepare their goulash."] = "| \"...Y así fue como ayudé a las brujas a preparar su gulash.",
        ["| Tai Bwo Wannai Trio"] = "| Trío Tai Bwo Wannai",
        ["| \"...so, that was how I helped the people of Tai Bwo Wannai return."] = "| \"... así fue como ayudé a la gente de Tai Bwo Wannai a regresar\".",
        ["| A Tail of Two Cats"] = "| Una cola de dos gatos",
        ["| \"...now Bob and Neite are very happy together!"] = "| \"...¡ahora Bob y Neite están muy felices juntos!",
        ["| \"Bob the cat? I have heard of that strange creature, but have never been able to fathom him. It is no small achievement for you to be able to."] = "| \"¿Bob el gato? He oído hablar de esa extraña criatura, pero nunca he podido comprenderlo. No es un logro pequeño para ti poder hacerlo\".",
        ["| Tales of the God Wars (miniquest)"] = "| Cuentos de las Guerras de Dios (minimisión)",
        ["| \"I discovered tales of the rivalries between the faction generals within the Heart of Gielinor."] = "| \"Descubrí historias de las rivalidades entre los generales de facciones dentro del Corazón de Gielinor\".",
        ["| The Tale of the Muspah"] = "| El cuento del Muspah",
        ["| \"...And so, with Jhallan hibernating again, I had managed to get a trophy for Erjolf."] = "| \"...Y así, con Jhallan hibernando nuevamente, logré conseguir un trofeo para Erjolf\".",
        ["| \"I must ponder whether your actions have interfered with balance or preserved it. Perhaps there is too little information to decide yet."] = "| \"Debo reflexionar si tus acciones han interferido con el equilibrio o lo han preservado. Quizás todavía haya muy poca información para decidir\".",
        ["| Tales of Nomad (miniquest)"] = "| Cuentos de Nomad (minimisión)",
        ["| \"I experienced the stories of Nomad's genesis by exploring cryptic and static scenes from his past."] = "| \"Experimenté las historias de la génesis de Nomad explorando escenas crípticas y estáticas de su pasado\".",
        ["| The Temple at Senntisten"] = "| El Temple at Senntisten",
        ["| \"...And with the communication portal restored, Azzanadra could talk to Zaros again."] = "| \"...Y con el portal de comunicación restaurado, Azzanadra pudo hablar con Zaros nuevamente.",
        ["Finally the order shifts towards balance again. You know, of course, that Zamorak is merely a pretender-god. For a mortal to assume such power is really not good for balance."] = "Finalmente, el orden cambia nuevamente hacia el equilibrio. Sabes, por supuesto, que Zamorak es simplemente un dios pretendiente. Que un mortal asuma tal poder realmente no es bueno para el equilibrio\".",
        ["To which Juna replies \"Guthix gained his power through honest means. He was unaware of what his actions would achieve. Zamorak, however, had unbalanced intentions that cannot be respected."] = "A lo que Juna responde: \"Guthix obtuvo su poder por medios honestos. No sabía lo que lograrían con sus acciones. Zamorak, sin embargo, tenía intenciones desequilibradas que no pueden ser respetadas\".",
        ["| Temple of Ikov (Helping Lucien)"] = "| Templo de Ikov (Ayudando a Lucien)",
        ["| \"...Lucien said that the Staff of Armadyl I gave him had made him more powerful."] = "| \"...Lucien dijo que el Staff o Armadyl que le di lo había hecho más poderoso\".",
        ["| Temple of Ikov (Against Lucien)"] = "| Templo de Ikov (contra Lucien)",
        ["| \"I refused to give Lucien the Staff of Armadyl and had to fight him."] = "| \"Me negué a darle a Lucien el Staff de Armadyl y tuve que pelear con él\".",
        ["| That Old Black Magic"] = "| Ese viejo negro Magic",
        ["| \"I helped to reunite the City of Um's jazz band."] = "| \"Ayudé a reunir la banda de jazz de City of Um\".",
        ["| Thok It To 'Em (saga)"] = "| Thok a ellos (saga)",
        ["| \"I listened to the first saga of Thok, the Daemonheim skillcape owner (but not wearer). He told a tall tale, of charging through a dungeon filled with huge beasts, all in the name of family, love and a fondness for killing creatures in surprisingly novel ways."] = "| \"Escuché la primera saga de Thok, el propietario (pero no el usuario) de Daemonheim skillcape. Contó una gran historia sobre cómo atravesar una mazmorra llena de enormes bestias, todo en nombre de la familia, el amor y la afición por matar criaturas de formas sorprendentemente novedosas\".",
        ["| \"I listened to the second saga of Thok, the Master of Dungeoneering, as he attempted to defeat his brother in a battle of brawn."] = "| \"Escuché la segunda saga de Thok, el maestro de Dungeoneering, mientras intentaba derrotar a su hermano en una batalla de fuerza\".",
        ["| Throne of Miscellania"] = "| Trono de Miscellania",
        ["| \"...So that was how I became King/Queen of Miscellania!<ref name=\"gender\">If a player switches their gender after the quest, the player will say their current gender instead of the one used to marry in the quest, despite the fact that the NPC the player marries to recognises that the player is a different gender.</ref>"] = "| \"...¡Así fue como me convertí en Rey/Reina de Miscellania! <ref name=\"gender\">Si un jugador cambia de género después de la misión, el player dirá su género actual en lugar del que solía casarse en la misión, a pesar de que el NPC con el que se casa el player reconoce que el player es de un género diferente.</ref>",
        ["| Three's Company (saga)"] = "| Compañía de tres (saga)",
        ["| \"I listened to Skaldrun's saga of Sir Owen, Ariane and Ozan's mission into Daemonheim in search of a criminal who had escaped their clutches."] = "| \"Escuché la saga de Skaldrun sobre la misión de Sir Owen, Ariane y Ozan en Daemonheim en busca de un criminal que había escapado de sus garras\".",
        ["| TokTz-Ket-Dill"] = "| TokTz-Ket-Eneldo",
        ["| \"...and that's how I defeated the TokTz-Ket-Dill and helped to write a Tzhaar play."] = "| \"...y así es como derroté al TokTz-Ket-Dill y ayudé a escribir una obra de Tzhaar\".",
        ["| \"I wish I could have seen your play, Player. I am always glad to hear your stories."] = "| \"Ojalá hubiera podido ver tu obra, Player. Siempre me alegra escuchar tus historias\".",
        ["| Tomes of the Warlock"] = "| Tomos del brujo",
        ["| \"I tracked down a series of books written by Orcus, a necromancer from the 2nd Age. From them, I learned of some ancient necromancy secrets."] = "| \"Rastreé una serie de libros escritos por Orcus, un nigromante de la Segunda Edad. A partir de ellos, aprendí algunos secretos antiguos de la nigromancia\".",
        ["| Tortle Combat (miniquest)"] = "| Combate Tortle (minimisión)",
        ["| \"I helped some tortles set up a dojo in Varrock Sewers."] = "| \"Ayudé a algunas tortugas a montar un dojo en Varrock Sewers\".",
        ["| The Tourist Trap"] = "| La trampa para turistas",
        ["| \"...Ana wasn't too happy to be cooped up in that barrel! But at least I got her out of the mining camp."] = "| \"... ¡Ana no estaba muy feliz de estar encerrada en ese barril! Pero al menos la saqué del campamento minero\".",
        ["| Tower of Life"] = "| Torre de la vida",
        ["| \"...So, it turned out that the alchemists had created a Homunculus - a mixture of logic and magic."] = "| \"...Entonces, resultó que los alquimistas habían creado un Homúnculo - una mezcla de lógica y magia.",
        ["| \"Ah, that is good. New forms of life should always be created according to a balance between different principles."] = "| \"Ah, eso es bueno. Siempre deben crearse nuevas formas de vida de acuerdo con un equilibrio entre diferentes principios\".",
        ["| Tree Gnome Village"] = "| Árbol Gnome Pueblo",
        ["| \"..And King Bolren thanked me for defeating the warlord and returning the orbs to the gnome people."] = "| \"...Y King Bolren me agradeció por derrotar al señor de la guerra y devolver los orbes al pueblo gnomo\".",
        ["| Tribal Totem"] = "| Tótem tribal",
        ["| \"...I returned the totem and the Rantuki tribe rewarded me for my help."] = "| \"...Devolví el tótem y la tribu Rantuki me recompensó por mi ayuda.",
        ["| Troll Romance"] = "| Romance trol",
        ["| \"...so Ug and Aga lived happily ever after."] = "| \"...así que Ug y Aga vivieron felices para siempre.",
        ["| Troll Stronghold"] = "| Fortaleza troll",
        ["| \"...and, after I rescued Godric, Dunstan gave me two magic lamps as a reward!"] = "| \"...y, después de rescatar a Godric, ¡Dunstan me dio dos lámparas mágicas como recompensa!",
        ["| Tuai Leit's Own (miniquest)"] = "| El propio Tuai Leit (minimisión)",
        ["| \"I explored the island of Tuai Leit in search of a cure for Ekahi."] = "| \"Exploré la isla de Tuai Leit en busca de una cura para Ekahi\".",
        ["| Twilight of the Gods"] = "| Crepúsculo de los dioses",
        ["| \"I prepared to re-establish the Edicts, in order to stop Zamorak from taking over Gielinor."] = "| \"Me preparé para restablecer los Edictos para evitar que Zamorak se hiciera cargo de Gielinor\".",
        ["| \"...I don't know who put all those traps in the underground pass!"] = "| \"... ¡No sé quién puso todas esas trampas en el underground pass!",
        ["| Unwelcome Guests"] = "| Invitados no deseados",
        ["| \"I found the source of undead attacking Fort Forinthry and helped the Raptor setup a defensive front."] = "| \"Encontré la fuente de los no-muertos que atacaban a Fort Forinthry y ayudé a the Raptor a establecer un frente defensivo\".",
        ["| \"...And once the vampyre was dead, the people of Draynor no longer lived in fear."] = "| \"...Y una vez que el vampyre estuvo muerto, la gente de Draynor ya no vivió con miedo\".",
        ["| Vengeance (saga)"] = "| Venganza (saga)",
        ["| \"I listened to Skaldrun's saga of a vengeful, poisoned forgotten warrior."] = "| \"Escuché la saga de Skaldrun sobre un guerrero olvidado, vengativo y envenenado\".",
        ["| Vessel of the Harbinger"] = "| Vasija del Heraldo",
        ["| \"I worked with a former student of Rasial's, Necrovarus of Port Phasmatys, and learned more about necromantic vessels."] = "| \"Trabajé con un antiguo alumno de Rasial, Necrovarus de Port Phasmatys, y aprendí más sobre las naves nigrománticas\".",
        ["| Violet is Blue"] = "| Violet es azul",
        ["| \"...and that was how I managed to escort Violet across the Land of Snow to the festival."] = "| \"...y así fue como logré escoltar a Violet a través del País de la Nieve hasta el festival\".",
        ["| \"What an uplifting tale! A shame you don't bring me more like these."] = "| \"¡Qué historia tan edificante! Es una pena que no me traigas más como estas\".",
        ["| Violet is Blue Too"] = "| Violet también es azul",
        ["| \"With the help of Violet, we found the missing snow imp and helped save Yeti town by getting new Christmas decorations and managed to decorate the town in time for Christmas day."] = "| \"Con la ayuda de Violet, encontramos al diablillo de nieve perdido y ayudamos a salvar la ciudad de Yeti consiguiendo nuevas decoraciones navideñas y logramos decorar la ciudad a tiempo para el día de Navidad\".",
        ["| Visions of Havenhythe"] = "| Visiones de Havenhythe",
        ["| \"I received a vision calling me to the ancient and beautiful land of Havenhythe, and helped the villagers of Wendlewick construct a lodestone."] = "| \"Recibí una visión que me llamaba a la antigua y hermosa tierra de Havenhythe y ayudé a los aldeanos de Wendlewick a construir un lodestone\".",
        ["| A Void Dance"] = "| Una danza del vacío",
        ["| \"...and on finally tracking down the missing Void Leech, I dealt with it appropriately."] = "| \"...y cuando finalmente localicé a Void Leech desaparecido, lo solucioné apropiadamente\".",
        ["| \"Your decisions and choices are a matter for your own conscience."] = "| \"Tus decisiones y elecciones son un asunto de tu propia conciencia.",
        ["| The Void Stares Back"] = "| El vacío te devuelve la mirada",
        ["| \"...so I defeated the Pest Queen, but lost a good friend."] = "| \"... así que derroté a la Reina Pest, pero perdí a un buen amigo\".",
        ["| \"The knights have not stood united for a very long time."] = "| \"Los caballeros no han estado unidos desde hace mucho tiempo.",
        ["| Wanted!"] = "| ¡Buscado!",
        ["| \"...and, after I finally managed to track him down, let me tell you, that Solus Dellagar was almost as powerful as he was insane!"] = "| \"...y, después de que finalmente logré localizarlo, ¡déjame decirte que Solus Dellagar era casi tan poderoso como loco!",
        ["| \"Yes, it seems he sacrificed his sanity for power. Power often comes with a cost, and the highest cost is often the one you do not immediately see."] = "| \"Sí, parece que sacrificó su cordura por el poder. El poder a menudo tiene un costo, y el costo más alto suele ser el que no se ve de inmediato\".",
        ["| Wandering Ga'al (miniquest)"] = "| Ga'al errante (minimisión)",
        ["| \"I found a Ga'al explorer who disappeared thanks to a very specific set of circumstances. Whomever conceived of them must surely possess a heart of gall."] = "| \"Encontré un explorador de Ga'al que desapareció gracias a una serie de circunstancias muy específicas. Quienquiera que los haya concebido seguramente debe poseer un corazón de descaro.",
        ["| Watchtower"] = "| Atalaya",
        ["| \"...and with the shield generator working, the ogres could never threaten Yanille again."] = "| \"...y con el generador de escudo funcionando, los ogros nunca más podrían amenazar a Yanille\".",
        ["| Waterfall Quest"] = "| Búsqueda de la cascada",
        ["| \"...And that was how I retrieved the Chalice of Eternity from the waterfall."] = "| \"...Y así fue como recuperé el Cáliz de la Eternidad de la cascada.",
        ["| What Lies Below"] = "| Lo que hay debajo",
        ["| \"...but after I defeated King Roald, Rat was able to remove Surok's mind control spell from him."] = "| \"...pero después de que derroté a King Roald, Rat pudo quitarle el hechizo de control mental de Surok\".",
        ["| \"I see the servants of Zamorak still play their part in balancing the world between good and evil."] = "| \"Veo que los servidores de Zamorak todavía desempeñan su papel en el equilibrio del mundo entre el bien y el mal\".",
        ["| What's Mine is Yours"] = "| Lo que es mío es tuyo",
        ["| \"...and that was how I convinced Doric to go back into business."] = "| \"...y así fue como convencí a Doric para que volviera al negocio.",
        ["| \"An uplifting story; I wish you the best in your future ventures."] = "| \"Una historia edificante; te deseo lo mejor en tus futuros proyectos\".",
        ["| While Guthix Sleeps"] = "| Mientras Guthix duerme",
        ["| \"...But Lucien took the Stone of Jas and teleported away!"] = "| \"... ¡Pero Lucien tomó la Piedra de Jas y se teletransportó!",
        ["| \"You should know better than to interfere. Without your involvement, the stone would still rest where my master had put it. But good may yet come of this. We shall see."] = "| \"Deberías saber que no debes interferir. Sin tu participación, la piedra aún permanecería donde mi maestro la había puesto. Pero aún puede salir algo bueno de esto. Ya veremos\".",
        ["| Witch's House"] = "| Casa de la bruja",
        ["| \"...All that trouble just to get a ball out of someone's garden!"] = "| \"... ¡Todos esos problemas sólo para sacar una pelota del jardín de alguien!",
        ["| \"It is often hard to know how long a task will take when we begin it."] = "| \"A menudo es difícil saber cuánto tiempo llevará una tarea cuando la iniciamos\".",
        ["| Witch's Potion (Removed)"] = "| Poción de bruja (eliminada)",
        ["| \"...And once I got her all the ingredients, Hetty's potion increased my magical power!"] = "| \"...Y una vez que le conseguí todos los ingredientes, ¡la poción de Hetty aumentó mi poder mágico!",
        ["| \"I see you are on your way to becoming strong in the magical arts."] = "| \"Veo que estás en camino de volverte fuerte en las artes mágicas\".",
        ["| Witch's Potion (miniquest)"] = "| Poción de bruja (minimisión)",
        ["| \"I've got the makings of a top-class witch! I created a witch's brew with a little help from Hetty."] = "| \"¡Tengo los ingredientes de una bruja de primera clase! Creé un brebaje de bruja con un poco de ayuda de Hetty\".",
        ["| \"...And that's what happened within the light."] = "| \"...Y eso es lo que pasó within the light.",
        ["| \"It must have taken great power to contain such an area within light itself. Intriguing."] = "| \"Debe haber sido necesario un gran poder para contener tal área dentro de la propia luz. Intrigante.",
        ["| Wiz Kid"] = "| niño mago",
        ["| \"I mentored an aspiring young wizard, Ben, in the ways of the runes."] = "| \"Fui mentor de un joven aspirante a mago, Ben, en los caminos de las runas\".",
        ["| Wolf Whistle"] = "| Silbato de lobo",
        ["| \"...And that was how I managed to stop the trolls from making druid soup."] = "| \"...Y así fue como logré evitar que los trolls hicieran sopa de druida.",
        ["| Wolf Whistle (historical) (Removed)"] = "| Wolf Whistle (histórico) (eliminado)",
        ["| \"...And that was how I learned the secrets of summoning."] = "| \"...Y así fue como aprendí los secretos de la invocación.",
        ["| The World Wakes"] = "| El mundo despierta",
        ["|...But it was too late. Sliske had struck the killing blow. Before Guthix died, he showed me what the world will be like if the gods return, and gave me power to defend against them."] = "|...Pero ya era demasiado tarde. Sliske había dado el golpe mortal. Antes de que Guthix muriera, me mostró cómo será el mundo si los dioses regresan y me dio poder para defenderme de ellos.",
        ["| \"These events have paved the way for a new age. Guthix's death removed the edicts from this world, allowing the gods to return. You must remember what he told you, Player."] = "| \"Estos eventos han allanado el camino para una nueva era. La muerte de Guthix eliminó los edictos de este mundo, permitiendo que los dioses regresen. Debes recordar lo que te dijo, Player\".",
        ["| You Are It"] = "| tu lo eres",
        ["| \"...and that was how I overcame the curse of the wishbringer and restored Uri."] = "| \"...y así fue como superé la maldición del cumplidor de deseos y restauré Uri.",
        ["| \"Charos's trinkets appear to have more power than we had previously suspected."] = "| \"Las baratijas de Charos parecen tener más poder de lo que habíamos sospechado anteriormente\".",
        ["| Zogre Flesh Eaters"] = "| Devoradores de carne de Zogre",
        ["| \"...Those Zogres were disgusting! But I learned how to fight them with brutal arrows and disease balm."] = "| \"... ¡Esos Zogres eran asquerosos! Pero aprendí a luchar contra ellos con flechas brutales y bálsamos contra enfermedades\".",
        ["| \"Zombie Ogres!? Some of the foulest creatures of Zamorak. In the great wars, the zogre armies would repel the forces of Saradomin with their stench alone."] = "| \"¿¡Ogros zombis!? Algunas de las criaturas más repugnantes de Zamorak. En las grandes guerras, los ejércitos de zogre repelerían a las fuerzas de Saradomin sólo con su hedor.",
        ["Hello, what are you doing here?"] = "Hola, ¿qué haces aquí?",
        ["Celebrating the anniversary, but also mourning all that we have lost."] = "Celebrando el aniversario, pero también lamentando todo lo que hemos perdido.",
        ["This past ten years has been filled with trying times and sad stories."] = "Estos últimos diez años han estado llenos de tiempos difíciles e historias tristes.",
        ["It has felt to me like the world was thrown out of balance, ever since..."] = "Me ha parecido como si el mundo estuviera fuera de equilibrio, desde entonces...",
        ["You don't have to say. I've felt it too. I think we all have."] = "No es necesario que lo digas. Yo también lo he sentido. Creo que todos lo hemos hecho.",
        ["It was the return of the gods - that started right here with the Battle of Lumbridge, which caused that crater right above where my nest is."] = "Fue el regreso de los dioses, que comenzó aquí mismo con la Batalla de Lumbridge, que causó ese cráter justo encima de donde está mi nido.",
        ["People have been fighting among themselves ever since, split into factions, and their hearts overtaken by greed."] = "La gente ha estado peleando entre sí desde entonces, dividida en facciones y sus corazones invadidos por la codicia.",
        ["The Tears of Guthix have been weeping heavily ever since, and I with them..."] = "Las Lágrimas de Guthix han estado llorando copiosamente desde entonces, y yo con ellas...",
        ["But one cannot remain lost in grief forever, and it is finally starting to feel as if the mood is shifting."] = "Pero uno no puede permanecer perdido en el dolor para siempre, y finalmente comienza a sentir como si el estado de ánimo estuviera cambiando.",
        ["Very true."] = "Muy cierto.",
        ["That is why I came to visit - both to honour the past, but also to look to the future, and what better time to reinvent oneself than an anniversary? Change is coming."] = "Por eso vine de visita: para honrar el pasado, pero también para mirar hacia el futuro, y ¿qué mejor momento para reinventarse que un aniversario? Se acerca el cambio.",
        ["What changes?"] = "¿Qué cambia?",
        ["Did you not see the crater has gone? It has not just healed, it has been rejuvenated!"] = "¿No viste que el cráter desapareció? ¡No sólo ha sanado, sino que ha rejuvenecido!",
        ["It is not just the crater either. I have heard many stories of positive change across our world."] = "Tampoco es sólo el cráter. He escuchado muchas historias de cambios positivos en nuestro mundo.",
        ["And even here, you can see disparate people rejoining hands - old friendships are renewed."] = "E incluso aquí puedes ver a personas dispares volver a unirse: viejas amistades se renuevan.",
        ["Their joy, too, is palpable. It no longer feels that everyone is in it for themselves. Greed is giving way to generosity."] = "Su alegría también es palpable. Ya no se siente que cada uno está en esto por sí mismo. La codicia está dando paso a la generosidad.",
        ["True, there are many wounds to heal, and many friendships to be rekindled, but it truly feels like hope is returning to Gielinor once again, and balance with it."] = "Es cierto, hay muchas heridas que sanar y muchas amistades que reavivar, pero realmente parece que la esperanza está regresando a Gielinor una vez más y el equilibrio con ella.",
        ["You know, I think you're on to something. Here's to the future!"] = "Sabes, creo que has descubierto algo. ¡Aquí está el futuro!",
    },
    ["June"] = {
        ["You have found raven #365, but you need to spot them in order, starting with Terry."] = "Has encontrado el cuervo n.° 365, pero debes ubicarlos en orden, comenzando con Terry.",
    },
    ["Jungle forester"] = {
        ["Hello friend. You're a long way from civilisation!"] = "Hola amigo. ¡Estás muy lejos de la civilización!",
        ["Select an Option"] = "Selecciona una opción",
        ["How do I get into the Kharazi Jungle?"] = "¿Cómo llego a la jungla Kharazi?",
        ["Well, I've not managed it yet but I heard that someone managed to find a way in. But they only just managed to escape the jungle with their lives."] = "Bueno, aún no lo he logrado, pero escuché que alguien logró encontrar una manera de entrar. Pero apenas lograron escapar de la jungla con vida.",
        ["Apparently he was on a mission to map the area. How foolish is that?"] = "Aparentemente tenía la misión de mapear el área. ¿Qué tan tonto es eso?",
        ["Well, in fact I plan to map that area myself."] = "Bueno, de hecho planeo mapear esa área yo mismo.",
        ["--The forester looks very interested-- <br>Oh, well, that sounds quite good actually... <br>Sorry if I sounded rude before, it just didn't seem like a good idea to me."] = "--El guardabosques parece muy interesado-- <br>Oh, bueno, eso suena bastante bien en realidad... <br>Perdón si soné grosero antes, simplemente no me pareció una buena idea.",
        ["I guess I just wouldn't want to do it myself. But a map of that area would certainly be a big task. And it would certainly be very useful... -- The forester looks very thoughtful --"] = "Supongo que no me gustaría hacerlo yo mismo. Pero un mapa de esa zona sería ciertamente una gran tarea. Y sin duda sería muy útil... -- El guardabosques se ve muy pensativo --",
        ["Hey, if you manage to complete it, be sure to let me take a look! Well, best of luck with it, I'm sure you're going to need it."] = "Oye, si logras completarlo, ¡déjame echarle un vistazo! Bueno, mucha suerte con esto, estoy seguro de que lo necesitarás.",
        ["Do you have any other tips about the Kharazi Jungle?"] = "¿Tienes algún otro consejo sobre la jungla Kharazi?",
        ["Not really, but I would say be careful, it's a dangerous place. And good luck."] = "En realidad no, pero diría que ten cuidado, es un lugar peligroso. Y buena suerte.",
        ["Have you seen any natives in the jungle?"] = "¿Has visto algún nativo en la jungla?",
        ["Ok thanks."] = "Bueno, gracias.",
        ["Are you calling me foolish?"] = "¿Me estás llamando tonto?",
        ["No, of course not... Sorry, I have to be on my way..."] = "No, claro que no... Lo siento, tengo que seguir mi camino...",
        ["So someone managed to get into the Kharazi Jungle?"] = "¿Alguien logró entrar en la jungla Kharazi?",
        ["So someone managed to get into the Jungle?"] = "¿Entonces alguien logró entrar a la jungla?",
        ["Yes, he said he was from some place... near the Sorcerer's Tower. Mentioned something about a legend? It meant nothing to me though."] = "Sí, dijo que era de algún lugar... cerca de la Torre del Hechicero. ¿Mencionó algo sobre una leyenda? Aunque no significó nada para mí.",
        ["How do I get into the jungle?"] = "¿Cómo entro a la jungla?",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["You're welcome! See you around..."] = "¡De nada! Nos vemos por ahí...",
        ["Can I get another bullroarer{{Sic please?}}"] = "¿Puedo conseguir otro bullroarer{{Sic please?}}?",
        ["Can I get another bullroarer{{Sic}} please?"] = "¿Puedo conseguir otro bullroarer{{Sic}}, por favor?",
        ["Hmmm, what we have here is an opportunity for trade! I'm a bit peckish so why not get me a tasty cooked oomlie wrap and we'll have a deal."] = "Mmmm, ¡lo que tenemos aquí es una oportunidad para comerciar! Tengo un poco de hambre, así que ¿por qué no me traes un delicioso wrap oomlie cocido y hacemos un trato?",
        ["I have one here!"] = "¡Tengo uno aquí!",
        ["Great! Hand it over then!"] = "¡Genial! ¡Dámelo entonces!",
        ["[You trade the cooked Oomlie bird for the bullroarer{{Sic].}}"] = "[Cambias el pájaro Oomlie cocido por el rugido{{Sic].}}",
        ["How can I get one of those?"] = "¿Cómo puedo conseguir uno de esos?",
        ["Oomlie birds are natives of the Kharazi Jungle but they won't be taken without a fight! Once that issue is resolved just cook the bird in a palm leaf over a fire. I'll leave it to your own imagination as to how you get the palm leaf!"] = "Los pájaros Oomlie son nativos de la jungla Kharazi, ¡pero no serán capturados sin luchar! Una vez que se resuelva el problema, simplemente cocine el ave en una hoja de palma al fuego. ¡Dejaré a tu imaginación cómo conseguir la hoja de palma!",
        ["Won't you take something else in return?"] = "¿No aceptarás algo más a cambio?",
        ["Well I doubt that you have anything else which is worth anything to me and Oomlie bird wraps are pretty tasty. I'd have to say sorry but no, that's my final offer."] = "Bueno, dudo que tengas algo más que valga la pena para mí y los wraps de aves de Oomlie son bastante sabrosos. Tendría que pedir perdón pero no, esa es mi oferta final.",
        ["Ok, I'll have a think about it."] = "Ok, lo pensaré.",
        ["Ok! You know where I am if you need me."] = "¡Vale! Sabes dónde estoy si me necesitas.",
        ["I'm a forester, and I specialise in exotic woods. I've not managed to penetrate the Kharazi Jungle very far but I have found some interesting tree specimens."] = "Soy forestal y me especializo en maderas exóticas. No he logrado penetrar muy lejos en la selva de Kharazi, pero he encontrado algunos ejemplares de árboles interesantes.",
        ["If you do happen to get into the Kharazi Jungle, do come and let me know. I'd love to be able to safely navigate my own way in and out."] = "Si por casualidad te adentras en la jungla Kharazi, ven y avísame. Me encantaría poder entrar y salir de forma segura.",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm a jungle forester. Names mean little in this part of the world."] = "Soy un jungle forester. Los nombres significan poco en esta parte del mundo.",
        ["Well, I've heard some funny sounds and I think I've seen a native... but I'm not sure. They generally don't like to be seen I guess."] = "Bueno, he escuchado algunos sonidos graciosos y creo que he visto a un nativo... pero no estoy seguro. Supongo que generalmente no les gusta que los vean.",
        ["But I found an item that you might be interested in. You swing it above your head and it makes a strange sound, it seems to attract their attention."] = "Pero encontré un artículo que podría interesarte. Lo mueves sobre tu cabeza y hace un sonido extraño, parece atraer su atención.",
        ["Can I have the item please?"] = "¿Me pueden dar el artículo, por favor?",
        ["Well, I wish I could give it to you. However, I have grown fond of it. And it may help me in case I get lost in the jungle."] = "Bueno, desearía poder dártelo. Sin embargo, le he cogido cariño. Y puede que me ayude en caso de que me pierda en la jungla.",
        ["Will you trade something for it?"] = "¿Cambiarías algo por ello?",
        ["Well, if you have something interesting, let me have a look at it and I'll offer you something in return. OK, I have to go now, but it's been nice talking with you."] = "Bueno, si tienes algo interesante, déjame echarle un vistazo y te ofreceré algo a cambio. Vale, tengo que irme ahora, pero ha sido un placer hablar contigo.",
        ["About the Task System..."] = "Acerca del sistema de tareas...",
        ["I've done all the Hard Tasks in the Karamja set."] = "He realizado todas las tareas difíciles del conjunto Karamja.",
        ["Hmm, indeed. I suppose you'll be wanting a reward!"] = "Hmm, efectivamente. ¡Supongo que querrás una recompensa!",
        ["Yes, please."] = "Sí, por favor.",
        ["How can I enchant your Karamja gloves with the power of the forest if you don't have them with you? Bring me the Karamja gloves earned from completing the Medium Tasks."] = "¿Cómo puedo encantar tus guantes Karamja con el poder del bosque si no los tienes contigo? Tráeme los guantes Karamja que se obtienen al completar las tareas medianas.",
        ["The forester takes the Karamja gloves and seems to go into a trance. You hear a rustle in the forest; the gloves seem to shimmer and then turn a darker shade of green."] = "El guardabosques toma los guantes Karamja y parece entrar en trance. Se oye un susurro en el bosque; los guantes parecen brillar y luego adquieren un tono verde más oscuro.",
        ["The blessing that I have placed on these Karamja gloves is a symbol of the exhaustive exploration of the island that you have performed. As well as the benefits of the previous pair, you can take yourself to a place below Shilo"] = "La bendición que he puesto en estos guantes Karamja es un símbolo de la exploración exhaustiva de la isla que habéis realizado. Además de los beneficios del par anterior, puedes ir a un lugar debajo de Shilo.",
        ["Village at any time and enter Brimhaven Dungeon for free. Oh, there's a little added extra for all your hard work, too."] = "Village en cualquier momento y entra gratis a Brimhaven Dungeon. Oh, también hay un pequeño extra por todo tu arduo trabajo.",
        ["Wow, thanks!"] = "¡Vaya, gracias!",
        ["If you lose them, come back to me to reclaim them."] = "Si los pierdes, vuelve conmigo para reclamarlos.",
        ["Ahh...I remember you - didn’t I bless your Karamja gloves?"] = "Ahh... Te recuerdo, ¿no bendije tus guantes Karamja?",
        ["Yes, but I lost them."] = "Sí, pero los perdí.",
        ["Thought as much. Here, have another pair."] = "Lo mismo pensé. Toma, toma otro par.",
        ["[Jungle forester hands you another pair of gloves.]"] = "[Jungle forester te entrega otro par de guantes.]",
        ["Choose an option:{{anchor"] = "Elige una opción:{{anchor",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Choose an option:"] = "Elige una opción:",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
        ["For completing the Tasks in the Karamja set, you are presented with a pair of gloves."] = "Para completar las tareas del conjunto Karamja, se te entregará un par de guantes.",
        ["Completing each difficulty level of the set will allow your gloves to be improved."] = "Completar cada nivel de dificultad del conjunto permitirá mejorar tus guantes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
        ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
        ["Some of the Karamja set's Tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Karamja son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
        ["To claim your Karamja set rewards, speak to Jackie the Fruit in Brimhaven's Agility Arena, Kaleb Paramaya in Shilo Village inn, or myself."] = "Para reclamar las recompensas del conjunto Karamja, habla con Jackie the Fruit en el Agility Arena de Brimhaven, con Kaleb Paramaya en la posada Shilo Village o conmigo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Karamja gloves 1"] = "guantes Karamja 1",
        ["Karamja gloves 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Guantes Karamja 1? Sí, pero me temo que te costaría 1.500 coins.",
        ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
        ["Yes"] = "si",
        ["[You're handed another Karamja gloves 1.]"] = "[Te entregan otros guantes Karamja 1.]",
        ["No thanks."] = "No, gracias.",
        ["Karamja gloves 2"] = "guantes Karamja 2",
        ["Karamja gloves 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Guantes Karamja 2? Sí, pero me temo que te costaría 2500 coins.",
        ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
        ["[You're handed another Karamja gloves 2.]"] = "[Te entregan otros guantes Karamja 2.]",
        ["Karamja gloves 3"] = "Guantes Karamja 3",
        ["Karamja gloves 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Guantes Karamja 3? Sí, pero me temo que te costaría 7.500 coins.",
        ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
        ["[You're handed another Karamja gloves 3.]"] = "[Te entregan otros guantes Karamja 3.]",
        ["Karamja gloves 4"] = "Guantes Karamja 4",
        ["Karamja gloves 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Guantes Karamja 4? Sí, pero me temo que te costaría 15.000 coins.",
        ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
        ["[You're handed another Karamja gloves 4.]"] = "[Te entregan otros guantes Karamja 4.]",
    },
    ["Junior Cadet Bertol"] = {
        ["*To access all of this dialogue the player must have:*"] = "*Para acceder a todo este diálogo, el player debe tener:*",
        [":*File:Ring of charos (a).png A Ring of Charos (a)"] = ":*Archivo:Ring of charos (a).png A Ring of Charos (a)",
        [":*File:H.A.M. logo.png Any one or combination of items from the H.A.M. robes set."] = ":*Archivo:H.A.M. logo.png Cualquiera o combinación de artículos del H.A.M. conjunto de batas.",
        ["*Some dialogue options require that certain pieces of equipment be equipped or unequipped.*"] = "*Algunas opciones de diálogo requieren que ciertos equipos estén equipados o desequipados.*",
        ["Hello, what's your job?"] = "Hola, cual es tu trabajo?",
        ["One of upmost importance."] = "Uno de suma importancia.",
        ["Which is?"] = "¿Cuál es?",
        ["**Dialogue Branches**"] = "**Ramas de Diálogo**",
        [":A. Ring of charos (a) on or off, H.A.M. robes off"] = ":A. Ring of charos (a) encendido o apagado, H.A.M. batas fuera",
        ["::A-2. Ring of charos (a) on, H.A.M. robes off"] = "::A-2. Ring of charos (a) en adelante, H.A.M. batas fuera",
        [":::A-2a. Do not use Charm"] = ":::A-2a. No uses encanto",
        [":::A-2b. Use Charm"] = ":::A-2b. Usar encanto",
        ["::::*A-2b becomes B-2*"] = "::::*A-2b se convierte en B-2*",
        ["::A-3. Ring of charos (a) off, H.A.M. robes off"] = "::A-3. Ring of charos (a) apagado, H.A.M. batas fuera",
        [":B. Ring of charos (a) on or off, H.A.M. robes on"] = ":B. Ring of charos (a) encendido o apagado, H.A.M. batas puestas",
        ["::B-2. H.A.M. Dialogue"] = "::B-2. JAMÓN. Diálogo",
        [":::b-1. H.A.M.?"] = ":::b-1. JAMÓN.?",
        [":::b-2. Why are you here?"] = ":::b-2. ¿Por qué estás aquí?",
        ["::::b-2a. Support his cause"] = "::::b-2a. Apoya su causa",
        ["::::b-2b. Disagree with him"] = "::::b-2b. No estoy de acuerdo con el",
        [":::b-3. What have you done?"] = ":::b-3. ¿Qué has hecho?",
        [":::b-4. Finishing up"] = ":::b-4. terminando",
        ["A. **Junior Cadet Bertol**: <span id=\"RingXHAMN\">It's so incredibly top-secret that I'd have to kill you if you found out.</span>"] = "A. **Junior Cadet Bertol**: <span id=\"RingXHAMN\">Es tan increíblemente secreto que tendría que matarte si te enteraras.</span>",
        [":Ring of charos (a) on, H.A.M. robes off"] = ":Ring of charos (a) en adelante, H.A.M. batas fuera",
        [":Ring of charos (a) off, H.A.M. robes off"] = ":Ring of charos (a) apagado, H.A.M. batas fuera",
        ["<span id=\"RingYHAMN\">A-2. **Use Ring of charos (a)?**</span>"] = "<span id=\"RingYHAMN\">A-2. **¿Usar Ring of charos (a)?**</span>",
        [":**Select an Option**"] = ":**Seleccione una opción**",
        ["::A-2a. 1. Best I not prod further, then."] = "::A-2a. 1. Entonces, será mejor que no insista más.",
        ["::A-2b. 2. I can keep a secret. (Charm.)"] = "::A-2b. 2. Puedo guardar un secreto. (Encanto.)",
        [":<span id=\"RingD\">**1. Best I not prod further, then.**</span>"] = ":<span id=\"RingD\">**1. Entonces, será mejor que no insista más.**</span>",
        ["::**Player**: Best I not prod further, then."] = "::**Player**: Entonces, será mejor que no insista más.",
        [":::*Dialogue ends.*"] = ":::*El diálogo termina.*",
        [":<span id=\"RingU\">**2. I can keep a secret. (Charm.)**</span>"] = ":<span id=\"RingU\">**2. Puedo guardar un secreto. (Encanto.)**</span>",
        ["::**Player**: I can keep a secret."] = "::**Player**: Puedo guardar un secreto.",
        ["::**Junior Cadet Bertol**: Very well. I'm a member of H.A.M."] = "::**Junior Cadet Bertol**: Muy bien. Soy miembro de H.A.M.",
        [":::*Skip to H.A.M. Dialogue*"] = ":::*Pasar a H.A.M. Diálogo*",
        ["<span id=\"RingNHAMN\">A-3. **With neither Ring of charos (a) nor H.A.M. robes**</span>"] = "<span id=\"RingNHAMN\">A-3. **Sin Ring of charos (a) ni H.A.M. batas**</span>",
        [":**Player**: I can keep a secret."] = ":**Player**: Puedo guardar un secreto.",
        [":**Junior Cadet Bertol**: The knowledge alone would fry your little brain."] = ":**Junior Cadet Bertol**: El conocimiento por sí solo freiría tu pequeño cerebro.",
        [":**Player**: I doubt it."] = ":**Player**: Lo dudo.",
        [":**Junior Cadet Bertol**: It so would!"] = ":**Junior Cadet Bertol**: ¡Así sería!",
        [":**Player**: Wouldn't."] = ":**Player**: No lo haría.",
        [":**Junior Cadet Bertol**: Would."] = ":**Junior Cadet Bertol**: Lo haría.",
        [":**Player**: Wouldn't times ten!"] = ":**Player**: ¡No sería multiplicado por diez!",
        [":**Junior Cadet Bertol**: Would times infinity!"] = ":**Junior Cadet Bertol**: ¡Se multiplicaría por el infinito!",
        [":**Player**: Prove it."] = ":**Player**: Pruébalo.",
        [":**Junior Cadet Bertol**: Okay, I'm under cover as...ah you almost had me, there."] = ":**Junior Cadet Bertol**: Está bien, estoy encubierto porque... ah, casi me tienes ahí.",
        [":**Player**: Ah, so close!"] = ":**Player**: ¡Ah, qué cerca!",
        ["::*Dialogue ends.*"] = "::*El diálogo termina.*",
        ["<span id=\"RingXHAMY\">B. **With any H.A.M. robe item worn, with or without Ring of charos (a)**</span>"] = "<span id=\"RingXHAMY\">B. **Con cualquier H.A.M. artículo de bata usado, con o sin Ring of charos (a)**</span>",
        [":**Junior Cadet Bertol**: Well, I see from your clothes that you're a member of H.A.M. I am too."] = ":**Junior Cadet Bertol**: Bueno, veo por tu ropa que eres miembro de H.A.M. Yo también lo soy.",
        ["::*To H.A.M. Dialogue*"] = "::*A H.A.M. Diálogo*",
        ["<span id=\"B2\">B-2. **H.A.M. Dialogue**</span>"] = "<span id=\"B2\">B-2. **JAMÓN. Diálogo**</span>",
        ["::b-1. 1. What's H.A.M.?"] = "::b-1. 1. ¿Qué es HAM?",
        ["::b-2. 2. What's H.A.M. got to do with this command centre?"] = "::b-2. 2. ¿Qué es H.A.M.? ¿Tiene que ver con este centro de mando?",
        [":::b-2a. 1. I wish you good luck."] = ":::b-2a. 1. Te deseo buena suerte.",
        [":::b-2b. 2. How awful."] = ":::b-2b. 2. Qué horrible.",
        ["::b-3. 3. What have you done while undercover?"] = "::b-3. 3. ¿Qué has hecho mientras estabas encubierto?",
        ["::b-4. 4. I've heard enough."] = "::b-4. 4. Ya he oído suficiente.",
        [":<span id=\"b1\">**1. What's H.A.M.?**"] = ":<span id=\"b1\">**1. ¿Qué es H.A.M.?**",
        ["::**Player**: What's H.A.M.?"] = "::**Player**: ¿Qué es H.A.M.?",
        ["::**Junior Cadet Bertol**: It stands for 'Humans Against Monsters': a group keen on enforcing that humans are all that belongs on RuneScape."] = "::**Junior Cadet Bertol**: Significa 'Humanos contra monstruos': un grupo interesado en hacer cumplir que los humanos son lo único que pertenece a RuneScape.",
        [":::*Back to H.A.M. Dialogue*"] = ":::*Volver a H.A.M. Diálogo*",
        [":<span id=\"b2\">**2. What's H.A.M. got to do with this command centre?**"] = ":<span id=\"b2\">**2. ¿Qué es H.A.M.? ¿Tiene algo que ver con este centro de mando?**",
        ["::**Player**: What's H.A.M. got to do with this command centre?"] = "::**Player**: ¿Qué es H.A.M.? ¿Tiene que ver con este centro de mando?",
        ["::**Junior Cadet Bertol**: Open your eyes! It's crawling with all manner of disgusting creatures. At least they've got one thing right - humans are officers rather than grunts."] = "::**Junior Cadet Bertol**: ¡Abre los ojos! Está plagado de todo tipo de criaturas repugnantes. Al menos tienen algo en claro: los humanos son oficiales y no gruñidos.",
        ["::**Player**: But what can H.A.M. do about it?"] = "::**Player**: ¿Pero qué puede hacer H.A.M. hacer al respecto?",
        ["::**Junior Cadet Bertol**: My friend, I'm on a mission to stop it all - by any means necessary."] = "::**Junior Cadet Bertol**: Amigo mío, tengo la misión de detenerlo todo, por cualquier medio necesario.",
        [":::**Select an Option**"] = ":::**Seleccione una opción**",
        ["::::<span id=\"b2a\">1. I wish you good luck.</span>"] = "::::<span id=\"b2a\">1. Te deseo buena suerte.</span>",
        [":::::**Player**: I wish you good luck."] = ":::::**Player**: Te deseo buena suerte.",
        [":::::**Junior Cadet Bertol**: Thanks. I can assure you that I'll need no luck with the ingenuity of my plans."] = ":::::**Junior Cadet Bertol**: Gracias. Puedo asegurarte que no necesitaré suerte con el ingenio de mis planes.",
        ["::::::*Back to H.A.M. Dialogue*"] = "::::::*Volver a H.A.M. Diálogo*",
        ["::::<span id=\"b2b\">2. How awful.</span>"] = "::::<span id=\"b2b\">2. Que horrible.</span>",
        [":::::**Player**: How awful."] = ":::::**Player**: Qué horrible.",
        [":::::**Junior Cadet Bertol**: There's nothing awful about my mission."] = ":::::**Junior Cadet Bertol**: No hay nada terrible en mi misión.",
        [":::::**Player**: I disagree. Give me one reason why I shouldn't head to an officer and tell them of your secret agenda."] = ":::::**Player**: No estoy de acuerdo. Dame una razón por la que no debería dirigirme a un oficial y contarle tu agenda secreta.",
        [":::::**Junior Cadet Bertol**: Do as you wish. He'll never believe some stranger over a cadet."] = ":::::**Junior Cadet Bertol**: Haz lo que desees. Nunca creerá en un extraño antes que en un cadete.",
        [":::::**Player**: You mean junior cadet."] = ":::::**Player**: Te refieres al cadete junior.",
        [":::::**Junior Cadet Bertol**: How observant of you."] = ":::::**Junior Cadet Bertol**: Qué observador de tu parte.",
        [":<span id=\"b3\">**3. What have you done while undercover?**"] = ":<span id=\"b3\">**3. ¿Qué has hecho mientras estabas encubierto?**",
        ["::**Player**: What have you done while undercover?"] = "::**Player**: ¿Qué has hecho mientras estabas encubierto?",
        ["::**Junior Cadet Bertol**: Plenty! Spreading rumours, sabotaging special units; recently, I've hit upon mixing up the battle orders so commanders end up travelling to the wrong destinations! He he."] = "::**Junior Cadet Bertol**: ¡Mucho! Difundir rumores, sabotear unidades especiales; ¡Recientemente, he llegado a mezclar las órdenes de batalla para que los comandantes terminen viajando a los destinos equivocados! Él, él.",
        ["::**Player**: Cunning."] = "::**Player**: Astuto.",
        [":<span id=\"b4\">**4. I've heard enough.**"] = ":<span id=\"b4\">**4. Ya he oído suficiente.**",
        ["::**Player**: I've heard enough."] = "::**Player**: Ya he oído suficiente.",
        ["::**Junior Cadet Bertol**: Fine by me."] = "::**Junior Cadet Bertol**: Por mí está bien.",
    },
    ["Junior Cadet Boff"] = {
        ["Hello. What do you do here?"] = "Hola. ¿Qué haces aquí?",
        ["Me? I'm the best junior cadet you'll ever find! Cream of the crop!"] = "¿Yo? ¡Soy el mejor cadete junior que jamás encontrarás! ¡Crema de la cosecha!",
        ["Prove it."] = "Pruébalo.",
        ["I don't need to. It's as sure as eggs."] = "No es necesario. Es tan seguro como los huevos.",
        ["Arrogant much?"] = "¿Muy arrogante?",
        ["Annoying much?"] = "¿Te molesta mucho?",
        ["Time-wasting much?"] = "¿Perdiste mucho el tiempo?",
        ["Duh! Much?"] = "¡Claro! ¿Mucho?",
        ["What?"] = "¿Qué?",
    },
    ["Junior Cadet Finda"] = {
        ["Hi. You look quite important. What do you do here?"] = "Hola. Pareces bastante importante. ¿Qué haces aquí?",
        ["Shhh, they're watching!"] = "¡Shhh, están mirando!",
        ["What? Who?"] = "¿Qué? ¿OMS?",
        ["There are secret agents everywhere. Trust no-one!"] = "Hay agentes secretos por todas partes. ¡No confíes en nadie!",
        ["Why, what's the matter?"] = "¿Por qué? ¿Cuál es el problema?",
        ["Such a conspiracy like you wouldn't imagine. I believe this place is the source, as I shall soon find out."] = "Una conspiración como no te la imaginas. Creo que este lugar es la fuente, como pronto descubriré.",
        ["Okay..."] = "Está bien...",
        ["I've said too much. Please - go on your way."] = "He dicho demasiado. Por favor, sigue tu camino.",
    },
    ["Junior Cadet Grimeface"] = {
        ["Hi. It looks like you're planning a complex battle?"] = "Hola. ¿Parece que estás planeando una batalla compleja?",
        ["We talking tactics. Trying to make tactic that beat any opponent."] = "Estamos hablando de tácticas. Intentando hacer una táctica que venza a cualquier oponente.",
        ["That sounds somewhat impossible."] = "Eso suena algo imposible.",
        ["Nothing impossible. Nothing at all."] = "Nada imposible. Nada en absoluto.",
        ["So, what's the tactic?"] = "Entonces, ¿cuál es la táctica?",
        ["I can tell, but remember it a work in progress."] = "Lo sé, pero recuerda que es un trabajo en progreso.",
        ["Of course, I understand."] = "Por supuesto que lo entiendo.",
        ["Okay. The plan start with running at them."] = "Está bien. El plan comienza corriendo hacia ellos.",
        ["Running at them?"] = "¿Corriendo hacia ellos?",
        ["Yes, and shout 'Die, die!' at top of our voices. Then, when the enemy least expects, we do what they least expect."] = "Sí, y grita '¡Muere, muere!' a la altura de nuestras voces. Luego, cuando el enemigo menos lo espera, hacemos lo que menos espera.",
        ["And that is?"] = "¿Y eso es?",
        ["Attack them!"] = "¡Attack ellos!",
        ["Hmmm, that sounds rather basic and predictable, but good luck."] = "Hmmm, eso suena bastante básico y predecible, pero buena suerte.",
    },
    ["Junior Cadet Mal"] = {
        ["What's the matter?"] = "¿Qué pasa?",
        ["Oh, such a crisis here at A.R.M.S.!"] = "¡Oh, qué crisis aquí en A.R.M.S.!",
        ["Can I help?"] = "¿Puedo ayudar?",
        ["Really? Rebellious mercenaries have made away with a cache of A.R.M.S.'s battle supplies, and all the other commanders are fighting a far-away battle. I've been left to 'hold the fort', but, being just one man, I don't think I can retrieve the stolen supplies."] = "¿En serio? Los mercenarios rebeldes se han llevado un alijo de suministros de batalla de A.R.M.S. y todos los demás comandantes están librando una batalla lejana. Me han dejado \"mantener el fuerte\", pero, siendo solo un hombre, no creo que pueda recuperar los suministros robados.",
        ["Don't worry, we'll sort this out."] = "No te preocupes, solucionaremos esto.",
        ["Great, let's go! There's no time to lose."] = "Genial, ¡vamos! No hay tiempo que perder.",
        ["*(Mobilising Armies Tutorial begins)*"] = "*(Comienza el tutorial sobre movilización de ejércitos)*",
        ["What's A.R.M.S.?"] = "¿Qué es A.R.M.S.?",
        ["The Army Recruitment and Mobilisation Society. We're here to make sure all war heroes and warriors can earn a living through honourable combat."] = "Sociedad de Reclutamiento y Movilización del Ejército. Estamos aquí para asegurarnos de que todos los héroes y guerreros de guerra puedan ganarse la vida mediante un combate honorable.",
        ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
        ["You're back! I still need your help with the battle."] = "¡Has vuelto! Todavía necesito tu ayuda con la batalla.",
        ["Okay, let's do this."] = "Bien, hagamos esto.",
        ["*(Mobilising Armies Tutorial continues)*"] = "*(El tutorial sobre movilización de ejércitos continúa)*",
        ["Maybe some other time."] = "Quizás en otro momento.",
        ["Oh no, what am I to do?"] = "Oh no, ¿qué debo hacer?",
        ["So, can I continue with the officer training?"] = "Entonces, ¿puedo continuar con la capacitación de oficiales?",
        ["Certainly!"] = "¡Por supuesto!",
        ["*(Officer training continues)*"] = "*(Continúa el entrenamiento de oficiales)*",
        ["Sorry, wrong person."] = "Lo siento, la persona equivocada.",
        ["Oh, okay."] = "Oh, está bien.",
        ["How might I help you?"] = "¿En qué puedo ayudarte?",
        ["Extra training."] = "Entrenamiento adicional.",
        ["These are optional, remember."] = "Estos son opcionales, recuerda.",
        ["*(Extra Lessons opens)*"] = "*(Se abren lecciones adicionales)*",
        ["Invest commodities."] = "Invertir materias primas.",
        ["*(Investment Credit Exchange opens)*"] = "*(Se abre el Intercambio de Créditos de Inversión)*",
        ["What are commodities?"] = "¿Qué son las mercancías?",
        ["*(Commodities list opens)*"] = "*(Se abre la lista de productos básicos)*",
        ["Nothing, thanks."] = "Nada, gracias.",
    },
    ["Junior Cadet Nirol"] = {
        ["Hello. What do you do here?"] = "Hola. ¿Qué haces aquí?",
        ["I'm the token gnome round here at the moment. Most officers think I'm here to to make drinks and serve gnome snacks."] = "Soy el gnomo simbólico que hay por aquí en este momento. La mayoría de los oficiales creen que estoy aquí para preparar bebidas y servir bocadillos a los gnomos.",
        ["It's a start, I guess."] = "Supongo que es un comienzo.",
        ["Pfft. Just you wait till my gnome unit comes back from battle, then I'll show 'em."] = "Pfft. Espera hasta que mi unidad de gnomos regrese de la batalla y luego se los mostraré.",
        ["Good luck with that."] = "Buena suerte con eso.",
    },
    ["Juvenile boulder crab"] = {
        ["Talk to crabs? How silly."] = "¿Hablar con cangrejos? Qué tonto.",
        ["I'm currently on a 50 pound boulder. Slowly working my way up to 100 pounds though, just like my da."] = "Actualmente estoy en una roca de 50 libras. Sin embargo, poco a poco voy subiendo a 100 libras, al igual que mi papá.",
        ["It's not too bad having your whole home on your back and all."] = "No está tan mal tener toda tu casa sobre tus espaldas y todo eso.",
        ["Heavy, sure, but gives me the freedom to move wherever I like with just the snap of a claw."] = "Pesado, claro, pero me da la libertad de moverme donde quiera con solo chasquear una garra.",
        ["Alright, mate?"] = "¿Está bien, amigo?",
        ["I heard the southern siders got some fancy huts built for them. Actually sounds quite nice."] = "Escuché que a los habitantes del sur les construyeron algunas cabañas elegantes. En realidad suena bastante bien.",
        ["That cave with the odd hermit human in it reeks a bit too much for my liking."] = "Esa cueva con algún que otro humano ermitaño dentro apesta demasiado para mi gusto.",
        ["You best not try to take any of my limestone. There's good mining rocks just over there without having to steal what's mine."] = "Será mejor que no intentes tomar nada de mi piedra caliza. Allí se pueden extraer buenas rocas sin tener que robar lo que es mío.",
    },
    ["Juvinate guard"] = {
        ["Hey! How do I get out of here?"] = "¡Oye! ¿Cómo salgo de aquí?",
        ["When you've filled the mine cart, we'll think about it."] = "Cuando hayas llenado el carro de la mina, lo pensaremos.",
        ["*(If the player has 15 loads of ore in the mine cart:)*"] = "*(Si el player tiene 15 cargas de mineral en el carro de la mina:)*",
        ["But I've filled the mine cart."] = "Pero ya llené el carro de la mina.",
        ["Okay, I guess you can go then, food sack!"] = "Está bien, supongo que entonces puedes irte, ¡saco de comida!",
        ["The juvinate sends you back through the mines."] = "El juvinate te envía de regreso a través de las minas.",
    },
}

dialogues.all = {
    ["You need to make things. Leather. Pottery. Every piece you make will increase your skill."] = "Necesitas hacer cosas. Cuero. Cerámica. Cada pieza que hagas aumentará tu habilidad.",
    ["Select an Option"] = "Selecciona una opción",
    ["I need Crafting supplies."] = "Necesito suministros Crafting.",
    ["Tell me about Crafting and other artisan skills."] = "Cuéntame sobre Crafting y otras habilidades artesanales.",
    ["Crafting is the most versatile skill by far. You can make leather armour, pottery, jewellery and even glasswork."] = "Crafting es, con diferencia, la habilidad más versátil. Puedes fabricar armaduras de cuero, cerámica, joyas e incluso cristalería.",
    ["If you ever get as good as me, you'll be able to perform extraordinary feats like making armour from the hides of dragons!"] = "¡Si alguna vez llegas a ser tan bueno como yo, podrás realizar hazañas extraordinarias como hacer armaduras con pieles de dragones!",
    ["Tell me about Fletching."] = "Háblame de Fletching.",
    ["Fletching is about making bows and arrows. The better you are at it, and the better the quality of your materials, the better the result."] = "Fletching se trata de hacer arcos y flechas. Cuanto mejor lo hagas y mejor sea la calidad de tus materiales, mejor será el resultado.",
    ["Every bow and every arrow you make will increase your skill."] = "Cada arco y cada flecha que hagas aumentará tu habilidad.",
    ["If you expect to spend any time as an archer you'll want to ensure you have the arrows you need."] = "Si esperas pasar algún tiempo como arquero, querrás asegurarte de tener las flechas que necesitas.",
    ["Most people have no appreciation for how many arrows an army goes through every day. We could really use your help re-supplying them."] = "La mayoría de la gente no aprecia cuántas flechas atraviesa un ejército cada día. Realmente nos vendría bien su ayuda para reabastecerlos.",
    ["Tell me about Smithing."] = "Háblame de Smithing.",
    ["Smithing is all about making weapons. And armour! The better you are at smithing, the higher the quality of the metal you can work with and the better the resulting items are."] = "Smithing se trata de fabricar armas. ¡Y armadura! Cuanto mejor seas forjando, mayor será la calidad del metal con el que podrás trabajar y mejores serán los elementos resultantes.",
    ["Every bar of metal you smelt and every metal item you smith will improve your abilities."] = "Cada barra de metal que fundes y cada objeto de metal que forjas mejorará tus habilidades.",
    ["As well as being able to make gear directly, some of the most powerful ancient relics need an expert smith to reassemble their fragmented parts."] = "Además de poder fabricar equipo directamente, algunas de las reliquias antiguas más poderosas necesitan un herrero experto para volver a ensamblar sus partes fragmentadas.",
    ["Burthorpe's militia need to be kept well supplied with arms and armour. It falls to smiths to meet that need."] = "La milicia de Burthorpe necesita estar bien provista de armas y armaduras. Corresponde a los herreros satisfacer esa necesidad.",
    ["(back)"] = "(atrás)",
    ["Tell me about the skills menu."] = "Cuéntame sobre el menú de habilidades.",
    ["You have many skills you can train. The more you practice a skill, the better it gets. Higher skill levels unlock new activities: equipment to craft, locations to explore, quests to complete, and much more."] = "Tienes muchas habilidades que puedes entrenar. Cuanto más practicas una habilidad, mejor se vuelve. Los skill levels superiores desbloquean nuevas actividades: equipos para crear, lugares para explorar, misiones para completar y mucho más.",
    ["Perform actions associated with a skill to earn experience points (XP) in that skill. Earn enough XP and you'll gain a level in that skill."] = "Realiza acciones asociadas con una habilidad para ganar puntos de experiencia (XP) en esa habilidad. Gana suficiente XP y ganarás un nivel en esa habilidad.",
    ["Most skills start at level 1, and you unlock all their benefits by leveling the skill to 99. (Some skills have unlocks up to level 120.)"] = "La mayoría de las habilidades comienzan en el nivel 1 y desbloqueas todos sus beneficios al subir la habilidad al nivel 99. (Algunas habilidades se pueden desbloquear hasta el nivel 120).",
    ["The bottom number next to a skill icon is your base level in that skill (un-modified by buffs or debuffs). It is used for most requirement checks."] = "El número inferior al lado del ícono de una habilidad es tu nivel base en esa habilidad (sin modificar por ventajas o desventajas). Se utiliza para la mayoría de las comprobaciones de requisitos.",
    ["The top number is your modified skill level (temporarily boosted or drained by skill buffs and debuffs - such as potions or spells). It is used for most skill checks."] = "El número superior es tu skill level modificado (impulsado o agotado temporalmente por mejoras y desventajas de habilidades, como pociones o hechizos). Se utiliza para la mayoría de las pruebas de habilidades.",
    ["Achieve 99 in all your skills to earn the coveted Max Cape!"] = "¡Consigue 99 en todas tus habilidades para ganar la codiciada capa Max!",
    ["Farewell."] = "Adiós.",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["Hello."] = "Hola.",
    ["Hello to you too."] = "Hola a ti también.",
    ["Yar!<br> We be pirates, yar! <br>Avast, ye scurvy land-lubbing lychee!"] = "¡Sí! <br> ¡Seremos piratas, sí! <br>Avast, ¡lichi que lubrica la tierra con escorbuto!",
    ["Please don't talk like that, it is extremely irritating."] = "Por favor, no hables así, es extremadamente irritante.",
    ["Also, please don't call me a lychee, whatever that may be."] = "Además, por favor no me llames lichi, sea lo que sea.",
    ["Oh.<br> Okay. <br>Sorry."] = "Oh.<br> Está bien. <br>Lo siento.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["So...<br>You're a pirate, huh?"] = "Entonces...<br>Eres un pirata, ¿eh?",
    ["It's what it says on my pay-packet at the end of the month."] = "Es lo que pone en mi nómina a final de mes.",
    ["How's that working out for you?"] = "¿Qué te parece?",
    ["Pretty good so far. <br>All the grog and loot that we can plunder, plus full medical including dental."] = "Bastante bien hasta ahora. <br>Todo el grog y el botín que podamos saquear, además de asistencia médica completa, incluido dental.",
    ["You mean you have insurance?"] = "¿Quieres decir que tienes seguro?",
    ["Not as such. <br>If any of us get sick we kidnap a doctor and don't let him go until we're better."] = "No como tal. <br>Si alguno de nosotros se enferma, secuestramos a un médico y no lo dejamos ir hasta que estemos mejor.",
    ["You'd be surprised what an incentive for expert health care that is."] = "Te sorprendería el incentivo que supone para la atención sanitaria experta.",
    ["I can imagine."] = "Me lo imagino.",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["Sorry, can't stop, the Captain will have my guts for garters if he catches me slacking off talking to the stowaway."] = "Lo siento, no puedo parar, el Capitán me tomará las tripas como ligas si me pilla holgazaneando hablando con el polizón.",
    ["I'm not a stowaway! <br>I was invited aboard!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo!",
    ["Yeah, whatever [guy/lady], it doesn't really matter who you are I'll get in trouble!"] = "Sí, sea lo que sea [guy/lady], realmente no importa quién seas, ¡me meteré en problemas!",
    ["*Dialogue 4:*"] = "*Diálogo 4:*",
    ["You know, I've always wondered what life as a pirate actually entails."] = "Sabes, siempre me he preguntado qué implica realmente la vida como pirata.",
    ["Well, at the moment it mostly involves being asked random questions by a stowaway."] = "Bueno, por el momento se trata principalmente de que un polizón te haga preguntas aleatorias.",
    ["I'm not a stowaway! <br>I was invited aboard! <br>By Lokar! <br>Ask him!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo! <br>Por Lokar! <br>¡Pregúntale!",
    ["Hey, whatever [pal/love]. <br>Just make sure the captain doesn't catch you, pirates don't like stowaways much."] = "Oye, lo que sea [pal/love]. <br>Solo asegúrate de que el capitán no te atrape, a los piratas no les gustan mucho los polizones.",
    ["*Dialogue 5:*"] = "*Diálogo 5:*",
    ["Ah, good day to you [sirrah/milady]! <br>Your face is unfamiliar, did you perhaps join us aboard the ship at Lunar Isle?"] = "¡Ah, buenos días para ti [sirrah/milady]! <br>Tu cara no te resulta familiar, ¿quizás te uniste a nosotros a bordo del barco en Lunar Isle?",
    ["No, Lokar offered me a lift in Rellekka actually."] = "No, Lokar me ofreció llevarme en Rellekka en realidad.",
    ["Oh, really? <br>You don't look like a Fremennik to me!"] = "Oh, ¿en serio? <br>¡No me pareces un Fremennik!",
    ["Well...<br> I kind of am, and I kind of aren't. <br>It's a long story."] = "Bueno... <br> En cierto modo lo soy y en cierto modo no. <br>Es una larga historia.",
    ["Sorry I don't have time to hear it then! <br>See you around young fremennik-who-is-not-really-a-fremennik!"] = "¡Lo siento, entonces no tengo tiempo para escucharlo! <br>¡Nos vemos por aquí, joven fremennik-que-no-es-realmente-un-fremennik!",
    ["Bye."] = "Adiós.",
    ["*Dialogue 6:*"] = "*Diálogo 6:*",
    ["Brrrr! <br>Its cold up here!"] = "¡Brrrr! <br>¡Hace frío aquí arriba!",
    ["You think this is cold? <br>Up by Acheron it gets so cold that when you talk you see the words freeze in the air in front of you!"] = "¿Crees que esto hace frío? <br>Up de Acheron ¡Hace tanto frío que cuando hablas ves las palabras congelarse en el aire frente a ti!",
    ["REALLY?"] = "¿EN SERIO?",
    ["Nah, not really. <br>I was exaggerating for humourous effect. It is very very cold though!"] = "No, en realidad no. <br>I estaba exagerando para lograr un efecto humorístico. ¡Aunque hace mucho, mucho frío!",
    ["*Dialogue 7:*"] = "*Diálogo 7:*",
    ["ARGH! <br>SOUND THE ALARM! <br>STOWAWAY ON BOARD! <br>STOWAWAY ON BOARD!"] = "¡ARGH! <br>¡SUENA LA ALARMA! <br> ¡PILOTO A BORDO! <br>STOWAWAY ¡A BORDO!",
    ["No! <br>I'm not a stowaway! <br>Honest! I was invited here!"] = "¡No! <br>¡No soy un polizón! <br>¡Honesto! ¡Me invitaron aquí!",
    ["Oh, sorry, my mistake then."] = "Oh, lo siento, entonces fue mi error.",
    ["You must admit you do look a lot like a stowaway though."] = "Aunque debes admitir que te pareces mucho a un polizón.",
    ["Why, what do they usually look like?"] = "¿Cómo son normalmente?",
    ["Erm... <br>I've never actually met one..."] = "Erm... <br>I nunca he conocido a uno...",
    ["Okay then..."] = "Bueno, entonces...",
    ["*Dialogue 8:*"] = "*Diálogo 8:*",
    ["Aren't you a little short for a pirate?"] = "¿No eres un poco bajo para ser un pirata?",
    ["My mother was a gnome. <br>Apparently it was a very painful birth."] = "Mi madre era un gnomo. <br>Al parecer fue un parto muy doloroso.",
    ["More info than I wanted, thanks!"] = "Más información de la que quería, ¡gracias!",
    ["*Dialogue 9:*"] = "*Diálogo 9:*",
    ["Hello there. <br>So what brings you aboard the Lady Zay?"] = "Hola. <br> Entonces, ¿qué te trae a bordo del Lady Zay?",
    ["Well, I was planning on visiting the Moon Clan, but I have to say your ship is very impressive."] = "Bueno, estaba planeando visitar el Clan de la Luna, pero debo decir que tu barco es muy impresionante.",
    ["Aye, she's a beauty alright! <br>The Lady Zay has been my home for many hard months, through storm and sun, and she always gets us to here we were headed!"] = "¡Sí, ella es una belleza! <br>La Lady Zay ha sido mi hogar durante muchos meses difíciles, a través de tormentas y sol, ¡y siempre nos lleva hacia donde nos dirigimos!",
    ["Yes, she's certainly one of the finest boats I've seen on my travels!"] = "Sí, ¡sin duda es uno de los mejores barcos que he visto en mis viajes!",
    ["That she is [lad/lass], that she is."] = "Que ella es [lad/lass], que ella es.",
    ["*Dialogue 10:*"] = "*Diálogo 10:*",
    ["So how's life as a pirate?"] = "Entonces, ¿cómo es la vida como pirata?",
    ["What kind of question is that? <br>How's life as a... <br>I dunno. <br>Whatever it is that you do for a living."] = "¿Qué tipo de pregunta es esa? <br>Cómo es la vida como... <br>No lo sé. <br>Sea lo que sea a lo que te dedicas.",
    ["I'm a freelance troubleshooter."] = "Soy un solucionador de problemas independiente.",
    ["What does that entail then?"] = "¿Qué implica eso entonces?",
    ["Mostly killing things for money and delivering items around the planet for people."] = "Principalmente matando cosas por dinero y entregando artículos en todo el planeta para las personas.",
    ["I collect stuff."] = "Colecciono cosas.",
    ["So how's that life?"] = "Entonces, ¿cómo es esa vida?",
    ["Can't complain, can't complain..."] = "No me puedo quejar, no me puedo quejar...",
    ["Well, there you go."] = "Bueno, ahí lo tienes.",
    ["Arrr, matey!"] = "¡Arrr, amigo!",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["I'm looking for Redbeard Frank."] = "Estoy buscando a Redbeard Frank.",
    ["Redbeard Frank ye say? He be outside. Says he likes the feel of the wind on his cheeks."] = "Redbeard Frank ¿dices? Él estará afuera. Dice que le gusta sentir el viento en sus mejillas.",
    ["Thanks."] = "Gracias.",
    ["What are you doing here?"] = "¿Qué haces aquí?",
    ["Drinking."] = "Bebiendo.",
    ["Fair enough."] = "Muy bien.",
    ["Have you got any quests I could do?"] = "¿Tienes alguna misión que pueda hacer?",
    ["Nay, but the barkeep hears most of the news around here. Or Redbeard Frank, he's often spoken of buried treasure. Perhaps ye should be asking them for quests."] = "No, pero el camarero se entera de la mayoría de las noticias por aquí. O Redbeard Frank, a menudo se habla de tesoro enterrado. Quizás deberías pedirles misiones.",
    ["Nay, but the barkeep hears most of the news around here. Perhaps ye should be asking him for a quest."] = "No, pero el camarero se entera de la mayoría de las noticias por aquí. Quizás deberías pedirle una misión.",
    ["Nay, but Redbeard Frank has often spoken of buried treasure. Perhaps ye should be asking him for a quest."] = "No, pero Redbeard Frank ha hablado a menudo de tesoros enterrados. Quizás deberías pedirle una misión.",
    ["Nay, I've got nothing for ye to do. But I hear there's an old landlubber in Draynor Village who's always a-looking for a lively [lad/lass] to do him a favour."] = "No, no tengo nada que hacer. Pero he oído que hay un viejo marinero de agua dulce en Draynor Village que siempre está buscando un [lad/lass] animado que le haga un favor.",
    ["Yo ho ho!"] = "¡Ho, ho, ho!",
    ["So are you pirates?"] = "Entonces, ¿sois piratas?",
    ["Aye [laddie/lassie], that we are."] = "Sí, [laddie/lassie], eso es lo que somos.",
    ["Aye, that we be."] = "Sí, así lo seremos.",
    ["Nay, always ye say it wrong! Tis 'we are', not 'we be'."] = "No, ¡siempre lo dices mal! Es \"somos\", no \"seremos\".",
    ["I be a pirate, not a scurvy schoolmaster!"] = "¡Seré un pirata, no un maestro de escuela sarcástico!",
    ["Ye be a fool, and a disgrace to piracy."] = "Sois un tonto y una deshonra para la piratería.",
    ["Now ye be saying 'be' too!"] = "¡Ahora tú también dirás 'ser'!",
    ["Arrr! Tis thy fault."] = "¡Arrr! Es tu culpa.",
    ["I think I'll leave you two to sort it out."] = "Creo que los dejaré a ustedes dos para que lo solucionen.",
    ["Ello, and what are you after then?"] = "Hola, ¿y qué buscas entonces?",
    ["Who are you?"] = "¿Quién eres?",
    ["I'm an apprentice Slayer Master."] = "Soy aprendiz de Slayer Master.",
    ["What's a slayer?"] = "¿Qué es un cazador?",
    ["Oh dear, what do they teach you in school?"] = "Dios mío, ¿qué te enseñan en la escuela?",
    ["Well...er..."] = "Bueno... ejem...",
    ["I suppose I'll have to educate you then. A slayer is someone who is trained to fight specific creatures. They know that creatures every weakness and strength. As you can guess it makes killing them a lot easier."] = "Supongo que tendré que educarte entonces. Un asesino es alguien que está entrenado para luchar contra criaturas específicas. Saben que las criaturas tienen todas sus debilidades y fortalezas. Como puedes adivinar, hace que matarlos sea mucho más fácil.",
    ["Wow, can you teach me?"] = "Vaya, ¿puedes enseñarme?",
    ["Sounds useless to me."] = "Me parece inútil.",
    ["Never heard of you."] = "Nunca había oído hablar de ti.",
    ["That's because my foe never lives to tell of me. We slayers are a dangerous bunch."] = "Eso es porque mi enemigo nunca vive para hablar de mí. Los cazadores somos un grupo peligroso.",
    ["Hmmm, well, I'm not so sure..."] = "Hmmm, bueno, no estoy tan seguro...",
    ["Pleeeaasssse!"] = "¡Por favor!",
    ["Oh, okay then, you twisted my arm. You'll have to train against specific groups of creatures."] = "Oh, está bien, entonces, torciste a my arm. Tendrás que entrenar contra grupos específicos de criaturas.",
    ["Ok then, what's first?"] = "Bueno, entonces, ¿qué es lo primero?",
    ["Change your assigned Slayer Task?"] = "¿Cambiar su tarea Slayer asignada?",
    ["[First task] (default)"] = "[First task] (predeterminado)",
    ["Modify your assigned Slayer Task?"] = "¿Modificar su tarea Slayer asignada?",
    ["[Number] [monster's name] (default)"] = "[número] [monster's name] (predeterminado)",
    ["[Number] [monster's name] (min)"] = "[número] [monster's name] (min)",
    ["[Number] [monster's name] (max)"] = "[número] [monster's name] (máx.)",
    ["We'll start you off hunting [monster]. You'll need to kill [number] of them."] = "Empezaremos cazando [monster]. Tendrás que matar a [número] de ellos.",
    ["You'll also need this enchanted gem, it allows Slayer Masters like myself to contact you and update you on your progress. Don't worry if you lose it; you can buy another from any Slayer Master."] = "También necesitarás esta gema encantada, le permite a Slayer Masters, como a mí, contactarte y actualizarte sobre tu progreso. No te preocupes si lo pierdes; puedes comprar otro en cualquier Slayer Master.",
    ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
    ["Ok great!"] = "Ok genial!",
    ["Okay, great!"] = "¡Vale, genial!",
    ["Good luck! Don't forget to come back when you need a new assignment."] = "¡Buena suerte! No olvides volver cuando necesites una nueva tarea.",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
    ["I have a wide selection of Slayer equipment; take a look!"] = "Tengo una amplia selección de equipos Slayer; ¡eche un vistazo!",
    ["Er...nothing..."] = "Eh... nada...",
    ["I need another assignment."] = "Necesito otra tarea.",
    ["You are still hunting [assigned creatures]; come back when you've finished your task."] = "Aún estás buscando a [assigned creatures]; Vuelve cuando hayas terminado tu tarea.",
    ["Do you have anything to trade?"] = "¿Tienes algo para intercambiar?",
    ["I am here to discuss any rewards I might be eligible for."] = "Estoy aquí para discutir cualquier recompensa para la que pueda ser elegible.",
    ["View rewards."] = "Ver recompensas.",
    ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
    ["You'll gain co-op reward points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on the task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos de recompensa cooperativa si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estés trabajando en la tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
    ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
    ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
    ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
    ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado a matar a [assigned creatures]; sólo faltan X más.",
    ["Where are you?"] = "¿Dónde estás?",
    ["That's all thanks."] = "Eso es todo, gracias.",
    ["My name is Jacquelyn; I'm a Slayer Master."] = "Mi nombre es Jacquelyn; Soy un Slayer Master.",
    ["You'll find me in Lumbridge. I'll be here when you need a new task."] = "Me encontrarás en Lumbridge. Estaré aquí cuando necesites una nueva tarea.",
    ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
    ["Nothing really."] = "Nada realmente.",
    ["Hello?"] = "¿Hola?",
    ["Ello, who's that?"] = "Hola, ¿quién es ese?",
    ["I'm Player. I'm using magic to communicate with you."] = "Soy Player. Estoy usando magia para comunicarme contigo.",
    ["Amazing! Wat can I do for you?"] = "¡Increíble! ¿Qué puedo hacer por ti?",
    ["Bats are rarely found on the ground, so you'll have to fight them while they're airborne. You can find some flying around in the Lumbridge Catacombs."] = "Los murciélagos rara vez se encuentran en el suelo, por lo que tendrás que luchar contra ellos mientras están en el aire. Puedes encontrar algunos volando en las Catacumbas Lumbridge.",
    ["Birds aren't the most intelligent of creatures, but watch out for their sharp, stabbing beaks. Even the chickens in Lumbridge are after your blood, so get them before they get you."] = "Los pájaros no son las criaturas más inteligentes, pero ten cuidado con sus picos afilados y punzantes. Incluso las gallinas en Lumbridge buscan tu sangre, así que consíguelas antes de que te atrapen a ti.",
    ["Cave bugs are like cave crawlers, except smaller and easier to squish; although, they still have a fondness for plants. They lurk in the dark beneath Lumbridge Swamp."] = "Los insectos de las cavernas son como rastreadores de cuevas, excepto que son más pequeños y más fáciles de aplastar; aunque todavía sienten afición por las plantas. Acechan en la oscuridad debajo del pantano Lumbridge.",
    ["Cave slimes are the lesser cousins of jellies. Don't be fooled, though: they can still be dangerous, as they're often poisonous. Killing the ones beneath Lumbridge Swamp might be a good start."] = "Los limos de las cavernas son los primos menores de las jaleas. Pero no te dejes engañar: aún así pueden ser peligrosos, ya que a menudo son venenosos. Matar a los que están debajo del pantano Lumbridge podría ser un buen comienzo.",
    ["Cows are bigger than you, and they'll often hit hard but react fairly slowly. You can slaughter the ones in Lumbridge - I bet they are up to no good."] = "Las vacas son más grandes que tú y, a menudo, golpean fuerte pero reaccionan con bastante lentitud. Puedes masacrar a los de Lumbridge. Apuesto a que no traman nada bueno.",
    ["Frogs will attack and move faster than the average human, but on the whole an experienced warrior can deal with a lot of them quite quickly. You can find them in the swamp to the south."] = "Las ranas atacarán y se moverán más rápido que el humano promedio, pero en general un guerrero experimentado puede lidiar con muchas de ellas con bastante rapidez. Puedes encontrarlos en el pantano del sur.",
    ["The last Ghost I killed I found thrown weapons took them down effectively."] = "El último fantasma que maté lo encontré con armas arrojadizas que los derribaron de manera efectiva.",
    ["Ghosts are undead, so not the easiest thing to find in populated areas. Try looking in the abandoned Draynor Manor."] = "Los fantasmas son muertos vivientes, por lo que no es lo más fácil de encontrar en zonas pobladas. Intenta buscar en el Draynor Manor abandonado.",
    ["Goblins are mostly just annoying, but they can be vicious. Watch out for the weapons they sometimes carry. You can find them on the east side of the river here in Lumbridge."] = "Los duendes en su mayoría son simplemente molestos, pero pueden ser crueles. Cuidado con las armas que a veces portan. Puedes encontrarlos en el lado este del río aquí en Lumbridge.",
    ["Rats come in different sizes if you want a challenge or not. You can find the normal variety lurking around the castle grounds or head south into the swamp for giant rats."] = "Las ratas vienen en diferentes tamaños si quieres un desafío o no. Puedes encontrar la variedad normal acechando en los terrenos del castillo o dirigirte hacia el sur, hacia el pantano, en busca de ratas gigantes.",
    ["Skeletons are undead, so Magic is your best bet against them. Skeletons can be found in the Lumbridge Catacombs."] = "Los esqueletos son muertos vivientes, por lo que Magic es tu mejor opción contra ellos. Los esqueletos se pueden encontrar en las catacumbas de Lumbridge.",
    ["Spiders are often venomous and many varieties are camouflaged, too. I've seen plenty to the south-west of Lumbridge."] = "Las arañas suelen ser venenosas y muchas variedades también se camuflan. He visto muchos al suroeste de Lumbridge.",
    ["Zombies are undead, so be careful. You can find a variety of corpse fighters in the Lumbridge Catacombs or zombies in the sewers under Draynor village."] = "Los zombis son muertos vivientes, así que ten cuidado. Puedes encontrar una variedad de luchadores de cadáveres en las catacumbas de Lumbridge o zombis en las alcantarillas en Draynor village.",
    ["Greetings warrior, how may I help you?"] = "Saludos guerrero, ¿en qué puedo ayudarte?",
    ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarte que tienes artículos listos para ser recogidos en Grand Exchange.",
    ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to check my PIN settings."] = "Me gustaría comprobar la configuración de mi PIN.",
    ["*(Bank Pin Settings interface opens)*"] = "*(Se abre la interfaz de configuración de PIN bancario)*",
    ["I'd like to see my Collection box."] = "Me gustaría ver mi cuadro de Colección.",
    ["How long have you worked here?"] = "¿Cuánto tiempo llevas trabajando aquí?",
    ["Oh ever since the Guild opened. I like it here."] = "Oh, desde que abrió el Gremio. Me gusta aquí.",
    ["Why's that?"] = "¿Por qué?",
    ["Well.. what with all these warriors around, there's not much chance of my bank being robbed is there!"] = "Bueno... ¡con todos estos guerreros alrededor, no hay muchas posibilidades de que roben mi banco!",
    ["Hello little cutie! Time to die."] = "¡Hola pequeña monada! Es hora de morir.",
    ["We've been told to keep everyone away."] = "Nos han dicho que mantengamos a todos alejados.",
    ["Acolytes. Pirates. Heroes."] = "Acólitos. Piratas. Héroes.",
    ["In these halls, you die by my hand."] = "En estos pasillos, mueres por mi mano.",
    ["Hi!"] = "¡Hola!",
    ["*Jadid may say one of the following at random:*"] = "*Jadid puede decir una de las siguientes palabras al azar:*",
    ["A fight over love and money would be a duel purpose."] = "Una pelea por amor y dinero sería un duelo.",
    ["What did the skeleton say before it ate?"] = "¿Qué dijo el esqueleto antes de comer?",
    ["I don't know."] = "No lo sé.",
    ["Bone appétit."] = "Apetito de huesos.",
    ["My favourite fighter is Mubariz."] = "Mi luchador favorito es Mubariz.",
    ["The guy at the information kiosk?"] = "¿El chico del quiosco de información?",
    ["Yeah! He rocks!"] = "¡Sí! ¡Él es genial!",
    ["Takes all sorts, I guess."] = "Supongo que se aceptan de todo tipo.",
    ["Did you know, they think this place dates back to the Second Age."] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
    ["Really?"] = "¿En serio?",
    ["Yeah, the guy at the information kiosk was telling me."] = "Sí, me lo estaba diciendo el chico del quiosco de información.",
    ["Why do giants lose all their duels against vampires?"] = "¿Por qué los gigantes pierden todos sus duelos contra vampiros?",
    ["I don't know - why?"] = "No lo sé, ¿por qué?",
    ["The stakes are always too high!"] = "¡Siempre hay mucho en juego!",
    ["Ooh, this is exciting."] = "Oh, esto es emocionante.",
    ["Yup!"] = "¡Sí!",
    ["Well, this beats doing the shopping."] = "Bueno, esto es mejor que hacer compras.",
    ["Can't you see I'm watching the duels?"] = "¿No ves que estoy viendo los duelos?",
    ["Sorry!"] = "¡Lo siento!",
    ["Aww, come on, keep fighting. It's just a flesh wound!"] = "Oh, vamos, sigue luchando. ¡Es sólo una herida superficial!",
    ["*Dialogue 11:*"] = "*Diálogo 11:*",
    ["My son just won his first duel!"] = "¡Mi hijo acaba de ganar su primer duelo!",
    ["Congratulations."] = "Felicitaciones.",
    ["He ripped his opponent in half."] = "Partió a su oponente por la mitad.",
    ["That's gotta hurt."] = "Eso tiene que doler.",
    ["He's only 15!"] = "¡Solo tiene 15 años!",
    ["You gotta start 'em young."] = "Tienes que empezarlos jóvenes.",
    ["*Dialogue 12:*"] = "*Diálogo 12:*",
    ["I wouldn't want to be the poor guy who has to clean up after the duels."] = "No me gustaría ser el pobre que tiene que limpiar después de los duelos.",
    ["Me neither."] = "Yo tampoco.",
    ["*Dialogue 13:*"] = "*Diálogo 13:*",
    ["Hi! I'm here to watch the duels."] = "¡Hola! Estoy aquí para ver los duelos.",
    ["Me too!"] = "¡Yo también!",
    ["*Dialogue 14:*"] = "*Diálogo 14:*",
    ["*Dialogue 15:*"] = "*Diálogo 15:*",
    ["I once duelled a man from Entrana,"] = "Una vez me batí en duelo con un hombre de Entrana,",
    ["Who wielded a mighty katana,"] = "Quien empuñaba una poderosa katana,",
    ["It caused me a fright, but it lost him the fight,"] = "Me dio un susto, pero le hizo perder la pelea,",
    ["It was made, not from steel, but banana!"] = "¡No estaba hecho de acero, sino de plátano!",
    ["*Dialogue 16:*"] = "*Diálogo 16:*",
    ["How many duellists does it take to kill a vampyre?"] = "¿Cuántos duelistas se necesitan para matar a un vampyre?",
    ["Uh, wait: I can do this. You would need thousands, because they'd all be too busy arguing ovr who gets the stake!"] = "Uh, espera: puedo hacer esto. ¡Necesitarías miles, porque estarían todos demasiado ocupados discutiendo sobre quién se queda con la apuesta!",
    ["What? No, we've got a vampyre problem back home. I was thinking of recruiting fighters."] = "¿Qué? No, tenemos un problema con vampyre en casa. Estaba pensando en reclutar combatientes.",
    ["Oh, I thought it was a joke."] = "Oh, pensé que era una broma.",
    ["Were you there when the arena collapsed?"] = "¿Estabas allí cuando se derrumbó la arena?",
    ["No. I was browsing the market stalls in Al Kharid at the time, fortunately."] = "No. Afortunadamente, estaba explorando los puestos del mercado en Al Kharid en ese momento.",
    ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
    ["You got beaten up by a troll!"] = "¡Te golpeó un troll!",
    ["That monster? If it dares to come here again, I will be ready for it, and it shall taste my spear."] = "¿Ese monstruo? Si se atreve a venir aquí otra vez, estaré preparado para recibirlo y probará mi lanza.",
    ["You didn't look so tough when the troll knocked you down."] = "No parecías tan duro cuando el troll te derribó.",
    ["Bwana, get knotted."] = "Bwana, haz un nudo.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Why, it should be clear to even the most ignorant of people that I am a fearless jungle hunter...out of my way you sanitised civilian!"] = "Vaya, debería quedar claro incluso para las personas más ignorantes que soy un intrépido cazador de la jungla... ¡fuera de mi camino, civil desinfectado!",
    ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
    ["Bwana, if anyone else asks me that question today, I'll explode! Go and ask Murcaily!"] = "Bwana, si alguien más me hace esa pregunta hoy, ¡explotaré! ¡Ve y pregúntale a Murcaily!",
    ["I'm just enjoying the sunshine, Bwana. Try asking Murcaily."] = "Solo estoy disfrutando del sol, Bwana. Intente preguntarle a Murcaily.",
    ["Well, I think that there's some work to be done...perhaps Murcaily can help you. He usually tends to the hardwood grove to the east of Trufitus' hut."] = "Bueno, creo que hay trabajo por hacer... tal vez Murcaily pueda ayudarte. Por lo general, atiende el bosquecillo de madera al este de la cabaña de Trufitus.",
    ["Sorry Bwana, I'm already busy, why not go and talk to Murcaily! He's around the village somewhere."] = "Lo siento Bwana, ya estoy ocupado, ¿por qué no vas y hablas con Murcaily? Está en alguna parte del pueblo.",
    ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
    ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
    ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
    ["Ok, thanks."] = "Vale, gracias.",
    ["You get [number] trading sticks. Your remaining favour totals [percentage]."] = "Obtienes palos comerciales [número]. El favor restante asciende a [percentage].",
    ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
    ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
    ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
    ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
    ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    ["What's it like guarding Khnum?"] = "¿Cómo es proteger a Khnum?",
    ["Oh, he's fine. I mean he's one angry bloke, but I've picked up a few decent recipes off him."] = "Oh, está bien. Quiero decir que es un tipo enojado, pero le he aprendido algunas recetas decentes.",
    ["The 'Little Boss' is a bit strict with us, but don't get me wrong, we're all glad that The Skulls aren't causing trouble in Draynor anymore."] = "El 'Pequeño Jefe' es un poco estricto con nosotros, pero no me malinterpretes, todos estamos contentos de que Los Calaveras ya no estén causando problemas en Draynor.",
    ["Welcome to NovtumberFest! Cooking is great!"] = "¡Bienvenido a NovtumberFest! ¡Cooking es genial!",
    ["Select an option"] = "Selecciona una opción",
    ["*(Only if not selected last:)*"] = "*(Sólo si no fue seleccionado en último lugar:)*",
    ["My name is Jakob, I'm in charge of watching over the grills."] = "Mi nombre es Jakob, soy el encargado de vigilar las parrillas.",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["How do the grills work?"] = "¿Cómo funcionan las parrillas?",
    ["It's dead easy!"] = "¡Es muy fácil!",
    ["Just head over to the grill and get those sausages sizzling!"] = "¡Simplemente dirígete a la parrilla y haz que esas salchichas chisporroteen!",
    ["You will receive Cooking XP for cooking sausages."] = "Recibirás Cooking XP por cocinar salchichas.",
    ["Best of all you can keep any which you cook."] = "Lo mejor de todo es que puedes conservar cualquiera que cocines.",
    ["Can you tell me about your sausages?"] = "¿Puedes hablarme de tus salchichas?",
    ["You could at least buy me dinner first..."] = "Al menos podrías invitarme a cenar primero...",
    ["It's been nice to meat you!"] = "¡Ha sido un placer comerte!",
    ["Ahh, a kind stranger. Get this old man another drink so that he may wet his throat and talk to you."] = "Ahh, un amable extraño. Dale otro trago a este old man para que se moje la garganta y te hable.",
    ["What were we talking about again? Yes yes, when I was a boy..... no that's not it."] = "¿De qué estábamos hablando otra vez? Si si, cuando era niño..... no, no es eso.",
    ["What you looking at."] = "Lo que estás mirando.",
    ["You know, I have this friend, and he.... I can't remember. What was I saying?"] = "Sabes, tengo un amigo y él... No lo recuerdo. ¿Qué estaba diciendo?",
    ["Did you hear the one where the camel walks into the bar and orders a pint? The barman asks 'Why the long face!'."] = "¿Escuchaste aquel en el que el camello entra al bar y pide una pinta? El camarero pregunta: \"¿Por qué esa cara tan larga?\".",
    ["Wha'? Are you lookin' at me? Are you lookin' at me? You know something? You're drunk, you are."] = "¿Qué? ¿Me estás mirando? ¿Me estás mirando? ¿Sabes algo? Estás borracho, lo estás.",
    ["Cheers for the beers!"] = "¡Salud por las cervezas!",
    ["I've got a lovely bunch of coconuts, doobidy do."] = "Tengo un montón de cocos preciosos, claro.",
    ["Thank you my friend - now if you don't mind I'm having a conversation with my imaginary friend Bob here."] = "Gracias amigo mío. Ahora, si no te importa, estoy teniendo una conversación con mi amigo imaginario Bob aquí.",
    ["I was a sailor once, you know..."] = "Una vez fui marinero, ya sabes...",
    ["Did you hear the one about the man who walked into a bar? He hurt his foot! Hah!"] = "¿Escuchaste la del hombre que entró en un bar? ¡Se lastimó el pie! ¡Ja!",
    ["Why does nobody like me?"] = "¿Por qué no le agrado a nadie?",
    ["Eh? What's this? I don't want that, get me a beer."] = "¿Eh? ¿Qué es esto? No quiero eso, tráeme una cerveza.",
    ["Ow! How did that pig give me an electric shock?"] = "¡Ay! ¿Cómo es que ese cerdo me dio una descarga eléctrica?",
    ["Where were you on the full moon?"] = "¿Dónde estabas en la luna llena?",
    ["I had intended to fight the giant mole, but by the time I got there, someone had already beaten me to it. So I spent the night enjoying Falador Park."] = "Tenía la intención de luchar contra el topo gigante, pero cuando llegué allí, alguien ya se me había adelantado. Así que pasé la noche disfrutando del parque Falador.",
    ["Did you see anything suspicious?"] = "¿Viste algo sospechoso?",
    ["I saw a hooded figure running southwards past the north gates of Falador. I didn't see where they went."] = "Vi una figura encapuchada corriendo hacia el sur pasando las puertas norte de Falador. No vi adónde fueron.",
    ["Who do you suspect of being the werewolf?"] = "¿De quién sospechas que es el hombre lobo?",
    ["Daniel smells funny, so him maybe?"] = "Daniel huele raro, ¿así que él tal vez?",
    ["[Accuse James of being the werewolf.]"] = "[Acusa a James de ser el hombre lobo.]",
    ["James! Your deception is unmasked! I name thee WEREWOLF!"] = "¡James! ¡Tu engaño está desenmascarado! ¡Te llamo HOMBRE LOBO!",
    ["*(James dies.)*"] = "*(James muere.)*",
    ["Ah...oops. Guess I was wrong."] = "Ah... Ups. Supongo que estaba equivocado.",
    ["Goodbye."] = "Adiós.",
    ["*James dies*"] = "*James muere*",
    ["Not that it's any of your business, but I was asleep in my bed."] = "No es que sea de tu incumbencia, pero estaba dormido en mi cama.",
    ["Your face is suspicious."] = "Tu cara es sospechosa.",
    ["YOU! Now go away."] = "¡TÚ! Ahora vete.",
    ["[Accuse Jamie of being the werewolf.]"] = "[Acusa a Jamie de ser el hombre lobo.]",
    ["Jamie! You're a werewolf! I know it, you know it, we all know it!"] = "¡Jamie! ¡Eres un hombre lobo! ¡Lo sé, tú lo sabes, todos lo sabemos!",
    ["*(Jamie dies.)*"] = "*(Jamie muere.)*",
    ["Your erroneous accusation has resulted in the death of an innocent bystander. The monster remains at large!"] = "Su acusación errónea ha resultado en la muerte de un espectador inocente. ¡El monstruo sigue prófugo!",
    ["Steve! Don't think you can hide your fangs from me! I see you for what you really are: A WEREWOLF!"] = "¡Steve! ¡No creas que puedes ocultarme tus colmillos! Te veo por lo que realmente eres: ¡UN HOMBRE LOBO!",
    ["*Jamie dies*"] = "*Jamie muere*",
    ["Hi. Are you one of the returned townspeople?"] = "Hola. ¿Eres uno de los habitantes que regresaron?",
    ["Why, yes. You must be the adventurer Maisa told us about."] = "Pues, sí. Debes ser el aventurero del que nos habló Maisa.",
    ["I guess so."] = "Supongo que sí.",
    ["I'd like to shop, please."] = "Me gustaría comprar, por favor.",
    ["Certainly!"] = "¡Por supuesto!",
    ["How is business?"] = "¿Cómo va el negocio?",
    ["Slow at the moment, so slow. Maybe time will make things better."] = "Lento en este momento, muy lento. Quizás el tiempo mejore las cosas.",
    ["Any tasks for me that you can think of?"] = "¿Se te ocurre alguna tarea para mí?",
    ["I have no plans that would require your mighty services...at least, not yet."] = "No tengo planes que requieran tus poderosos servicios... al menos no todavía.",
    ["Goodbye for now."] = "Adiós por ahora.",
    ["Goodbye for now"] = "Adiós por ahora",
    ["Come back soon!"] = "¡Vuelve pronto!",
    ["Do you not know who I am? I am the future, I am the conduit of Sliske's might; I am Janus!"] = "¿No sabes quién soy? Soy el futuro, soy el conducto del poder de Sliske; ¡Soy Janus!",
    ["Yeah, but really, who are you?"] = "Sí, pero en realidad, ¿quién eres?",
    ["I'm a mage of great power, come to bring forth change to the world of Gielinor."] = "Soy un mago de gran poder, vengo a traer cambios al mundo de Gielinor.",
    ["Ah, so you're a mage. Are you part of the Zamorak Magical Institute?"] = "Ah, entonces eres un mago. ¿Eres parte del Instituto Mágico Zamorak?",
    ["The ZMI is full of shortsighted fools, I am doing work far greater than anything they will ever accomplish. I am glad that I am no longer part of them, they were holding me back."] = "El ZMI está lleno de tontos miopes. Estoy haciendo un trabajo mucho mayor que cualquier cosa que ellos puedan lograr. Me alegro de no ser más parte de ellos, me estaban frenando.",
    ["What happened with the ZMI?"] = "¿Qué pasó con el ZMI?",
    ["They thought that they knew better than me, my mentor tried to interfere with my learnings! She tried to stop a magical experiment that I was conducting and was badly burned by the spells that I had cast. It was her own fault, she knows the dangers of magic, but no, she had to step in. They told me to leave the ZMI because of it, yet she was allowed to stay. They will see what a mistake they have made when they see the results of my endeavours."] = "Pensaban que sabían más que yo, ¡mi mentor intentó interferir con mis aprendizajes! Intentó detener un experimento mágico que yo estaba realizando y resultó gravemente quemada por los hechizos que le había lanzado. Fue culpa suya, conoce los peligros de la magia, pero no, tuvo que intervenir. Me dijeron que dejara el ZMI por eso, pero a ella le permitieron quedarse. Verán el error que han cometido cuando vean los resultados de mis esfuerzos.",
    ["What are you planning on doing?"] = "¿Qué planeas hacer?",
    ["Works beyond your understanding. I am furthering the cause of the majestic Sliske. These rifts will further his journey towards being the greatest god of them all, and I am a pivotal part of that plan."] = "Funciona más allá de tu comprensión. Estoy promoviendo la causa del majestuoso Sliske. Estas divisiones impulsarán su viaje hacia convertirse en el dios más grande de todos, y yo soy una parte fundamental de ese plan.",
    ["Nevermind."] = "No importa.",
    ["*Dialogue terminates.*"] = "*El diálogo termina.*",
    ["Though this scheme has been thwarted Sliske's overall strategy cannot be stopped. He will be successful. This was just one plan of many, each reaching towards the same final plan, and I will stand by him as he succeeds."] = "Aunque este plan se ha visto frustrado, la estrategia general de Sliske no se puede detener. Tendrá éxito. Este fue sólo un plan entre muchos, cada uno de los cuales apuntaba hacia el mismo plan final, y lo apoyaré en su éxito.",
    ["What? Can't you see I'm busy?"] = "¿Qué? ¿No ves que estoy ocupado?",
    ["Can you heal me?"] = "¿Puedes curarme?",
    ["Okay. This will hurt you more than it will me."] = "Está bien. Esto te hará más daño a ti que a mí.",
    ["These facilities aren't ideal for a hospital, but I can make them work."] = "Estas instalaciones no son ideales para un hospital, pero puedo hacer que funcionen.",
    ["Okay. This will hurt you more than it will hurt me."] = "Está bien. Esto te dolerá más a ti que a mí.",
    ["*If at full health:*"] = "*Si está en plena salud:*",
    ["You look healthy to me!"] = "¡Me pareces saludable!",
    ["*If not at full health:*"] = "*Si no está en plena salud:*",
    ["You feel a little better."] = "Te sientes un poco mejor.",
    ["You must see some gruesome things."] = "Debes ver algunas cosas espantosas.",
    ["It's a gruesome business, and, with the tools they give me, it gets more gruesome before it gets better."] = "Es un negocio espantoso y, con las herramientas que me dan, se vuelve más espantoso antes de mejorar.",
    ["You must have seen some gruesome things."] = "Debes haber visto algunas cosas espantosas.",
    ["In my time at the Duel Arena? Certainly, it was a gruesome business."] = "¿En mi tiempo en Duel Arena? Ciertamente, fue un asunto espantoso.",
    ["But now that the arena has sunk back into the desert, things are a little bit better."] = "Pero ahora que la arena se ha hundido nuevamente en el desierto, las cosas están un poco mejor.",
    ["Why do they call you 'The Butcher'?"] = "¿Por qué te llaman 'El Carnicero'?",
    ["The Butcher'?"] = "¿'El Carnicero'?",
    ["Ha!"] = "¡Ja!",
    ["Would you like me to demonstrate?"] = "¿Quieres que te lo demuestre?",
    ["Er... I'll give it a miss, thanks."] = "Er... Lo dejaré pasar, gracias.",
    ["Er...I'll give it a miss, thanks."] = "Er... Lo dejaré pasar, gracias.",
    ["Here! Now, I have work to do!"] = "¡Aquí! ¡Ahora tengo trabajo que hacer!",
    ["[Jaraah has given you another clue scroll!]"] = "[¡Jaraah te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Good day, [sir/madam]."] = "Buenos días, [sir/madam].",
    ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
    ["I'm waiting to work on the digging."] = "Estoy esperando trabajar en la excavación.",
    ["It's the first excavation I've worked on, and I'm looking forward to it."] = "Es la primera excavación en la que trabajo y estoy deseando que llegue.",
    ["Good day."] = "Buenos días.",
    ["What do you want from me outerlander? It is our policy not to associate with those not of our tribe."] = "¿Qué quieres de mí, outsider? Es nuestra política no asociarnos con personas que no sean de nuestra tribu.",
    ["What would you like to ask about?"] = "¿Sobre qué te gustaría preguntar?",
    ["Where is your chieftain?"] = "¿Dónde está tu jefe?",
    ["Where is your chieftain? I find it highly discriminatory to refuse to talk to someone on the grounds that they are not part of your tribe."] = "¿Dónde está tu jefe? Considero muy discriminatorio negarse a hablar con alguien alegando que no forma parte de su tribu.",
    ["I don't rightly understand your speech outerlander, but my loyalty is with Chieftain Brundt. He resides in our long hall; it is the large building over there, you should speak to him for he speaks for us all."] = "No entiendo bien tu discurso externo, pero mi lealtad está con el cacique Brundt. Él reside en nuestro largo salón; es el gran edificio de allí, deberías hablar con él porque él habla por todos nosotros.",
    ["What Jarvald is doing."] = "Qué está haciendo Jarvald.",
    ["So what are you doing here?"] = "Entonces, ¿qué estás haciendo aquí?",
    ["This should not concern you, outerlander. I am awaiting other Fremenniks to join me on an expedition to Waterbirth Island."] = "Esto no debería preocuparte, extranjero. Estoy esperando que otros Fremenniks se unan a mí en una expedición a la Isla Waterbirth.",
    ["Waterbirth Island?"] = "¿Isla del nacimiento del agua?",
    ["It is a small crescent-shaped island just north-west of here, outerlander. We have many legends about it, such as the tale of the broken sky, and the day of the green seas. The reason I am travelling there is more serious Fremennik business, however. I doubt an outerlander would be interested."] = "Es una pequeña isla en forma de media luna justo al noroeste de aquí, outsider. Tenemos muchas leyendas al respecto, como el cuento del cielo roto y el día de los mares verdes. Sin embargo, el motivo por el que viajo allí es un asunto más serio de Fremennik. Dudo que un extranjero esté interesado.",
    ["Can I come?"] = "¿Puedo ir?",
    ["Hey, scary barbarian type guy, think I can join you on this expedition?"] = "Oye, tipo bárbaro aterrador, ¿crees que puedo unirme a ti en esta expedición?",
    ["An outerlander join us on an honoured hunt??? Well.... I guess... I might be able to allow you to join us, although it is a breach of many of our customs..."] = "¿¿Un extranjero se une a nosotros en una cacería honorable??? Bueno... supongo... que podría permitirte unirte a nosotros, aunque es una violación de muchas de nuestras costumbres...",
    ["Oh, pleeeeease? I really LOVE killing stuff!"] = "Oh, ¿por favor? ¡Realmente AMO matar cosas!",
    ["Well... I remain unconvinced that it would be wise to allow an outerlander to join us in such dangerous battle, but your enthusiasm seems genuine enough... I will allow you to escort us, but you must pay me a sum of money first."] = "Bueno... Sigo sin estar convencido de que sería prudente permitir que un extranjero se una a nosotros en una batalla tan peligrosa, pero tu entusiasmo parece bastante genuino... Te permitiré escoltarnos, pero primero debes pagarme una suma de dinero.",
    ["What? That's outrageous, why charge me money? And, uh, how much does it cost me?"] = "¿Qué? Eso es indignante, ¿por qué cobrarme dinero? ¿Y cuánto me cuesta?",
    ["Ah, the outerlanders have stolen from my people for many years, in this way you can help my community with a small amount of money... Let us say... 1000 coins. Payable in advance, of course. For this I will take you to Waterbirth Island on my boat, and will bring you back here when you have had your fill of the hunt. Assuming you are still alive to wish to leave, of course."] = "Ah, los extranjeros le han robado a mi gente durante muchos años, de esta manera puedes ayudar a mi comunidad con una pequeña cantidad de dinero... Digamos... 1000 coins. A pagar por adelantado, por supuesto. Para ello, te llevaré a la isla Waterbirth en mi barco y te traeré de regreso aquí cuando te hayas saciado de la caza. Suponiendo que todavía estés vivo para desear irte, por supuesto.",
    ["YES"] = "SI",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["Ah, outerlander... I go beyond my duty to allow you to accompany me, and you attempt to swindle me out of a reasonable fee? This is no way even for an outerlander to behave..."] = "Ah, extranjero... Voy más allá de mi deber al permitirte que me acompañes, ¿y tú intentas estafarme con una tarifa razonable? Esta no es forma de comportarse ni siquiera para un extranjero...",
    ["I suggest you head to the cave with some urgency outerlander, the cold air out here might be too much for the likes of you..."] = "Te sugiero que te dirijas a la cueva con cierta urgencia, extranjero, el aire frío aquí afuera podría ser demasiado para personas como tú...",
    ["I would head straight for the cave and not tarry too long [Fremennik name], the cold winds on this island can cut right through you should you spend too long in them."] = "Me dirigiría directamente a la cueva y no me demoraría demasiado [Fremennik name], los vientos fríos de esta isla pueden atravesarte si pasas demasiado tiempo en ellos.",
    ["As you wish. Come and see me when your bloodlust needs sating."] = "Como desees. Ven a verme cuando tu sed de sangre necesite saciar.",
    ["Nice hat!"] = "¡Bonito sombrero!",
    ["Hey, I have to say, that's a fine looking hat you are wearing there."] = "Oye, tengo que decir que el sombrero que llevas ahí luce muy bien.",
    ["It is actually a helm, outerlander, but the sentiment is appreciated nonetheless."] = "En realidad es un timón, outsider, pero de todos modos se agradece el sentimiento.",
    ["Ok, 'bye."] = "Vale, adiós.",
    ["Nothing"] = "nada",
    ["No, outerlander I am not taking you there."] = "No, extranjero, no te llevaré allí.",
    ["Ah, you live yet, outerlander! Have you had your fill of the hunt and wish to return, or are you still feeling the joy of the cull?"] = "¡Ah, aún vives, extranjero! ¿Se ha hartado de la caza y desea volver, o todavía siente la alegría del sacrificio?",
    ["Yes"] = "si",
    ["Then let us away; There will be death to bring here another day!"] = "Entonces déjanos ir; ¡Habrá muerte que traerá aquí otro día!",
    ["Ha Ha Ha! A true huntsman at heart!"] = "¡Ja, ja, ja! ¡Un verdadero cazador de corazón!",
    ["I myself have killed over a hundred of the daggermouths, and did not think it too many!"] = "Yo mismo he matado a más de cien bocas de daga, ¡y no pensé que fueran demasiados!",
    ["Greetings, [Fremennik name]!"] = "¡Saludos, [Fremennik name]!",
    ["Ah, and what a glorious name that is! Worthy of only the finest warriors!"] = "¡Ah, y qué nombre tan glorioso es ese! ¡Digno sólo de los mejores guerreros!",
    ["Heh. Yup, you're right there."] = "Je. Sí, tienes razón.",
    ["So what brings you back to fair Rellekka? It has been too long since you have drunk in the long hall with us and sang of your battles!"] = "Entonces, ¿qué te trae de vuelta a la feria Rellekka? ¡Ha pasado demasiado tiempo desde que bebiste en el gran salón con nosotros y cantaste sobre tus batallas!",
    ["You have not heard, [Fremennik name]? I am leading an expedition to Waterbirth Island!"] = "¿No te has enterado, [Fremennik name]? ¡Estoy liderando una expedición a la isla Waterbirth!",
    ["You have not ever travelled to Waterbirth Island, [Fremennik name]? I am surprised, it is a place of outstanding natural beauty."] = "¿Nunca has viajado a Waterbirth Island, [Fremennik name]? Me sorprende, es un lugar de una belleza natural excepcional.",
    ["Or at least it used to be! But things have now changed..."] = "¡O al menos así era! Pero ahora las cosas han cambiado...",
    ["Changed? How do you mean, changed?"] = "¿Cambiado? ¿Qué quieres decir con cambiado?",
    ["It seems as though the sea-beasts known to us as the daggermouths have begun their hatching once again... And there may be others of their ilk there too."] = "Parece que las bestias marinas que conocemos como bocas de daga han comenzado a eclosionar una vez más... Y puede que haya otras de su calaña allí también.",
    ["Daggermouths?"] = "¿Bocas de daga?",
    ["Aye, the daggermouths! The vile creatures lived near here once, but we had thought them all driven back to the ocean depths many moons past."] = "¡Sí, los bocas de daga! Estas viles criaturas vivieron cerca de aquí una vez, pero pensábamos que todas habían sido expulsadas a las profundidades del océano hace muchas lunas.",
    ["I can only imagine a daggermouth queen has nested somewhere nearby, and spawned her foul brood under the sea once more, and some of them have migrated to fair Waterbirth Island."] = "Solo puedo imaginar que una reina boca de daga haya anidado en algún lugar cercano y haya engendrado su loque bajo el mar una vez más, y algunas de ellas hayan migrado a la hermosa Isla Waterbirth.",
    ["So you're scared they might attack Rellekka?"] = "¿Entonces tienes miedo de que ataquen a Rellekka?",
    ["Scared? Ha ha ha!"] = "¿Asustado? ¡Ja, ja, ja!",
    ["You wound us with your questioning, [Fremennik name]!"] = "¡Nos hieres con tu interrogatorio, [Fremennik name]!",
    ["We are glad the daggermouths have returned to these shores, for it means we will get the chance to hunt them once again as our ancestors did!"] = "¡Nos alegra que los boca de daga hayan regresado a estas costas, porque eso significa que tendremos la oportunidad de cazarlos una vez más como lo hicieron nuestros antepasados!",
    ["When treated in the correct manner, the creatures' remains can be used to make fine battleworthy armour!"] = "¡Cuando se tratan de la manera correcta, los restos de las criaturas se pueden usar para fabricar excelentes armaduras dignas de batalla!",
    ["Of course, [Fremennik name]! Your presence is more than welcome on this cull! You wish to leave now?"] = "¡Por supuesto, [Fremennik name]! ¡Su presencia es más que bienvenida en este sacrificio! ¿Quieres irte ahora?",
    ["Aye, that it is [Fremennik name]! Skulgrimen fashioned it for me from the carcass of one of the monsters on Waterbirth Island after our last hunt! I hope to kill enough creatures to fashion some fine armour as well when next we leave!"] = "¡Sí, que es [Fremennik name]! ¡Skulgrimen lo creó para mí a partir del cadáver de uno de los monstruos de la isla Waterbirth después de nuestra última cacería! ¡Espero matar suficientes criaturas para crear algunas armaduras finas la próxima vez que nos vayamos!",
    ["Ah, [Fremennik name]! Such glorious battle makes you feel glad of life, does it not?"] = "¡Ah, [Fremennik name]! Una batalla tan gloriosa te hace sentir feliz por la vida, ¿no es así?",
    ["So what say you, stay here for the hunt, or return home to sweet Rellekka to feast and drink with your tribe?"] = "Entonces, ¿qué te parece, quedarte aquí para cazar o regresar a casa, al dulce Rellekka, para darte un festín y beber con tu tribu?",
    ["*Jasim the Camel and the player say one of the following at random:*"] = "*Jasim the Camel y el player dicen uno de los siguientes al azar:*",
    ["I'm not going to pet that! I might get fleas or something else that nasty creature might have."] = "¡No voy a acariciar eso! Podría contraer pulgas o cualquier otra cosa que esa criatura desagradable pudiera tener.",
    ["You're fairly nasty yourself, human. Poking and prodding me like a lump of meat."] = "Tú también eres bastante desagradable, humano. Empujándome y pinchándome como si fuera un trozo de carne.",
    ["I'm not going to pet that! It will probably bite my hand off, that filthy beast."] = "¡No voy a acariciar eso! Probablemente me arrancará la mano de un mordisco, esa bestia inmunda.",
    ["Watch who you're calling a filthy beast, human."] = "Mira a quién llamas bestia inmunda, humano.",
    ["That beast would probably bite my fingers off if I tried to pet it."] = "Esa bestia probablemente me arrancaría los dedos de un mordisco si intentara acariciarla.",
    ["If you want me to bite your fingers off, you're going the right way about it."] = "Si quieres que te arranque los dedos de un mordisco, estás yendo por el camino correcto.",
    ["Mmmm... Won't you make the nicest kebab?"] = "Mmmm... ¿No harías el mejor kebab?",
    ["How would you like it if you were destined for the kebab shop when you finally keeled over?"] = "¿Qué te parecería si estuvieras destinado a la tienda de kebab cuando finalmente te desplomaras?",
    ["Are you here to practice your herblore?"] = "¿Estás aquí para practicar tu herbolaria?",
    ["I need herblore supplies."] = "Necesito suministros de herblore.",
    ["Tell me more about Herblore."] = "Cuéntame más sobre Herblore.",
    ["Every natural plant has powers locked within. Herblore is the art of unlocking these powers through potion-making."] = "Cada planta natural tiene poderes encerrados en su interior. Herblore es el arte de desbloquear estos poderes mediante la elaboración de pociones.",
    ["You'll be able to brew potions to do just about anything. Most significantly, you can restore yourself when you feel depleted."] = "Podrás preparar pociones para hacer casi cualquier cosa. Lo más importante es que puedes recuperarte cuando te sientas agotado.",
    ["Every stage in the brewing of a potion will give you a little practise. You can also start out by cleaning herbs for use."] = "Cada etapa de la elaboración de una poción te dará un poco de práctica. También puedes empezar limpiando las hierbas para su uso.",
    ["Hello, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
    ["What are you selling?"] = "¿Qué estás vendiendo?",
    ["You can't; I'm beyond help."] = "No puedes; No tengo ayuda.",
    ["I'm okay, thank you."] = "Estoy bien, gracias.",
    ["You hear the spiritual warrior's voice in your head: \"Gal'Son."] = "Escuchas la voz del guerrero espiritual en tu cabeza: \"Gal'Son\".",
    ["*(The player responds with one of the following, at random, and then the dialogue ends.)*"] = "*(el player responde con una de las siguientes opciones, al azar, y luego finaliza el diálogo.)*",
    ["I beg your pardon?"] = "¿Perdón?",
    ["Sorry, what?"] = "Lo siento, ¿qué?",
    ["What does that mean?"] = "¿Qué significa eso?",
    ["Hello there."] = "Hola.",
    ["I understand that you can take me to the Fishing Platform."] = "Entiendo que puedes llevarme a la Plataforma Fishing.",
    ["Yes, we can do that. Board the boat and we shall depart."] = "Sí, podemos hacerlo. Sube al barco y partiremos.",
    ["Hey, Jeb."] = "Hola, Jeb.",
    ["Business here is complete. Do you wish to return to the dry land?"] = "El negocio aquí está completo. ¿Quieres volver a tierra firme?",
    ["Okay, let's go back."] = "Bien, volvamos.",
    ["Then board the rowing boat."] = "Luego sube al bote de remos.",
    ["No, I'm going to stay a while."] = "No, me quedaré un rato.",
    ["Then stay if that is your wish."] = "Entonces quédate si ese es tu deseo.",
    ["Hello there. You seem familiar somehow."] = "Hola. Pareces familiar de alguna manera.",
    ["Uh, I get that a lot."] = "Uh, lo entiendo mucho.",
    ["*Jeed may say one of the following at random:*"] = "*Jeed puede decir una de las siguientes palabras al azar:*",
    ["Can't you see I'm watching the crocodiles?"] = "¿No ves que estoy mirando a los cocodrilos?",
    ["Did you know, they think this place dates back to the Second Age?"] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
    ["Yeah, an archaeologist was telling me."] = "Sí, me lo decía un arqueólogo.",
    ["I do miss the fighting sometimes."] = "A veces extraño las peleas.",
    ["I think I prefer the cool water across the oasis to the mass murder."] = "Creo que prefiero el agua fresca del oasis al asesinato en masa.",
    ["I miss the duels."] = "Extraño los duelos.",
    ["The view's quite pleasant really."] = "La vista es realmente agradable.",
    ["Congratulations! You have come to the right place."] = "¡Felicitaciones! Has venido al lugar correcto.",
    ["Keep it quick. What do you want?"] = "Que sea rápido. ¿Qué deseas?",
    ["Choose an option:"] = "Elige una opción:",
    ["*(After Gunnar's Ground)* Who was that love poem for?"] = "*(Después de Gunnar's Ground)* ¿Para quién era ese poema de amor?",
    ["It, er, it didn't work out well. I don't want to talk about it! Leave me alone!"] = "Eso, ejem, no funcionó bien. ¡No quiero hablar de eso! ¡Déjame en paz!",
    ["I want to use the furnace."] = "Quiero usar el horno.",
    ["You want to use my furnace? No one can use my furnace! Only I can use my furnace!"] = "¿Quieres usar mi horno? ¡Nadie puede usar mi horno! ¡Solo yo puedo usar mi horno!",
    ["You want to use my furnace? I only let exceptional people use my furnace. You don't look exceptional to me."] = "¿Quieres usar mi horno? Sólo dejo que personas excepcionales utilicen mi horno. No me pareces excepcional.",
    ["How do I become exceptional?"] = "¿Cómo puedo llegar a ser excepcional?",
    ["Exceptional people have earned exceptional items; earning Varrock armour would impress me."] = "Personas excepcionales han obtenido artículos excepcionales; ganarme la armadura Varrock me impresionaría.",
    ["Alright!"] = "¡Muy bien!",
    ["You seem exceptional enough. Go ahead."] = "Pareces bastante excepcional. Adelante.",
    ["What can I make here, exactly?"] = "¿Qué puedo hacer aquí exactamente?",
    ["Well, depending on your skill as a blacksmith, you can use this furnace to smelt ore into metal bars."] = "Bueno, dependiendo de tu habilidad como herrero, puedes usar este horno para fundir mineral y convertirlo en barras de metal.",
    ["Oh, I see. What's so special about this furnace, then?"] = "Ah, ya veo. Entonces, ¿qué tiene de especial este horno?",
    ["If you smelt at this furnace while wearing your Varrock armour the enchantment on the armour will give you a small chance of smelting two bars instead of one."] = "Si fundes en este horno mientras usas tu armadura Varrock, el encantamiento de la armadura te dará una pequeña posibilidad de fundir dos barras en lugar de una.",
    ["I see. So, which metal will I be able to obtain more of when smelting with the armour I'm wearing?"] = "Ya veo. Entonces, ¿de qué metal podré obtener más al fundir con la armadura que llevo puesta?",
    ["While wearing the Varrock armour, you will have a chance of smelting an extra bar of any metal up to, and including, adamant."] = "Mientras uses la armadura Varrock, tendrás la posibilidad de fundir una barra adicional de cualquier metal, incluido el adamant.",
    ["Oh, that's useful. That should save me a fair bit of time. Thanks very much."] = "Oh, eso es útil. Eso debería ahorrarme bastante tiempo. Muchas gracias.",
    ["Stay exceptional!"] = "¡Mantente excepcional!",
    ["Try coming back when you're actually wearing your Varrock armour."] = "Intenta regresar cuando estés usando tu armadura Varrock.",
    ["Oh, right. Yes, I see. Okay, thanks."] = "Ah, claro. Sí, ya veo. Bien, gracias.",
    ["Er, nothing."] = "Er, nada.",
    ["Keep away from that! It's dangerous!"] = "¡Manténgase alejado de eso! ¡Es peligroso!",
    ["A giant jellyfish has appeared!"] = "¡Ha aparecido una medusa gigante!",
    ["As the jellyfish departs, water splashes the area."] = "Cuando la medusa se aleja, el agua salpica el área.",
    ["Boost active: An additional 5% Fishing XP (30 minutes)"] = "Impulso activo: 5% adicional de XP Fishing (30 minutos)",
    ["The giant jellyfish has departed..."] = "La medusa gigante se ha ido...",
    ["As the jellyfish depart feeling satisfied with their invasion."] = "Mientras las medusas parten sintiéndose satisfechas con su invasión.",
    ["Unfortunately the encounter was not completed in time. Completing encounters successfully rewards deep sea fishing buffs."] = "Lamentablemente el encuentro no se completó a tiempo. Completar encuentros con éxito recompensa a los aficionados a la pesca en alta mar.",
    ["Hey there!"] = "¡Hola!",
    ["What's your story?"] = "¿Cuál es tu historia?",
    ["So, what's your story? What do you do here?"] = "Entonces, ¿cuál es tu historia? ¿Qué haces aquí?",
    ["I love it out here! I came here to make money and catch big fish, but I stayed for the peace and the calm the ocean brings to my mind and the camaraderie amongst the people here."] = "¡Me encanta estar aquí! Vine aquí para ganar dinero y pescar peces grandes, pero me quedé por la paz y la calma que me trae el océano y la camaradería entre la gente de aquí.",
    ["This collaborative spirit inspired me to start combining parts of jellyfish for the other fisherfolk. I want to do my part to turn this place into a fishing utopia!"] = "Este espíritu colaborativo me inspiró a empezar a combinar partes de medusas para los demás pescadores. ¡Quiero hacer mi parte para convertir este lugar en una utopía de pesca!",
    ["Don't you ever get seasick on these platforms?"] = "¿Nunca te mareas en estas plataformas?",
    ["Never! To me, it feels as if I'm cradled soothingly by the ocean, night and day."] = "¡Nunca! Para mí, siento como si el océano me acunara dulcemente, noche y día.",
    ["Not sure my stomach agrees..."] = "No estoy seguro de que mi estómago esté de acuerdo...",
    ["There you go."] = "Ahí lo tienes.",
    ["Sorry, I don't know how to combine anything that you're carrying."] = "Lo siento, no sé cómo combinar nada de lo que llevas.",
    ["You don't have any jellyfish to combine!"] = "¡No tienes medusas para combinar!",
    ["Er... You okay, buddy?"] = "Er... ¿Estás bien, amigo?",
    ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
    ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
    ["*Jennella will greet the player with any of the following at random, before continuing with the dialogue:*"] = "*Jennella saludará a el player con cualquiera de los siguientes al azar, antes de continuar con el diálogo:*",
    ["*Greeting 1:*"] = "*Saludo 1:*",
    ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
    ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
    ["All is well with me also!"] = "¡Todo está bien para mí también!",
    ["*Greeting 2:*"] = "*Saludo 2:*",
    ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["*If the player hasn't completed Hero's Welcome:*"] = "*Si el player no ha completado la Bienvenida del héroe:*",
    ["Nothing thanks. I just fancied a chat."] = "Nada, gracias. Simplemente me apetecía charlar.",
    ["My door is always open should you ever need my help [Fremennik name]."] = "Mi puerta siempre está abierta si alguna vez necesitas mi ayuda [Fremennik name].",
    ["*Greeting 3:*"] = "*Saludo 3:*",
    ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
    ["No, not really."] = "No, en realidad no.",
    ["Well... okay then!"] = "Bueno... ¡está bien entonces!",
    ["*Greeting 4:*"] = "*Saludo 4:*",
    ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
    ["*Greeting 5:*"] = "*Saludo 5:*",
    ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["*Greeting 6:*"] = "*Saludo 6:*",
    ["Hello to you, too!"] = "¡Hola a ti también!",
    ["*Greeting 7:*"] = "*Saludo 7:*",
    ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
    ["*(If the player has completed Hero's Welcome, the dialogue continues below.)*"] = "*(Si el player ha completado la bienvenida del héroe, el diálogo continúa a continuación.)*",
    ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
    ["*Jennella may reply to you with any of the following at random:*"] = "*Jennella puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["*Reply 1:*"] = "*Respuesta 1:*",
    ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    ["*Reply 2:*"] = "*Respuesta 2:*",
    ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
    ["*Reply 3:*"] = "*Respuesta 3:*",
    ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
    ["*Reply 4:*"] = "*Respuesta 4:*",
    ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["Don't mind me, I'm just checking on the mummies' enchantments. Don't want them falling apart mid-game, do we?"] = "No me hagas caso, solo estoy comprobando los encantamientos de las momias. No queremos que se desmoronen a mitad del juego, ¿verdad?",
    ["Their enchantments?"] = "¿Sus encantamientos?",
    ["Oh, yes. The mummies are kept animated by powerful enchantments passed down from cat to cat."] = "Ah, sí. Las momias se mantienen animadas mediante poderosos encantamientos que se transmiten de gato a gato.",
    ["My family line has kept these mummies going for centuries. It's quite the honour."] = "Mi línea familiar ha mantenido estas momias durante siglos. Es todo un honor.",
    ["That she is lad, that she is."] = "Que es muchacho, que lo es.",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["Just passing by."] = "Sólo estoy de paso.",
    ["Jerico is busy looking for his bird feed."] = "Jerico está ocupado buscando alimento para pájaros.",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["Leave me alone."] = "Déjame en paz.",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["Oh dear, oh dear. I'm sorry, but I have to get going!"] = "Dios mío, Dios mío. ¡Lo siento, pero tengo que irme!",
    ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
    ["What do you want to say?"] = "¿Qué quieres decir?",
    ["I'm Jessika. I'm a mage from the Wizards' Tower, doing research on pests."] = "Soy Jessika. Soy un mago de Wizards' Tower y estoy investigando plagas.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["This is the Void Knight Outpost. For some reason there is a disturbance in these islands and pests come through portals. I'm studying those portals. You should talk to one of the Void Knights if you want to know more."] = "Este es el puesto avanzado Void Knight. Por alguna razón hay una perturbación en estas islas y las plagas entran por los portales. Estoy estudiando esos portales. Deberías hablar con uno de los Void Knights si quieres saber más.",
    ["I'm fine, thanks."] = "Estoy bien, gracias.",
    ["Hello. We don't get many newcomers around here."] = "Hola. No recibimos muchos recién llegados por aquí.",
    ["Hello. I've been seeing more newcomers around here since the revolution. I don't miss the plague...but it would be good to have more peace and quiet."] = "Hola. He estado viendo más recién llegados por aquí desde la revolución. No extraño la plaga... pero sería bueno tener más paz y tranquilidad.",
    ["Greetings, non-believer. May the blessings of Icthlarin rest on your tired shoulders and may they set you at ease during interesting times."] = "Saludos, no creyente. Que las bendiciones de Icthlarin descansen sobre tus hombros cansados ​​y que te tranquilicen en momentos interesantes.",
    ["Hello, Jex."] = "Hola, Jex.",
    ["Hello, Player."] = "Hola, Player.",
    ["Jex rubs his head tenderly."] = "Jex se frota la cabeza con ternura.",
    ["Are you okay?"] = "¿Estás bien?",
    ["Some degenerate clubbed me and gave me a lump the size of an egg on the back of my head."] = "Un degenerado me golpeó y me hizo un bulto del tamaño de un huevo en la nuca.",
    ["I'll keep my eyes peeled for suspicious characters."] = "Estaré atento a personajes sospechosos.",
    ["I have a fairly good idea who did it."] = "Tengo una idea bastante clara de quién lo hizo.",
    ["Who?"] = "¿Quién?",
    ["That linen merchant, Siamun; she's never liked me."] = "Ese comerciante de ropa blanca, Siamun; A ella nunca le agrado.",
    ["I'll keep an eye out for her."] = "Estaré atento a ella.",
    ["Could you tell me more about the minor gods?"] = "¿Podrías contarme más sobre los dioses menores?",
    ["Could you tell me more about Scabaras?"] = "¿Podrías contarme más sobre Scabaras?",
    ["I think you'll have gathered most of the relevant details from elsewhere, but general knowledge isn't always the most accurate."] = "Creo que habrás recopilado la mayoría de los detalles relevantes de otros lugares, pero el conocimiento general no siempre es el más preciso.",
    ["Are you claiming I've been misinformed?"] = "¿Estás afirmando que me han informado mal?",
    ["Not really; there are simply details of Scabaras's fall from grace that are only known to we priests."] = "En realidad no; simplemente hay detalles de la caída en desgracia de Scabaras que sólo conocemos los sacerdotes.",
    ["Such as?"] = "¿Por ejemplo?",
    ["Some of his supposed faults can be forgiven. I just can't explain why at the moment."] = "Algunas de sus supuestas faltas pueden ser perdonadas. Simplemente no puedo explicar por qué en este momento.",
    ["I'm not sure whether I should thank you for that bit of confusion or add to that bump on your head."] = "No estoy seguro de si debería agradecerte por ese poco de confusión o aumentar ese chichón en tu cabeza.",
    ["Could you tell me more about Het?"] = "¿Podrías contarme más sobre Het?",
    ["Het is the least strange looking of our deities to foreign eyes; he looks just like us. I suspect this is why his shrines are particularly targeted by the infamous Templeton."] = "Es el aspecto menos extraño de nuestras deidades a ojos extranjeros; se parece a nosotros. Sospecho que es por eso que sus santuarios son particularmente atacados por el infame Templeton.",
    ["What does his patronage cover?"] = "¿Qué cubre su patrocinio?",
    ["He is the very incarnation of health and strength in both mind and body."] = "Él es la encarnación misma de la salud y la fuerza tanto en la mente como en el cuerpo.",
    ["Could you tell me more about Het's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Het en el desierto?",
    ["When I was young, I thought of Het as a strong virtuous knight: brave, daring, and, perhaps, just a little dim."] = "Cuando era joven, pensaba en Het como un caballero fuerte y virtuoso: valiente, atrevido y, tal vez, un poco tonto.",
    ["Sounds like every knight I've ever known."] = "Suena como todos los caballeros que he conocido.",
    ["But, as I grow older, I'm not so sure. It is clear that Het's influence is felt all over the desert; his strength can be felt on the serrated edges of the Menaphites' blades. His nerve is in the tip of every spear wielded by the soldiers of Al Kharid."] = "Pero, a medida que crezco, no estoy tan seguro. Está claro que la influencia de Het se siente en todo el desierto; su fuerza se puede sentir en los bordes dentados de las espadas de los menafitas. Su valor está en la punta de cada lanza que empuñan los soldados de Al Kharid.",
    ["He fortifies each steel cuff that constrains a slave. He is the very tug in the river Elid that drags many to their deaths."] = "Fortalece cada esposa de acero que restringe a un esclavo. Él es el mismo remolcador del río Elid que arrastra a muchos a la muerte.",
    ["Yet, we have enfeebled slaves and weakened villages. Even in this very city there is a plague sapping us of our strength."] = "Sin embargo, hemos debilitado a los esclavos y a las aldeas. Incluso en esta misma ciudad hay una plaga que nos está quitando nuestras fuerzas.",
    ["So, you feel that Het has turned his back on your people?"] = "Entonces, ¿sientes que Het le ha dado la espalda a tu gente?",
    ["No, I wouldn't say that. We mortals are too quick to blame our problems on the gods. Without weakness there is no strength, after all."] = "No, yo no diría eso. Nosotros, los mortales, nos apresuramos a culpar a los dioses de nuestros problemas. Después de todo, sin debilidad no hay fuerza.",
    ["Could you tell me more about Het's followers?"] = "¿Podrías contarme más sobre los seguidores de Het?",
    ["Het originated in the north, so he is worshipped fervently by the people of Al Kharid; however, he is a popular god across the desert - his powerful image of strength and health make him a popular god amongst soldiers and leaders."] = "Het se originó en el norte, por lo que la gente de Al Kharid lo adora fervientemente; sin embargo, es un dios popular en todo el desierto: su poderosa imagen de fuerza y ​​salud lo convierte en un dios popular entre soldados y líderes.",
    ["Could you tell me more about Crondis?"] = "¿Podrías contarme más sobre Crondis?",
    ["Crondis is a ferocious lady with the head of a mighty crocodile."] = "Crondis es una dama feroz con cabeza de un poderoso cocodrilo.",
    ["That must be awkward when buying helmets."] = "Eso debe ser incómodo a la hora de comprar cascos.",
    ["Enough flippancy: remember she is a deity, and this is her place of power."] = "Basta de ligereza: recuerda que ella es una deidad y este es su lugar de poder.",
    ["What kind of people follow her?"] = "¿Qué tipo de gente la sigue?",
    ["She embodies modesty, diligence and resourcefulness, so Crondis is worshipped by the desert's subsistence farmers and hunters. Conversely, she proves unpopular amongst society's elite."] = "Ella encarna la modestia, la diligencia y el ingenio, por eso Crondis es adorada por los agricultores y cazadores de subsistencia del desierto. Por el contrario, resulta impopular entre la élite de la sociedad.",
    ["How so?"] = "¿Cómo es eso?",
    ["Crondis teaches that people should take no more than they need and make do with little, which, as you can imagine, conflicts with the values of many in the richer echelons of society."] = "Crondis enseña que las personas no deben tomar más de lo que necesitan y arreglárselas con poco, lo cual, como puedes imaginar, entra en conflicto con los valores de muchos en los niveles más ricos de la sociedad.",
    ["In Menaphos, she is particularly frowned upon, although that is hardly surprising."] = "En Menaphos, ella está particularmente mal vista, aunque eso no es sorprendente.",
    ["Why?"] = "¿Por qué?",
    ["The Pharaoh of Menaphos is a greedy, cruel man whose lack of restraint is beyond even Crondis's help."] = "El faraón de Menaphos es un hombre codicioso y cruel cuya falta de control está más allá incluso de la ayuda de Crondis.",
    ["Excuse me, I should not have spoken that way. It is unwise to speak ill of one's betters."] = "Disculpe, no debería haber hablado de esa manera. No es prudente hablar mal de los mejores.",
    ["Could you tell me more about Crondis's connection with crocodiles?"] = "¿Podrías contarme más sobre la conexión de Crondis con los cocodrilos?",
    ["Crondis was once a crocodile. Many people believe that those that hunt in the waters of the River Elid embody her very spirit. They were her most beloved supporters."] = "Crondis fue una vez un cocodrilo. Mucha gente cree que quienes cazan en las aguas del río Elid encarnan su espíritu. Eran sus seguidores más queridos.",
    ["When I was young, people were wary of them, revered them even, but were not afraid of them. With the recent crocodile attacks, that has changed."] = "Cuando era joven, la gente desconfiaba de ellos, incluso los veneraban, pero no les tenían miedo. Con los recientes ataques de cocodrilos, eso ha cambiado.",
    ["I'm afraid that the growing lack of restraint of the crocodiles along the River Elid is only further proof that not all is well with Crondis."] = "Me temo que la creciente falta de control de los cocodrilos a lo largo del río Elid es sólo una prueba más de que no todo va bien con Crondis.",
    ["Could you tell me more about Crondis's followers?"] = "¿Podrías contarme más sobre los seguidores de Crondis?",
    ["Crondis is worshipped by those who rely upon their ingenuity to survive: sailors, engineers and rogues hold her in high regard."] = "Crondis es adorada por aquellos que dependen de su ingenio para sobrevivir: marineros, ingenieros y pícaros la tienen en alta estima.",
    ["Due to her popularity amongst seafarers, word of Crondis has spread far and wide and her followers can be found in a great number of exotic places."] = "Debido a su popularidad entre la gente de mar, la palabra sobre Crondis se ha extendido por todas partes y sus seguidores se pueden encontrar en una gran cantidad de lugares exóticos.",
    ["Could you tell me more about Crondis's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Crondis sobre el desierto?",
    ["Could you tell me more about Crondis's influence?"] = "¿Podrías contarme más sobre la influencia de Crondis?",
    ["Crondis hopes to inspire resourcefulness and unassuming modesty. While this has always been her goal, her methods vary more than most."] = "Crondis espera inspirar ingenio y modestia sin pretensiones. Si bien este siempre ha sido su objetivo, sus métodos varían más que la mayoría.",
    ["I'm confused. What do you mean?"] = "Estoy confundido. ¿Qué quieres decir?",
    ["Crondis may save a struggling harvest by bursting the clouds, or she might set swarms of locusts upon a bountiful crop to stop complacency."] = "Crondis puede salvar una cosecha difícil haciendo estallar las nubes, o puede lanzar enjambres de langostas sobre una cosecha abundante para detener la complacencia.",
    ["Could you tell me more about Apmeken?"] = "¿Podrías contarme más sobre Apmeken?",
    ["Something tells me that you might know more than I. I've sensed a change in the heavens, albeit a small one, and I can't help thinking it has something to do with you."] = "Algo me dice que quizás sepas más que yo. He sentido un cambio en los cielos, aunque sea pequeño, y no puedo evitar pensar que tiene algo que ver contigo.",
    ["What makes you think that?"] = "¿Qué te hace pensar eso?",
    ["Not many people come here, and, of those few that do, only a few care to mention Apmeken. I feel her sunny smile shining upon the desert, and I am convinced you are responsible for that. I thank you."] = "No viene mucha gente aquí y, de los pocos que lo hacen, solo unos pocos se preocupan por mencionar Apmeken. Siento su sonrisa soleada brillando sobre el desierto y estoy convencido de que tú eres el responsable de ello. Te lo agradezco.",
    ["Apmeken was the most mischievous, playful and unpredictable of the minor deities. My personal favourite, in fact."] = "Apmeken era la más traviesa, juguetona e impredecible de las deidades menores. Mi favorito personal, de hecho.",
    ["I'm guessing I shouldn't trust you, then?"] = "Supongo que no debería confiar en ti, ¿entonces?",
    ["While Apmeken was mischievous, she was also a goddess of friendship. Like her, I may trip you, but I'd catch you before you fell."] = "Si bien Apmeken era traviesa, también era una diosa de la amistad. Como ella, puedo hacerte tropezar, pero te atraparé antes de que caigas.",
    ["Well, that's good to know. I presume she looks slightly inhuman?"] = "Bueno, es bueno saberlo. ¿Supongo que parece un poco inhumana?",
    ["She had the head of a monkey, ape or baboon, depending on the nature she was displaying at the time. The monkey was skilful, the ape was wise and the baboon was comical."] = "Tenía cabeza de mono, simio o babuino, dependiendo de la naturaleza que mostrara en ese momento. El mono era hábil, el simio sabio y el babuino cómico.",
    ["I see. Jex, I can't help notice that you're speaking in the past tense."] = "Ya veo. Jex, no puedo evitar notar que estás hablando en tiempo pasado.",
    ["Ah, sorry, yes. I'm of the opinion - and it's an opinion not shared by many, I should add - that Apmeken has moved on from these lands."] = "Ah, lo siento, sí. Soy de la opinión -y es una opinión que no comparten muchos, debo añadir- que Apmeken ha abandonado estas tierras.",
    ["I've read reams of scripture detailing Apmeken, and heard endless tales of her deeds. I can't believe that the desert would be such a warring, sombre, plague-filled place if she was still felt here."] = "He leído montones de escrituras que detallan a Apmeken y he escuchado infinitas historias sobre sus hazañas. No puedo creer que el desierto sería un lugar tan guerrero, sombrío y lleno de plagas si todavía se sintiera aquí.",
    ["That's interesting, Jex; can I ask you some more questions about her?"] = "Eso es interesante, Jex; ¿Puedo hacerte más preguntas sobre ella?",
    ["Of course."] = "Por supuesto.",
    ["Could you tell me more about Apmeken's connection with monkeys?"] = "¿Podrías contarme más sobre la conexión de Apmeken con los monos?",
    ["Apmeken was once a monkey. Many people believe that the native monkeys embodied her very spirit. They were her most beloved supporters. There hasn't been any wild monkeys in the desert for a long time - not since I was a child."] = "Apmeken alguna vez fue un mono. Mucha gente cree que los monos nativos encarnaban su espíritu. Eran sus seguidores más queridos. Hace mucho tiempo que no hay monos salvajes en el desierto, desde que yo era niño.",
    ["I'm afraid that the lack of monkeys living here is only further proof that Apmeken has indeed moved on."] = "Me temo que la falta de monos viviendo aquí es sólo una prueba más de que Apmeken realmente ha seguido adelante.",
    ["Could you tell me more about Apmeken's followers?"] = "¿Podrías contarme más sobre los seguidores de Apmeken?",
    ["Apmeken is worshipped by those who value the community and friendship above everything else: mothers, priests and even politicians."] = "Apmeken es adorado por quienes valoran la comunidad y la amistad por encima de todo: madres, sacerdotes e incluso políticos.",
    ["Apmeken originated in the west, in the space between two warring tribes, and it is there she found most of her support."] = "Apmeken se originó en el oeste, en el espacio entre dos tribus en guerra, y es allí donde encontró la mayor parte de su apoyo.",
    ["Could you tell me more about Apmeken's influence over the desert?"] = "¿Podrías contarme más sobre la influencia de Apmeken sobre el desierto?",
    ["Apmeken's influence was subtle but incredible, she was an infectious laugh, a jaunty jig, a joke you've heard a hundred times before, but still chuckle at."] = "La influencia de Apmeken fue sutil pero increíble, ella era una risa contagiosa, una jiga alegre, una broma que has escuchado cientos de veces antes, pero de la que aún te ríes.",
    ["It may not sound like much, but these subtleties have been known to avert wars and make enemies set aside their differences."] = "Puede que no parezca mucho, pero se sabe que estas sutilezas evitan guerras y hacen que los enemigos dejen de lado sus diferencias.",
    ["Goodbye, Jex."] = "Adiós, Jex.",
    ["Goodbye. May the gods be with you."] = "Adiós. Que los dioses estén contigo.",
    ["Why is your temple still in such a state?"] = "¿Por qué tu templo sigue en ese estado?",
    ["The minor gods aren't particularly revered in our fine city. Icthlarin holds sway here and, although a fine deity indeed, he's not the most jolly of sorts."] = "Los dioses menores no son particularmente venerados en nuestra hermosa ciudad. Icthlarin domina aquí y, aunque es una excelente deidad, no es el más alegre.",
    ["I thought you were a priest of Icthlarin?"] = "¿Pensé que eras un sacerdote de Icthlarin?",
    ["Well, yes and no. I am primarily a priest of Icthlarin, certainly, but I have been trained in the rites of the minor gods as well."] = "Bueno, sí y no. Ciertamente soy principalmente un sacerdote de Icthlarin, pero también he sido entrenado en los ritos de los dioses menores.",
    ["What would it take to repair this temple, then? Money? Materials? Manpower?"] = "¿Qué se necesitaría entonces para reparar este templo? ¿Dinero? ¿Materiales? ¿Mano de obra?",
    ["I'm not really sure, to be honest. Most of the natural worshippers are in Menaphos; of course, and the local economy is rather depressed. In addition, that Templeton rogue made off with some of the damaged stonework. We should hunt him down like the jackal he is."] = "Para ser honesto, no estoy muy seguro. La mayoría de los adoradores naturales están en Menaphos; Por supuesto, y la economía local está bastante deprimida. Además, ese pícaro de Templeton se llevó parte de la mampostería dañada. Deberíamos cazarlo como el chacal que es.",
    ["I'm sure you'll think of something; you'll be able to count on me when you do."] = "Estoy seguro de que se te ocurrirá algo; Podrás contar conmigo cuando lo hagas.",
    ["You are welcome in our home."] = "Eres bienvenido a nuestra casa.",
    ["Greetings. Do you have a moment to spare? I need some help."] = "Saludos. ¿Tienes un momento libre? Necesito ayuda.",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["Yes."] = "Sí.",
    ["My appreciation."] = "Mi agradecimiento.",
    ["Not right now."] = "No ahora mismo.",
    ["I am exhausted because my children are unable to sleep at night."] = "Estoy exhausto porque mis hijos no pueden dormir por la noche.",
    ["Oh, that's awful, how come they cannot sleep?"] = "Oh, eso es horrible, ¿por qué no pueden dormir?",
    ["My oldest son is too afraid to sleep because of the [monster]."] = "Mi hijo mayor tiene demasiado miedo para dormir debido al [monster].",
    ["Would you be able to go and find some [monster] and thin their numbers?"] = "¿Podrías ir a buscar algunos [monster] y reducir sus números?",
    ["Seems a little excessive... How many would I need to deal with?"] = "Parece un poco excesivo... ¿Con cuántos tendría que lidiar?",
    ["Could you kill [number] [monster] for me?"] = "¿Podrías matar a [número] [monster] por mí?",
    ["Where could I find [monster]?"] = "¿Dónde puedo encontrar [monster]?",
    ["They were exiled. Rumour has it they've set themselves up in Pollnivneach. That's what I've heard."] = "Fueron exiliados. Se rumorea que se han instalado en Pollnivneach. Eso es lo que he oído.",
    ["The mining camp is somewhere out in the desert to the north. That's what I've heard."] = "El campamento minero está en algún lugar del desierto, al norte. Eso es lo que he oído.",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Did you deal with the [number] [monster]? ([number] remaining)"] = "¿Se ocuparon del [número] [monster]? ([número] restantes)",
    ["Not yet. Where could I find [monster] again?"] = "Todavía no. ¿Dónde podría encontrar [monster] nuevamente?",
    ["They were exiled. Rumour has it they've set themselves up in Pollnivneach."] = "Fueron exiliados. Se rumorea que se han instalado en Pollnivneach.",
    ["The mining camp is somewhere out in the desert to the north."] = "El campamento minero está en algún lugar del desierto, al norte.",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["Yeah, the [monster] won't be scaring your son again anytime soon."] = "Sí, el [monster] no volverá a asustar a tu hijo en el corto plazo.",
    ["Thank you. As excessive as it may have seemed, it was necessary!"] = "Gracias. Por excesivo que pareciera, ¡era necesario!",
    ["Now that he can sleep peacefully, let us talk about my daughter."] = "Ahora que puede dormir tranquilo, hablemos de mi hija.",
    ["Ever since she was a little baby, she has been unable to sleep without [item]."] = "Desde que era pequeña, no puede dormir sin [item].",
    ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
    ["Yes, I know it's a bit strange, but [item] were the only thing that would help her drift off."] = "Sí, sé que es un poco extraño, pero [item] era lo único que la ayudaría a quedarse dormida.",
    ["So, please, if you could get [number] [item] I would greatly appreciate it."] = "Entonces, por favor, si pudieras conseguir [número] [item], te lo agradecería mucho.",
    ["Alright."] = "Muy bien.",
    ["Do you know where I could get [item]?"] = "¿Sabes dónde puedo conseguir [item]?",
    ["Copper ore can be found south-east of Varrock."] = "El mineral de cobre se puede encontrar al sureste de Varrock.",
    ["No, sorry."] = "No, lo siento.",
    ["Have you found [number] [item] yet? ([number] remaining)"] = "¿Ya has encontrado [número] [item]? ([número] restantes)",
    ["Nope, where should I be looking for the [item]?"] = "No, ¿dónde debería buscar el [item]?",
    ["Number of [item] given to Jhonatan ([number]/[number])"] = "Número de [item] dado a Jhonatan ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["I have the [item]."] = "Tengo el [item].",
    ["Excellent, my daughter will be able to sleep like a baby once again!"] = "¡Excelente, mi hija podrá volver a dormir como un bebé!",
    ["Now, my youngest son, he recently lost his teddy bear."] = "Ahora, mi hijo menor, recientemente perdió su osito de peluche.",
    ["You want me to find him a new teddy bear?"] = "¿Quieres que le busque un nuevo osito de peluche?",
    ["No, no. I may not look like it, but I am quite skilled in crafting. I plan to make him a new one if you could get me the materials."] = "No, no. Puede que no lo parezca, pero soy bastante hábil en la elaboración. Planeo hacerle uno nuevo si pudieras conseguirme los materiales.",
    ["What do you need?"] = "¿Qué necesitas?",
    ["I need [number] [item] to make it out of."] = "Necesito [número] [item] para salir.",
    ["So, could you get [number] [item] for me?"] = "Entonces, ¿podrías conseguirme [número] [item]?",
    ["Sure."] = "Claro.",
    ["What do you know about [item]?"] = "¿Qué sabes sobre [item]?",
    ["I hear there is a renowned candlemaker in Catherby."] = "He oído que hay un fabricante de velas de renombre en Catherby.",
    ["Nope."] = "No.",
    ["Did you bring [number] [item]? This teddy bear won't build itself! ([number] remaining)"] = "¿Trajiste [número] [item]? ¡Este osito de peluche no se construirá solo! ([número] restantes)",
    ["Not yet. Could you point me in the direction of some [item]?"] = "Todavía no. ¿Podrías indicarme la dirección de algún [item]?",
    ["Yes, I have brought the [item]."] = "Sí, he traído el [item].",
    ["So how do you make a teddy bear from..."] = "Entonces, ¿cómo se hace un osito de peluche con...?",
    ["No. I think it's better to not know."] = "No. Creo que es mejor no saberlo.",
    ["Excellent! I'll get right to work!"] = "¡Excelente! ¡Me pondré manos a la obra!",
    ["So, my other son..."] = "Entonces, mi otro hijo...",
    ["Uh... Bye."] = "Eh... Adiós.",
    ["The magnificent Crondis has been angered by [monster]. She requires a blood sacrifice and a tribute."] = "El magnífico Crondis se ha enfadado con [monster]. Requiere un sacrificio de sangre y un tributo.",
    ["First, go and kill [number] [monster]."] = "Primero, ve y mata a [número] [monster].",
    ["What have the [monster] done to anger the almighty Crondis?"] = "¿Qué han hecho los [monster] para enojar al todopoderoso Crondis?",
    ["You don't need to know. Will you go to kill them?"] = "No necesitas saberlo. ¿Irás a matarlos?",
    ["Have you vanquished the [number] [monster] for Lady Crondis? ([number] remaining)"] = "¿Has vencido al [número] [monster] para Lady Crondis? ([número] restantes)",
    ["I've been tasked to procure supplies for the war effort."] = "Me han encomendado la tarea de conseguir suministros para el esfuerzo bélico.",
    ["Who are we- Who are YOU at war with?"] = "¿Quiénes somos? ¿Con quién estás en guerra TÚ?",
    ["All will be revealed. First up I need [number] [items]. Can I rely on you?"] = "Todo será revelado. Primero necesito [número] [items]. ¿Puedo confiar en ti?",
    ["Affirmative."] = "Afirmativo.",
    ["Negative."] = "Negativo.",
    ["Do you have the [number] [item] at hand, soldier? ([number] remaining)"] = "¿Tienes el [número] [item] a mano, soldado? ([número] restantes)",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["Good work, soldier!"] = "¡Buen trabajo, soldado!",
    ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
    ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
    ["Have you ever tried to fight a war without [item]? I didn't think so."] = "¿Alguna vez has intentado pelear una guerra sin [item]? No lo creo.",
    ["The war effort requires [number] [item]. I assume I can trust you to obtain the [item]?"] = "El esfuerzo de guerra requiere [número] [item]. ¿Asumo que puedo confiar en usted para obtener el [item]?",
    ["You sure can."] = "Seguro que puedes.",
    ["Do you have the supplies, soldier? This war won't fund itself! We need [number] [item]! ([number] remaining)"] = "¿Tienes los suministros, soldado? ¡Esta guerra no se financiará sola! ¡Necesitamos [número] [item]! ([número] restantes)",
    ["Great! Now we are ready to drive the offensive home!"] = "¡Genial! ¡Ahora estamos listos para llevar la ofensiva a casa!",
    ["Can I ask why you're talking like this?"] = "¿Puedo preguntar por qué hablas así?",
    ["Whatever do you mean, soldier?"] = "¿Qué quieres decir, soldado?",
    ["You're talking like an imperial general. It's a bit off-putting."] = "Estás hablando como un general imperial. Es un poco desagradable.",
    ["The guards are always watching. I have to keep up appearances."] = "Los guardias siempre están mirando. Tengo que guardar las apariencias.",
    ["Right...fair enough. What else do...we...need for the war effort?"] = "Cierto... bastante justo. ¿Qué más... nosotros... necesitamos para el esfuerzo bélico?",
    ["Now is the time you have been waiting for, soldier! The killing!"] = "¡Ahora es el momento que estabas esperando, soldado! ¡La matanza!",
    ["We will finally vanquish our dreaded enemy, the [monster]!"] = "¡Finalmente venceremos a nuestro temido enemigo, el [monster]!",
    ["What?"] = "¿Qué?",
    ["Yes, kill [number] [monster] in the name of the Pharaoh himself!"] = "¡Sí, mata a [número] [monster] en nombre del propio Faraón!",
    ["Okay."] = "Está bien.",
    ["Have you killed [number] [monster]? They're usually sliming around Sophanem. We might win this war yet! ([number] remaining)"] = "¿Has matado a [número] [monster]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! ([número] restantes)",
    ["Have you killed [number] [monster]? They're usually sliming around Sophanem. We might win this war yet! (0 remaining)"] = "¿Has matado a [número] [monster]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! (0 restante)",
    ["Yes, I have killed the [monster]."] = "Sí, he matado al [monster].",
    ["Have you danced, as they say, in the blood of your enemies? Have you sent the souls of [number] [monster] to the Underworld?"] = "¿Has bailado, como dicen, en la sangre de tus enemigos? ¿Has enviado las almas de [número] [monster] al Inframundo?",
    ["Not that those [monster] have souls, I believe they are truly beyond help."] = "No es que esos [monster] tengan alma, creo que realmente no pueden recibir ayuda.",
    ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    ["I fear you still need a lot more help."] = "Me temo que todavía necesitas mucha más ayuda.",
    ["Nothing. It was my pleasure."] = "Nada. Fue un placer.",
    ["Hi Jim!"] = "¡Hola Jim!",
    ["What do you think you're doing? You'll blow your cover. Let me get you out of that suit."] = "¿Qué crees que estás haciendo? Vas a arruinar tu tapadera. Déjame sacarte ese traje.",
    ["Do you want to get out of the penguin suit?"] = "¿Quieres quitarte el traje de pingüino?",
    ["I don't have enough room to store my penguin suit in my pack. I'll have to make room first."] = "No tengo suficiente espacio para guardar mi traje de pingüino en mi mochila. Primero tendré que hacer espacio.",
    ["The spell wears off as you climb out of the suit, growing back to normal size."] = "El hechizo desaparece cuando te quitas el traje y vuelve a crecer hasta su tamaño normal.",
    ["No, thanks."] = "No, gracias.",
    ["Tuxedo-time."] = "Hora del esmoquin.",
    ["You will need your hands free to operate the suit."] = "Necesitará tener las manos libres para operar el traje.",
    ["You can't wear a cape inside the suit, it might get caught."] = "No puedes usar una capa dentro del traje, podría quedar atrapada.",
    ["You shrink and walk in to the penguin suit."] = "Te encoges y te pones el traje de pingüino.",
    ["Ask about hunting ground."] = "Preguntar por cotos de caza.",
    ["Pssst."] = "Psst.",
    ["Oh, so you can talk now?"] = "Oh, ¿entonces puedes hablar ahora?",
    ["I could always talk. But I didn't want to reveal myself to the enemy."] = "Siempre podría hablar. Pero no quería revelarme al enemigo.",
    ["Well, what do you want?"] = "Bueno, ¿qué quieres?",
    ["I have heard of Larry's capture. I am sorry for your loss. Larry is very brave."] = "He oído hablar de la captura de Larry. Lamento tu pérdida. Larry es muy valiente.",
    ["Yeah. I hope he's okay. Where ever he is."] = "Sí. Espero que esté bien. Dondequiera que esté.",
    ["That is why I wish to speak to you. I have been instructed to assist you in infiltrating the penguins and training for future assignments."] = "Por eso deseo hablar contigo. Me han ordenado que le ayude a infiltrarse entre los pingüinos y a entrenar para futuras asignaciones.",
    ["What? What future assignments?"] = "¿Qué? ¿Qué futuras asignaciones?",
    ["When you go to rescue Larry, of course. It is not a task to be approached unprepared."] = "Cuando vayas a rescatar a Larry, claro. No es una tarea que deba abordarse sin estar preparado.",
    ["So what exactly am I supposed to do?"] = "Entonces, ¿qué se supone que debo hacer exactamente?",
    ["Should you wish to infiltrate the penguins, I have been granted access to the spell that puts you in your penguin suit."] = "Si deseas infiltrarte entre los pingüinos, se me ha concedido acceso al hechizo que te pone tu traje de pingüino.",
    ["There is more than that, though. A new iceberg has floated down from the north, bringing with it reinforcements for the Penguin Outpost."] = "Pero hay más que eso. Un nuevo iceberg ha descendido flotando desde el norte, trayendo consigo refuerzos para Penguin Outpost.",
    ["To prepare you for the times ahead, we have provided some equipment for you to practise hunting and tracking penguins."] = "Para prepararte para los tiempos venideros, te proporcionamos algunos equipos para que practiques la caza y el rastreo de pingüinos.",
    ["In exchange for the experience you gain, we only ask that you hand over the captured KGP agents to us."] = "A cambio de la experiencia que ganes, solo te pedimos que nos entregues a los agentes de KGP capturados.",
    ["Simply jump across the ice floes here."] = "Simplemente salta sobre los témpanos de hielo aquí.",
    ["Why KGP agents? What will you do with them?"] = "¿Por qué agentes de KGP? ¿Qué harás con ellos?",
    ["That is classified. You do not need to know."] = "Eso está clasificado. No necesitas saberlo.",
    ["What do you want to do?"] = "¿Qué quieres hacer?",
    ["Press him further."] = "Presiónelo más.",
    ["That's not good enough? I'm tired of just taking orders. What will you do with the captured penguins?"] = "¿Eso no es suficiente? Estoy cansado de sólo recibir órdenes. ¿Qué harás con los pingüinos capturados?",
    ["Very well, if you insist on knowing. We will interrogate them and keep them imprisoned. They may reveal valuable information about Larry's location. That is why we only want KGP agents, the other penguins know nothing of"] = "Muy bien, si insistes en saberlo. Los interrogaremos y los mantendremos encarcelados. Pueden revelar información valiosa sobre la ubicación de Larry. Por eso solo queremos agentes del KGP, los otros pingüinos no saben nada de ello.",
    ["interest."] = "interés.",
    ["Ignorance is bliss."] = "La ignorancia es felicidad.",
    ["Fine, I don't want to know."] = "Bien, no quiero saberlo.",
    ["It is for the best."] = "Es lo mejor.",
    ["Do you have any captured KGP agents you would like to hand over?"] = "¿Tiene algún agente de KGP capturado que le gustaría entregar?",
    ["Yes, I do have some."] = "Sí, tengo algunos.",
    ["Very good. Let me take a look."] = "Muy bien. Déjame echar un vistazo.",
    ["You don't appear to have any with you."] = "Parece que no tienes ninguno contigo.",
    ["The PBJ thanks you for your help."] = "La PBJ te agradece tu ayuda.",
    ["No, I don't have any for you right now."] = "No, no tengo ninguno para ti en este momento.",
    ["You tickle the polar bear."] = "Le haces cosquillas al oso polar.",
    ["You do not have enough space in your inventory to get out of the suit."] = "No tienes suficiente espacio en tu inventario para quitarte el traje.",
    ["Welcome to Jiminua's Jungle Store. Can I help you at all?"] = "Bienvenido a la tienda Jungle Store de Jiminua. ¿Puedo ayudarte en algo?",
    ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
    ["Take a good look."] = "Míralo bien.",
    ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
    ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
    ["Can you un-note any of my items?"] = "¿Puedes anular la nota de alguno de mis artículos?",
    ["I can un-note pure essence, but nothing else. Just give me the notes you wish to exchange."] = "Puedo eliminar la esencia pura, pero nada más. Sólo dame las notas que deseas intercambiar.",
    ["What is your name and what is your business here?"] = "¿Cuál es tu nombre y cuál es tu negocio aquí?",
    ["My name is Player, and I have a couple of questions for you."] = "Mi nombre es Player y tengo un par de preguntas para usted.",
    ["What do you mean by no?"] = "¿Qué quieres decir con no?",
    ["That just isn't the ticket. I don't know you nor will I answer any questions. Now begone from here, you'll attract unwanted attention to me."] = "Ese no es el billete. No te conozco ni responderé ninguna pregunta. Ahora vete de aquí, atraerás atención no deseada hacia mí.",
    ["As if those 'clothes' you're wearing wouldn't do that already."] = "Como si esa 'ropa' que llevas puesta no hiciera eso ya.",
    ["Ah, Player, aren't you just the ticket?"] = "Ah, Player, ¿no eres sólo el billete?",
    ["Can you tell me where I could find..."] = "¿Puedes decirme dónde puedo encontrar...?",
    ["Grimesquit and Phingspet"] = "Grimesquit y Phingspet",
    ["Can you tell me where I could find Phingspet and Grimesquit?"] = "¿Puedes decirme dónde puedo encontrar Phingspet y Grimesquit?",
    ["You can find those vile harpies in the sewers of Varrock."] = "Puedes encontrar esas viles arpías en las alcantarillas de Varrock.",
    ["~ Jimmy shudders when he thinks of them. ~"] = "~ Jimmy se estremece cuando piensa en ellos. ~",
    ["If you ask me, it's too good a place for them."] = "Si me preguntas, es un lugar demasiado bueno para ellos.",
    ["Can you tell me where I could find Hooknosed Jack?"] = "¿Puedes decirme dónde puedo encontrar Hooknosed Jack?",
    ["He should be in the roughest area of Varrock, knowing him. He likes a good scrap does Jack."] = "Debería estar en la zona más dura de Varrock, conociéndolo. A Jack le gusta una buena pelea.",
    ["Can you tell me where I could find Smokin' Joe?"] = "¿Puedes decirme dónde puedo encontrar Smokin' Joe?",
    ["You won't find him around here. They wouldn't let a filthy old dwarf like him into a civilised town like this."] = "No lo encontrarás por aquí. No dejarían que un viejo y asqueroso enano como él entrara en una ciudad civilizada como ésta.",
    ["Well, if he's not here, where would I find him?"] = "Bueno, si no está aquí, ¿dónde lo encontraría?",
    ["If the old rascal's lungs haven't given up yet, you should find him in Keldagrim, the city of dwarves."] = "Si los pulmones del viejo sinvergüenza aún no se han rendido, deberías encontrarlo en Keldagrim, la ciudad de los enanos.",
    ["Can you tell me where I could find 'The Face'?"] = "¿Puedes decirme dónde puedo encontrar 'The Face'?",
    ["Old Pugly? My oh my, she got her comeuppance alright!"] = "¿Viejo Pugly? ¡Dios mío, ella recibió su merecido!",
    ["Old Pugly?"] = "¿Viejo Pugly?",
    ["Pug ugly."] = "Pug feo.",
    ["That's really nasty."] = "Eso es realmente desagradable.",
    ["Believe me, she deserves everything she gets!"] = "Créeme, ¡ella se merece todo lo que recibe!",
    ["What did she do?"] = "¿Qué hizo ella?",
    ["I couldn't possibly tell you, but be careful around her."] = "No podría decírtelo, pero ten cuidado con ella.",
    ["Will you please tell me where I could find her?"] = "¿Podrías decirme dónde puedo encontrarla?",
    ["She'll be in or around Port Sarim I reckon."] = "Supongo que estará en Port Sarim o sus alrededores.",
    ["Can you tell me where I would find Felkrash?"] = "¿Puedes decirme dónde encontraría Felkrash?",
    ["The Boss? You'll find her in Port Sarim."] = "¿El jefe? La encontrarás en Port Sarim.",
    ["She's your boss?"] = "¿Ella es tu jefa?",
    ["Well, sort of. She's the unofficial head of the rat catchers."] = "Bueno, más o menos. Ella es la jefa no oficial de los cazadores de ratas.",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["Hello mate!"] = "¡Hola amigo!",
    ["Ello there."] = "Hola.",
    ["Tell me about this room."] = "Háblame de esta habitación.",
    ["Tell me about this room?"] = "¿Cuéntame sobre esta habitación?",
    ["Well... s'like thish... Thish here'sh a shtore room right?"] = "Bueno... es así... Aquí hay un trastero, ¿verdad?",
    ["A store roorr. you mean?"] = "Una tienda. ¿te refieres a?",
    ["That'sh what I shaid! *HIC* A shtore room.... Now technic'ly shpeaking, I should be outshide guarding it..."] = "¡Eso es lo que dije! *HIC* Un almacén... Ahora, técnicamente hablando, debería estar afuera cuidándolo...",
    ["But you just nipped in to have a quick drink?"] = "¿Pero viniste a tomar un trago rápido?",
    ["Yep... and to practish."] = "Sí... y a practicar.",
    ["Practish? I mean.. practise what?"] = "¿Practicar? Quiero decir... ¿practicar qué?",
    ["Keg balancin. I'm the besht."] = "Equilibrio del barril. Soy el mejor.",
    ["Tell me how to balance kegs."] = "Dime cómo equilibrar barriles.",
    ["Tell me how to balance kegs?"] = "¿Dime cómo equilibrar los barriles?",
    ["Yer very very shtrange. But.... you pick the keg up, and balance it on yer head, then you pick another keg up and put that on top. S'really very eashy."] = "Eres muy, muy extraño. Pero... levantas el barril y lo equilibras sobre tu cabeza, luego tomas otro barril y lo pones encima. Es realmente muy fácil.",
    ["Eashy?"] = "¿Tranquilo?",
    ["Yesh. Eashy."] = "Sí. Fácil.",
    ["But you couldn't ever balansh ash many ash meee!"] = "¡Pero nunca podrías equilibrar ash muchos ash meee!",
    ["That sounds like a challenge, I'll show you!"] = "Eso suena como un desafío, ¡te lo mostraré!",
    ["What's with the multicoloured furniture?"] = "¿Qué pasa con el furniture multicolor?",
    ["Keg tag. S'my invenshun."] = "Etiqueta de barril. Es mi invención.",
    ["Keg tag? How does that work?"] = "¿Etiqueta de barril? ¿Cómo funciona eso?",
    ["Eashy. Balance kegsh on yer head, then shee if you can tag the coloured shtuff in order, before you loshe control of yer kegsh."] = "Tranquilo. Equilibra el barril sobre tu cabeza y luego comprueba si puedes etiquetar las cosas de colores en orden, antes de que pierdas el control del barril.",
    ["So, I put some kegs on my head, then go around tagging each of the coloured furniture in order. Sounds easy! What do I get?"] = "Entonces, me pongo algunos barriles en la cabeza y luego voy etiquetando cada uno de los furniture de colores en orden. ¡Suena fácil! ¿Qué obtengo?",
    ["Well...I could teash yer shumfin' abou' strength."] = "Bueno... podría molestarte sobre la fuerza.",
    ["Knowledge in strength. Hmm, could be useful."] = "Conocimiento en fuerza. Mmmm, podría ser útil.",
    ["Bye!"] = "¡Adiós!",
    ["Shure you wouldn't like an ickle drinkie fore yer go?"] = "¿Seguro que no te gustaría tomar un trago antes de irte?",
    ["No thanks, got things to do, people to see, tokens to earn..."] = "No, gracias, tengo cosas que hacer, gente que ver, fichas que ganar...",
    ["That's another year in Um been and gone..."] = "Ese es otro año en el que Um ha estado y se ha ido...",
    ["Hello!"] = "¡Hola!",
    ["Arr? Be ye wantin' te go on account with our gang o' fillibusters?"] = "¿Llegó? ¿Quieres ir a cuenta con nuestra banda de filibusteros?",
    ["The powder monkey be takin' a caulk after gettin' rowdy on bumboo, so there be plenty of room for ye."] = "El mono de la pólvora se va a poner masilla después de ponerse alborotado en bumboo, así que habrá mucho espacio para ti.",
    ["Riiiiight..."] = "Correcto...",
    ["I'll just be over here if you need me."] = "Estaré aquí si me necesitas.",
    ["Whadda ya want?"] = "¿Qué quieres?",
    ["Whadda ya got?"] = "¿Qué tienes?",
    ["We gots grog and we gots food. Here, take a look."] = "Tenemos grog y comida. Aquí, echa un vistazo.",
    ["Nothing! Honest!"] = "¡Nada! ¡Honesto!",
    ["Then stop takin' up me floor space!"] = "¡Entonces deja de ocuparme espacio!",
    ["I wanted to know where you got that harpoon hand."] = "Quería saber de dónde sacaste esa mano de arpón.",
    ["Yer new in town aintcha?"] = "¿Eres nuevo en la ciudad?",
    ["Newish certainly."] = "Nuevo, sin duda.",
    ["Well, if ye wants te hear the story, here goes."] = "Bueno, si quieres escuchar la historia, aquí va.",
    ["See, I was walkin' along the docks one day, and this fierce storm blew up."] = "Mira, un día estaba caminando por los muelles y estalló una tormenta feroz.",
    ["All of a sudden I turn an there, bearin' down on me is this albatross..."] = "De repente me giro y allí, acercándose a mí, está este albatros...",
    ["Sorry to interrupt, but I would just like to clear something up."] = "Perdón por interrumpir, pero me gustaría aclarar algo.",
    ["What? I was just gettin' to the good bit."] = "¿Qué? Estaba llegando a la parte buena.",
    ["When I said 'I wanted to know where you got that harpoon hand', I meant where did you get it made, or buy it from?"] = "Cuando dije 'Quería saber de dónde sacaste esa mano de arpón', quise decir ¿dónde la hiciste o dónde la compraste?",
    ["If ye don't wants to hear the story then I ain't gonna tell ye!"] = "¡Si no quieres escuchar la historia entonces no te la contaré!",
    ["What'll it be?"] = "¿Qué será?",
    ["A Long Drop."] = "Una caída larga.",
    ["Ye sure?"] = "¿Estás seguro?",
    ["Aye, drop me..."] = "Sí, déjame...",
    ["Take a seat."] = "Toma asiento.",
    ["Er, nothing?"] = "Er, ¿nada?",
    ["Then stop tryin' te take up me table space!"] = "¡Entonces deja de intentar ocupar mi espacio en la mesa!",
    ["Sorry, lad, I think you've had enough of those. I'm cutting you off."] = "Lo siento, muchacho, creo que ya has tenido suficiente de eso. Te estoy interrumpiendo.",
    ["Hi, I'm Joe, door guard for Lady Keli."] = "Hola, soy Joe, guardia de puerta de Lady Keli.",
    ["Hi, who are you guarding here?"] = "Hola, ¿a quién estás protegiendo aquí?",
    ["Can't say, all very secret. You should get out of here. I am not supposed to talk while I guard."] = "No puedo decirlo, todo es muy secreto. Deberías salir de aquí. Se supone que no debo hablar mientras estoy en guardia.",
    ["Hey, chill out, I won't cause you trouble. I was just wondering what you do to relax."] = "Oye, relájate, no te causaré problemas. Me preguntaba qué haces para relajarte.",
    ["You never relax with these people, but it's a good career for a young man and some of the shouting I rather like."] = "Nunca te relajas con esta gente, pero es una buena carrera para un joven y algunos de los gritos me gustan bastante.",
    ["RESISTANCE IS USELESS!"] = "¡LA RESISTENCIA ES INÚTIL!",
    ["So what do you buy with these great wages?"] = "Entonces, ¿qué compras con estos fantásticos salarios?",
    ["Really, after working here, there's only time for a drink or three. All us guards go to the same bar and drink ourselves stupid."] = "Realmente, después de trabajar aquí, solo hay tiempo para tomar una copa o tres. Todos los guardias vamos al mismo bar y bebemos hasta quedar estupefactos.",
    ["It's what I enjoy these days, that fade into unconsciousness. I can't resist the sight of a really cold beer."] = "Es lo que disfruto estos días, lo que se desvanece en la inconsciencia. No puedo resistirme a ver una cerveza bien fría.",
    ["Would you be interested in making a little more money?"] = "¿Estarías interesado en ganar un poco más de dinero?",
    ["WHAT?! Are you trying to bribe me? I may not be a great guard, but I am loyal. How DARE you try to bribe me!"] = "¡¿QUÉ?! ¿Estás intentando sobornarme? Puede que no sea un gran guardia, pero soy leal. ¡Cómo te ATREVES a intentar sobornarme!",
    ["No, no, you got the wrong idea, totally. I just wondered if you wanted some part-time bodyguard work."] = "No, no, tienes una idea totalmente equivocada. Sólo me preguntaba si querías un trabajo de guardaespaldas a tiempo parcial.",
    ["Oh. Sorry. No, I don't need money. As long as you were not offering me a bribe."] = "Ah. Lo siento. No, no necesito dinero. Siempre y cuando no me ofrecieras un soborno.",
    ["Tell me about the life of a guard."] = "Cuéntame sobre la vida de un guardia.",
    ["Well, the hours are good....."] = "Bueno, el horario es bueno.....",
    [".... But most of those hours are a drag. If only I had spent more time in Knight school when I was a young boy. Maybe I wouldn't be here now, scared of Keli."] = ".... Pero la mayoría de esas horas son un fastidio. Si tan solo hubiera pasado más tiempo en la escuela Knight cuando era un niño. Quizás no estaría aquí ahora, asustada de Keli.",
    ["What did you want to be when you were a boy?"] = "¿Qué querías ser cuando eras niño?",
    ["Well, I loved to sit by the lake, with my toes in the water and shoot the fish with my bow and arrow."] = "Bueno, me encantaba sentarme junto al lago, con los dedos de los pies en el agua y disparar a los peces con mi arco y flecha.",
    ["That was a strange hobby for a little boy."] = "Ese era un pasatiempo extraño para un niño pequeño.",
    ["It kept us from goblin hunting, which was what most boys did. What are you here for?"] = "Nos impedía cazar duendes, que era lo que hacían la mayoría de los niños. ¿Para qué estás aquí?",
    ["I had better leave, I don't want trouble."] = "Será mejor que me vaya, no quiero problemas.",
    ["Thanks, I appreciate that. Talking on duty can be punishable by having your mouth stitched up. These are tough people, no mistake."] = "Gracias, lo aprecio. Hablar durante el servicio puede ser castigado con que le cosen la boca. Son personas duras, no hay duda.",
    ["*(If the player has tokens to hand in:)*"] = "*(Si el player tiene fichas para entregar:)*",
    ["Handing in event currency will increase your progress and unlock unique rewards. This will remove all currency from your bags and pouch."] = "Entregar moneda del evento aumentará tu progreso y desbloqueará recompensas únicas. Esto eliminará todo el dinero de sus bolsos y carteras.",
    ["Do you wish to continue?"] = "¿Quieres continuar?",
    ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
    ["*(If a cloak is rewarded, repeated for possible multiples:)*"] = "*(Si se recompensa una capa, se repite para posibles múltiplos:)*",
    ["Congratulations, you have unlocked the [cloak] Override in the wardrobe."] = "Felicitaciones, has desbloqueado la anulación [cloak] en el armario.",
    ["*(If the player reaches a new level:)*"] = "*(Si el player alcanza un nuevo nivel:)*",
    ["*(If a mystery box would be rewarded but there is not enough space in backpack for it:)*"] = "*(Si se recompensa una caja misteriosa pero no hay suficiente espacio en backpack para ella:)*",
    ["Please ensure you have at least 2 free spaces in your inventory."] = "Asegúrese de tener al menos 2 espacios libres en su inventario.",
    ["*(Continues with chat, without tokens being handed in.)*"] = "*(Continúa con el chat, sin entrega de tokens.)*",
    ["*(If big event mystery boxes are rewarded:)*"] = "*(Si se recompensan las cajas misteriosas del gran evento:)*",
    ["Congratulations, you received Big event mystery box x [amount]."] = "Felicitaciones, recibió la caja misteriosa del gran evento x [amount].",
    ["*(If event mystery boxes are rewarded:)*"] = "*(Si se recompensan las cajas misteriosas del evento:)*",
    ["Congratulations, you received Event mystery box x [amount]."] = "Felicitaciones, recibió la caja misteriosa del evento x [amount].",
    ["Congratulations, you have levelled up to Level [level]"] = "Felicitaciones, has subido de nivel al nivel [level].",
    ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
    ["Greetings! Allow me to introduce myself. I am Joey the renowned cape designer and this is my cape festival, Rune Capers! I also like Piña Coladas and getting caught in the rain. Gonna be honest though, not really into yoga, it's just not my sort of thing."] = "¡Saludos! Permítanme presentarme. Soy Joey, el renombrado diseñador de capas, y este es mi festival de capas, ¡Rune Capers! También me gustan las piñas coladas y que me pille la lluvia. Pero voy a ser honesto, no me gusta mucho el yoga, simplemente no es mi tipo de cosas.",
    ["Nice to meet you Joey!"] = "¡Encantado de conocerte Joey!",
    ["*(Only after the first time:)*"] = "*(Sólo después de la primera vez:)*",
    ["What can I do for you today?"] = "¿Qué puedo hacer por ti hoy?",
    ["*(Only if not asked last and it's not the first time:)*"] = "*(Solo si no se te preguntó la última vez y no es la primera vez :)*",
    ["Allow me to introduce myself. I am Joey the renowned cape designer and this is my cape festival, Rune Capers! I also like Piña Coladas and getting caught in the rain. Gonna be honest though, not really into yoga, it's just not my sort of thing."] = "Permítanme presentarme. Soy Joey, el renombrado diseñador de capas, y este es mi festival de capas, ¡Rune Capers! También me gustan las piñas coladas y que me pille la lluvia. Pero voy a ser honesto, no me gusta mucho el yoga, simplemente no es mi tipo de cosas.",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["Tell me about the event!"] = "¡Cuéntame sobre el evento!",
    ["It's really simple, I just want you to prove to me that you are worthy of wearing my ostentatious designs! If you want to wear my Cloak of Might design you're gonna have to go out and get you hands dirty, doesn't matter what combat style you're using, just give me the Tokens of Might that you find. Or if you're feeling a bit more passive and want to wear my Cloak of Talents design... head on out and get to skilling! Gathering, artisan, whatever you like, just bring me the Tokens of Talent that you find along the way! Then for the truly dedicated, if you manage to get enough tokens for both of my designs you'll be deemed worthy to wear my finest creation, The Cloak of Proficiency!"] = "Es muy simple, ¡solo quiero que me demuestres que eres digno de lucir mis ostentosos diseños! Si quieres usar mi diseño de Capa de Poder tendrás que salir y ensuciarte las manos, no importa qué estilo de combate estés usando, solo dame las Fichas de Poder que encuentres. O si te sientes un poco más pasivo y quieres usar mi diseño de Capa de Talentos... ¡sal y empieza a desarrollar habilidades! Recolector, artesano, lo que quieras, ¡tráeme las Fichas de Talento que encuentres en el camino! Luego, para los verdaderamente dedicados, si logran obtener suficientes fichas para mis dos diseños, serán considerados dignos de usar mi mejor creación, ¡La Capa de la Competencia!",
    ["What makes your capes so special?"] = "¿Qué hace que tus capas sean tan especiales?",
    ["Did you really just ask that question?! Have you not heard of Joey, King of fashion capes? Winner of the Gielinor Cape Designs of the Year Award four out of the past five years!?"] = "¡¿De verdad acabas de hacer esa pregunta?! ¿No has oído hablar de Joey, el rey de las capas de moda? ¿¡Ganador del premio Gielinor Cape Designs of the Year en cuatro de los últimos cinco años!?",
    ["Only four out of five?"] = "¿Sólo cuatro de cinco?",
    ["Yeah... we don't talk about the Great S Cape fiasco."] = "Sí... no hablamos del fiasco de Great S Cape.",
    ["Take care!"] = "¡Cuídate!",
    ["Well, that was another successful Cape Festival, I hope you enjoyed our Es-cape-ades!"] = "Bueno, ese fue otro Festival del Cabo exitoso. ¡Espero que hayas disfrutado de nuestros Es-cape-ades!",
    ["... Well, I'm going to go on ahead."] = "... Bueno, voy a seguir adelante.",
    ["... Like a hat."] = "... Como un sombrero.",
    ["HAHAHAHAHAHAHAHAHAHAHAHAHA!"] = "¡HAHAHAHAHAHAHAHAHAHAHAHAHA!",
    ["OHOHOHOHOHOHOHOHO!"] = "¡OHOHOHOHOHOHOHOHO!",
    ["Ha...ha...Oh..."] = "Ja... ja... Oh...",
    ["Doug! Write that one down! I have an idea for a new festival!"] = "¡Doug! ¡Escribe eso! ¡Tengo una idea para un nuevo festival!",
    ["Hahaha..."] = "Jajaja...",
    ["You take this opportunity to slowly back away and take your leave."] = "Aprovechas esta oportunidad para retroceder lentamente y despedirte.",
    ["Get it away from me! Don't let it get on my cape!"] = "¡Aléjamelo de mí! ¡No dejes que se manche mi capa!",
    ["Joey, are you o... What happened to your hair!?"] = "Joey, ¿estás... ¿¡Qué le pasó a tu cabello!?",
    ["It was so dark... I never thought I'd get out... I had to eat my cape to survive."] = "Estaba tan oscuro... Nunca pensé que saldría... Tuve que comerme mi capa para sobrevivir.",
    ["You ate your cape? ... How was it?"] = "¿Te comiste tu capa? ... ¿Cómo fue?",
    ["Expensive."] = "Caro.",
    ["Hey Joey!"] = "¡Hola Joey!",
    ["*(After first time:)*"] = "*(Después de la primera vez:)*",
    ["How's it going??"] = "¿Cómo te va?",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["I'm having hair troubles! That's what's going on!"] = "¡Tengo problemas con el cabello! ¡Eso es lo que está pasando!",
    ["Sorry Joey, I meant what's going on with the event?"] = "Lo siento Joey, quise decir ¿qué está pasando con el evento?",
    ["Don't worry about it."] = "No te preocupes por eso.",
    ["I've decided to kill two birds with one stone and win this competition by concocting a potion which will bring back my luscious locks."] = "He decidido matar dos pájaros de un tiro y ganar este concurso preparando una poción que me devolverá mis deliciosos mechones.",
    ["Is this potion safe?"] = "¿Es segura esta poción?",
    ["You'll be the one making it so that's up to you."] = "Tú serás quien lo haga, así que eso depende de ti.",
    ["I'm not sure I'm comfortable risking your life over this..."] = "No estoy seguro de sentirme cómodo arriesgando tu vida por esto...",
    ["You'll be able to earn some Herblore XP while you do so!"] = "¡Podrás ganar algo de XP Herblore mientras lo haces!",
    ["I think I can help."] = "Creo que puedo ayudar.",
    ["Why did you enter the Summer Skill Off?"] = "¿Por qué participaste en el Summer Skill Off?",
    ["People just aren't interested in my capes anymore."] = "La gente ya no está interesada en mis capas.",
    ["I think it's time for a change in the business, time to branch out into other outfits!"] = "Creo que es hora de un cambio en el negocio, ¡es hora de expandirse hacia otras marcas!",
    ["But I can't do that without some serious money!"] = "¡Pero no puedo hacer eso sin mucho dinero!",
    ["What sort of of outfits are you thinking of?{{Sic}}"] = "¿En qué tipo de ropa estás pensando?{{Sic}}",
    ["You tell me!"] = "¡Dímelo tú!",
    ["What kind of outfits would you like to see?"] = "¿Qué tipo de outfits te gustaría ver?",
    ["Regular clothes."] = "Ropa normal.",
    ["Light or leather armour."] = "Armadura ligera o de cuero.",
    ["Robes and magical gear."] = "Túnicas y equipo mágico.",
    ["Goofy armour."] = "Armadura tonta.",
    ["Heavy and bulky armour."] = "Armadura pesada y voluminosa.",
    ["That's a great idea, I'll keep that in mind when I'm designing my next outfit!"] = "¡Es una gran idea, la tendré en cuenta cuando diseñe mi próximo conjunto!",
    ["Thanks Joey!"] = "¡Gracias Joey!",
    ["Question?"] = "¿Pregunta?",
    ["Can I ask you an important question?"] = "¿Puedo hacerte una pregunta importante?",
    ["Of course!"] = "¡Por supuesto!",
    ["What happened down that well?"] = "¿Qué pasó en ese pozo?",
    ["It was horrible..."] = "Fue horrible...",
    ["Horrors you can't even imagine..."] = "Horrores que ni siquiera puedes imaginar...",
    ["I still hear the 'Gloop gloop gloop' every night..."] = "Todavía escucho el 'Gloop gloop gloop' todas las noches...",
    ["Hope to hear from you again soon!"] = "¡Espero volver a tener noticias tuyas pronto!",
    ["What did you say about my hair!?"] = "¿¡Qué dijiste sobre mi cabello!?",
    ["You slink away from the angry man."] = "Te alejas del hombre enojado.",
    ["Hi Player..."] = "Hola Player...",
    ["While he wasn't the winner of the Summer Skill Off, he certainly was the baldest."] = "Si bien no fue el ganador del Summer Skill Off, ciertamente fue el más calvo.",
    ["Welcome back..."] = "Bienvenido de nuevo...",
    ["What do I need to do here?"] = "¿Qué necesito hacer aquí?",
    ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
    ["Well... I guess you just have to toss stuff into the cauldron and hope it brings my hair back."] = "Bueno... Supongo que solo tienes que tirar cosas al caldero y esperar que me devuelva el cabello.",
    ["Using the cauldron Joey is at will grant increased XP while skilling at this location!"] = "¡Usar el caldero en el que se encuentra Joey otorgará más XP mientras practicas en esta ubicación!",
    ["I'll do my best to get your hair back Joey!"] = "¡Haré todo lo posible para recuperar tu cabello Joey!",
    ["Thank you."] = "Gracias.",
    ["Why did you enter the Winter Chill Off?"] = "¿Por qué participaste en el Winter Chill Off?",
    ["What brings you back to the Chill Off?"] = "¿Qué te trae de vuelta al Chill Off?",
    ["What if I never get my hair back?"] = "¿Qué pasa si nunca recupero mi cabello?",
    ["It's not so bad, just think of all the money you will save on shampoo!"] = "No es tan malo, ¡solo piensa en todo el dinero que ahorrarás en champú!",
    ["I guess..."] = "Supongo...",
    ["Why do you need your hair back so badly?"] = "¿Por qué necesitas tanto recuperar tu cabello?",
    ["I'm just not good enough without it..."] = "Simplemente no soy lo suficientemente bueno sin él...",
    ["Joey, you're a wonderful person, don't let anyone make you think otherwise."] = "Joey, eres una persona maravillosa, no dejes que nadie te haga pensar lo contrario.",
    ["It's not about the hair on your head, it's about the hair in your heart."] = "No se trata del pelo de tu cabeza, se trata del pelo de tu corazón.",
    ["And you have the hairiest heart I've ever seen."] = "Y tienes el corazón más peludo que he visto en mi vida.",
    ["That may be the strangest thing I've ever said."] = "Eso puede ser lo más extraño que he dicho en mi vida.",
    ["Who's winning?"] = "¿Quién está ganando?",
    ["Joey appears to be in a daze."] = "Joey parece estar aturdido.",
    ["Joey, I think you might be the second best fashion designes on Gielinor."] = "Joey, creo que podrías ser el segundo mejor diseño de moda en Gielinor.",
    ["The second best fashion designer..."] = "El segundo mejor diseñador de moda...",
    ["Second best..."] = "Segundo mejor...",
    ["He's not responding."] = "Él no responde.",
    ["Oh Joey, if only you had hair like mine, then maybe you wouldn't just be the second best fashion designer!"] = "¡Oh, Joey, si tan solo tuvieras el cabello como el mío, entonces tal vez no serías el segundo mejor diseñador de moda!",
    ["Bloomin' bananas!"] = "¡Plátanos florecientes!",
    ["Don't bother with him, he's only the second best fashion designer!"] = "¡No te molestes con él, es solo el segundo mejor diseñador de moda!",
    ["Hahaha!"] = "¡Jajaja!",
    ["Hehehe!"] = "¡Jejeje!",
    ["Hohoho!"] = "¡Hohoho!",
    ["What a loser!"] = "¡Qué perdedor!",
    ["Hm..."] = "Mmm...",
    ["Maybe you should leave him be for now."] = "Quizás deberías dejarlo en paz por ahora.",
    ["Goodbye!"] = "¡Adiós!",
    ["Bye..."] = "Adiós...",
    ["Hello there. Would you like to see the goods I have for sale?"] = "Hola. ¿Quieres ver los productos que tengo a la venta?",
    ["Yes please, Jofridr"] = "Si por favor, Jofridr",
    ["Yes please, Jofridr."] = "Sí, por favor, Jofridr.",
    ["No thank you, Jofridr"] = "No, gracias Jofridr.",
    ["No thank you, Jofridr."] = "No, gracias, Jofridr.",
    ["Fair thee well."] = "Que te vaya bien.",
    ["Why do you have so much wool in your store?"] = "¿Por qué tienes tanta lana en tu tienda?",
    ["Why do you have so much wool in your store? I haven't seen any sheep anywhere."] = "¿Por qué tienes tanta lana en tu tienda? No he visto ninguna oveja por ningún lado.",
    ["Ah, I have contacts on the mainland. I have a sailor friend who brings me crates of wool on a regular basis."] = "Ah, tengo contactos en el continente. Tengo un amigo marinero que me trae cajas de lana con regularidad.",
    ["What do you trade for it?"] = "¿Qué cambias por él?",
    ["Rope of course! What else can we sell? Fish would go off before it got so far south."] = "¡Cuerda, por supuesto! ¿Qué más podemos vender? Los peces se lanzarían antes de llegar tan al sur.",
    ["Where does all this rope go?"] = "¿A dónde va toda esta cuerda?",
    ["Err, I don't remember the name of the place very well. Dreinna? Drennor? Something like that."] = "Err, no recuerdo muy bien el nombre del lugar. ¿Dreinna? ¿Drennor? Algo así.",
    ["That's very interesting. Thanks Jofridr."] = "Eso es muy interesante. Gracias Jofridr.",
    ["What kind of organisation is this?"] = "¿Qué tipo de organización es esta?",
    ["We're a proactive organisation working towards the cessation of monsters in normal civilised human society. There seems to be no backbone in this land so we're stepping up to the challenge."] = "Somos una organización proactiva que trabaja para el cese de los monstruos en la sociedad humana civilizada normal. Parece que no hay columna vertebral en esta tierra, por lo que estamos asumiendo el desafío.",
    ["Hmm, how do you propose to do that? I mean, I see people every day killing goblins around here!"] = "Hmm, ¿cómo propones hacer eso? Quiero decir, ¡veo gente todos los días matando duendes por aquí!",
    ["We're mobilising people and we're starting our own society...cleaning out the caves once inhabited by these foul creatures and defending them so that they can never again shelter sub-human species."] = "Estamos movilizando gente y estamos iniciando nuestra propia sociedad... limpiando las cuevas que alguna vez estuvieron habitadas por estas repugnantes criaturas y defendiéndolas para que nunca más puedan albergar especies subhumanas.",
    ["That sounds kind of strange, but, hey, it's your choice."] = "Eso suena un poco extraño, pero bueno, es tu elección.",
    ["Who are you and what do you do here?"] = "¿Quién eres y qué haces aquí?",
    ["My name is Johanhus and I lead these glorious people on a courageous mission called 'Humans Against Monsters'. We mean to make this land free of monsters, so that we can all live in peace."] = "Mi nombre es Johanhus y dirijo a estas gloriosas personas en una valiente misión llamada 'Humanos contra monstruos'. Queremos hacer que esta tierra esté libre de monstruos, para que todos podamos vivir en paz.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["Sad news, brother. Sigmund’s group has been destroyed by a goblin attack."] = "Triste noticia, hermano. El grupo de Sigmund ha sido destruido por un ataque de duendes.",
    ["This just goes to show the danger of taking action directly… All that Sigmund’s attacks achieved was getting some good humans killed."] = "Esto sólo sirve para mostrar el peligro de tomar medidas directamente... Todo lo que lograron los ataques de Sigmund fue matar a algunos buenos humanos.",
    ["Besides, the cave goblins aren’t much of a threat. They may not be human, but they’re no worse than the dwarves or gnomes. From now on, we’ll leave them alone, and focus on occupying caves and lobbying the government."] = "Además, los duendes de las cavernas no son una gran amenaza. Puede que no sean humanos, pero no son peores que los enanos o los gnomos. De ahora en adelante, los dejaremos en paz y nos concentraremos en ocupar cuevas y presionar al gobierno.",
    ["Barrel making is just the thing for all you smithies."] = "La fabricación de barriles es ideal para todos los herreros.",
    ["Do you have the stomach for our race course?"] = "¿Tienes estómago para nuestro circuito de carreras?",
    ["Join our dancers and learn some new moves."] = "Únete a nuestros bailarines y aprende algunos movimientos nuevos.",
    ["NovtumberFest is open! It is time for revelry and sausages!"] = "¡NovtumberFest está abierto! ¡Es hora de juerga y salchichas!",
    ["Practice your glass blowing by making steins."] = "Practica cómo soplar vidrio haciendo jarras.",
    ["Take part in the Bar Crawl to earn prismatic lamps."] = "Participa en el Bar Crawl para ganar lámparas prismáticas.",
    ["Talk to me if you haven't yet got your Bar Crawl card."] = "Habla conmigo si aún no tienes tu tarjeta Bar Crawl.",
    ["Test your aim at the Archery Targets."] = "Pon a prueba tu puntería en los objetivos de tiro con arco.",
    ["Try hopping into an open portal for instant travel."] = "Intente ingresar a un portal abierto para viajar instantáneamente.",
    ["Welcome to NovtumberFest!"] = "¡Bienvenido a NovtumberFest!",
    ["You are missing a Bar Crawl card. Would you like a new one?"] = "Te falta una tarjeta de rastreo de bares. ¿Quieres uno nuevo?",
    ["A bar crawl card has been added to your inventory."] = "Se ha agregado una tarjeta de rastreo de bares a su inventario.",
    ["You do not have any space for a bar crawl card at the moment."] = "No tienes espacio para una tarjeta de rastreo de bares en este momento.",
    ["Hello there, I'm Johanna, head of this merry rabble of people who have come to celebrate NovtumberFest!"] = "Hola, soy Johanna, jefe de esta alegre chusma de personas que han venido a celebrar NovtumberFest.",
    ["What is NovtumberFest?"] = "¿Qué es NovtumberFest?",
    ["It's a celebration! A chance for people to come together and just relax and have a good time."] = "¡Es una celebración! Una oportunidad para que la gente se reúna, se relaje y pase un buen rato.",
    ["So it's a place to talk and unwind?"] = "Entonces, ¿es un lugar para hablar y relajarse?",
    ["Well, we know that's not everyone's idea of fun, so we've added a few games and such for you to try while you are here."] = "Bueno, sabemos que esa no es la idea de diversión que todos tienen, por eso hemos agregado algunos juegos y cosas así para que los pruebes mientras estás aquí.",
    ["There are all sorts of things for you to try your hand at."] = "Hay todo tipo de cosas que puedes probar.",
    ["Just roll up to an activity and give it a go!"] = "¡Simplemente acércate a una actividad y pruébala!",
    ["How long will you be here for?"] = "¿Cuánto tiempo estarás aquí?",
    ["We're going to be here for about 4 weeks, so plenty of time to have a go at everything."] = "Estaremos aquí aproximadamente 4 semanas, así que tendremos tiempo de sobra para probarlo todo.",
    ["What is there to do at NovtumberFest?"] = "¿Qué se puede hacer en NovtumberFest?",
    ["Roaming events."] = "Eventos itinerantes.",
    ["We've sent out our cart to travel around Gielinor to spread word of our little get-together."] = "Hemos enviado nuestro carrito para viajar por Gielinor para difundir nuestra pequeña reunión.",
    ["However, the driver is known to get into the occasional spot of trouble."] = "Sin embargo, se sabe que el conductor se mete en problemas ocasionales.",
    ["If you see him out and about could you check on him and make sure he's safe?"] = "Si lo ves por ahí, ¿podrías controlarlo y asegurarte de que está a salvo?",
    ["And if he's not, help him out of whatever trouble he's got in to."] = "Y si no es así, ayúdalo a salir de cualquier problema en el que se haya metido.",
    ["So you want me to take care of him?"] = "¿Entonces quieres que lo cuide?",
    ["Oh, he's not that bad, but he does sometimes need a nudge in the right direction."] = "Oh, no es tan malo, pero a veces necesita un empujón en la dirección correcta.",
    ["He's always generous to those who help him out, though."] = "Sin embargo, siempre es generoso con quienes lo ayudan.",
    ["Cooking sausages."] = "Salchichas Cooking.",
    ["The perfect thing to go with a cold drink is a nice meaty sausage."] = "Lo perfecto para acompañar una bebida fría es una rica salchicha con carne.",
    ["We have only the best sausages at NovtumberFest. Jakob is very particular."] = "Solo tenemos las mejores salchichas en NovtumberFest. Jakob es muy particular.",
    ["Have a go at cooking some for yourself on the grills."] = "Intenta cocinar algo tú mismo en las parrillas.",
    ["Just follow your nose and you'll find your way there."] = "Simplemente sigue tu olfato y encontrarás el camino hasta allí.",
    ["A little more intensive this one."] = "Este es un poco más intensivo.",
    ["You too can experience what it is like to be a bar person on a very, very busy shift."] = "Tú también puedes experimentar lo que es ser un bar en un turno muy, muy ocupado.",
    ["Try to serve all of the customers that you can and get rewarded for your hard work."] = "Intente atender a todos los clientes que pueda y obtenga recompensas por su arduo trabajo.",
    ["I'll warn you - it won't be easy, but it should be fun."] = "Te lo advierto: no será fácil, pero debería ser divertido.",
    ["More."] = "Más.",
    ["Archery targets."] = "Dianas de tiro con arco.",
    ["Test your aim! Nice and simple this one."] = "¡Pon a prueba tu puntería! Bonito y sencillo este.",
    ["Just pick your target and fire away at it with arrows."] = "Simplemente elige tu objetivo y dispárale con flechas.",
    ["Just imagine the target is someone you don't like - always cheers me up no end."] = "Imagínate que el objetivo es alguien que no te agrada; siempre me alegra muchísimo.",
    ["NovtumberFest racing."] = "Carreras del NovtumberFest.",
    ["A lovely little racetrack inside our freezer-tent."] = "Una pequeña y encantadora pista de carreras dentro de nuestra tienda congeladora.",
    ["It's a bit slippery, but that makes it all the more fun."] = "Es un poco resbaladizo, pero eso lo hace aún más divertido.",
    ["Just try to stay up on your feet!"] = "¡Intenta mantenerte de pie!",
    ["Gathering hops."] = "Recogiendo lúpulo.",
    ["To keep the drink flowing we need a good supply of hops."] = "Para que la bebida siga fluyendo necesitamos un buen suministro de lúpulo.",
    ["You should be able to find lots of hops growing around the crater."] = "Deberías poder encontrar muchos lúpulos creciendo alrededor del cráter.",
    ["If you want to help you can harvest some and then deposit them in the hops crate, over by the glassblowing area."] = "Si quieres ayudar, puedes cosechar un poco y luego depositarlos en la caja de lúpulo, junto al área de soplado de vidrio.",
    ["Crafting steins."] = "Jarras Crafting.",
    ["Moritz is our man in charge of keeping our supply of steins up for our drinks."] = "Moritz es nuestro hombre a cargo de mantener nuestro suministro de jarras para nuestras bebidas.",
    ["A remarkable amount of them get broken during the festivities."] = "Una cantidad notable de ellos se rompen durante las festividades.",
    ["If you head over to the furnace he'll set you up with the equipment you need."] = "Si te diriges al horno, él te proporcionará el equipo que necesitas.",
    ["Making barrels."] = "Fabricación de barriles.",
    ["We can never have too many barrels. We always keep losing some."] = "Nunca podemos tener demasiados barriles. Siempre seguimos perdiendo algo.",
    ["I know the driver keeps taking some out and about round Gielinor, but he never seems to return with a full cart-full."] = "Sé que el conductor sigue sacando algo alrededor de Gielinor, pero parece que nunca regresa con el carrito lleno.",
    ["If you want to help out with making us more go talk to Lukas by his workbench."] = "Si quieres ayudarnos a hacer más, habla con Lukas junto a su mesa de trabajo.",
    ["Deedit's wolpertinger experiment."] = "El experimento Wolpertinger de Deedit.",
    ["Ah, yes. The wizard. He came to us and asked if we would mind helping him out."] = "Ah, sí. El mago. Vino a nosotros y nos preguntó si nos importaría ayudarlo.",
    ["I didn't expect it to cause such a big disturbance though."] = "Sin embargo, no esperaba que causara tal alboroto.",
    ["Oh well, he seems to be keeping things under control, just about."] = "Oh, bueno, parece estar manteniendo las cosas bajo control, más o menos.",
    ["Probably best to go talk to Wizard Deedit yourself for more information on the experiment though."] = "Probablemente sea mejor hablar con Wizard Deedit usted mismo para obtener más información sobre el experimento.",
    ["Dancing."] = "Bailando.",
    ["There is no more lovely a way to display your joy at the world around you than with a dance."] = "No hay manera más hermosa de mostrar tu alegría al mundo que te rodea que con un baile.",
    ["Join Mila and Elias on the tables and show everyone how happy you are."] = "Únete a Mila y Elias en las mesas y muestra a todos lo feliz que eres.",
    ["Carousel."] = "Carrusel.",
    ["The centrepiece of our little celebration."] = "La pieza central de nuestra pequeña celebración.",
    ["Isn't it delightful? I could just watch it go round and round for hours."] = "¿No es delicioso? Podría verlo girar y girar durante horas.",
    ["Hop on and give it a whirl, it is so much fun."] = "Súbete y pruébalo, es muy divertido.",
    ["Bar Crawl."] = "Rastreo de bares.",
    ["Linus' shop."] = "Tienda Linus.",
    ["The lovely Linus. He's the person to go for any cosmetics you might be looking for."] = "La encantadora Linus. Es la persona indicada para cualquier cosmético que estés buscando.",
    ["All of the cosmetics for sale in Linus' shop are also available as drops from doing the activities."] = "Todos los cosméticos a la venta en la tienda de Linus también están disponibles como obsequios al realizar las actividades.",
    ["Portals."] = "Portales.",
    ["Portals seem to be all the rage at these kinds of gatherings, so we made sure that we had some too."] = "Los portales parecen estar de moda en este tipo de reuniones, así que nos aseguramos de tener algunos también.",
    ["They're really handy for zipping around the world."] = "Son muy útiles para viajar por el mundo.",
    ["Leni will be able to keep you up to date with which portals are active."] = "Leni podrá mantenerlo actualizado sobre qué portales están activos.",
    ["Of course, they light up when they can be used, so you could just look out for the lights."] = "Por supuesto, se iluminan cuando se pueden usar, así que puedes simplemente estar atento a las luces.",
    ["Ask about something else."] = "Pregunta por otra cosa.",
    ["Tell me about the bar crawl."] = "Cuéntame sobre el recorrido por los bares.",
    ["We've set up a little bar crawl around the world to help celebrate this NovtumberFest."] = "Hemos organizado un pequeño recorrido por bares por todo el mundo para ayudar a celebrar este NovtumberFest.",
    ["I can give you a card with a list of bars on and what drink to purchase at each."] = "Puedo darte una tarjeta con una lista de bares y qué bebida comprar en cada uno.",
    ["There are 18 different tasks to complete. One will be unlocked for each of the first 18 days of NovtumberFest."] = "Hay 18 tareas diferentes para completar. Se desbloqueará uno para cada uno de los primeros 18 días de NovtumberFest.",
    ["This leaves you with the remaining time to collect all of the drinks on your card."] = "Esto te deja el tiempo restante para recoger todas las bebidas de tu tarjeta.",
    ["Ok, that makes sense. What do I get for doing the tasks?"] = "Ok, eso tiene sentido. ¿Qué obtengo por realizar las tareas?",
    ["You will get a lamp for completing each task, and then two lamps for completing the entire card."] = "Recibirás una lámpara por completar cada tarea y luego dos lámparas por completar la tarjeta completa.",
    ["There are two different cards. One is the standard card, and then we have an advanced version."] = "Hay dos cartas diferentes. Una es la tarjeta estándar y luego tenemos una versión avanzada.",
    ["The standard card only covers bars that are in the F2P world. The rewards for this are small lamps for each task and two medium lamps on card completion."] = "La tarjeta estándar solo cubre bares que están en el mundo F2P. La recompensa por esto son lámparas pequeñas por cada tarea y dos lámparas medianas al completar la tarjeta.",
    ["The advanced card covers members-only bars and some of those will require certain quests to be completed. The rewards for this card are small lamps for each task and two large lamps on card completion."] = "La tarjeta avanzada cubre barras exclusivas para miembros y algunas de ellas requerirán que se completen ciertas misiones. Las recompensas por esta tarjeta son lámparas pequeñas por cada tarea y dos lámparas grandes al completar la tarjeta.",
    ["Once you choose which card you would like you will NOT be able to change your mind."] = "Una vez que elijas qué tarjeta quieres, NO podrás cambiar de opinión.",
    ["As long as you complete the card before NovtumberFest finishes it doesn't matter when you start your card."] = "Siempre que complete la tarjeta antes de que finalice NovtumberFest, no importa cuándo comience su tarjeta.",
    ["You can wait until all of the tasks are revealed before choosing which type of card to take."] = "Puedes esperar hasta que se revelen todas las tareas antes de elegir qué tipo de tarjeta tomar.",
    ["What kind of card would you like?"] = "¿Qué tipo de tarjeta te gustaría?",
    ["Standard."] = "Estándar.",
    ["Advanced."] = "Avanzado.",
    ["An advanced bar crawl card has been added to your inventory."] = "Se ha agregado una tarjeta de rastreo de bares avanzado a su inventario.",
    ["I'll make my mind up later."] = "Me decidiré más tarde.",
    ["Now you have your bar crawl card a different task will be unlocked each day.{{Sic}}"] = "Ahora que tienes tu tarjeta de rastreo de bares, se desbloqueará una tarea diferente cada día.{{Sic}}",
    ["You have from the day that is is unlocked until the end of NovtumberFest to complete the task."] = "Tienes desde el día en que se desbloquea hasta el final de NovtumberFest para completar la tarea.",
    ["This will give you an XP lamp per task completed."] = "Esto te dará una lámpara de XP por cada tarea completada.",
    ["This means you can wait until all tasks are unlocked before starting your crawl, and do it all in one go."] = "Esto significa que puedes esperar hasta que todas las tareas estén desbloqueadas antes de comenzar a rastrear y hacerlo todo de una vez.",
    ["You must complete the task before the end of the NovtumberFest though!"] = "¡Debes completar la tarea antes de que finalice el NovtumberFest!",
    ["If you complete the whole card you will receive an addition two XP lamps as reward."] = "Si completas la tarjeta completa, recibirás dos lámparas XP adicionales como recompensa.",
    ["Well done on completing the bar crawl. May all of your future journeys around Gielinor be as fun!"] = "Enhorabuena por completar el rastreo de bares. ¡Que todos tus viajes futuros por Gielinor sean igual de divertidos!",
    ["To your health!"] = "¡A tu salud!",
    ["You need to complete one task on the bar crawl."] = "Debes completar una tarea en el rastreo de barras.",
    ["You need to throw some sausages on the grills."] = "Hay que echar unas salchichas a las parrillas.",
    ["You need to craft a stein."] = "Necesitas elaborar una jarra.",
    ["You need to help create barrels for the festival."] = "Necesitas ayudar a crear barriles para el festival.",
    ["You need to take part in a round of kegger."] = "Necesitas participar en una ronda de barril.",
    ["You need to take your shot over at the Archery area."] = "Debes disparar en el área de tiro con arco.",
    ["You need to gather some hops from around the crater."] = "Necesitas recolectar algunos saltos alrededor del cráter.",
    ["You need to help Wizard Deedit with his wolpertinger issues."] = "Necesitas ayudar a Wizard Deedit con sus problemas con el wolpertinger.",
    ["You need to talk to Jakob, who is manning the cooking grills."] = "Debes hablar con Jakob, quien se encarga de las parrillas.",
    ["You need to talk to Friedrich, over by the Archery area."] = "Necesitas hablar con Friedrich, cerca del área de tiro con arco.",
    ["You need to talk to Klara, stood by the portal for the racing arena."] = "Necesitas hablar con Klara, que se encuentra junto al portal del campo de carreras.",
    ["You need to talk to Marta, probably next to one of the crops of hops around the crater."] = "Necesitas hablar con Marta, probablemente al lado de uno de los cultivos de lúpulo alrededor del cráter.",
    ["You need to talk to Moritz, follow the smell of molten glass to the stein making area."] = "Necesitas hablar con Moritz, sigue el olor a vidrio fundido hasta el área de fabricación de jarras.",
    ["You need to talk to Lukas, he'll be busy making barrels."] = "Necesitas hablar con Lukas, estará ocupado fabricando barriles.",
    ["You need to talk to Elias, one of our spectacular dancers."] = "Necesitas hablar con Elias, uno de nuestros espectaculares bailarines.",
    ["You need to talk to Mila, one of our spectacular dancers."] = "Necesitas hablar con Mila, uno de nuestros espectaculares bailarines.",
    ["You need to talk to Jonas, the host of the kegger area."] = "Necesitas hablar con Jonas, el anfitrión del área de barriles.",
    ["You need to talk to Linus, the resident vendor for NovtumberFest."] = "Debes hablar con Linus, el proveedor residente de NovtumberFest.",
    ["You need to talk to Leni, who will be keeping the portals in check."] = "Debes hablar con Leni, quien mantendrá los portales bajo control.",
    ["You have already unlocked the NovtumberFest title."] = "Ya has desbloqueado el título NovtumberFest.",
    ["Where did it come from?"] = "¿De dónde vino?",
    ["I hear it came from the well. Hey, that's a cute dog! Does he have a name?"] = "He oído que vino del pozo. ¡Oye, qué lindo perro! ¿Tiene un nombre?",
    ["... Okay."] = "... Está bien.",
    ["<nowiki>*</nowiki>Dog is barking beside the well<nowiki>*</nowiki>"] = "<nowiki>*</nowiki>El perro ladra junto al pozo<nowiki>*</nowiki>",
    ["What's that boy? Joey fell down the well!?"] = "¿Qué es ese chico? ¿¡Joey se cayó al pozo!?",
    ["... How on Gielinor did that happen?"] = "... ¿Cómo fue que Gielinor sucedió eso?",
    ["He probably lost his glasses. And without them he just didn't see well."] = "Probablemente perdió sus gafas. Y sin ellos simplemente no veía bien.",
    ["Dog. Stay."] = "Perro. Permanecer.",
    ["Well, that's it over."] = "Bueno, se acabó.",
    ["It sure is!"] = "¡Seguro que lo es!",
    ["John looks down to Dog"] = "John mira hacia abajo a Perro",
    ["It's okay. Let's go home."] = "Está bien. Vámonos a casa.",
    ["Dog barks happily"] = "perro ladra alegremente",
    ["*When speaking to John Wyrd in Draynor Village.*"] = "*Al hablar con John Wyrd en Draynor Village.*",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["Practicing my form. I'm having trouble gathering memories and Orla said this might help."] = "Practicando mi forma. Tengo problemas para reunir recuerdos y Orla dijo que esto podría ayudar.",
    ["I see."] = "Ya veo.",
    ["If you're new to divination you should speak to Orla. I still have a lot to learn."] = "Si eres nuevo en la adivinación, deberías hablar con Orla. Todavía tengo mucho que aprender.",
    ["I am so very tired... Leave me be... to rest..."] = "Estoy muy cansada... Déjame en paz... para descansar...",
    ["Hello again. My family now considers you a hero."] = "Hola de nuevo. Mi familia ahora te considera un héroe.",
    ["Your father tells me you can improve these gauntlets for me..."] = "Tu padre me dice que puedes mejorar estos guanteletes para mí...",
    ["And right he is at that. Although my skill with Death Rune magiks was not great enough to defeat Chronozon, I am adequately skilled at Chaos Rune magiks. If you give me your gauntlets I will bestow upon them some of my power, and make any bolt spells you wish to cast more effective."] = "Y tiene razón en eso. Aunque mi habilidad con las magias de las Runas de la Muerte no fue lo suficientemente grande como para derrotar a Chronozon, tengo habilidades adecuadas con las magias de las Runas del Caos. Si me das tus guanteletes, les otorgaré parte de mi poder y haré que cualquier hechizo de rayo que desees lanzar sea más efectivo.",
    ["That sounds good to me."] = "Eso me suena bien.",
    ["That sounds good to me!"] = "¡Eso me parece bien!",
    ["Johnathon takes your gauntlets from you, and begins a low chant over them. You see them begin to glow and sparkle, before he returns them to you."] = "Johnathon te quita los guanteletes y comienza un canto bajo sobre ellos. Los ves comenzar a brillar y brillar, antes de que él te los devuelva.",
    ["I shall see what options your brothers can offer me first."] = "Primero veré qué opciones pueden ofrecerme tus hermanos.",
    ["I think I'll check my other options with your brothers before committing myself."] = "Creo que comprobaré mis otras opciones con tus hermanos antes de comprometerme.",
    ["I doubt they will offer anything as useful as my magical boost, but as you wish."] = "Dudo que ofrezcan algo tan útil como mi impulso mágico, pero como desees.",
    ["Maybe because… I am."] = "Quizás porque… lo soy.",
    ["Yes well... Is there anything I can help you with?"] = "Sí, bueno... ¿Hay algo en lo que pueda ayudarte?",
    ["Can you change my gauntlets for me?"] = "¿Puedes cambiar mis guanteletes por mí?",
    ["Can you change my gauntlets for me? {{anchor|change-gauntlets}}"] = "¿Puedes cambiarme los guanteletes? {{anchor|change-gauntlets}}",
    ["*(If the player has no gauntlets:)*"] = "*(Si el player no tiene guanteletes:)*",
    ["You don't have any gauntlets I can imbue."] = "No tienes ningún guantelete que pueda imbuirte.",
    ["*(If the player currently has chaos gauntlets in inventory:)*"] = "*(Si el player actualmente tiene guanteletes del caos en su inventario:)*",
    ["Your gauntlets are already imbued with my powers. You don't have any gauntlets I can imbue."] = "Tus guanteletes ya están imbuidos de mis poderes. No tienes ningún guantelete que pueda imbuirte.",
    ["*(If the player has the gauntlets:)*"] = "*(Si el player tiene los guanteletes:)*",
    ["Yes certainly, though it will cost you 25,000 coins?"] = "Sí, claro, aunque te costará 25.000 coins.",
    ["Great thanks!"] = "¡Muchas gracias!",
    ["*(If the player has at least 25,000 coins:)*"] = "*(Si el player tiene al menos 25,000 coins:)*",
    ["Your gauntlets are already imbued with my powers."] = "Tus guanteletes ya están imbuidos de mis poderes.",
    ["*(If the player has less than 25,000 coins:)*"] = "*(Si el player tiene menos de 25,000 coins:)*",
    ["Unfortunately you don't have enough coins on you, come back with 25,000 and I'll change those gauntlets for you."] = "Desafortunadamente no tienes suficiente coins contigo, regresa con 25,000 y te cambiaré esos guanteletes.",
    ["No that's ok thanks."] = "No, está bien, gracias.",
    ["*(After having the family gauntlets enchanted for the first time:)*"] = "*(Después de encantar los guanteletes familiares por primera vez :)*",
    ["Does your family own any more gauntlets?"] = "¿Tu familia posee más guanteletes?",
    ["Does your family own any more gauntlets? I really appreciate the skill and effort you and your brothers have put into those gauntlets, and to prove it, I would like to own one of each pair."] = "¿Tu familia posee más guanteletes? Realmente aprecio la habilidad y el esfuerzo que tú y tus hermanos habéis puesto en esos guanteletes y, para demostrarlo, me gustaría tener uno de cada par.",
    ["I own a pair my father gave me, but they are a family heirloom and I’m not supposed to part with them. However if my dad saw fit to give you his, I could be convinced."] = "Tengo un par que me regaló mi padre, pero son una reliquia familiar y se supone que no debo separarme de ellos. Sin embargo, si mi padre considerara oportuno darte el suyo, podría convencerme.",
    ["How much would you want for them?"] = "¿Cuánto pedirías por ellos?",
    ["1 million coins."] = "1 millón de coins.",
    ["I would like to buy them for 1 million."] = "Me gustaría comprarlos por 1 millón.",
    ["Are you sure? That's a lot of money!"] = "¿Estás seguro? ¡Eso es mucho dinero!",
    ["Yes!"] = "¡Sí!",
    ["I suppose not."] = "Supongo que no.",
    ["I suppose you had better keep them."] = "Supongo que será mejor que los guardes.",
    ["Thank you!"] = "¡Gracias!",
    ["No thanks."] = "No, gracias.",
    ["Don't bother me."] = "No me molestes.",
    ["You are unusually helpful for an outerlander, [Fremennik name]."] = "Eres inusualmente útil para un extranjero, [Fremennik name].",
    ["Ehm, thanks... I guess."] = "Ehm, gracias... Supongo.",
    ["Welcome to Kegger!"] = "¡Bienvenido a Kegger!",
    ["This is a game of skill. Can you keep up?"] = "Este es un juego de habilidad. ¿Puedes seguir el ritmo?",
    ["All you have to do is click on the taps to send drinks to the customers."] = "Todo lo que tienes que hacer es hacer clic en los grifos para enviar bebidas a los clientes.",
    ["You need to keep &nbsp;{{Sic}}your customers happy. If they get to the line without a drink they are going to get upset."] = "Debes mantener contentos a  {{Sic}}tus clientes. Si llegan a la fila sin beber, se enojarán.",
    ["Look out for faster customers as you get slicker with your serving."] = "Esté atento a los clientes más rápidos a medida que se vuelve más hábil con su servicio.",
    ["Click the entrance sign to Kegger to begin a game."] = "Haga clic en la señal de entrada a Kegger para comenzar un juego.",
    ["Hi, Jones."] = "Hola, Jones.",
    ["Can we hunt the Thalassus again?"] = "¿Podremos volver a cazar el Thalassus?",
    ["Certainly. Let's go!"] = "Por supuesto. ¡Vamos!",
    ["Hold on a second, you can't take your follower with you."] = "Espera un segundo, no puedes llevarte a tu seguidor contigo.",
    ["It doesn't seem so. The Thalassus seems to have fled to another part of the sea; doubt we'll ever see it again. Luckily, no one seems to have realised, so I can keep selling my Miracle Thalassus Protection Cream."] = "No lo parece. El Talaso parece haber huido a otra parte del mar; Dudo que lo volvamos a ver. Por suerte, nadie parece haberse dado cuenta, así que puedo seguir vendiendo mi Crema Protectora Miracle Thalassus.",
    ["Those cast nets sound good!"] = "¡Esas redes suenan bien!",
    ["They are! Which type would you like?"] = "¡Lo son! ¿Qué tipo te gustaría?",
    ["Both, please!"] = "¡Ambos, por favor!",
    ["[Jones hands you the two cast nets.]"] = "[Jones te entrega las dos atarrayas.]",
    ["Use them wisely!"] = "¡Úsalos sabiamente!",
    ["Small, please!"] = "¡Pequeño, por favor!",
    ["[Jones hands you a small cast net.]"] = "[Jones te entrega una pequeña atarraya.]",
    ["Use it wisely!"] = "¡Úsalo sabiamente!",
    ["Big, please!"] = "¡Grande, por favor!",
    ["[Jones hands you a big cast net.]"] = "[Jones te entrega una gran atarraya.]",
    ["Actually, I changed my mind."] = "En realidad, cambié de opinión.",
    ["You said something about deposit boxes?"] = "¿Dijiste algo sobre las cajas de depósito?",
    ["Yes, they're all around the coastline. There's one near Eagles' Peak; in Tirannwn; down at Ape Atoll; near Brimhaven; a couple around the settlements in the Kharidian Desert; on Harmony Island; and along the River Salve."] = "Sí, están por toda la costa. Hay uno cerca de Eagles' Peak; en Tirannwn; abajo en Ape Atoll; cerca de Brimhaven; una pareja por los asentamientos en Kharidian Desert; en la isla Armonía; y a lo largo del río Salve.",
    ["You seem to get around a bit?"] = "¿Parece que te mueves un poco?",
    ["Around the coastlines I do. There's some good fishing to be done around the world."] = "Alrededor de las costas lo hago. Hay buena pesca que hacer en todo el mundo.",
    ["What's your cousin's real name?"] = "¿Cuál es el verdadero nombre de tu prima?",
    ["You mean what's 'The Guns' really called?"] = "¿Te refieres a cómo se llama realmente 'The Guns'?",
    ["Yeah, he wouldn't tell me."] = "Sí, no me lo dijo.",
    ["Listen closely; it's..."] = "Escuche atentamente; es...",
    ["Julian."] = "Julián.",
    ["Interesting..."] = "Interesante...",
    ["Actually, nothing."] = "En realidad, nada.",
    ["Fair enough!"] = "¡Es justo!",
    ["Jonny the beard is not interested in talking."] = "Jonny the beard no está interesado en hablar.",
    ["I'd give my left arm to join your band."] = "Daría mi brazo izquierdo por unirme a tu banda.",
    ["Pong, he's back again."] = "Pong, ha vuelto.",
    ["Tell him we don't want groupies."] = "Dile que no queremos groupies.",
    ["I just want to be Jonny the Bard! <br>I play a mean flute!"] = "¡Solo quiero ser Jonny el Bardo! <br>I ¡toco una flauta mala!",
    ["My dreams of being Jonny the Bard are over. <br> You can't play a flute wit' one arm."] = "Mis sueños de ser Jonny el Bardo se acabaron. <br> No puedes tocar la flauta con un solo brazo.",
    ["Jonny the Bard?"] = "¿Jonny el Bardo?",
    ["All my life - and zombie life - I been dreamin' of playing in taverns."] = "Toda mi vida, y mi vida zombie, he soñado con jugar en tabernas.",
    ["I were gonna play the flute like a demon, I tells ya. <br>Ne'er mind. Back to a life of crime..."] = "Iba a tocar la flauta como un demonio, te lo dije. <br>No importa. De vuelta a una vida de crimen...",
    ["A pox on Katrine and her recruitment process.<br>One of her Black Arm initiates beat me up and stole my arm."] = "Una viruela en Katrine y su proceso de reclutamiento.<br>Uno de sus iniciados de Black Arm me golpeó y robó my arm.",
    ["Why is it that whenever that enchanted key re-appears, you soon come visiting?"] = "¿Por qué cada vez que esa llave encantada reaparece, pronto vienes de visita?",
    ["How's the archaeology going?"] = "¿Cómo va la arqueología?",
    ["Good. I'm looking more into the background of that enchanted key; hopefully, we'll be able to time travel with it again in future."] = "Bien. Estoy investigando más el trasfondo de esa llave encantada; Con suerte, podremos viajar en el tiempo con él nuevamente en el futuro.",
    ["Don't you mean the past?"] = "¿No te refieres al pasado?",
    ["Yes, travel to the past, in our future. I hadn't even considered trying to travel into the future!"] = "Sí, viajar al pasado, a nuestro futuro. ¡Ni siquiera había considerado intentar viajar al futuro!",
    ["Could I have the key back?"] = "¿Me podrían devolver la llave?",
    ["Sure, but it'll cost you! 6,000 coins!"] = "Claro, ¡pero te costará! ¡6.000 coins!",
    ["6,000? Seems fair!"] = "¿6.000? ¡Parece justo!",
    ["Here you go then."] = "Aquí tienes entonces.",
    ["I'm not that interested."] = "No estoy tan interesado.",
    ["I suppose you'll be needing this."] = "Supongo que necesitarás esto.",
    ["The key? But how...what...why?"] = "¿La clave? Pero ¿cómo... qué... por qué?",
    ["I think you should take better care of it in the future."] = "Creo que deberías cuidarlo mejor en el futuro.",
    ["*When speaking to Jorzik at the Blast Furnace in Keldagrim.*"] = "*Al hablar con Jorzik en el Alto Horno en Keldagrim.*",
    ["Do you want to trade?"] = "¿Quieres comerciar?",
    ["The finest smiths from all over Gielinor come here to work, and I buy the fruit of their craft. Armour made from the strongest metals!"] = "Los mejores herreros de todo Gielinor vienen aquí a trabajar y yo compro el fruto de su oficio. ¡Armadura hecha de los metales más fuertes!",
    ["Let's have a look, then."] = "Entonces, echemos un vistazo.",
    ["You just don't appreciate the beauty of fine metalwork."] = "Simplemente no se aprecia la belleza del trabajo en metal fino.",
    ["Yeah? What you want?"] = "¿Sí? ¿Lo que quieras?",
    ["Um... nothing really..."] = "Um... nada realmente...",
    ["Quit bugging me then, [dude/doll]! I got me some fish to catch!"] = "¡Entonces deja de molestarme, [dude/doll]! ¡Tengo algo de pescado para pescar!",
    ["Can I fish here instead of you?"] = "¿Puedo pescar aquí en lugar de ti?",
    ["Nuh uh [dude/doll]. Less talk, more fishing!"] = "No, eh, [dude/doll]. ¡Menos charla, más pesca!",
    ["Do you have any tips for me?"] = "¿Tienes algún consejo para mí?",
    ["[Dude/Doll]! Why should I help you? You like, might beat me! I'm not giving away my secrets like that dude Grampa Jack does!"] = "¡[Dude/Doll]! ¿Por qué debería ayudarte? ¡Si te gusta, podrías vencerme! ¡No voy a revelar mis secretos como lo hace ese tipo, el abuelo Jack!",
    ["Who's Grampa Jack?"] = "¿Quién es el abuelo Jack?",
    ["Who's Grampa Jack [he/she] says! He won this competition four years in a row! He lives in the house just outside the gate."] = "¿Quién es el abuelo Jack [he/she]? ¡Ganó esta competencia cuatro años seguidos! Vive en la casa justo afuera de la puerta.",
    ["Hello again adventurer. What brings you this way?"] = "Hola de nuevo aventurero. ¿Qué te trae por este camino?",
    ["Can I see your wares?"] = "¿Puedo ver tus productos?",
    ["Sure thing! I think you'll agree, my prices are remarkable."] = "¡Claro! Creo que estarás de acuerdo, mis precios son notables.",
    ["Have you found any new prayer books?"] = "¿Has encontrado algún libro de oraciones nuevo?",
    ["cond=If the Blood Runs Deep quest has been completed:"] = "cond=Si la misión Blood Runs Deep se ha completado:",
    ["I think I may have found your uncle."] = "Creo que pude haber encontrado a tu tío.",
    ["Really? Where is he? How is he?"] = "¿En serio? ¿Dónde está? ¿Cómo está él?",
    ["Well, he was being looked after by the mages in Lunar Isle but, when he got better, he wanted to leave, so they had to let him go."] = "Bueno, los magos de Lunar Isle lo estaban cuidando pero, cuando mejoró, quiso irse, así que tuvieron que dejarlo ir.",
    ["He just left? Oh my... Well, now I'll never find him."] = "¿Se acaba de ir? Oh Dios... Bueno, ahora nunca lo encontraré.",
    ["At least we know he's alive and well. I'm sure he'll show up sooner or later."] = "Al menos sabemos que está vivo y bien. Estoy seguro de que aparecerá tarde o temprano.",
    ["Funnily enough I have! I found these [number] books in caskets just the other day! I'll sell one to you for 5000 coins: what do you say?"] = "¡Curiosamente sí! ¡Encontré estos libros [número] en ataúdes el otro día! Te vendo uno por 5000 coins: ¿qué dices?",
    ["Buy a book"] = "comprar un libro",
    ["Here you go!"] = "¡Aquí tienes!",
    ["Don't buy anything"] = "no compres nada",
    ["Okay! Suit yourself."] = "¡Está bien! Haz lo que quieras.",
    ["Nope. Sorry, adventurer, I guess you've found them all! I'll let you know if any new ones show up, though."] = "No. Lo siento, aventurero, ¡supongo que los has encontrado todos! Sin embargo, te avisaré si aparece alguno nuevo.",
    ["As a matter of fact, I did! This book washed up on the beach not so long ago, I recognised it as yours immediately! Here you go!"] = "¡De hecho, lo hice! Este libro apareció en la playa no hace mucho, ¡lo reconocí como tuyo inmediatamente! ¡Aquí tienes!",
    ["*When speaking to Jukat at the Zanaris marketplace.*"] = "*Al hablar con Jukat en el mercado Zanaris.*",
    ["Dragon swords! Here, dragon swords! Straight from Frenaskrae!"] = "¡Espadas de dragón! ¡Aquí, espadas de dragón! ¡Directamente desde Frenaskrae!",
    ["Yes, please."] = "Sí, por favor.",
    ["Yes, please!"] = "¡Sí, por favor!",
    ["No thanks, I'm just browsing."] = "No, gracias, solo estoy navegando.",
    ["I am Julienne. I have been a priestess of Saradomin for several years, and I am here to act as his emissary. I would be happy to help you understand the wisdom of Saradomin, if you have questions. Also, you can declare your allegiance to Saradomin. If you do so, I may have some work for your."] = "Soy Juliana. He sido sacerdotisa de Saradomin durante varios años y estoy aquí para actuar como su emisaria. Estaré encantado de ayudarle a comprender la sabiduría de Saradomin, si tiene preguntas. Además, puedes declarar tu lealtad a Saradomin. Si lo haces, puede que tenga algo de trabajo para ti.",
    ["*Can you tell me about Saradomin?*"] = "*¿Puedes contarme sobre Saradomin?*",
    ["Can you tell me about Saradomin?"] = "¿Puedes hablarme de Saradomin?",
    ["What do you want to know about Sardomin?"] = "¿Qué quieres saber sobre Sardomin?",
    ["*Who is Saradomin?*"] = "*¿Quién es Saradomin?*",
    ["**Player: :** Who is Saradomin?"] = "**Player: :** ¿Quién es Saradomin?",
    ["Saradomin is the great protector - the god of light and order. He is first among the gods. Saradomin has more followers than any other god on Gielinor, and he has returned to protect us from evil and chaos."] = "Saradomin es el gran protector, el dios de la luz y el orden. Es el primero entre los dioses. Saradomin tiene más seguidores que cualquier otro dios en Gielinor y ha regresado para protegernos del mal y el caos.",
    ["*Why should I follow Saradomin?*"] = "*¿Por qué debería seguir a Saradomin?*",
    ["**Player: :** Why should I follow Saradomin?"] = "**Player: :** ¿Por qué debería seguir a Saradomin?",
    ["Saradomin is the guardian of us all. Under his protection, you need never fear chaos or evil. Through the grace of Saradomin, we will all achieve peace and security."] = "Saradomin es el guardián de todos nosotros. Bajo su protección, nunca deberás temer al caos ni al mal. Gracias a Saradomin, todos lograremos la paz y la seguridad.",
    ["*What does Saradomin want?*"] = "*¿Qué quiere Saradomin?*",
    ["**Player: :** What does Saradomin want?"] = "**Player: :** ¿Qué quiere Saradomin?",
    ["Saradomin is the one true god. This is his world, and he will watch over us all. He wants us to be safe. He will banish all other gods, so we can live on his world in peace - and in his glory!"] = "Saradomin es el único dios verdadero. Este es su mundo y él velará por todos nosotros. Él quiere que estemos a salvo. Él desterrará a todos los demás dioses, para que podamos vivir en su mundo en paz... ¡y en su gloria!",
    ["*I want to declare my support for Saradomin!*"] = "*¡Quiero declarar mi apoyo a Saradomin!*",
    ["That’s wonderful! On behalf of Saradomin’s followers, I welcome you. Please, take this banner to show your support. I have a gift for you: a book of stories regarding the gods. Please, read it. Even in the misguided tenets of others, there is something to be learned through comparison. The book is not yet complete, however. When you complete some jobs I will give you more pages."] = "¡Eso es maravilloso! En nombre de los seguidores de Saradomin, les doy la bienvenida. Por favor, lleve este banner para mostrar su apoyo. Tengo un regalo para ti: un libro de historias sobre los dioses. Por favor, léelo. Incluso en los principios equivocados de otros, hay algo que aprender a través de la comparación. Sin embargo, el libro aún no está completo. Cuando completes algunos trabajos te daré más páginas.",
    ["Category:God Emissaries"] = "Categoría:God Emissaries",
    ["After completing the Tears of Guthix quest, players have the option to collect tears once a week. To do so, players must first tell Juna a story of their travels and adventures. Each story can be linked to a quest done in the past."] = "Después de completar la misión Tears of Guthix, los jugadores tienen la opción de recolectar lágrimas una vez a la semana. Para hacerlo, los jugadores primero deben contarle a Juna una historia de sus viajes y aventuras. Cada historia se puede vincular a una misión realizada en el pasado.",
    ["Note that these dialogues can be story or non-story related. Story-related dialogues are listed under the List of stories section, while the ones below are for dialogues not related to the stories."] = "Tenga en cuenta que estos diálogos pueden estar relacionados con una historia o no. Los diálogos relacionados con las historias se enumeran en la sección Lista de historias, mientras que los que aparecen a continuación son para diálogos no relacionados con las historias.",
    ["Tell me... a story..."] = "Cuéntame... una historia...",
    ["Choose an option"] = "Elige una opción:",
    ["Okay..."] = "Está bien...",
    ["You tell Juna some stories of your adventures."] = "Le cuentas a Juna algunas historias de tus aventuras.",
    ["*See the List of stories section below*"] = "*Consulta la sección Lista de historias a continuación*",
    ["Your stories have entertained me. I will let you into the cave for a short time."] = "Tus historias me han entretenido. Te dejaré entrar a la cueva por un corto tiempo.",
    ["I see you are not currently enlightened, but you have a light creature summoned, as well as a scroll it can use in your inventory."] = "Veo que actualmente no estás iluminado, pero tienes una criatura de luz invocada, así como un pergamino que puedes usar en tu inventario.",
    ["I see you are not currently enlightened, but you have a light creature summoned, and the light creature is holding a scroll it can use."] = "Veo que actualmente no estás iluminado, pero tienes una criatura de luz convocada y la criatura de luz sostiene un pergamino que puede usar.",
    ["I see you are not currently enlightened, but you have a both a light creature pouch, and a scroll it can use, in your inventory."] = "Veo que actualmente no estás iluminado, pero tienes en tu inventario una bolsa de criatura ligera y un pergamino que puedes usar.",
    ["Do you wish to collect the tears anyway?"] = "¿Quieres recoger las lágrimas de todos modos?",
    ["Yes, I understand that none of the tears I collect will be doubled."] = "Sí, entiendo que ninguna de las lágrimas que recoja se duplicará.",
    ["No thank you, I would like to cast enlightenment first."] = "No, gracias. Primero me gustaría transmitir la iluminación.",
    ["As you wish, Player."] = "Como desees, Player.",
    ["Collect as much as you can from the blue streams. If you let in water from the green streams, it will take away from the blue. For Guthix is god of balance, and balance lies in the juxtaposition of opposites."] = "Recoge todo lo que puedas de las corrientes azules. Si dejas entrar agua de los arroyos verdes, se la quitará a los azules. Porque Guthix es el dios del equilibrio, y el equilibrio reside en la yuxtaposición de los opuestos.",
    ["Your stories have entertained me. But I will not permit any adventurer to access the tears more than once a week. Come back in # days."] = "Tus historias me han entretenido. Pero no permitiré que ningún aventurero acceda a las lágrimas más de una vez por semana. Vuelve en # días.",
    ["Your stories have entertained me, but the creation of Armadyl that follows you will not enter my cave. Dismiss it and return to me."] = "Tus historias me han entretenido, pero la creación de Armadyl que te sigue no entrará en mi cueva. Deséchalo y regresa a mí.",
    ["How do I make the improved bowl?"] = "¿Cómo hago el cuenco mejorado?",
    ["A story?"] = "¿Una historia?",
    ["I have been waiting here for three thousand years, guarding the Tears of Guthix. I serve my master faithfully, but I am bored."] = "He estado esperando aquí durante tres mil años, guardando las Lágrimas de Guthix. Sirvo fielmente a mi amo, pero estoy aburrido.",
    ["An adventurer such as yourself must have many tales to tell. If you can entertain me, I will let you in the cave for a time."] = "Un aventurero como tú debe tener muchas historias que contar. Si puedes entretenerme, te dejaré entrar a la cueva por un tiempo.",
    ["The more I enjoy your story, the more time I will give you in the cave."] = "Cuanto más disfrute tu historia, más tiempo te daré en la cueva.",
    ["Then you can drink the power of balance, which will make you stronger in whatever area you are weakest."] = "Entonces podrás beber el poder del equilibrio, que te hará más fuerte en cualquier área en la que estés más débil.",
    ["Okay... (see the top)"] = "Está bien... (ver arriba)",
    ["Not now."] = "Ahora no.",
    ["What are the Tears of Guthix?"] = "¿Qué son las Lágrimas de Guthix?",
    ["The Third Age of the world was a time of great conflict, of destruction never seen before or since, when all the gods save Guthix warred for control."] = "La Tercera Edad del mundo fue una época de gran conflicto, de destrucción nunca vista antes ni después, cuando todos los dioses, excepto Guthix, lucharon por el control.",
    ["The colossal wyrms, of whom today's dragons are a pale reflection, turned all the sky to fire, while on the ground armies of foot soldiers - goblins and trolls and humans - filled the valleys and plains with blood."] = "Los colosales wyrms, de los cuales los dragones de hoy son un pálido reflejo, convirtieron todo el cielo en fuego, mientras que en tierra ejércitos de soldados de infantería (duendes, trolls y humanos) llenaron de sangre los valles y llanuras.",
    ["In the time the noise of the conflict woke Guthix from His deep slumber, and He rose and stood in the centre of the battlefield so the splendour of His wrath filled the world, and He called for the conflict to cease!"] = "En el momento en que el ruido del conflicto despertó a Guthix de Su profundo sueño, se levantó y se paró en el centro del campo de batalla para que el esplendor de Su ira llenara el mundo, ¡y pidió que cesara el conflicto!",
    ["Silence fell, for the gods knew that none could challenge the power of the mighty Guthix; for His power is that of nature itself, to which all other things are subject, in the end."] = "Se hizo el silencio, porque los dioses sabían que nadie podía desafiar el poder del poderoso Guthix; porque su poder es el de la naturaleza misma, a la que, en última instancia, están sujetas todas las demás cosas.",
    ["Guthix reclaimed that which had been stolen from Him, and went back underground to His sleep and continue to draw the world's power into Himself."] = "Guthix reclamó lo que le había sido robado, volvió a dormir bajo tierra y continuó atrayendo el poder del mundo hacia sí mismo.",
    ["But on His way into the depths of the earth He sat and rested in this cave; and, thinking of the battle-scarred desert that now streched from one side of His world to the other, He wept."] = "Pero en Su camino hacia las profundidades de la tierra, se sentó y descansó en esta cueva; y, pensando en el desierto marcado por la batalla que ahora se extendía de un lado a otro de Su mundo, lloró.",
    ["And so great was His sorrow, and so great was His life-giving power, that the rocks themselves began to weep with Him."] = "Y tan grande era Su dolor, y tan grande era Su poder vivificante, que las rocas mismas comenzaron a llorar con Él.",
    ["Later, Guthix noticed that the rocks continued to weep, and that their tears was infused with a small part of His power."] = "Más tarde, Guthix notó que las rocas seguían llorando y que sus lágrimas estaban impregnadas de una pequeña parte de Su poder.",
    ["So He set me, His servant, to guard the cave, and He entrusted me the task of judging who was and was not worthy to access the tears."] = "Entonces Él me puso a mí, Su sirviente, para custodiar la cueva, y me confió la tarea de juzgar quién era y quién no era digno de acceder a las lágrimas.",
    ["You tell me a story."] = "Cuéntame una historia.",
    ["Tell me about the Tears of Guthix. (see above)"] = "Háblame de las Lágrimas de Guthix. (ver arriba)",
    ["Tell me a new story."] = "Cuéntame una nueva historia.",
    ["I will tell you the story of the light-creatures."] = "Te contaré la historia de las criaturas de luz.",
    ["Myriad and beautiful were the creatures and civilizations of the early ages of the world. Gielinor was a work of art, shaped lovingly over the millennia by the creative mind of Guthix."] = "Innumerables y hermosas fueron las criaturas y civilizaciones de las primeras edades del mundo. Gielinor fue una obra de arte, moldeada con amor a lo largo de milenios por la mente creativa de Guthix.",
    ["Only the sturdiest races survived the God Wars, and even then by only abandoning their high culture and gearing the societies towards war. Of the more delicate races there is now no trace, and almost no memory."] = "Sólo las razas más resistentes sobrevivieron a las Guerras de Dios, e incluso entonces abandonaron su alta cultura y orientaron a las sociedades hacia la guerra. De las razas más delicadas ya no queda rastro, y casi ningún recuerdo.",
    ["One such race had bodies as fragile as snowflakes, yet they built crystal cities that stood for a thousand years."] = "Una de esas razas tenía cuerpos tan frágiles como los copos de nieve, pero construyeron ciudades de cristal que duraron mil años.",
    ["The wind would whisper through the spires and fill them with street harmonies, and the rising sun would shine through the precious gems that studded the towers and create inter plays of light as if rainbows were dancing."] = "El viento susurraría a través de las agujas y las llenaría con armonías callejeras, y el sol naciente brillaría a través de las gemas preciosas que tachonaban las torres y crearía juegos de luces como si los arcoíris estuvieran bailando.",
    ["Indeed, so marvellous was this light-show at it's height that the patterns of light themselves became alive, and the great flocks of luminous creatures rode along the gem-cast beams, each drawn to its own colour."] = "De hecho, tan maravilloso fue este espectáculo de luces en su apogeo que los propios patrones de luz cobraron vida, y las grandes bandadas de criaturas luminosas cabalgaban a lo largo de los rayos de gemas, cada una atraída por su propio color.",
    ["The creatures you see floating in this chasm are the last sorry remnants of that age. I do not know how they made their way here and survived to this time, but I am grateful for their company."] = "Las criaturas que ves flotando en este abismo son los últimos restos lamentables de esa época. No sé cómo llegaron hasta aquí y sobrevivieron hasta este momento, pero estoy agradecido por su compañía.",
    ["Not after the start of my vigil a party of goblins happened on my cave. They were the ugly brutes of the gods' armies, but their armour bore a faded patch where the symbol of a god had been removed."] = "No después del comienzo de mi vigilia, apareció un grupo de duendes en mi cueva. Eran los feos brutos de los ejércitos de los dioses, pero sus armaduras tenían un parche descolorido donde se había eliminado el símbolo de un dios.",
    ["They looked around hesitantly, squinting in the light of crude torches, but as soon as they saw me they raised their spears and charged."] = "Miraron a su alrededor vacilantes, entrecerrando los ojos a la luz de toscas antorchas, pero tan pronto como me vieron levantaron sus lanzas y cargaron.",
    ["No one may access the Tears of Guthix by force. I sent them tumbling into the chasm."] = "Nadie puede acceder a las Lágrimas de Guthix por la fuerza. Los envié al abismo.",
    ["Two hundred years later, another goblin found me. This one was unarmed, and although she was very wary I succeeded in engaging her in conversation."] = "Doscientos años después, otro duende me encontró. Esta estaba desarmada y, aunque estaba muy cautelosa, logré entablar conversación con ella.",
    ["Since then I have had many more visits from the descendants of those lost warriors, and over the centuries I have seen them change."] = "Desde entonces he recibido muchas más visitas de los descendientes de esos guerreros perdidos y, a lo largo de los siglos, los he visto cambiar.",
    ["They have become timid rather than aggressive, and I have seen the light of intelligence grow in their bulging eyes."] = "Se han vuelto más tímidos que agresivos, y he visto crecer la luz de la inteligencia en sus ojos saltones.",
    ["Their stories are repetitive and grim, of scraping a living out of the harsh rock through ingenuity and toil shaping it into a home."] = "Sus historias son repetitivas y sombrías, sobre cómo ganarse la vida a partir de la dura roca a través del ingenio y el trabajo duro para convertirla en un hogar.",
    ["I have followed the progress of their race, but their individual stories hold little interest for me."] = "He seguido el progreso de su carrera, pero sus historias individuales tienen poco interés para mí.",
    ["Tell me a...wait one moment."] = "Dime... espera un momento.",
    ["What's the matter?"] = "¿Qué pasa?",
    ["I feel that you possess great skill; great enough to gain the full power of the tears."] = "Siento que posees una gran habilidad; lo suficientemente grande como para obtener todo el poder de las lágrimas.",
    ["Use your great skill to make a more ornate bowl. The pattern will come to you as you work."] = "Usa tu gran habilidad para hacer un cuenco más adornado. El patrón te llegará a medida que trabajes.",
    ["Bring the bowl to me, and you can use it to collect the tears to gain the full power they hold."] = "Tráeme el cuenco y podrás usarlo para recoger las lágrimas y obtener todo el poder que contienen.",
    ["Now, tell me...a story..."] = "Ahora, cuéntame... una historia...",
    ["Leave to make the bowl."] = "Dejar hacer el bol.",
    ["Very well. Return soon..."] = "Muy bien. Vuelve pronto...",
    ["Keep talking."] = "Sigue hablando.",
    ["You have the bowl for me?"] = "¿Tienes el cuenco para mí?",
    ["I have it here."] = "Lo tengo aquí.",
    ["Very good. With this larger bowl you will gain ever greater benefit from the tears."] = "Muy bien. Con este cuenco más grande obtendrás un beneficio cada vez mayor de las lágrimas.",
    ["I will keep this bowl with me, and you may use it from now on to drink deeply of the tears."] = "Guardaré este cuenco conmigo y podrás usarlo de ahora en adelante para beber profundamente de las lágrimas.",
    ["Now, tell me a story..."] = "Ahora, cuéntame una historia...",
    ["I would like to talk about Guthix's death."] = "Me gustaría hablar sobre la muerte de Guthix.",
    ["I cannot say it is something I wish to think about."] = "No puedo decir que sea algo en lo que desee pensar.",
    ["Sorry Juna, but we cannot ignore it. I just wanted to ask some questions."] = "Lo siento Juna, pero no podemos ignorarlo. Sólo quería hacer algunas preguntas.",
    ["I'd like some advice about being a Guardian of Guthix."] = "Me gustaría recibir algún consejo sobre cómo ser un guardián de Guthix.",
    ["Guthix chose you as a Guardian because he could already see it in you."] = "Guthix te eligió como Guardián porque ya podía verlo en ti.",
    ["You were chosen to be one of us because you showed not only a great talent, but also an understanding of balance, and the potential to be much more."] = "Fuiste elegido para ser uno de nosotros porque demostraste no solo un gran talento, sino también una comprensión del equilibrio y el potencial para ser mucho más.",
    ["With Guthix's death, and the knowledge he imparted to you, he clearly intends us to become an army against the young gods."] = "Con la muerte de Guthix y el conocimiento que te impartió, claramente tiene la intención de que nos convirtamos en un ejército contra los dioses jóvenes.",
    ["You should think on what he told you; remember his intentions when giving you his power. He wants you to lead the defence of this world."] = "Deberías pensar en lo que te dijo; Recuerda sus intenciones al darte su poder. Él quiere que lideres la defensa de este mundo.",
    ["Surely the other Guardians can help? Where did they go?"] = "¿Seguramente los otros Guardianes pueden ayudar? ¿A dónde fueron?",
    ["Of course. We will be by your side whenever you need us, but in the mean time we must all continue our previous duties. I cannot leave these caves unattended, Death cannot abandon his role... Guthix may be gone, but that does not mean we should abandon our posts."] = "Por supuesto. Estaremos a tu lado siempre que nos necesites, pero mientras tanto todos debemos continuar con nuestras funciones anteriores. No puedo dejar estas cuevas desatendidas, la Muerte no puede abandonar su papel... Puede que Guthix se haya ido, pero eso no significa que debamos abandonar nuestros puestos.",
    ["What do you think will happen now?"] = "¿Qué crees que pasará ahora?",
    ["We have already seen it begin. Saradomin has already returned."] = "Ya lo hemos visto comenzar. Saradomin ya ha regresado.",
    ["The others will come. Nothing has changed, Player, they will be as determined and greedy as they were thousands of years ago."] = "Los demás vendrán. Nada ha cambiado, Player, serán tan decididos y codiciosos como lo fueron hace miles de años.",
    ["We are on the brink of another God Wars. If we do not act, the world will be ravaged. Guthix is not here to stop them, this time. It is up to us."] = "Estamos al borde de otra Guerra de Dioses. Si no actuamos, el mundo quedará devastado. Guthix no está aquí para detenerlos esta vez. Depende de nosotros.",
    ["How are you feeling?"] = "¿Cómo te sientes?",
    ["It is very difficult to speak about. I can't believe..."] = "Es muy difícil hablar de ello. No puedo creer...",
    ["I'm sorry, I'm not ready to discuss this with anyone. It's too painful."] = "Lo siento, no estoy listo para discutir esto con nadie. Es demasiado doloroso.",
    ["We have already seen it begin. Saradomin and Zamorak have already returned. Armadyl and Bandos have clashed, and the new God War has claimed its first divine victim."] = "Ya lo hemos visto comenzar. Saradomin y Zamorak ya regresaron. Armadyl y Bandos se han enfrentado y el nuevo Dios War ha reclamado su primera víctima divina.",
    ["More yet will come. Nothing has changed, player. They will be as determined and greedy as they were thousands of years ago."] = "Vendrán más. Nada ha cambiado, jugador. Serán tan decididos y codiciosos como lo fueron hace miles de años.",
    ["I want to talk about Zanik and Bandos."] = "Quiero hablar sobre Zanik y Bandos.",
    ["My feelings on this matter have changed. Do you wish to know how I felt at the time, or how I feel in the light of the death of my lord Guthix?"] = "Mis sentimientos sobre este asunto han cambiado. ¿Quieres saber cómo me sentí en ese momento o cómo me siento ante la muerte de mi señor Guthix?",
    ["I want to know how you felt then."] = "Quiero saber cómo te sentiste entonces.",
    ["Player, I hope you realise the magnitude of your actions. In helping Zanik to drive off Bandos you have betrayed all the gods."] = "Player, espero que te des cuenta de la magnitud de tus acciones. Al ayudar a Zanik a expulsar a Bandos, has traicionado a todos los dioses.",
    ["I thought you and Zanik were friends."] = "Pensé que tú y Zanik eran amigos.",
    ["We were, but no more. I will never deal with that blasphemer again. She has done more than betray her god - she has betrayed all the gods."] = "Lo estábamos, pero ya no. Nunca volveré a tratar con ese blasfemo. Ha hecho más que traicionar a su dios: ha traicionado a todos los dioses.",
    ["What do you mean, betrayed all the gods?"] = "¿Qué quieres decir con traicionar a todos los dioses?",
    ["You betrayed the principle of the gods' sovereignty! Bandos brought the goblins to Gielinor, and so they are his rightful property. They have no more right to defy him than your own weapon has to strike at you. That was why Guthix allowed Zanik to be raised from the dead. It was not only Bandos's{{Sic}} interests at stake. In defying him you stood against all the gods."] = "¡Traicionaste el principio de la soberanía de los dioses! Bandos trajo los duendes a Gielinor, por lo que son su propiedad legítima. No tienen más derecho a desafiarlo que el que tu propia arma tiene a atacarte. Por eso Guthix permitió que Zanik resucitara de entre los muertos. No sólo estaban en juego los intereses de Bandos, {{Sic}}. Al desafiarlo te enfrentaste a todos los dioses.",
    ["It was still the right thing to do."] = "Aún así era lo correcto.",
    ["The will of the gods is the measure of what is right."] = "La voluntad de los dioses es la medida de lo que es correcto.",
    ["So I'm an enemy of the gods now?"] = "¿Entonces ahora soy un enemigo de los dioses?",
    ["No. I do not sense that about you. For whatever reason, Guthix does not wish to punish you. Perhaps he senses that you will serve the gods well in the future."] = "No. No siento eso en ti. Por alguna razón, Guthix no desea castigarte. Quizás sienta que servirás bien a los dioses en el futuro.",
    ["I don't like the sound of that."] = "No me gusta cómo suena eso.",
    ["What you want or do not want is of no consequence to the gods. In any case, Guthix still wishes me to deal with you. Will you tell me a story?"] = "Lo que quieras o no quieras no tiene importancia para los dioses. En cualquier caso, Guthix todavía desea que me ocupe de usted. ¿Me contarás una historia?",
    ["That's a relief."] = "Eso es un alivio.",
    ["I am glad to hear that you are still on the right path. In any case, Guthix still wishes me to deal with you. Will you tell me a story?"] = "Me alegra saber que todavía estás en el camino correcto. En cualquier caso, Guthix todavía desea que me ocupe de usted. ¿Me contarás una historia?",
    ["I want to know how you feel now."] = "Quiero saber cómo te sientes ahora.",
    ["I served Guthix for longer than most mortal dynasties exist. I spent most of that time alone, patiently fulfilling the task to which he assigned me. In that time, my thoughts and feelings became...twisted."] = "Serví a Guthix durante más tiempo del que existe la mayoría de las dinastías mortales. Pasé la mayor parte de ese tiempo solo, cumpliendo pacientemente la tarea que me asignó. En ese momento, mis pensamientos y sentimientos se volvieron... retorcidos.",
    ["For centuries, my only thought was love for my lord Guthix. I longed for him to return and bless me with his divine gaze, to tell me that I had been a good and faithful servant. I loved Guthix not because he was the most powerful or benevolent god - although he was both those things - but because he was my god and he had chosen me to be his servant."] = "Durante siglos, mi único pensamiento fue el amor por mi señor Guthix. Anhelaba que regresara y me bendijera con su mirada divina, para decirme que había sido un buen y fiel servidor. Amaba a Guthix no porque fuera el dios más poderoso o benévolo (aunque era ambas cosas), sino porque era mi dios y me había elegido para ser su sirviente.",
    ["When I saw that Zanik had been chosen by her god to be his servant, and that she refused, that seemed to me to be the greatest possible blasphemy. I see now that, in my isolation, I had constructed a false idol in my mind and no longer worshipped the real Guthix. In defying the war god, Zanik followed the true path of Guthix, and in opposing her...I was wrong."] = "Cuando vi que Zanik había sido elegida por su dios para ser su sirvienta, y que ella se negó, eso me pareció la mayor blasfemia posible. Ahora veo que, en mi aislamiento, había construido un ídolo falso en mi mente y ya no adoraba al verdadero Guthix. Al desafiar al dios de la guerra, Zanik siguió el verdadero camino de Guthix, y al oponerme a ella... me equivoqué.",
    ["I have not had news of Zanik since Guthix died. Perhaps if I saw her again, she could forgive me...but I do not know where she is or what her place will be in this new age."] = "No he tenido noticias de Zanik desde que murió Guthix. Quizás si la volviera a ver podría perdonarme... pero no sé dónde está ni cuál será su lugar en esta nueva era.",
    ["I do not wish to think of this any more... Will you tell me a story?"] = "No deseo pensar más en esto... ¿Me cuentas una historia?",
    ["{| class=\"wikitable"] = "{| clase=\"wikitabla",
    ["! Quest"] = "! Búsqueda",
    ["! Story ending"] = "! final de la historia",
    ["! Juna's reply"] = "! La respuesta de Juna",
    ["| Aftermath"] = "| Secuelas",
    ["| \"I defeated Zamorak, and said farewell to the gods before they were banished from Gielinor."] = "| \"Derroté a Zamorak y me despedí de los dioses antes de que fueran desterrados de Gielinor\".",
    ["| All Fired Up"] = "| Todo encendido",
    ["| \"...And that was how I learned to maintain King Roald's watchtower beacons."] = "| \"...Y así fue como aprendí a mantener las balizas de vigilancia de King Roald\".",
    ["| Alpha vs Omega"] = "| Alfa vs Omega",
    ["| \"I finally felt ready to face Rasial in immortal combat and destroyed his physical body. At least he was true to his word, and freed his army of enthralled souls back to Um."] = "| \"Finalmente me sentí listo para enfrentarme a Rasial en un combate inmortal y destruí su cuerpo físico. Al menos cumplió su palabra y liberó a su ejército de almas cautivadas de regreso a Um\".",
    ["| Ancient Awakening"] = "| Antiguo despertar",
    ["| \"I led an expedition to the island of Ungael and witnessed Zemouregal reanimating the dragon Vorkath."] = "| \"Dirigí una expedición a la isla de Ungael y fui testigo de cómo Zemouregal reanimaba al dragón Vorkath\".",
    ["| Animal Magnetism"] = "| Magnetismo animal",
    ["| \"...and so the attractor works using an undead chicken and a magnet."] = "| \"...y así el atractor funciona usando un pollo no-muerto y un imán.",
    ["| \"How odd."] = "| \"Qué extraño.",
    ["| Another Slice of H.A.M."] = "| Otra rebanada de H.A.M.",
    ["| \"...so I rescued Zanik from Sigmund and the railway was opened."] = "| \"... así que rescaté a Zanik de Sigmund y se abrió el ferrocarril\".",
    ["|(Before The Chosen Commander)"] = "|(Ante el Comandante Elegido)",
    ["| As a First Resort"] = "| Como primer recurso",
    ["| \"...So now the Oo'glog spa is open!"] = "| \"...¡Así que ahora el spa Oo'glog está abierto!",
    ["| Back to my Roots"] = "| De vuelta a mis raíces",
    ["| \"...So I defeated the wild vine and learned how to care for my own Jade Vine."] = "| \"... Así que derroté a la vid salvaje y aprendí a cuidar mi propia Jade Vine\".",
    ["| \"The care of nature is important, but wild plants are creatures of Guthix just as much as cultivated ones."] = "| \"El cuidado de la naturaleza es importante, pero las plantas silvestres son criaturas de Guthix tanto como las cultivadas.",
    ["| Back to the Freezer"] = "| De vuelta al congelador",
    ["| \"...And I stopped the Penguins from sending Gielinor into an Ice Age."] = "| \"...Y evité que los pingüinos enviaran a Gielinor a una Edad de Hielo\".",
    ["| \"A truly mammoth feat! Those penguins could one day become more powerful than we could possibly imagine!"] = "| \"¡Una hazaña verdaderamente gigantesca! ¡Esos pingüinos algún día podrían volverse más poderosos de lo que podríamos imaginar!",
    ["| Battle of Forinthry"] = "| Batalla de Forinthry",
    ["| \"I defended Fort Forinthry against an invasion from Zemouregal and Vorkath."] = "| \"Defendí Fort Forinthry contra una invasión de Zemouregal y Vorkath.",
    ["| Bar Crawl (miniquest)"] = "| Rastreo de bares (minimisión)",
    ["| \"I completed my bar crawl card and earned access to the Barbarian Outpost agility course."] = "| \"Completé mi tarjeta de rastreo de bares y obtuve acceso al curso de agilidad de Barbarian Outpost\".",
    ["| Battle of the Monolith"] = "| Batalla del monolito",
    ["| \"I fought in the Battle of the Monolith."] = "| \"Luché en la Batalla del Monolito\".",
    ["| Beneath Cursed Tides"] = "| Debajo de las mareas malditas",
    ["| \"I discovered the true fate of Tutorial Island and helped break the curse that had been put upon the tutors."] = "| \"Descubrí el verdadero destino de Tutorial Island y ayudé a romper la maldición que habían caído sobre los tutores\".",
    ["| Beneath Scabaras' Sands"] = "| Debajo de las arenas de Scabaras",
    ["| \"I located the god Scabaras and watched as Osman's plot to kill him was foiled."] = "| \"Localicé al dios Scabaras y vi cómo se frustraba el plan de Osman para matarlo\".",
    ["| Benedict's World Tour (miniquest)"] = "| Gira mundial de Benedict (minimisión)",
    ["| \"I visited all the locations in Benedict Encumberyak's scrapbook."] = "| \"Visité todos los lugares del álbum de recortes de Benedict Encumberyak\".",
    ["| Between a Rock..."] = "| Entre una roca...",
    ["| \"...I had to be shot out of a cannon into a rock! But, finally, I banished the spirit of the rock and Dondakan could mine his gold."] = "| \"...¡Tuve que ser disparado desde un cañón hacia una roca! Pero, finalmente, desterré el espíritu de la roca y Dondakan pudo extraer su oro\".",
    ["| Big Chompy Bird Hunting"] = "| Gran caza Chompy Bird",
    ["| \"...poor Rantz was so clumsy he couldn't shoot anything, but I managed to kill the Chompy bird."] = "| \"...el pobre Rantz era tan torpe que no podía disparar a nada, pero logré matar al Chompy bird\".",
    ["| \"...it turned out there was no plague after all!"] = "| \"... ¡Resultó que después de todo no había ninguna plaga!",
    ["| \"Deception of the people by their rulers is a terrible thing."] = "| \"El engaño del pueblo por parte de sus gobernantes es algo terrible\".",
    ["| Birthright of the Dwarves"] = "| Patrimonio de los enanos",
    ["| \"...and that was how we finally defeated the Red Axe."] = "| \"...y así fue como finalmente derrotamos al Hacha Roja.",
    ["| \"The spectre of chaos dwarves has loomed over all dwarves since the Third Age. I am glad you stopped those who sought to create more of those abominations."] = "| \"El espectro de los enanos del caos se ha cernido sobre todos los enanos desde la Tercera Edad. Me alegra que hayas detenido a aquellos que buscaban crear más de esas abominaciones\".",
    ["| Black Knights' Fortress (Removed)"] = "| Fortaleza de Black Knights (eliminada)",
    ["| \"...in the end the Black Knights were defeated by a cabbage!"] = "| \"...¡al final los Black Knights fueron derrotados por un repollo!",
    ["| \"One should never underestimate the vegetables of Guthix."] = "| \"Nunca se deben subestimar las verduras de Guthix.",
    ["| The Blood Pact"] = "| El pacto de sangre",
    ["| \"...so I rescued the prisoner, but the last cultist's death completed the ritual. Dragith Nurn's tomb broke open to reveal a staircase to the lower level of the catacombs."] = "| \"... así que rescaté al prisionero, pero la muerte del último cultista completó el ritual. La tumba de Dragith Nurn se abrió para revelar una escalera al nivel inferior de las catacumbas\".",
    ["| Blood Runs Deep"] = "| La sangre corre profunda",
    ["| \"After sealing away the dagganoth mother, we held a funeral for Prince Brand and Princess Astrid."] = "| \"Después de sellar a la madre dagganoth, celebramos un funeral para Prince Brand y Princess Astrid\".",
    ["| \"Death is a natural part of life. Celebrate it that as much mourn it."] = "| \"La muerte es una parte natural de la vida. Celebrenla tanto como la lloren.",
    ["| Boric's Task I (miniquest)"] = "| Tarea I de Boric (minimisión)",
    ["| \"I completed another Mining task for Boric."] = "| \"Completé otra tarea Mining para Boric\".",
    ["| Boric's Task II (miniquest)"] = "| Tarea II de Boric (minimisión)",
    ["| Boric's Task III (miniquest)"] = "| Tarea III de Boric (minimisión)",
    ["| The Branches of Darkmeyer"] = "| Las ramas de Darkmeyer",
    ["| \"...and, when I went back to Veliaf, he said I'd just put the Myreque in more danger."] = "| \"...y, cuando volví con Veliaf, me dijo que simplemente pondría al Myreque en mayor peligro\".",
    ["We do not yet know what will happen due to your actions. You had good intentions and therefore, good may still come of it."] = "Aún no sabemos qué sucederá debido a tus acciones. Tenías buenas intenciones y, por lo tanto, aún puede salir algo bueno de ello\".",
    ["| Bringing Home the Bacon"] = "| Llevar el tocino a casa",
    ["| \"...and that is how I managed to help preserve the pig population."] = "| \"...y así es como logré ayudar a preservar la población porcina.",
    ["| \"Such a balance would be pleasing Guthix. I cannot help but wonder what happened to those bacon addicts, though. I hope they too found balance."] = "| \"Un equilibrio así agradaría a Guthix. Sin embargo, no puedo evitar preguntarme qué pasó con esos adictos al tocino. Espero que ellos también encuentren el equilibrio\".",
    ["| The Brink of Extinction"] = "| El borde de la extinción",
    ["| \"...And so the TzHaar declared me their great champion. After I beat TokHaar-Hok into submission, he withdrew to the Elder Kiln to recover."] = "| \"...Y entonces TzHaar me declaró su gran campeón. Después de que vencí a TokHaar-Hok hasta someterlo, se retiró al Elder Kiln para recuperarse\".",
    ["| \"It saddens me that the TokHaar would resort to an act of genocide to purify their ancient race. You have established a precarious balance between the TokHaar and their TzHaar brethren."] = "| \"Me entristece que los TokHaar recurran a un acto de genocidio para purificar su antigua raza. Habéis establecido un equilibrio precario entre los TokHaar y sus hermanos TzHaar\".",
    ["| Broken Home"] = "| Hogar roto",
    ["| \"...and that's how I broke the curse on Senecianus and put the ghost of Ormod Gulvas to rest."] = "| \"...y así fue como rompí la maldición sobre Senecianus y puse a descansar al fantasma de Ormod Gulvas\".",
    ["| \"A tale of madness and troubled men. How very sad. I am relieved you've restored balance to the world, hero."] = "| \"Una historia de locura y hombres con problemas. Qué triste. Me alivia que hayas restaurado el equilibrio del mundo, héroe\".",
    ["| Buyers and Cellars"] = "| Compradores y bodegas",
    ["| \"With stealth and misdirection, I secured the funds to get the Thieves' Guild of Lumbridge up and running."] = "| \"Con sigilo y desvío, conseguí los fondos para poner en funcionamiento el Gremio de Ladrones de Lumbridge\".",
    ["| Cabin Fever"] = "| Fiebre de cabina",
    ["| \"...so I holed the enemy ship with another cannon shot, and the Adventurous sailed triumphantly into Mos Le'Harmless!"] = "| \"...así que agujereé el barco enemigo con otro disparo de cañón, ¡y el Adventurous navegó triunfalmente hacia Mos Le'Harmless!",
    ["| Call of the Ancestors"] = "| Llamado de los Ancestros",
    ["| \"I discovered a truly ancient Goebie, and helped three young goebs harness the powers of Mazcab."] = "| \"Descubrí un Goebie verdaderamente antiguo y ayudé a tres jóvenes goebs a aprovechar los poderes de Mazcab\".",
    ["| Carnillean Rising"] = "| Levantamiento carnilleano",
    ["| \"...so Philipe Carnilean now travels the world, seeking out adventure!"] = "| \"... ¡Así que ahora Philipe Carnilean viaja por el mundo en busca de aventuras!",
    ["| \"A worthy career, indeed. It is good that the boy has taken charge of his own life instead of living in his parents' shadow."] = "| \"Una carrera digna, por cierto. Es bueno que el niño se haya hecho cargo de su propia vida en lugar de vivir a la sombra de sus padres\".",
    ["| Catapult Construction"] = "| Catapulta Construction",
    ["| \"...And that was how I repaired the catapult in the Tyras camp."] = "| \"...Y así fue como reparé la catapulta en el campamento de Tyras.",
    ["| \"Catapults are terrible devices. They move rocks from their proper Guthix-assigned positions."] = "| \"Las catapultas son dispositivos terribles. Mueven rocas desde las posiciones apropiadas asignadas por Guthix\".",
    ["| Chef's Assistant"] = "| asistente de chef",
    ["| \"I followed the Head Chef's instructions and learned how to make cheesecake."] = "| \"Seguí las instrucciones de Head Chef y aprendí a hacer tarta de queso\".",
    ["| Children of Mah"] = "| hijos de mah",
    ["| \"...And that is how Mah came to pass and the mahjarrat were freed from their rituals."] = "| \"...Y así es como Mah sucedió y los mahjarrat fueron liberados de sus rituales\".",
    ["| \"A grand tale! I only hope that they will treat Gielinor with respect now that they are free of their curse."] = "| \"¡Una gran historia! Sólo espero que traten a Gielinor con respeto ahora que están libres de su maldición\".",
    ["| The Chosen Commander"] = "| El comandante elegido",
    ["| \"...so Zanik and I defeated the Bandos Avatar!"] = "| \"...¡Así que Zanik y yo derrotamos al Avatar Bandos!",
    ["| \"I know what happened. Your actions were an affront to the authority of the gods. You may redeem yourself in the eyes of Guthix, but Zanik is no longer welcome here."] = "| \"Sé lo que pasó. Tus acciones fueron una afrenta a la autoridad de los dioses. Puedes redimirte ante los ojos de Guthix, pero Zanik ya no es bienvenido aquí\".",
    ["| City of Senntisten"] = "| Ciudad de Senntisten",
    ["| \"I worked with Azzanadra to reclaim and secure Senntisten's cathedral in preparation for our defence against the elder gods."] = "| \"Trabajé con Azzanadra para recuperar y asegurar la catedral de Senntisten en preparación para nuestra defensa contra los dioses mayores\".",
    ["| Clock Tower"] = "| Torre del Reloj",
    ["| \"...so, it was I who repaired the clock tower."] = "| \"... entonces, fui yo quien reparó la torre del reloj\".",
    ["| A Clockwork Syringe"] = "| Una jeringa mecánica",
    ["| \"...and then I sank the fleet of zomboats, and protected Mos Le'Harmless from Annihilation."] = "| \"...y luego hundí la flota de zombos y protegí a Mos Le'Harmless de la aniquilación\".",
    ["| \"Undead pirates enhanced by machinery? If ever a more abominable affront to balance existed.."] = "| \"¿Piratas no muertos mejorados por maquinaria? Si alguna vez existiera una afrenta más abominable al equilibrio...",
    ["| Cold War"] = "| Frío War",
    ["| \"...It was a close call, but I managed to discover the penguins' plans and escape from their base."] = "| \"...Estuve cerca, pero logré descubrir los planes de los pingüinos y escapar de su base\".",
    ["| \"Penguins? Those creatures are not to be underestimated."] = "| \"¿Pingüinos? Esas criaturas no deben subestimarse.",
    ["| Contact!"] = "| ¡Contacto!",
    ["| \"...And when I emerged from the temple I found the place hugely changed. The deserted food stalls and empty streets were replaced with a healthy city filled with life, colour and commerce."] = "| \"...Y cuando salí del templo encontré el lugar enormemente cambiado. Los puestos de comida desiertos y las calles vacías fueron reemplazadas por una ciudad saludable llena de vida, color y comercio\".",
    ["| \"...And, in the end, I found all the ingredients, so the Duke of Lumbridge had a birthday cake after all."] = "| \"...Y, al final, encontré todos los ingredientes, así que, después de todo, el duque de Lumbridge tenía un pastel de cumpleaños\".",
    ["| \"Ah, a happy ending. It would not be good for such an anniversary to go unmarked."] = "| \"Ah, un final feliz. No sería bueno que un aniversario así quedara sin marcar\".",
    ["| Creature of Fenkenstrain"] = "| Criatura de Fenkenstrain",
    ["| \"...But in the end I stopped Fenkenstrain from continuing his horrible experiments."] = "| \"...Pero al final impidí que Fenkenstrain continuara con sus horribles experimentos\".",
    ["| Crocodile Tears"] = "| Crocodile Lágrimas",
    ["| \"...so I kept telling her no, and she spat up her corruption in the form of a crocodile demon, which I dealt with."] = "| \"... así que seguí diciéndole que no, y ella escupió su corrupción en la forma de un demonio cocodrilo, con el cual me ocupé\".",
    ["| \"Restoring Crondis is but a tilt of the scales in bringing balance to the desert. Still, it is a tilt in the right direction."] = "| \"Restaurar Crondis no es más que una inclinación de la balanza para traer equilibrio al desierto. Aún así, es una inclinación en la dirección correcta\".",
    ["| The Curse of Arrav"] = "| La maldición de Arrav",
    ["| \"...And so I escaped with the heart of Arrav."] = "| \"...Y así escapé con el corazón de Arrav.",
    ["| \"This separation of heart from man is not natural. It is good you are looking to resolve such matters."] = "| \"Esta separación del corazón del hombre no es natural. Es bueno que busquen resolver estos asuntos\".",
    ["| Curse of the Black Stone"] = "| Maldición de la Piedra Negra",
    ["| \"I defeated the Ambassador and saved Gielinor from a horrific hidden presence."] = "| \"Derroté a the Ambassador y salvé a Gielinor de una horrible presencia oculta\".",
    ["| Curse of the Empty Lord (miniquest)"] = "| La maldición del Señor Vacío (minimisión)",
    ["| \"I communed with six spirits, and learned more of an ancient entity whose name I probably shouldn't speak aloud. I also acquired ghostly robes."] = "| \"Me comuniqué con seis espíritus y aprendí más sobre una entidad antigua cuyo nombre probablemente no debería pronunciar en voz alta. También adquirí túnicas fantasmales\".",
    ["| Damage Control (miniquest)"] = "| Control de daños (minimisión)",
    ["| \"I salvaged materials from the island of Goshima to repair the Sarim's Revenge."] = "| \"Rescaté materiales de la isla de Goshima para reparar el Sarim's Revenge\".",
    ["| The Darkness of Hallowvale"] = "| La oscuridad de Hallowvale",
    ["| \"...I gave Safalaan the book on haemalchemy, and he recommended me for a position in the Myreque."] = "| \"...Le di a Safalaan el libro sobre hemalquimia y él me recomendó para un puesto en el Myreque\".",
    ["| \"I'm sure you will have many more adventures on behalf of the Myreque. Then, perhaps, you will have even more stories to tell me."] = "| \"Estoy seguro de que tendrás muchas más aventuras en nombre del Myreque. Entonces, tal vez, tendrás aún más historias que contarme\".",
    ["| Daughter of Chaos"] = "| hija del caos",
    ["| \"I tracked Moia through the Wilderness and witnessed the turning point of the Zamorakian Civil War."] = "| \"Seguí a Moia a través de Wilderness y fui testigo del punto de inflexión del War civil de Zamorak\".",
    ["| Dead and Buried"] = "| Muerto y enterrado",
    ["| \"The Raptor and I delved deeper into the crypt north of Fort Forinthry and discovered Zemouregal's nefarious plot."] = "| \"The Raptor y yo profundizamos en la cripta al norte de Fort Forinthry y descubrimos el nefasto complot de Zemouregal\".",
    ["| Deadliest Catch"] = "| Captura más mortal",
    ["| \"...and we returned to the Fishing Guild where Jones set up shop selling his own Miracle Thalassus Protection Cream."] = "| \"...y regresamos al Gremio Fishing donde Jones instaló una tienda vendiendo su propia Crema Protectora Miracle Thalassus\".",
    ["| \"It's a small blessing that the creature can continue to exist."] = "| \"Es una pequeña bendición que la criatura pueda seguir existiendo\".",
    ["| Dealing with Scabaras"] = "| Lidiando con Scabaras",
    ["| \"...And that was how I dealt with the High Priest of Scabaras."] = "| \"...Y así fue como lidié con el High Priest of Scabaras\".",
    ["| \"The desert gods are strange, but you must be sure to pay them the proper respect."] = "| \"Los dioses del desierto son extraños, pero debes asegurarte de mostrarles el debido respeto\".",
    ["| The Death of Chivalry"] = "| La muerte de la caballería",
    ["| \"...Saradomin brought Sir Owen back to life, but the resurrected knight's sword arm was corrupted and skeletal."] = "| \"...Saradomin devolvió la vida a Sir Owen, pero el brazo espada del caballero resucitado estaba corrupto y esquelético\".",
    ["| \" I hope now you appreciate the power the gods seek to wield, at any cost."] = "| \"Espero que ahora aprecies el poder que los dioses buscan ejercer, a cualquier precio\".",
    ["| Death Plateau"] = "| Meseta de la muerte",
    ["| \"...So, from then on, the Imperial Guard was able to access Death Plateau safely and take the trolls by surprise."] = "| \"... Entonces, a partir de ese momento, la Guardia Imperial pudo acceder a la Meseta de la Muerte de manera segura y tomar a los trolls por sorpresa\".",
    ["| Death to the Dorgeshuun"] = "| Muerte al Dorgeshuun",
    ["| \"...Sigmund escaped again, but Zanik and I destroyed the machine and Dorgesh-Kaan was saved!"] = "| \"...¡Sigmund escapó de nuevo, pero Zanik y yo destruimos la máquina y Dorgesh-Kaan se salvó!",
    ["|(Before The Chosen Commander) \"Zanik still has her destiny to fulfil, and I have a feeling you will have a part in that."] = "|(Antes de The Chosen Commander) \"Zanik todavía tiene su destino que cumplir, y tengo la sensación de que tú tendrás parte en eso\".",
    ["| Defender of Varrock"] = "| Defensor de Varrock",
    ["| \"...The Shield of Arrav glowed with lightning, and Dimintheis used it to defeat the zombie army."] = "| \"...El Escudo de Arrav brillaba con un rayo, y Dimintheis lo usó para derrotar al ejército zombie\".",
    ["| Demon Slayer"] = "| Demonio Slayer",
    ["| \"...so I destroyed the demon Delrith and saved Varrock!"] = "| \"... ¡así que destruí al demonio Delrith y salvé a Varrock!",
    ["| \"I remember Delrith. A most unpleasant character; I am glad he has been dispatched."] = "| \"Recuerdo a Delrith. Un personaje muy desagradable; me alegro de que lo hayan enviado\".",
    ["| Desert Slayer Dungeon (miniquest)"] = "| Mazmorra del Desierto Slayer (minimisión)",
    ["| \"In the Pollnivneach Slayer Dungeon, I defeated a monstrous cave crawler, basilisk boss, mightiest turoth and kurask overlord."] = "| \"En la mazmorra Pollnivneach Slayer, derroté a un monstruoso rastreador de cuevas, al jefe basilisco, al turoth más poderoso y al señor supremo kurask\".",
    ["| \"...In the pyramid I discovered a whole new set of magic spells!"] = "| \"...¡En la pirámide descubrí un conjunto completamente nuevo de hechizos mágicos!",
    ["| \"I suggest you think about the origin of those spells. Ancient magicks are not to be toyed with."] = "| \"Te sugiero que pienses en el origen de esos hechizos. No se debe jugar con la magia antigua\".",
    ["| Desperate Measures"] = "| Medidas desesperadas",
    ["| \"I tracked down Kerapac and foiled his plot to destroy Gielinor. He's now fallen back under Jas's control, bound to the Needle this time."] = "| \"Rastreé a Kerapac y frustré su plan para destruir Gielinor. Ahora ha vuelto a caer bajo el control de Jas, esta vez atado a la Aguja\".",
    ["| Desperate Times"] = "| Tiempos desesperados",
    ["| \"I may have accidentally helped a dragonkin take control of an elder artefact, endangering all life on Gielinor. Oops."] = "| \"Es posible que accidentalmente haya ayudado a un dragonante a tomar el control de un artefacto antiguo, poniendo en peligro toda la vida en Gielinor. Ups\".",
    ["| Devious Minds"] = "| Mentes tortuosas",
    ["| \"...it was I who accidentally brought a teleport beacon onto Entrana! But the Temple Knights are investigating, so it should be all right."] = "| \"... ¡Fui yo quien accidentalmente trajo una baliza de teletransporte a Entrana! Pero los Caballeros del Templo están investigando, así que todo debería estar bien\".",
    ["| Diamond in the Rough"] = "| Diamante en bruto",
    ["| \"So it turned out Lady Keli was really the desert goddess Amascut in disguise! She escaped with the heart, and left Ozan and I to defeat her bodyguards."] = "| \"¡Resultó que Lady Keli era en realidad la diosa del desierto Amascut disfrazada! Ella escapó con el corazón y nos dejó a Ozan y a mí para derrotar a sus guardaespaldas\".",
    ["| \"It is good that the prince was safely returned home to retain the balance of peace, but the cost may prove to be high."] = "| \"Es bueno que el príncipe haya regresado sano y salvo a casa para mantener el equilibrio de la paz, pero el coste puede resultar elevado\".",
    ["| The Dig Site"] = "| El sitio de excavación",
    ["| \"...And the examiner was very impressed that I had discovered an ancient altar of Zaros."] = "| \"...Y el examinador quedó muy impresionado de que hubiera descubierto un antiguo altar de Zaros\".",
    ["| \"Zaros? I had not heard that name for a thousand years, even before the start of my sojourn here."] = "| \"¿Zaros? No había oído ese nombre en mil años, incluso antes del comienzo de mi estancia aquí.",
    ["| Dimension of Disaster"] = "| Dimensión del desastre",
    ["| \"...and so I returned to Varrock, the hero of two worlds."] = "| \"...y así regresé a Varrock, el héroe de dos mundos\".",
    ["| \"Fascinating. A city of villains, in a world where Guthix still sleeps. Your tale intrigues me."] = "| \"Fascinante. Una ciudad de villanos, en un mundo donde Guthix todavía duerme. Tu historia me intriga\".",
    ["| Dimension of Disaster: Coin of the Realm"] = "| Dimensión del desastre: moneda del reino",
    ["| \"I opened the way to New Varrock."] = "| \"Abrí el camino hacia el nuevo Varrock\".",
    ["| Dimension of Disaster: Curse of Arrav"] = "| Dimensión del desastre: La maldición de Arrav",
    ["| \"I defeated Zemouregal in New Varrock."] = "| \"Derroté a Zemouregal en New Varrock\".",
    ["| Dimension of Disaster: Shield of Arrav"] = "| Dimensión del Desastre: Escudo de Arrav",
    ["| \"I returned the Shield of Arrav to New Varrock museum."] = "| \"Devolví el escudo de Arrav al nuevo museo Varrock\".",
    ["| Dimension of Disaster: Defender of Varrock"] = "| Dimensión del desastre: Defensor de Varrock",
    ["| \"I weakened Zemouregal's control over Arrav in New Varrock."] = "| \"Debilité el control de Zemouregal sobre Arrav en New Varrock\".",
    ["| Dimension of Disaster: Demon Slayer"] = "| Dimensión del desastre: Demonio Slayer",
    ["| \"I defeated the demons Delrith and Agrith Naar in New Varrock."] = "| \"Derroté a los demonios Delrith y Agrith Naar en New Varrock\".",
    ["| Dishonour among Thieves (siding with Zamorak)"] = "| Deshonra entre ladrones (del lado de Zamorak)",
    ["| \"...and then Zamorak and I simultaneously blasted Sliske, delivering a blow that forced him to withdraw to the Shadow Realm with the Stone of Jas!"] = "| \"... ¡y luego Zamorak y yo atacamos simultáneamente a Sliske, dándole un golpe que lo obligó a retirarse al Reino de las Sombras con la Piedra de Jas!",
    ["| \"Another step closer to all out God Wars. Guthix would weep at the anarchy that is sweeping Gielinor, the other Guardians and I must do everything within our power to prevent it."] = "| \"Otro paso más hacia God Wars. Guthix lloraría ante la anarquía que está arrasando Gielinor, los otros Guardianes y yo debemos hacer todo lo que esté a nuestro alcance para evitarlo.",
    ["| Dishonour among Thieves (neutral)"] = "| Deshonra entre ladrones (neutral)",
    ["| \"...and after drawing power from the Stone of Jas, Zamorak blasted Sliske, forcing him to withdraw to the Shadow Realm with the stone."] = "| \"...y después de extraer poder de la Piedra de Jas, Zamorak atacó a Sliske, obligándolo a retirarse al Reino de las Sombras con la piedra.",
    ["| Dishonour among Thieves (siding with Sliske)"] = "| Deshonra entre ladrones (del lado de Sliske)",
    ["| \"...then I channeled  the Stone of Jas and blasted Zamorak to save Sliske, giving him enough time to shift both of us into the Shadow Realm along with the Stone!"] = "| \"...luego canalicé la Piedra de Jas y lancé a Zamorak para salvar a Sliske, ¡dándole tiempo suficiente para trasladarnos a ambos al Reino de las Sombras junto con la Piedra!",
    ["| Do No Evil"] = "| No hacer el mal",
    ["| \"...and so the monkey colony prospers and Apmeken is restored."] = "| \"...y así la colonia de monos prospera y Apmeken se restablece.",
    ["| \"Restoring Apmeken is but a tilt of the scales in bringing balance to the desert. Still, it is a tilt in the right direction."] = "| \"Restaurar Apmeken no es más que una inclinación de la balanza para lograr el equilibrio en el desierto. Aún así, es una inclinación en la dirección correcta\".",
    ["| Doric's Task I (miniquest)"] = "| Tarea I de Doric (minimisión)",
    ["| \"I completed another Smithing task for Doric."] = "| \"Completé otra tarea Smithing para Doric\".",
    ["| Doric's Task II (miniquest)"] = "| Tarea II de Doric (minimisión)",
    ["| Doric's Task III (miniquest)"] = "| Tarea III de Doric (minimisión)",
    ["| Doric's Task IV (miniquest)"] = "| Tarea IV de Doric (minimisión)",
    ["| Doric's Task V (miniquest)"] = "| Tarea V de Doric (minimisión)",
    ["| Doric's Task VI (miniquest)"] = "| Tarea VI de Doric (minimisión)",
    ["| Doric's Task VII (miniquest)"] = "| Tarea VII de Doric (minimisión)",
    ["| Doric's Task VIII (miniquest)"] = "| Tarea VIII de Doric (minimisión)",
    ["| Doric's Quest (Removed)"] = "| La misión de Doric (eliminada)",
    ["| \"...so once I had got all the ores he wanted, Doric let me use his anvils."] = "| \"... así que una vez que obtuve todos los minerales que quería, Doric me dejó usar sus yunques\".",
    ["| \"Such a small task hardly seems worthy of the term 'quest'."] = "| \"Una tarea tan pequeña difícilmente merece el término 'búsqueda'.",
    ["| \"...so with Elvarg the dragon dead, the master of the Champions' Guild let me in, and I was able to wear rune plate armour!"] = "| \"... así que con Elvarg el dragón muerto, el maestro de Champions' Guild me dejó entrar y ¡pude usar una armadura de placas rúnicas!",
    ["| Dream Mentor"] = "| Mentor de sueños",
    ["| \"...So in the end I travelled into Cyrisus's Dreamland and defeated his fear of combat."] = "| \"... Así que al final viajé al País de los Sueños de Cyrisus y derroté su miedo al combate\".",
    ["| Druidic Ritual"] = "| Ritual druídico",
    ["| \"...so Kaqemeex taught me how to use the Herblore skill."] = "| \"... entonces Kaqemeex me enseñó cómo usar la habilidad Herblore\".",
    ["| \"A generous reward indeed."] = "| \"Una recompensa generosa en verdad.",
    ["| Duck Quest"] = "| Búsqueda del pato",
    ["| \"I helped reunite a lost duckling with her family, and learnt the philosophy of the duck along the way."] = "| \"Ayudé a reunir a un patito perdido con su familia y, en el camino, aprendí la filosofía del pato\".",
    ["| Dwarf Cannon"] = "| Cañón enano",
    ["| \"...and that was how I fixed the dwarf multicannon."] = "| \"...y así fue como arreglé el multicañón enano.",
    ["| \"So, war still rages in the world above? Will you never tire of creating machines of destruction?"] = "| \"Entonces, ¿la guerra todavía hace estragos en el mundo de arriba? ¿Nunca te cansarás de crear máquinas de destrucción?",
    ["| Eadgar's Ruse"] = "| La artimaña de Eadgar",
    ["| \"...Eadgar's ruse was absurd, but it worked! The trolls ate a fake human, and I got the herb for the druids' ritual."] = "| \"... ¡La artimaña de Eadgar fue absurda, pero funcionó! Los trolls se comieron a un humano falso y yo conseguí la hierba para el ritual de los druidas\".",
    ["| Eagles' Peak"] = "| Pico de las Águilas",
    ["| \"...in the end I had to dress up as an eagle in order to get the zoo a new ferret!"] = "| \"...¡al final tuve que disfrazarme de águila para conseguirle al zoológico un nuevo hurón!",
    ["| \"You should not make light of your tampering with the balance of nature. Always treat the natural world with respect."] = "| \"No debes tomar a la ligera tu alteración del equilibrio de la naturaleza. Trata siempre el mundo natural con respeto\".",
    ["| \"...and that's how I reunited the demigods of the desert pantheon, stopped Amascut's destruction, and saved Menaphos!"] = "| \"... ¡y así fue como reuní a los semidioses del panteón del desierto, detuve la destrucción de Amascut y salvé a Menaphos!",
    ["| \"You were wise not to end Amascut's life. With her returned from the brink, balance has been restored to the desert."] = "| \"Hiciste bien en no acabar con la vida de Amascut. Con su regreso del borde del abismo, se ha restablecido el equilibrio en el desierto\".",
    ["| The Elder Kiln"] = "| El horno mayor",
    ["| \"...Ga'al-Xox left without another word, I can't help but think that the memories of the dead TzHaar champion weigh heavily on his mind."] = "| \"...Ga'al-Xox se fue sin decir una palabra más, no puedo evitar pensar que los recuerdos del campeón TzHaar muerto pesan mucho en su mente.",
    ["| \"The dead's memories are sacred. To channel them through the living is an affront to Guthix. The TzHaar should have steered clear of that kiln."] = "| \"Los recuerdos de los muertos son sagrados. Canalizarlos a través de los vivos es una afrenta para Guthix. Los TzHaar deberían haberse mantenido alejados de ese horno\".",
    ["| Elemental Workshop I"] = "| Taller Elemental I",
    ["| \"...once I had repaired the Elemental Workshop, I was able to make an elemental shield."] = "| \"...una vez que reparé el Taller Elemental, pude hacer un escudo elemental\".",
    ["| Elemental Workshop II"] = "| Taller Elemental II",
    ["| \"...so I instilled the power of my mind into the primed bar and smithed it into an elemental mind helm!"] = "| \"...¡así que inculqué el poder de mi mente en la barra preparada y la forjé en un yelmo mental elemental!",
    ["| \"You should be careful about meddling with your own head."] = "| \"Debes tener cuidado de no entrometerte en tu propia cabeza\".",
    ["| Elemental Workshop III"] = "| Taller Elemental III",
    ["| \"...pressing the button powered the elemental bar. I was then able to make a body body."] = "| \"...al presionar el botón se encendió la barra elemental. Entonces pude crear un cuerpo\".",
    ["| \"Sounds like an arduous task."] = "| \"Suena como una tarea ardua\".",
    ["| Elemental Workshop IV"] = "| Taller Elemental IV",
    ["| \"...pressing the button powered the elemental bar. I was then able to make some chaos boots."] = "| \"...al presionar el botón se encendió la barra elemental. Luego pude hacer algunas botas del caos\".",
    ["| \"This workshop sounds complex."] = "| \"Este taller suena complejo\".",
    ["| Enakhra's Lament"] = "| El lamento de Enakhra",
    ["| \"...then Akthanakos and Enakhra went away to the north to continue fighting."] = "| \"...entonces Akthanakos y Enakhra se fueron al norte para seguir luchando.",
    ["| \"A battle between two such powerful beings will take much time and unleash much energy. I hope that the natural world is not damaged in this conflict!"] = "| \"Una batalla entre dos seres tan poderosos llevará mucho tiempo y liberará mucha energía. ¡Espero que el mundo natural no resulte dañado en este conflicto!",
    ["| Enlightened Journey"] = "| Viaje iluminado",
    ["| \"...we landed the balloon in Taverley and Auguste thanked me for helping him get his idea off the ground."] = "| \"...aterrizamos el globo en Taverley y Auguste me agradeció por ayudarlo a hacer despegar su idea\".",
    ["| Enter the Abyss (miniquest)"] = "| Entra en el abismo (minimisión)",
    ["| \"I gained access to the Abyss."] = "| \"Obtuve acceso al Abismo\".",
    ["| Ernest the Chicken"] = "| Ernesto el Chicken",
    ["| \"...So, once I had found all the parts for the machine, poor Ernest could be himself once more."] = "| \"...Así que, una vez que encontré todas las piezas de la máquina, el pobre Ernest pudo volver a ser él mismo.",
    ["| \"That was a good deed. It is a terrible thing to be locked out of one's natural form."] = "| \"Esa fue una buena acción. Es algo terrible que uno se quede fuera de su forma natural\".",
    ["| Evil Dave's Big Day Out"] = "| El gran día de Evil Dave",
    ["| \"I somehow switched bodies with Evil Dave and survived enough chores and shouting from Doris to find a way to swap back."] = "| \"De alguna manera cambié de cuerpo con Evil Dave y sobreviví suficientes tareas y gritos de Doris para encontrar una manera de volver a cambiar\".",
    ["| Extinction"] = "| extinción",
    ["| \"...and that's how I prevented the Elder Gods from destroying Gielinor, once and for all!"] = "| \"... ¡y así es como evité que los Dioses Mayores destruyeran Gielinor, de una vez por todas!",
    ["| \"Guthix knew the Elders were the greatest threat Gielinor could ever face. He saw that this day would come...and that you would rise to meet it. Mourn the fate of Iaia, World Guardian. The greatest victories require the greatest sacrifices."] = "| \"Guthix sabía que los Ancianos eran la mayor amenaza que Gielinor podría enfrentar. Vio que este día llegaría... y que tú te levantarías para enfrentarlo. Llora el destino de Iaia, Guardiana Mundial. Las mayores victorias requieren los mayores sacrificios\".",
    ["| Eye for an Eye (miniquest)"] = "| Ojo por ojo (minimisión)",
    ["| \"I assisted the one-eyed inhabitants of Cyclosis, and dispatched undead Jed."] = "| \"Ayudé a los habitantes tuertos de Cyclosis y envié a Jed no-muertos\".",
    ["| Eye of Het I"] = "| Ojo de Het I",
    ["| \"I helped Icthlarin recover a priceless relic following the Duel Arena's destruction."] = "| \"Ayudé a Icthlarin a recuperar una reliquia de valor incalculable tras la destrucción del Duel Arena\".",
    ["| Eye of Het II"] = "| Ojo de Het II",
    ["| \"I solved the mystery of the Duel Arena's destruction."] = "| \"Resolví el misterio de la destrucción del Duel Arena\".",
    ["| The Eyes of Glouphrie"] = "| Los ojos de Gloufrie",
    ["| \"...the machine revealed that the cute creatures were actually Arposandran spies! I destroyed them, and King Narnode gave me a crystal seed that belonged to Oaknock the Engineer."] = "| \"... ¡la máquina reveló que las lindas criaturas eran en realidad espías arposandranos! Los destruí y el rey Narnode me dio una semilla de cristal que pertenecía a Oaknock el Ingeniero\".",
    ["| A Fairy Tale I - Growing Pains"] = "| Un cuento de Fairy I - Dolores de crecimiento",
    ["| \"...so I defeated the tanglefoot and returned the Fairy Queen's enchanted secateurs to the Fairy Godfather."] = "| \"... así que derroté al pie enredado y devolví las tijeras de podar encantadas de Fairy Queen al Padrino de Fairy\".",
    ["| \"These fairies seem to be well-versed in the powers of nature."] = "| \"Estas hadas parecen conocer bien los poderes de la naturaleza.",
    ["| A Fairy Tale II - Cure a Queen"] = "| A Fairy Tale II - Cura a una reina",
    ["| \"...the Fairy Queen awoke, and we realized that the Godfather had betrayed her!"] = "| \"...¡la Fairy Queen despertó y nos dimos cuenta de que el Padrino la había traicionado!",
    ["| \"Politics is never straightforward."] = "| \"La política nunca es sencilla\".",
    ["| A Fairy Tale III - Battle at Ork's Rift"] = "| A Fairy Tale III - Batalla en Ork's Rift",
    ["| \"...and as the Fairy Godfather got sucked into the rift, his power grew so immense that the rift exploded and destroyed an entire area of Zanaris. Cursed Ivory orks now roam that area, continually regrowing from the cursed farming patches!"] = "| \"...y cuando el Padrino de Fairy fue absorbido por la grieta, su poder creció tan inmenso que la grieta explotó y destruyó un área entera de Zanaris. ¡Los orkos de Marfil Malditos ahora deambulan por esa área, rebrotando continuamente de las parcelas agrícolas malditas!",
    ["That is indeed troubling, Player."] = "Eso es realmente preocupante, Player\".",
    ["To which you reply: \"However, the Fairy Queen has now been returned to her rightful throne, and the Fairy Godfather won't be around to bother anyone again!"] = "A lo que usted responde: \"Sin embargo, la Fairy Queen ha vuelto a ocupar el trono que le corresponde, ¡y el padrino de Fairy no volverá a molestar a nadie!\".",
    ["To which Juna replies: \"It seems you truly are a force for good, Player. Guthix himself would approve of you returning balance to the realm of Zanaris."] = "A lo que Juna responde: \"Parece que realmente eres una fuerza para el bien, Player. El propio Guthix aprobaría que devuelvas el equilibrio al reino de Zanaris\".",
    ["| Family Crest"] = "| Escudo familiar",
    ["| \"...So all three parts of the family crest were reunited."] = "| \"...Así que las tres partes del escudo familiar se reunieron\".",
    ["| Fate of the Gods (returning Zaros at full strength)"] = "| Destino de los Dioses (regresando Zaros con toda su fuerza)",
    ["| \"...And so Zaros has returned to Gielinor at full strength, and he intends to become an elder god! "] = "| \"... ¡Y entonces Zaros ha regresado a Gielinor con toda su fuerza, y tiene la intención de convertirse en un dios anciano! ",
    ["| \"While his intentions may seem noble, his methods are questionable and his history tarnished. Whatever he might be, he is not Guthix."] = "| \"Si bien sus intenciones pueden parecer nobles, sus métodos son cuestionables y su historia está empañada. Sea lo que sea, no es Guthix.",
    ["| Fate of the Gods (sabotaging Zaros)"] = "| Destino de los dioses (saboteando a Zaros)",
    ["| \"...and so Zaros has returned to Gielinor in a weakened state, but he still intends to become an elder god!"] = "| \"...y entonces Zaros ha regresado a Gielinor en un estado debilitado, ¡pero todavía tiene la intención de convertirse en un dios mayor!",
    ["| Father and Son (miniquest)"] = "| Padre e hijo (minimisión)",
    ["| \"I passed on a message to Sigli from Irwinsson and gave Irwinsson a bow created by his father."] = "| \"Le pasé un mensaje a Sigli de Irwinsson y le di a Irwinsson un arco creado por su padre.",
    ["| \"...So despite the failure of my original task, Ali Morrisane was very happy about his nephew's fortunes."] = "| \"... Entonces, a pesar del fracaso de mi tarea original, Ali Morrisane estaba muy contento con la suerte de su sobrino\".",
    ["| Fight Arena"] = "| Arena de lucha",
    ["| \"...I beat General Khazard in his own arena and won the Servils their freedom!"] = "| \"... ¡Vencí a General Khazard en su propia arena y le gané a los Servils su libertad!",
    ["| Final Destination (miniquest)"] = "| Destino final (minimisión)",
    ["| \"I defeated Captain Cora and eased the khan of Goshima's passage to her final destination."] = "| \"Derroté al Capitán Cora y facilité el paso del Khan de Goshima hasta su destino final\".",
    ["| The Firemaker's Curse"] = "| La maldición del bombero",
    ["| \"...so Char is still there, supposedly planning for Zaros's return."] = "| \"...así que Char todavía está allí, supuestamente planeando el regreso de Zaros.",
    ["| \"Zaros's return is not something I can look on kindly, but we must admire Char's devotion. It takes strength to stay loyal for so many centuries."] = "| \"El regreso de Zaros no es algo que pueda ver con buenos ojos, pero debemos admirar la devoción de Char. Se necesita fuerza para permanecer leal durante tantos siglos\".",
    ["| Fishing Contest"] = "| Concurso Fishing",
    ["| \"...And after I had won the fishing contest, the Dwarves let me go under White Wolf Mountain."] = "| \"...Y después de ganar el concurso de pesca, los enanos me dejaron ir bajo la Montaña del Lobo Blanco\".",
    ["| \"Fishing? A strange test of worthiness to pass through an underground tunnel!"] = "| \"¿Fishing? ¡Una extraña prueba de dignidad para pasar por un túnel subterráneo!",
    ["| Flag Fall (miniquest)"] = "| Caída de bandera (minimisión)",
    ["| \"I learned how to travel to uncharted islands and claimed an island of my own."] = "| \"Aprendí a viajar a islas inexploradas y reclamé una isla propia\".",
    ["| Forgettable Tale of a Drunken Dwarf"] = "| Historia olvidable de un Drunken Dwarf",
    ["| \"...I think I did something with a drunken dwarf, but I can't remember what."] = "| \"...Creo que hice algo con drunken dwarf, pero no recuerdo qué.",
    ["| \"You must be careful not to let drink muddle your brain!"] = "| \"¡Debes tener cuidado de no dejar que la bebida enturbie tu cerebro!",
    ["| Forgiveness of a Chaos Dwarf"] = "| El perdón de un enano del caos",
    ["| \"...And it turned out that Hilda had been the chaos dwarf we killed in the tower. Veldaban was devestated."] = "| \"...Y resultó que Hilda había sido el enano del caos que matamos en la torre. Veldaban estaba devastado\".",
    ["| \"Losing one's identity is worse than death."] = "| \"Perder la identidad es peor que la muerte\".",
    ["| The Fremennik Isles"] = "| Las islas Fremennik",
    ["| \"...I slew many trolls and brought the Troll King's head back to Neitiznot as a trophy."] = "| \"... Maté a muchos trolls y traje la cabeza del Rey Troll a Neitiznot como trofeo\".",
    ["| The Fremennik Trials"] = "| Los juicios de Fremennik",
    ["| \" ...And that was how I became an honourary member of the Fremennik, and was given my Fremennik name, <small>*(player's Fremennik name)*</small>."] = "| \"...Y así fue como me convertí en miembro honorario del Fremennik, y me dieron mi nombre de Fremennik, <small>*(nombre de Fremennik del jugador)*</small>\".",
    ["| From Tiny Acorns (miniquest)"] = "| De Tiny Acorns (minimisión)",
    ["| \"I completed another caper for the Lumbridge Thieves' Guild."] = "| \"Completé otra travesura para el gremio de ladrones Lumbridge\".",
    ["| Fur 'n Seek"] = "| Fur 'n buscar",
    ["| \"...So, I fetched all the furs the Odd Old Man wanted and he gave me a reward!"] = "| \"... Entonces, ¡busqué todas las pieles que quería el Odd Old Man y él me dio una recompensa!",
    ["| \"This Odd Old Man has some puzzling requests. I wonder about the motivations of his actions."] = "| \"Este Odd Old Man tiene algunas solicitudes desconcertantes. Me pregunto cuáles son las motivaciones de sus acciones\".",
    ["| Garden of Tranquillity"] = "| Jardín de la Tranquilidad",
    ["| \"...so the garden at Varrock palace is all my work!"] = "| \"... ¡así que el jardín del palacio Varrock es todo mi trabajo!",
    ["| \"It is good that you can take time from slaying and adventuring to grow a beautiful garden."] = "| \"Es bueno que puedas tomarte el tiempo de matar y aventurarte para cultivar un hermoso jardín\".",
    ["| The General's Shadow (miniquest)"] = "| La sombra del general (minimisión)",
    ["| \"I peered into the shadow realm and encountered General Khazard. I completed his assignment and earned the shadow sword."] = "| \"Miré hacia el reino de las sombras y me encontré con General Khazard. Completé su tarea y obtuve la espada de las sombras.",
    ["| Gertrude's Cat"] = "| El gato de Gertrude",
    ["| \"...I returned Fluffs safely to Gertrude and she gave me a cat of my own!"] = "| \"... ¡Devolví Fluffs sano y salvo a Gertrude y ella me dio mi propio gato!",
    ["| \"Cats are one of the most mysterious creatures of Guthix. I hope you take your responsibility seriously."] = "| \"Los gatos son una de las criaturas más misteriosas de Guthix. Espero que tomes en serio tu responsabilidad\".",
    ["| Ghosts Ahoy"] = "| Fantasmas a la vista",
    ["| \"...so the people of Port Phasmatys were finally able to rest."] = "| \"...así que la gente de Port Phasmatys finalmente pudo descansar.",
    ["| Ghosts from the Past (miniquest)"] = "| Fantasmas del pasado (minimisión)",
    ["| \"I visited the Islands That Once Were Turtles and discovered more than anyone would prefer to know about Quartermaster Gully's personal life."] = "| \"Visité las islas que alguna vez fueron tortugas y descubrí más de lo que nadie preferiría saber sobre la vida personal de Quartermaster Gully\".",
    ["| The Giant Dwarf"] = "| El enano gigante",
    ["| \"...the statue in Keldagrim was rebuilt and I witnessed a meeting of the Mining Consortium."] = "| \"...la estatua en Keldagrim fue reconstruida y fui testigo de una reunión del Consorcio Mining.",
    ["| \"I have a feeling that Keldagrim will be the setting of many great adventures for you."] = "| \"Tengo la sensación de que Keldagrim será el escenario de muchas grandes aventuras para ti\".",
    ["| Glorious Memories"] = "| Recuerdos gloriosos",
    ["| \"As soon as King Vargas had regained his human form, he set off on another adventure."] = "| \"Tan pronto como King Vargas recuperó su forma humana, se embarcó en otra aventura\".",
    ["| Goblin Diplomacy"] = "| Diplomacia duende",
    ["| \"...and so the goblins ended up wearing the armour colour they had to start off with!"] = "| \"...¡y así los goblins terminaron usando el color de armadura con el que tenían que empezar!",
    ["| \"Poor, silly goblins! Their race had such potential; if only they could rise above their petty squabbles."] = "| \"¡Pobres y tontos duendes! Su raza tenía mucho potencial; si tan solo pudieran superar sus pequeñas disputas.",
    ["| The Golem"] = "| El Golem",
    ["| \"...And I had to reprogram the golem before it would believe that the demon was dead."] = "| \"...Y tuve que reprogramar el golem antes de que creyera que el demonio estaba muerto.",
    ["| \"I remember well the battle of Uzer."] = "| \"Recuerdo bien la batalla de Uzer\".",
    ["| Gower Quest"] = "| Búsqueda de Gower",
    ["| \"...and that's how the Gowers repaired the life altar with my help and saved Behind the Scenes."] = "| \"...y así es como los Gowers repararon el altar de la vida con mi ayuda y salvaron Detrás de Escenas\".",
    ["| \"To believe such a place exists. I wonder if perhaps I will ever have chance  to visit."] = "| \"Creer que existe un lugar así. Me pregunto si quizás alguna vez tendré la oportunidad de visitarlo\".",
    ["| The Grand Tree"] = "| El gran árbol",
    ["| \"...Glough fled like the coward he really is, and the Grand Tree was saved!"] = "| \"...Glough huyó como el cobarde que realmente es, ¡y el Gran Árbol se salvó!",
    ["| The Great Brain Robbery"] = "| El gran robo de cerebros",
    ["| \"...but after the monks' brains had been restored, I had to fight an enormous abomination called Barrelchest!"] = "| \"...pero después de que los cerebros de los monjes fueron restaurados, ¡tuve que luchar contra una enorme abominación llamada Barrelchest!",
    ["| \"Zombies and brain-swapping? It is good that you stopped this disrespect for nature."] = "| \"¿Zombis e intercambio de cerebros? Es bueno que hayas puesto fin a esta falta de respeto por la naturaleza\".",
    ["| Grim Tales"] = "| Cuentos sombríos",
    ["| \"...so I found the golden goblin and cut down the beanstalk, and that was the end of that grim tale!"] = "| \"... así que encontré al duende dorado y corté el tallo de habichuelas, ¡y ese fue el final de esa sombría historia!",
    ["| A Guild of Our Own (miniquest)"] = "| Un gremio propio (minimisión)",
    ["| I completed another caper for the Lumbridge Thieves' Guild."] = "| Completé otra travesura para el gremio de ladrones Lumbridge.",
    ["| Gunnar's Ground"] = "| Tierra de Gunnar",
    ["| \"...and the chieftain agreed to settle on the land that his ancestors had won."] = "| \"...y el cacique accedió a establecerse en la tierra que sus antepasados ​​habían ganado.",
    ["| \"These militant Fremennik think they serve Guthix, but they serve only themselves."] = "| \"Estos militantes fremennik creen que sirven a Guthix, pero sólo se sirven a sí mismos\".",
    ["| The Hand in the Sand"] = "| La mano en la arena",
    ["| \"...so that was how I gave Bert a hand solving the murder and returned the wizard's head, solving the riddle of the ever-full sand pits!"] = "| \"... ¡Así fue como le di una mano a Bert para resolver el asesinato y le devolví la cabeza al mago, resolviendo el enigma de los siempre llenos pozos de arena!",
    ["| \"A victim dies and a murderer is punished - that is balance."] = "| \"La víctima muere y el asesino es castigado: eso es equilibrio.",
    ["| Harbinger (miniquest)"] = "| Heraldo (minimisión)",
    ["| \"I embarked on a voyage to the scholarly island of Tuai Leit. It didn't go entirely according to plan, and my ship was severely damaged by a mysterious new adversary."] = "| \"Me embarqué en un viaje a la erudita isla de Tuai Leit. No salió del todo según lo planeado y mi barco resultó gravemente dañado por un nuevo y misterioso adversario\".",
    ["| Haunted Mine"] = "| Mina embrujada",
    ["| \"...And from the legendary crystals I cut a salve shard to fight the undead."] = "| \"...Y de los cristales legendarios corté un fragmento de ungüento para luchar contra los no-muertos\".",
    ["| Hazeel Cult (Ceril's side)"] = "| Culto Hazeel (lado de Ceril)",
    ["| \"...that was how I foiled the cultists in their plan to resurrect Hazeel."] = "| \"...así fue como frustré a los cultistas en su plan de resucitar a Hazeel.",
    ["| \"The Mahjarrat are a vile race. You would do well to steer clear of them."] = "| \"Los Mahjarrat son una raza vil. Harías bien en mantenerte alejado de ellos\".",
    ["| Hazeel Cult (Hazeel's side)"] = "| Culto Hazeel (lado de Hazeel)",
    ["| \"...So that was how I helped return Hazeel to his followers."] = "| \"... Así fue como ayudé a que Hazeel regresara a sus seguidores\".",
    ["| Head of the Family (miniquest)"] = "| Jefe de familia (minimisión)",
    ["| \"I helped the moai of Waiko and Aminishi resolve their troubled long-distance relationship."] = "| \"Ayudé a los moai de Waiko y Aminishi a resolver su problemática relación a larga distancia\".",
    ["| \"...and as the prehistoric abyssal fell back into the portal, we learned that Xenia may have already started the elder gods re-awakening."] = "| \"...y cuando el abisal prehistórico volvió a caer en el portal, supimos que es posible que Xenia ya haya iniciado el despertar de los dioses mayores\".",
    ["| \"I am saddened that we have lost Xenia. She was a good woman in her own way. But perhaps you were right to stop her."] = "| \"Me entristece que hayamos perdido a Xenia. Ella era una buena mujer a su manera. Pero tal vez hiciste bien en detenerla\".",
    ["| Hearts of Sanguine"] = "| Corazones de sangre",
    ["| \"With the aid of a vampyre named Anya, I destroyed the sanguine heart near Wendlewick and saved the village from the blight it was spreading."] = "| \"Con la ayuda de un vampyre llamado Anya, destruí el corazón sanguíneo cerca de Wendlewick y salvé a la aldea de la plaga que se estaba propagando\".",
    ["| Heartstealer"] = "| ladrón de corazones",
    ["| \"We may not have stolen a priceless ruby, but I helped Annette steal Caelyn's heart."] = "| \"Puede que no hayamos robado un rubí de valor incalculable, pero ayudé a Annette a robar el corazón de Caelyn\".",
    ["| Heralds of Crimson"] = "| Heraldos de carmesí",
    ["| \"...and so we teamed up to defeat the Ghrazi Blood Knights! Unfortunately, one of them escaped and closed the portal, stranding Anya on Gielinor."] = "| \"... ¡y así nos unimos para derrotar a los Caballeros de Sangre Ghrazi! Desafortunadamente, uno de ellos escapó y cerró el portal, dejando varado a Anya en Gielinor\".",
    ["| \"You do make some questionable friends, but I am glad to hear Havenhythe is well protected."] = "| \"Haces algunos amigos cuestionables, pero me alegra saber que Havenhythe está bien protegida\".",
    ["| Hermit Permits"] = "| Permisos Hermit",
    ["| \"I helped the villagers of Wendlewick to solve their crab problem."] = "| \"Ayudé a los aldeanos de Wendlewick a resolver el problema de los cangrejos\".",
    ["| Helping Laniakea (miniquest)"] = "| Ayudando a Laniakea (minimisión)",
    ["| \"I helped Laniakea find a Fugu so she could make a very potent poison."] = "| \"Ayudé a Laniakea a encontrar un Fugu para que pudiera producir un veneno muy potente\".",
    ["| Hero's Welcome"] = "| Bienvenida del héroe",
    ["| \"...but in the end V is still dead, even though the  Tarshak paid the price."] = "| \"...pero al final V sigue muerto, a pesar de que Tarshak pagó el precio\".",
    ["| \"The world is safer for that monster's passing. I am sure V would be proud."] = "| \"El mundo es más seguro tras la muerte de ese monstruo. Estoy seguro de que V estaría orgulloso\".",
    ["| Heroes' Quest"] = "| Búsqueda de héroes",
    ["| \"...so, after I had retrieved all the items, I became a member of the Heroes' Guild!"] = "| \"...así que, después de haber recuperado todos los artículos, ¡me convertí en miembro de Heroes' Guild!",
    ["| Holy Grail"] = "| Santo Grial",
    ["| \"...and out of all the Knights of the Round Table, it was I who found the Holy Grail."] = "| \"...y de todos los Caballeros de la Mesa Redonda, fui yo quien encontró el Santo Grial.",
    ["| Hopespear's Will (miniquest)"] = "| Voluntad de Hopespear (minimisión)",
    ["| \"I buried five goblin priests for the ghost of Hopespear, laying their souls to rest."] = "| \"Enterré a cinco sacerdotes duendes para el fantasma de Hopespear, haciendo descansar sus almas\".",
    ["| Horror from the Deep"] = "| Terror desde las profundidades",
    ["| \"...And that was the end of the horror from the deep!"] = "| \"... ¡Y ese fue el fin del horror de las profundidades!",
    ["| Housing of Parliament"] = "| Vivienda del Parlamento",
    ["| \"I cleaned up the City of Um's owlery, and enticed some owls back to the city."] = "| \"Limpié la lechucería de City of Um y atraje a algunas lechuzas a la ciudad\".",
    ["| Hunt for Red Raktuber"] = "| Caza del Raktuber rojo",
    ["| \"...and then Larry was kidnapped by the penguins and I had to swim on a polar bear to get back to the mainland."] = "| \"...y luego Larry fue secuestrado por los pingüinos y tuve que nadar sobre un oso polar para regresar al continente\".",
    ["| \"Those penguins are shifty characters."] = "| \"Esos pingüinos son personajes astutos\".",
    ["| The Hunt for Surok (miniquest)"] = "| La caza de Surok (minimisión)",
    ["| \"I hunted down Surok Magis in the Chaos Tunnels, and encountered a big ork."] = "| \"Perseguí a Surok Magis en los Túneles del Caos y me encontré con un gran orko\".",
    ["| Icthlarin's Little Helper"] = "| El pequeño ayudante de Icthlarin",
    ["| \"...And, with the amulet I received, I could understand the language of cats!"] = "| \"... ¡Y con el amuleto que recibí, pude entender el lenguaje de los gatos!",
    ["| \"It is a rare privilege to understand the language of those beings. You should listen carefully to all they have to say - but not believe too much of it."] = "| \"Es un raro privilegio entender el lenguaje de esos seres. Hay que escuchar atentamente todo lo que tienen que decir, pero no creer demasiado en ello\".",
    ["| Imp Catcher"] = "| Cazador de diablillos",
    ["| \"...took some time, but I finally got all four beads back, and Mizgog gave me my reward."] = "| \"...me tomó algo de tiempo, pero finalmente recuperé las cuatro cuentas y Mizgog me dio mi recompensa\".",
    ["| \"Imps! I remember the age of great war, when armies of Zamorak's imps bloodied the ankles of the other gods' creatures."] = "| \"¡Diablillos! Recuerdo la época de las grandes guerras, cuando los ejércitos de diablillos de Zamorak ensangrentaban los tobillos de las criaturas de los otros dioses\".",
    ["| Impressing the Locals"] = "| Impresionando a los lugareños",
    ["| \"...and so now I'm the captain of the Sarim's Revenge, with a motley crew under my command."] = "| \"...y ahora soy el capitán del Sarim's Revenge, con una tripulación heterogénea bajo mi mando\".",
    ["| \"Guthix visited these Wushanko Isles when he first arrived, but he did not tell me much of his time there."] = "| \"Guthix visitó estas islas Wushanko cuando llegó por primera vez, pero no me contó mucho sobre su tiempo allí\".",
    ["| In Aid of the Myreque"] = "| En ayuda del Myreque",
    ["| \"...Veliaf was very impressed by the Rod of Ivandis, and I can use it to kill juves and the juvinates!"] = "| \"...Veliaf quedó muy impresionado con la Vara de Ivandis, ¡y puedo usarla para matar a los juves y a los juvinates!",
    ["| In Memory of the Myreque (miniquest)"] = "| En Memoria del Myreque (minimisión)",
    ["| \"I constructed a memorial to the Myreque."] = "| \"Construí un monumento al Myreque\".",
    ["| In Pyre Need"] = "| En necesidad de pira",
    ["| \"...And that was how I helped the phoenix to be reborn!"] = "| \"... ¡Y así fue como ayudé al fénix a renacer!",
    ["| \"You have performed a service to one of the creatures of Guthix, and for that I thank you."] = "| \"Has prestado un servicio a una de las criaturas de Guthix, y te lo agradezco\".",
    ["| In Search of the Myreque"] = "| En busca del Myreque",
    ["| \"...so, I suppose it was my fault that the young members of the Myreque were killed by Vanstrom."] = "| \"...entonces, supongo que fue mi culpa que los jóvenes miembros del Myreque fueran asesinados por Vanstrom.",
    ["| The Jack of Spades"] = "| La jota de espadas",
    ["| \"...but it was just Ozan in disguise, and he only wanted to meet away from watchful eyes and to show me the corruption in Menaphos."] = "| \"...pero era sólo Ozan disfrazado, y él sólo quería encontrarse lejos de miradas atentas y mostrarme la corrupción en Menaphos\".",
    ["| \"The souls of humans are so easily corrupted, especially of those who have no friends."] = "| \"Las almas de los humanos se corrompen muy fácilmente, especialmente las de aquellos que no tienen amigos.",
    ["| Jed Hunter (miniquest)"] = "| Jed Hunter (minimisión)",
    ["| \"I hunted down and defeated Jed, and claimed vengeance for the people of Port Sarim."] = "| \"Perseguí y derroté a Jed, y reclamé venganza para la gente de Port Sarim\".",
    ["| Jungle Potion"] = "| Poción de la selva",
    ["| \"...and once I had gathered all the herbs, Trufitus Shakaya was able to commune with his gods."] = "| \"...y una vez que reuní todas las hierbas, Trufitus Shakaya pudo comunicarse con sus dioses\".",
    ["| Kennith's Concerns"] = "| Preocupaciones de Kennith",
    ["| \"...And my last step was to bring Kennith his toy train."] = "| \"...Y mi último paso fue traerle a Kennith su tren de juguete\".",
    ["| Kili Row"] = "| Fila Kili",
    ["| \"I met the City of Um's blacksmith, and learned how to upgrade my necromancer's equipment."] = "| \"Conocí al herrero de City of Um y aprendí a mejorar mi equipo de nigromante\".",
    ["| Kindred Spirits"] = "| Espíritus afines",
    ["| \"I escaped Sliske's twisted game with the Barrows Brothers. Sadly Linza was turned into a wight in the process."] = "| \"Escapé del retorcido juego de Sliske con los hermanos Barrows. Lamentablemente, Linza se convirtió en un monstruo en el proceso\".",
    ["| King of the Dwarves"] = "| rey de los enanos",
    ["| \"...So now Veldaban is the king of the dwarves"] = "| \"...Así que ahora Veldaban es el rey de los enanos",
    ["| \"...You may have had noble motives, but you have robbed the rightful king of his throne. This action is not balanced."] = "| \"...Puede que hayas tenido motivos nobles, pero le has robado el trono al legítimo rey. Esta acción no es equilibrada\".",
    ["| King's Ransom"] = "| El rescate del rey",
    ["| \"...And after I had used the spell to free King Arthur, I disguised him as a guard so he could escape."] = "| \"...Y después de haber usado el hechizo para liberar a King Arthur, lo disfrazé de guardia para que pudiera escapar\".",
    ["| The Knight's Sword"] = "| La espada del caballero",
    ["| \"...that was how I found the Imcando Dwarves and got the knight a new sword."] = "| \"... así fue como encontré a los Enanos Imcando y le conseguí al caballero una nueva espada\".",
    ["| Koschei's Troubles (miniquest)"] = "| Los problemas de Koschei (minimisión)",
    ["| \"I discovered the mysterious origin of Koschei the Deathless."] = "| \"Descubrí el misterioso origen de Koschei el Inmortal.",
    ["| Lair of Tarn Razorlor (miniquest)"] = "| Guarida de Tarn Razorlor (minimisión)",
    ["| \"I defeated Tarn Razorlor and learned his secret knowledge by reading the diary in his living quarters."] = "| \"Derroté a Tarn Razorlor y aprendí su conocimiento secreto leyendo el diario en su vivienda\".",
    ["| Land of the Goblins"] = "| Tierra de los duendes",
    ["| \"...Oldak and I escaped from Yu'biusk before the portal closed, but Zanik was trapped in the box."] = "| \"...Oldak y yo escapamos de Yu'biusk antes de que se cerrara el portal, pero Zanik quedó atrapado en la caja\".",
    ["| (Before The Chosen Commander)"] = "| (Ante el comandante elegido)",
    ["| Legacy of Seergaze"] = "| El legado de la mirada vidente",
    ["| \"...I slew a Vyrewatch, as Safalaan had asked, and took the corpse to the Paterdomus Columbarium to cremate it. In gratitude the spirit left a key which allowed me to gain access to their worldly wealth. My first prize was a blood talisman!"] = "| \"... Maté un Vyrewatch, como me había pedido Safalaan, y llevé el cadáver al Columbario Paterdomus para cremarlo. En agradecimiento, el espíritu dejó una llave que me permitió acceder a sus riquezas mundanas. ¡Mi primer premio fue un talismán de sangre!",
    ["| \"With your mind so focused on material wealth, I worry whether the intrigues overshadowing your discoveries are being properly looked into. Drakan, I fear, is a whole world of trouble for which you are ill-prepared."] = "| \"Con tu mente tan concentrada en la riqueza material, me preocupa si las intrigas que ensombrecen tus descubrimientos están siendo investigadas adecuadamente. Me temo que Drakan es todo un mundo de problemas para los cuales no estás preparado\".",
    ["| Legends' Quest"] = "| Búsqueda de leyendas",
    ["| \"...and when I had completed all the tasks, I became a member of the Legends' Guild!"] = "| \"...y cuando hube completado todas las tareas, ¡me convertí en miembro de Legends' Guild!",
    ["| Let Them Eat Pie"] = "| Déjalos comer pastel",
    ["| \"...and in the end Rolo's food stores were given to the people of Burthorpe to enjoy."] = "| \"...y al final las tiendas de alimentos de Rolo fueron entregadas a la gente de Burthorpe para que las disfrutara\".",
    ["| \"So the hungry became fed and the overfed became...well, empty. Guthix might not approve of the methods used, but a balance has been struck."] = "| \"Así que los hambrientos se alimentaron y los sobrealimentados quedaron... bueno, vacíos. Puede que Guthix no apruebe los métodos utilizados, pero se ha logrado un equilibrio\".",
    ["| The Light Within"] = "| La luz interior",
    ["| \"I helped return the light of Seren to the world by reforging her body and soul."] = "| \"Ayudé a devolver la luz de Seren al mundo reformando su cuerpo y su alma\".",
    ["| The Lord of Vampyrium"] = "| El Señor del Vampyrium",
    ["| \"...so with most of the Myreque killed by Lord Drakan, Veliaf has given up hope, and Ivan has returned to Paterdomus. The Myreque are broken."] = "| \"... así que con la mayoría de los Myreque asesinados por Lord Drakan, Veliaf ha perdido la esperanza y Ivan ha regresado a Paterdomus. Los Myreque están rotos\".",
    ["| \"Even in death, the Myreque light the way for the people of Morytania. Anything is lost can be found again, even hope. Stay strong, Player."] = "| \"Incluso en la muerte, los Myreque iluminan el camino para la gente de Morytania. Todo lo que se pierde se puede encontrar de nuevo, incluso la esperanza. Mantente fuerte, Player\".",
    ["| Lost City"] = "| ciudad perdida",
    ["| \"...And when I entered the door carrying the Dramen Staff, I was transported to a whole new world - a world populated by magical fairies!"] = "| \"...Y cuando entré por la puerta llevando el Dramen Staff, fui transportado a un mundo completamente nuevo: ¡un mundo poblado por hadas mágicas!",
    ["| Lost Her Marbles (miniquest)"] = "| Perdió sus canicas (minimisión)",
    ["| The Lost Toys (miniquest)"] = "| Los juguetes perdidos (minimisión)",
    ["| \"I hunted down and hugged 13 vampyre plushies hidden throughout Morytania."] = "| \"Busqué y abracé 13 peluches de vampyre escondidos por todo Morytania\".",
    ["| The Lost Tribe"] = "| La tribu perdida",
    ["| \"...Sigmund was dismissed, and the duke and the ruler of the cave goblins signed a peace treaty."] = "| \"...Sigmund fue despedido, y el duque y el gobernante de los duendes de las cavernas firmaron un tratado de paz\".",
    ["| \"The Dorgueshuun goblins have been good neighbours during my vigil here. They are a timid race, but not cowardly, and I am glad they have the peace they desire."] = "| \"Los duendes Dorgueshuun han sido buenos vecinos durante mi vigilia aquí. Son una raza tímida, pero no cobarde, y me alegro de que tengan la paz que desean\".",
    ["| Love Story"] = "| Historia de amor",
    ["| \"...so the Wise Old Man and Zenevivia are living happily ever after, but they still wouldn't give me that hat!"] = "| \"...así que Wise Old Man y Zenevivia viven felices para siempre, ¡pero aun así no me dieron ese sombrero!",
    ["A hat is just a hat Player."] = "Un sombrero es sólo un sombrero Player.",
    ["To which you reply: \"Grr!"] = "A lo que respondes: \"¡Grr!",
    ["| Lunar Diplomacy"] = "| Diplomacia lunar",
    ["| \"...so I defeated my mirror image, won the respect of the Moon Clan and persuaded them to communicate with the Fremennik."] = "| \"... así que derroté a mi imagen reflejada, me gané el respeto del Clan de la Luna y los persuadí para que se comunicaran con los Fremennik\".",
    ["| \"The Moon Clan's reliance on magic is no more balanced than the Fremennik's hatred of it."] = "| \"La dependencia del Clan de la Luna en la magia no es más equilibrada que el odio de los Fremennik hacia ella.",
    ["| Making History"] = "| Haciendo historia",
    ["| \"...so the outpost became a museum."] = "| \"...así que el puesto de avanzada se convirtió en un museo\".",
    ["| \"History is the greatest story of all, and it is very good that you have helped to preserve it."] = "| \"La historia es la historia más grande de todas y es muy bueno que hayan ayudado a preservarla\".",
    ["| Mahjarrat Memories (miniquest)"] = "| Recuerdos de Mahjarrat (minimisión)",
    ["| \"I helped Kharshai the Mahjarrat recover 15 memories of his kin."] = "| \"Ayudé a Kharshai el Mahjarrat a recuperar 15 recuerdos de sus parientes\".",
    ["| Meeting History"] = "| Historial de reuniones",
    ["| \"...And that was how I travelled into the past and met the first family to arrive on Gielinor."] = "| \"...Y así fue como viajé al pasado y conocí a la primera familia que llegó a Gielinor\".",
    ["| \"You have been truly blessed by Guthix. I can only dream of such an honour."] = "| \"Has sido realmente bendecido por Guthix. Sólo puedo soñar con tal honor\".",
    ["| Merlin's Crystal"] = "| El cristal de Merlín",
    ["| \"...and when I told King Arthur that I had single-handedly freed Merlin from his crystal prison, he made me a knight of the Round Table!"] = "| \"...y cuando le dije a King Arthur que yo solo había liberado a Merlín de su prisión de cristal, ¡me nombró caballero de la Mesa Redonda!",
    ["| The Mighty Fall (sparing Zanik)"] = "| La poderosa caída (ahorrando a Zanik)",
    ["| \"...and then I defeated Graardor, and so Zanik became leader of the Bandosians. She led many of them away on an exodus into Yu'biusk, hoping to find either peace or death."] = "| \"...y luego derroté a Graardor, y así Zanik se convirtió en líder de los bandosianos. Ella condujo a muchos de ellos en un éxodo a Yu'biusk, con la esperanza de encontrar la paz o la muerte\".",
    ["| \"I will miss Zanik. I am shamed by my condemnation of her. In the end her heroism shone through. Between you, you have neutralised the remaining Bandosian imbalance."] = "| \"Extrañaré a Zanik. Me avergüenza haberla condenado. Al final, su heroísmo brilló. Entre ustedes, habéis neutralizado el desequilibrio bandosiano restante\".",
    ["| The Mighty Fall (killing Zanik)"] = "| La poderosa caída (matando a Zanik)",
    ["| \"...and then, uh, Zanik died, and so Graardor became leader of the Bandosians. Some of them returned to Gielinor and some remained on Yu'biusk"] = "| \"...y luego, eh, Zanik murió, y así Graardor se convirtió en líder de los bandosianos. Algunos de ellos regresaron a Gielinor y otros permanecieron en Yu'biusk",
    ["| \"I will miss Zanik. I am shamed by my condemnation of her. At least you seem to have neutralised the Bandosian imbalance. Graardor will not be much of a leader."] = "| \"Extrañaré a Zanik. Me avergüenza haberla condenado. Al menos parece que has neutralizado el desequilibrio bandosiano. Graardor no será un gran líder\".",
    ["| Missing My Mummy"] = "| Extrañando a mi mamá",
    ["| \"...So, I was able to restore the mummy enough to make sense of what she was saying."] = "| \"... Entonces, pude restaurar la momia lo suficiente como para darle sentido a lo que estaba diciendo\".",
    ["| \"To have your body, spirit and shadow scattered by time must be a terrible thing. It is good that you have helped ease the mummy's torment by restoring her."] = "| \"Tener tu cuerpo, espíritu y sombra esparcidos por el tiempo debe ser algo terrible. Es bueno que hayas ayudado a aliviar el tormento de la momia restaurándola\".",
    ["| Missing, Presumed Death"] = "| Desaparecido, presunta muerte",
    ["| \"...and that's how Icthlarin and I saved Death. But not before Sliske could deliver his challenge: that the person to kill the most gods would receive the Stone of Jas."] = "| \"...y así fue como Icthlarin y yo salvamos a la Muerte. Pero no antes de que Sliske pudiera cumplir su desafío: que la persona que matara a la mayor cantidad de dioses recibiría la Piedra de Jas\".",
    ["| \"I'm glad you found Death. He is a devoted Guardian of Guthix. Alas, it seems that with Guthix gone and his edicts no longer in place, another God Wars is on the horizon."] = "| \"Me alegro de que hayas encontrado a la Muerte. Es un devoto guardián de Guthix. Por desgracia, parece que con Guthix desaparecido y sus edictos ya no vigentes, otra Guerra de Dios está en el horizonte\".",
    ["| Monk's Friend"] = "| Amigo del monje",
    ["| \"...so the monks had a drunken party to celebrate the child's birthday."] = "| \"... entonces los monjes organizaron una fiesta de borracheras para celebrar el cumpleaños del niño\".",
    ["Mirth should not be taken to excess. These Saradominists have never understood the importance of balance."] = "La alegría no debe llevarse al exceso. Estos saradoministas nunca han entendido la importancia del equilibrio\".",
    ["To which you reply: \"Also, although they'd brought plenty of alcohol, I never saw them getting anything for the child to drink."] = "A lo que usted responde: \"Además, aunque habían traído mucho alcohol, nunca los vi trayendo nada para que bebiera el niño\".",
    ["| \"...So I defeated the Jungle Demon and stopped the Monkeys' plot to take over Karamja."] = "| \"... Así que derroté al Demonio de la Selva y detuve el complot de los Monos para apoderarse de Karamja\".",
    ["I see they couldn't make a monkey out of you!"] = "¡Veo que no podrían convertirte en un mono!",
    ["To which you reply: \"Well, actually, I was a monkey for a bit."] = "A lo que respondes: \"Bueno, en realidad, fui mono por un tiempo\".",
    ["| Mountain Daughter"] = "| Hija de la montaña",
    ["| \"...I was too late to save the chieftan's daughter, but at least I gave her a proper burial."] = "| \"... Llegué demasiado tarde para salvar a la hija del cacique, pero al menos le di un entierro adecuado\".",
    ["| \"Brief is life, but more precious if its passing is properly honoured."] = "| \"Breve es la vida, pero más preciosa si se honra adecuadamente su paso.",
    ["| Mourning's End Part I"] = "| Mourning's End Parte I",
    ["| \"...after I had told the Head Mourner I had poisoned the city, he told me about the lost temple in the mountains that they're searching for."] = "| \"...después de haberle dicho al Jefe Mourner que había envenenado la ciudad, él me habló del templo perdido en las montañas que estaban buscando\".",
    ["| Mourning's End Part II"] = "| Mourning's End Parte II",
    ["| \"...What kind of twisted mind would come up with the light-beam puzzle in that temple?"] = "| \"... ¿A qué clase de mente retorcida se le ocurriría el rompecabezas del rayo de luz en ese templo?",
    ["| Murder on the Border"] = "| Asesinato en la frontera",
    ["| \"I solved the mystery behind Duke Hoarse's murder, and unraveled a plot to assassinate King Roald."] = "| \"Resolví el misterio detrás del asesinato de Duke Hoarse y desentrañé un complot para asesinar a King Roald\".",
    ["| Murder Mystery"] = "| Misterio del asesinato",
    ["| \"...And that's how I solved the murder of Lord Sinclair."] = "| \"...Y así es como resolví el asesinato de Lord Sinclair.",
    ["| My Arm's Big Adventure"] = "| La gran aventura de My Arm",
    ["| \"...My Arm is still up on that rooftop, growing goutweed in his little farming patch!"] = "| \"...¡My Arm todavía está en esa azotea, cultivando gota en su pequeño huerto!",
    ["| \"it is good that a troll wishes to study the complex skill that is Farming."] = "| \"Es bueno que un troll desee estudiar la compleja habilidad que es Farming\".",
    ["| Myths of the White Lands"] = "| Mitos de las Tierras Blancas",
    ["| \"...I went through the snow imps' prank. Explorer Jack had no idea the 'riches' were really frozen yeti dung!"] = "| \"...Pasé por la broma de los diablillos de nieve. ¡Explorer Jack no tenía idea de que las 'riquezas' eran en realidad estiércol de yeti congelado!",
    ["| \"It is pleasant to hear that the snow imps are still up to their old tricks."] = "| \"Es agradable saber que los diablillos de las nieves siguen haciendo sus viejos trucos.",
    ["| \"I listened to Skaldrun's saga of Moia, the half-Mahjarrat daughter of Lucien, and her descent into Daemonheim."] = "| \"Escuché la saga de Skaldrun sobre Moia, la hija medio Mahjarrat de Lucien, y su descenso a Daemonheim\".",
    ["| Nature Spirit"] = "| Naturaleza Spirit",
    ["| \"...and that was how I helped Filliman Tarlock transform into a nature spirit."] = "| \"...y así fue como ayudé a Filliman Tarlock a transformarse en un espíritu de la naturaleza\".",
    ["| \"It is good that you helped a servant of Guthix to his rest."] = "| \"Es bueno que hayas ayudado a descansar a un sirviente de Guthix\".",
    ["| \"After being killed by an animated sword, and a quick visit to Death's office, Death took me to the City of Um. There we witnessed Rasial, the first necromancer, stealing all of its souls."] = "| \"Después de ser asesinado por una espada animada y de una rápida visita a la oficina de la Muerte, la Muerte me llevó al City of Um. Allí fuimos testigos de Rasial, the first necromancer, robando todas sus almas\".",
    ["| The Needle Skips"] = "| La aguja salta",
    ["| \"...and that was how I learned the secrets of the Needle and the impact on that poor family."] = "| \"...y así fue como aprendí los secretos de la Aguja y el impacto en esa pobre familia.",
    ["| \"Elder artefacts can be dangerous things, in more ways that the physical."] = "| \"Los artefactos antiguos pueden ser cosas peligrosas, en más formas que las físicas\".",
    ["| New Foundations"] = "| Nuevas fundaciones",
    ["| \"I helped King Roald establish a new Duchy in the Wilderness which I now manage."] = "| \"Ayudé a King Roald a establecer un nuevo Ducado en Wilderness que ahora administro\".",
    ["| Nomad's Elegy"] = "| Elegía del nómada",
    ["| \"...allowing the souls of the dead to move on without being stolen by Nomad."] = "| \"...permitiendo que las almas de los muertos sigan adelante sin ser robadas por Nomad.",
    ["| \"A noble goal. His false Guthix and wicked scheme brought great unbalance to the underworld."] = "| \"Un objetivo noble. Su falso Guthix y su perverso plan trajeron un gran desequilibrio al inframundo\".",
    ["| Nomad's Requiem"] = "| Réquiem del nómada",
    ["| \"...And, finally, Nomad fell before me."] = "| \"...Y, finalmente, Nomad cayó ante mí.",
    ["| \"Impressive...Most impressive."] = "| \"Impresionante...Muy impresionante.",
    ["| Observatory Quest"] = "| Búsqueda del Observatorio",
    ["| \"...and, when I had fixed the telescope, I looked through and saw the stars."] = "| \"...y, cuando hube arreglado el telescopio, miré a través de él y vi las estrellas.",
    ["| \"It is long since I have seen the stars."] = "| \"Hace mucho que no veo las estrellas.",
    ["| Ode of the Devourer"] = "| Oda del Devorador",
    ["| \"With the aid of Icthlarin and Zemouregal, I cleansed the Gate of Elidinis and saved Bill and the citizens of Al Kharid from Amascut's curse."] = "| \"Con la ayuda de Icthlarin y Zemouregal, limpié la Puerta de Elidinis y salvé a Bill y a los ciudadanos de Al Kharid de la maldición de Amascut\".",
    ["| Olaf's Quest"] = "| La búsqueda de Olaf",
    ["| \"...It wasn't easy, but I managed to convince Olaf's family that he was a good navigator."] = "| \"...No fue fácil, pero logré convencer a la familia de Olaf de que era un buen navegante\".",
    ["| Once Upon a Slime"] = "| Érase una vez un limo",
    ["| \"\"I helped Peter eliminate the King Slime threat.\";"] = "| \"\"Ayudé a Peter a eliminar la amenaza King Slime.\";",
    ["| Once Upon a Time in Gielinor"] = "| Érase una vez en Gielinor",
    ["| \"...and that's how Relomia went from being Sliske's emissary to a renowned heroic adventurer."] = "| \"...y así fue como Relomia pasó de ser el emisario de Sliske a un reconocido heroico aventurero\".",
    ["| \"It goes to show the transformative power of stories. Thank you for sharing this with me."] = "| \"Esto demuestra el poder transformador de las historias. Gracias por compartir esto conmigo\".",
    ["| One Foot in the Grave (miniquest)"] = "| Un pie en la tumba (minimisión)",
    ["| \"I lent the Yanille wizards' guild another hand by finding (most of) Clarence's remaining body parts. We managed to put all but one foot in the grave, and I had to hand it to the Yanille wizards...it was quite a touching funeral."] = "| \"Le presté otra mano al gremio de magos de Yanille al encontrar (la mayoría de) las partes restantes del cuerpo de Clarence. Logramos poner todos menos un pie en la tumba, y tuve que entregárselo a los magos de Yanille... fue un funeral bastante conmovedor\".",
    ["| One of a Kind (siding with Kerapac)"] = "| Único en su clase (del lado de Kerapac)",
    ["| \"...and after defeating the Echo of an Elder God, I encouraged Hannibus to return with Kerapac and endure stasis so that he had a chance to save his people."] = "| \"...y después de derrotar al Eco de un Dios Antiguo, animé a Hannibus a regresar con Kerapac y soportar la estasis para tener la oportunidad de salvar a su pueblo\".",
    ["| \"You fought the will of an Elder God and allowed the Dragonkin to experiment on the last of the Dragon Riders? I fear that there might be unforeseen repercussions Player."] = "| \"¿Luchaste contra la voluntad de un Dios anciano y permitiste que los Dragonkin experimentaran con el último de los Jinetes de Dragón? Me temo que podría haber repercusiones imprevistas Player\".",
    ["| One of a Kind (siding with Sharrigan)"] = "| Único en su clase (del lado de Sharrigan)",
    ["| \"...and after defeating the Echo of an Elder God, I encouraged Hannibus to return with his people and allow himself to rest amongst his own kind."] = "| \"...y después de derrotar al Eco de un Dios Antiguo, animé a Hannibus a regresar con su gente y permitirse descansar entre los de su propia especie\".",
    ["| \"The Ilujanka sound like a noble species, it is a shame that they are dying out. I wonder if this is the last we'll see of them however."] = "| \"Los Ilujanka parecen una especie noble, es una pena que estén desapareciendo. Sin embargo, me pregunto si será la última vez que los veremos.",
    ["| One Piercing Note"] = "| Una nota penetrante",
    ["| \"...and that's how I caught the Citharede Abbey murderer."] = "| \"...y así fue como atrapé al asesino de Citharede Abbey\".",
    ["| \"Of course, I worked out who the murderer was half way through your story."] = "| \"Por supuesto, descubrí quién era el asesino a mitad de tu historia\".",
    ["| One Small Favour"] = "| Un pequeño favor",
    ["| \"...I still can't believe how long that 'one small favour' took me!"] = "| \"...¡Todavía no puedo creer cuánto tiempo me tomó ese 'un pequeño favor'!",
    ["| Osseous Rex"] = "| Óseo Rex",
    ["| \"...and that's how I helped resurrect the old matriarch, Osseous."] = "| \"...y así fue como ayudé a resucitar a la vieja matriarca, Osseous\".",
    ["| \"A great being walks among us once more."] = "| \"Un gran ser camina entre nosotros una vez más.",
    ["| Our Man in the North"] = "| Nuestro hombre en el norte",
    ["| \"...and now everyone knows that Osman is the rightful ruler of Menaphos, but also has been exiled from Al Kharid."] = "| \"...y ahora todo el mundo sabe que Osman es el gobernante legítimo de Menaphos, pero también ha sido exiliado de Al Kharid\".",
    ["| \"While in some cultures blood might decree a right to rule, it rarely suggests ability or competence."] = "| \"Si bien en algunas culturas la sangre puede decretar el derecho a gobernar, rara vez sugiere capacidad o competencia\".",
    ["| The Path of Glouphrie"] = "| El camino de Gloufrie",
    ["| \"...The room filled up with gas and I nearly died, but Hazelmere came to my rescue."] = "| \"...La habitación se llenó de gas y casi muero, pero Hazelmere vino a rescatarme\".",
    ["| \"A truly exciting tale of failing and needing to be rescued."] = "| \"Una historia realmente emocionante sobre el fracaso y la necesidad de ser rescatados.",
    ["| Perils of Ice Mountain"] = "| Peligros de la montaña de hielo",
    ["| \"...So now Nurmof's pickaxe machine is powered by a windmill."] = "| \"... Así que ahora la máquina pico de Nurmof funciona con un molino de viento\".",
    ["| \"You acted as a true servant of Guthix in this matter."] = "| \"Actuaste como un verdadero servidor de Guthix en este asunto\".",
    ["| Pharaoh's Folly"] = "| La locura del faraón",
    ["| \"...and that's how I helped overthrow the Pharaoh of Menaphos. Again."] = "| \"...y así es como ayudé a derrocar al faraón de Menaphos. Otra vez\".",
    ["| \"We can hope that the cycle of destruction in Menaphos is broken."] = "| \"Podemos esperar que se rompa el ciclo de destrucción en Menaphos\".",
    ["| 'Phite Club"] = "| 'Club de Fito",
    ["| \"...and then I defeated the Pharoah  and ripped off his mask, revealing the corruption beneath."] = "| \"...y luego derroté al Faraón y le arranqué la máscara, revelando la corrupción que había debajo\".",
    ["| \"But the problem is that the corruption didn't end at the Pharaoh..."] = "| \"Pero el problema es que la corrupción no terminó en el faraón...",
    ["| Pieces of Hate"] = "| pedazos de odio",
    ["| \"...and then I plugged the portal. Literally."] = "| \"...y luego conecté el portal. Literalmente\".",
    ["| \"Unspeakable horror lies beyond but, at least for now, you won't be having kittens."] = "| \"Más allá se esconde un horror indescriptible, pero, al menos por ahora, no tendrás gatitos\".",
    ["| Pirate's Treasure"] = "| El tesoro de Pirate",
    ["| \"...And when I dug in the middle of the park in Falador, I found the pirate's treasure!"] = "| \"... ¡Y cuando cavé en medio del parque en Falador, encontré el tesoro del pirata!",
    ["| \"Such is ever the folly of pirates, to bury their loot in the ground so that another can dig it up."] = "| \"Esa es siempre la locura de los piratas: enterrar su botín en la tierra para que otro pueda desenterrarlo\".",
    ["| \"...And that was how I rescued Elena from West Ardougne."] = "| \"...Y así fue como rescaté a Elena de West Ardougne\".",
    ["| Plague's End"] = "| El fin de la plaga",
    ["| \"...so at last the Dark Lord was dead, Ardougne was free of the plague, and the elves could re-grow their city!"] = "| \"... ¡así que por fin el Señor Oscuro estaba muerto, Ardougne estaba libre de la plaga y los elfos podían volver a hacer crecer su ciudad!",
    ["That was the end of - perhaps - your most epic adventure, Player."] = "Ese fue el final de, quizás, tu aventura más épica, Player\".",
    ["What started as the rescue of one woman took you across the mountains, and had you take part in the fates of kingdoms."] = "Lo que comenzó como el rescate de una mujer te llevó a través de las montañas y te hizo participar en el destino de los reinos\".",
    ["I can only admire your perseverance."] = "Sólo puedo admirar tu perseverancia\".",
    ["| Priest in Peril"] = "| Sacerdote en peligro",
    ["| \"...but with Drezel's help I was able to purify the River Salve."] = "| \"...pero con la ayuda de Drezel pude purificar el río Salve.",
    ["| Prince Ali Rescue (Removed)"] = "| Rescate del Príncipe Ali (eliminado)",
    ["| \"...And I had to disguise Prince Ali as a woman in order to smuggle him out!"] = "| \"... ¡Y tuve que disfrazar al Príncipe Ali de mujer para poder sacarlo clandestinamente!",
    ["| Princess and the Pauper"] = "| La princesa y el mendigo",
    ["| \"I took Princess for a very eventful walk around Varrock."] = "| \"Llevé a Princess a dar un paseo lleno de acontecimientos por Varrock\".",
    ["| The Prisoner of Glouphrie"] = "| El prisionero de Glouphrie",
    ["| \"...and that's how Bolrie was reunited with his family."] = "| \"...y así fue como Bolrie se reunió con su familia.",
    ["| \"Bringing families back together is a noble cause; however, what you tell me of the city of Arposandra is a crime towards nature and balance, and it worries me greatly."] = "| \"Reunir a las familias es una causa noble; sin embargo, lo que me cuentas de la ciudad de Arposandra es un crimen contra la naturaleza y el equilibrio, y me preocupa mucho.",
    ["| Purple Cat (miniquest)"] = "| Gato Púrpura (minimisión)",
    ["| \"In exchange for helping Wendy the witch, and her best friend, Lottie, I learned how to permanently dye my pet cat purple."] = "| \"A cambio de ayudar a la bruja Wendy y a su mejor amiga, Lottie, aprendí a hacer dye permanentemente de color morado a mi gato\".",
    ["| Quiet Before the Swarm"] = "| Tranquilo ante el enjambre",
    ["| \"...and I unlocked Korasi's memories and learned what happened on the ship."] = "| \"...y desbloqueé los recuerdos de Korasi y supe lo que pasó en el barco\".",
    ["| \"The Void Knights walk a fine line as they seek balance."] = "| \"Los Caballeros del Vacío caminan sobre una delgada línea mientras buscan el equilibrio\".",
    ["| Rag and Bone Man"] = "| Hombre de trapo y hueso",
    ["| \"...I fetched all the bones the Odd Old Man wanted and he gave me a reward!"] = "| \"... ¡Conseguí todos los huesos que Odd Old Man quería y me dio una recompensa!",
    ["| \"What could that man have wanted all those bones for? Collecting that many bones cannot be a balanced activity."] = "| \"¿Para qué podría haber querido ese hombre todos esos huesos? Recolectar tantos huesos no puede ser una actividad equilibrada\".",
    ["| Rat Catchers"] = "| Cazadores de ratas",
    ["| \"...those rat-catchers are odd people, but, by the end of it, I had caught a huge number of rats all over RuneScape!"] = "| \"...esos cazadores de ratas son gente rara, pero, al final, ¡había atrapado una gran cantidad de ratas por todo RuneScape!",
    ["| \"Rats are a highly unbalanced creature and it is right that their numbers be controlled."] = "| \"Las ratas son criaturas muy desequilibradas y es correcto controlar su número\".",
    ["| Rebuilding Edgeville (miniquest)"] = "| Reconstrucción de Edgeville (minimisión)",
    ["| \"I assisted Mandrith in cleaning up Edgeville after it was attacked by the dragonkin."] = "| \"Ayudé a Mandrith a limpiar Edgeville después de que fuera atacado por los dragonantes\".",
    ["| \"...after I had freed all the dinner guests, I was finally able to face the Culinaromancer and put an end to his mad schemes!"] = "| \"...después de haber liberado a todos los invitados a la cena, ¡finalmente pude enfrentar al Culinaromancer y poner fin a sus locos planes!",
    ["| \"That evil wizard's time spells sent a ripple through the fabric of balance. I am glad he is no longer at large!"] = "| \"Los hechizos de tiempo de ese mago malvado enviaron una onda a través del tejido del equilibrio. ¡Me alegro de que ya no esté suelto!",
    ["| Recipe for Disaster: Another Cook's Quest"] = "| Recipe for Disaster: La búsqueda de otro cocinero",
    ["| \"I helped the Lumbridge cook prepare a centennial feast in the castle banquet hall. Aris froze the council members in time to stop an evil magician from the past. This gave me time to hunt down some special recipes to protect them."] = "| \"Ayudé al cocinero de Lumbridge a preparar un banquete centenario en el salón de banquetes del castillo. Aris congeló a los miembros del consejo a tiempo para detener a un mago malvado del pasado. Esto me dio tiempo para buscar algunas recetas especiales para protegerlos\".",
    ["| Recipe for Disaster: Defeating the Culinaromancer"] = "| Recipe for Disaster: Derrotando al Culinaromancer",
    ["| \"I gave the Culinaromancer his just desserts and the Duke's party can go on unhindered."] = "| \"Le di al Culinaromancer sus postres justos y la fiesta del Duque puede continuar sin obstáculos\".",
    ["| Recipe for Disaster: Freeing Evil Dave"] = "| Recipe for Disaster: Liberando Evil Dave",
    ["| \"I freed Evil Dave."] = "| \"Liberé a Evil Dave\".",
    ["| Recipe for Disaster: Freeing King Awowogei"] = "| Recipe for Disaster: Liberando al Rey Awowogei",
    ["| \"I freed King Awowogei."] = "| \"Liberé al rey Awowogei\".",
    ["| Recipe for Disaster: Freeing Pirate Pete"] = "| Recipe for Disaster: Liberando Pirate Pete",
    ["| \"I freed Pirate Pete."] = "| \"Liberé a Pirate Pete\".",
    ["| Recipe for Disaster: Freeing Sir Amik Varze"] = "| Recipe for Disaster: Liberando Sir Amik Varze",
    ["| \"I freed Sir Amik Varze."] = "| \"Liberé a Sir Amik Varze\".",
    ["| Recipe for Disaster: Freeing Skrach Uglogwee"] = "| Recipe for Disaster: Liberando a Skrach Uglogwee",
    ["| \"I freed Skrach Uglogwee."] = "| \"Liberé a Skrach Uglogwee\".",
    ["| Transcript:Recipe for Disaster: Freeing the Goblin Generals"] = "| Transcripción:Recipe for Disaster: Liberando el Goblin Generals",
    ["| \"I freed the Goblin generals."] = "| \"Liberé el Goblin generals\".",
    ["| Recipe for Disaster: Freeing the Lumbridge Sage"] = "| Recipe for Disaster: Liberando el Lumbridge Sage",
    ["| \"I freed the Lumbridge Sage."] = "| \"Liberé el Lumbridge Sage\".",
    ["| Recipe for Disaster: Freeing the Mountain Dwarf"] = "| Recipe for Disaster: Liberando al enano de la montaña",
    ["| \"I freed Vestri the Mountain dwarf."] = "| \"Liberé a Vestri, el enano de la montaña\".",
    ["| Recruitment Drive"] = "| Campaña de reclutamiento",
    ["| \"...So I figured out their weird puzzles, and the Temple Knights asked me to join as an initiate member!"] = "| \"... ¡Así que descubrí sus extraños acertijos y los Caballeros del Templo me pidieron que me uniera como miembro iniciado!",
    ["| \"I have heard tales of these 'Temple Knights' from many years past. Be wary, their motivations are not what they might lead you to believe."] = "| \"He oído historias sobre estos 'Caballeros del Templo' de muchos años atrás. Ten cuidado, sus motivaciones no son las que podrían hacerte creer\".",
    ["| \"...I returned to tell King Lathas that the assassination was successful, and he rewarded me."] = "| \"... Regresé para decirle a King Lathas que el asesinato fue un éxito y él me recompensó\".",
    ["| Remains of the Necrolord"] = "| Restos del Necroseñor",
    ["| \"I worked with a former student of Rasial's, the infamous Lord Yudura, and learned about how power can be consolidated from rituals."] = "| \"Trabajé con un antiguo alumno de Rasial, el infame Lord Yudura, y aprendí cómo se puede consolidar el poder a partir de los rituales\".",
    ["| The Restless Ghost"] = "| El Restless Ghost",
    ["| \"...and once I returned the skull, the ghost was able to rest."] = "| \"...y una vez que le devolví el cráneo, el fantasma pudo descansar.",
    ["| \"A strange attachment to an item that has no use after one's death."] = "| \"Un extraño apego a un objeto que no tiene utilidad después de la muerte.",
    ["| Requiem for a Dragon"] = "| Réquiem por un dragón",
    ["| \"I faced off against Vengeance and Bilrach. Although I failed to stop their ritual, I was able to save a portion of Vorkath's soul and lay him to rest."] = "| \"Me enfrenté a Vengeance y Bilrach. Aunque no pude detener su ritual, pude salvar una parte del alma de Vorkath y dejarlo descansar\".",
    ["| Ritual of the Mahjarrat"] = "| Ritual del Mahjarrat",
    ["| \"...and, after the dragonkin killed Lucien, we hid the Stone of Jas again."] = "| \"...y, después de que los dragonantes mataron a Lucien, escondimos la Piedra de Jas nuevamente\".",
    ["| \"It is good that the stone is once more hidden away, but the damage has been done. Lucien was dangerous, but these dragonkin could end up destroying everything."] = "| \"Es bueno que la piedra esté escondida una vez más, pero el daño ya está hecho. Lucien era peligroso, pero estos dragonantes podrían terminar destruyendo todo\".",
    ["| River of Blood"] = "| río de sangre",
    ["| \"...and so my adventure with the Myreque in Morytania has finally reached its titanic conclusion. Many have died, many more have suffered, but I emerged victorious from those dark lands."] = "| \"...y así mi aventura con el Myreque en Morytania finalmente ha llegado a su titánica conclusión. Muchos han muerto, muchos más han sufrido, pero yo salí victorioso de esas tierras oscuras.",
    ["| \"I can't help but notice that your journey ended as it began...with King Roald in Varrock. To think your humble search for a priest in peril could end at the brink of war between Misthalin and Morytania."] = "| \"No puedo evitar notar que tu viaje terminó como comenzó... con King Roald en Varrock. Pensar que tu humilde búsqueda de un sacerdote en peligro podría terminar al borde de la guerra entre Misthalin y Morytania\".",
    ["| Rocking Out"] = "| Rockeando",
    ["| \"...And that was how I heard the tale of the death of Rabid Jack the pirate."] = "| \"...Y así fue como escuché la historia de la muerte del pirata Rabid Jack.",
    ["| \"The lives of pirates often make for good tales."] = "| \"Las vidas de los piratas a menudo dan lugar a buenas historias.",
    ["| Romeo & Juliet (Removed)"] = "| Romeo y Julieta (eliminado)",
    ["| \"...I gave the message to Romeo, but he misunderstood, so they never were together."] = "| \"...Le di el mensaje a Romeo, pero él no lo entendió, así que nunca estuvieron juntos\".",
    ["| \"Never was there a story of more woe that this of Juliet and her Romeo."] = "| \"Nunca hubo una historia más triste que la de Juliet y su Romeo\".",
    ["| \"...and when I planted the shard it grew into a crystal tree!"] = "| \"...y cuando planté el fragmento, ¡se convirtió en un árbol de cristal!",
    ["| Royal Trouble"] = "| Problema real",
    ["| \"...I showed that the war was based on a misunderstanding, and now Miscellania and Etceteria are at peace again!"] = "| \"...Mostré que la guerra se basó en un malentendido, ¡y ahora Miscellania y Etceteria están en paz nuevamente!",
    ["War? What is it good for?"] = "¿War? ¿Para qué sirve?",
    ["To which you reply: \"Absolutely nothing."] = "A lo que usted responde: \"Absolutamente nada\".",
    ["| Rum Deal"] = "| Oferta de ron",
    ["| \"...so that was how I helped keep the zombie pirates drunk!"] = "| \"...¡Así fue como ayudé a mantener borrachos a los piratas zombies!",
    ["| \"Drunken zombie pirates? What is the world coming to?"] = "| \"¿Piratas zombis borrachos? ¿A dónde está llegando el mundo?",
    ["| Rune Mechanics"] = "| Mecánica de runas",
    ["| \"...So Clerval and I successfully made a Rune Guardian pet."] = "| \"...Así que Clerval y yo creamos con éxito una mascota Rune Guardian\".",
    ["| \"Hmm, be careful of such powers - they are better left with the gods."] = "| \"Hmm, ten cuidado con esos poderes; es mejor dejarlos en manos de los dioses\".",
    ["| Rune Memories"] = "| Recuerdos rúnicos",
    ["| Rune Mysteries"] = "| Misterios de runas",
    ["| \"...so Ariane and I trapped the anomalies in the ruins beneath the Wizards' Tower, but we didn't find out who had released them or what they were."] = "| \"... entonces Ariane y yo atrapamos las anomalías en las ruinas debajo del Wizards' Tower, pero no descubrimos quién las había liberado ni qué eran\".",
    ["| \"I fear that some things are best left in the past."] = "| \"Me temo que es mejor dejar algunas cosas en el pasado.",
    ["| Rune Mythos"] = "| Mitos de las runas",
    ["| \"I learned how to create impure essence, craft necrotic runes and to use necromancy incantations."] = "| \"Aprendí a crear esencias impuras, crear runas necróticas y utilizar encantamientos de nigromancia\".",
    ["| Rune Mysteries (historical) (Removed)"] = "| Rune Mysteries (histórico) (eliminado)",
    ["| \"...So, I brought Aubury's notes to Sedridor the head wizard and, from then on, I was able to mine rune essence."] = "| \"... Entonces, le llevé las notas de Aubury a Sedridor, el mago principal, y, a partir de ese momento, pude extraer esencia rúnica\".",
    ["| \"So, the mortals above have discovered magic once more? Very interesting."] = "| \"Entonces, ¿los mortales de arriba han descubierto la magia una vez más? Muy interesante\".",
    ["| Salt in the Wound"] = "| Sal en la herida",
    ["| \"...and, when I awoke, the queen was dead and the villagers of Witchaven were free."] = "| \"...y, cuando desperté, la reina estaba muerta y los aldeanos de Witchaven estaban libres\".",
    ["| \"This just goes to show the power of teamwork."] = "| \"Esto simplemente demuestra el poder del trabajo en equipo\".",
    ["| Scorpion Catcher"] = "| Cazador de escorpiones",
    ["| \"...I would never have thought that three scorpions would take that long to find!"] = "| \"... ¡Nunca hubiera pensado que tres escorpiones tomarían tanto tiempo para encontrarlos!",
    ["| Sea Slug"] = "| babosa de mar",
    ["| \"...and that was how I rescued Caroline's family from the sea slugs."] = "| \"...y así fue como rescaté a la familia de Caroline de las babosas marinas.",
    ["| Secrets of Amberfell"] = "| Secretos de Amberfell",
    ["| \"I met Inanna on Havenhythe and saved the village of Amberfell from the sanguine blight."] = "| \"Conocí a Inanna en Havenhythe y salvé al pueblo de Amberfell de la plaga sanguínea\".",
    ["| Shades of Mort'ton"] = "| Tonos de Mort'ton",
    ["| \"...so Mort'ton returned pretty much to normal and I was able to put the shades to rest."] = "| \"...así que Mort'ton volvió prácticamente a la normalidad y pude poner las cortinas en reposo\".",
    ["| Shadow of the Storm"] = "| Sombra de la tormenta",
    ["| \"...Denath was Agrith-Naar all along! But I managed to summon the demon again and slay him."] = "| \"... ¡Denath fue Agrith-Naar todo el tiempo! Pero logré convocar al demonio nuevamente y matarlo\".",
    ["| \"Agrith-Naar was one of the demons my master banished at the end of the great war. It seems he found a way to work around the ban on direct intervention."] = "| \"Agrith-Naar fue uno de los demonios que mi maestro desterró al final de la gran guerra. Parece que encontró una manera de evitar la prohibición de la intervención directa\".",
    ["| A Shadow over Ashdale"] = "| Una sombra sobre Ashdale",
    ["| \"...I defeated Agoroth, the crassians' leader, and freed the villagers."] = "| \"... Derroté a Agoroth, el líder de los crassianos, y liberé a los aldeanos\".",
    ["| \"There are many fell terrors sleeping beneath the surface of the world. The people of Ashdale are fortunate to have such a protector."] = "| \"Hay muchos terrores que duermen bajo la superficie del mundo. La gente de Ashdale tiene suerte de contar con un protector así\".",
    ["| Sheep Herder"] = "| Sheep Pastor",
    ["| \"...so the sheep were safely killed and incinerated."] = "| \"...así que las ovejas fueron sacrificadas e incineradas de forma segura\".",
    ["| Sheep Shearer (miniquest)"] = "| Sheep Esquilador (minimisión)",
    ["| \"Out of sheer hard work, I managed to shear some sheep for farmer Fred. Then I got in a spin and created some balls of wool."] = "| \"Con mucho trabajo logré esquilar algunas ovejas para el granjero Fred. Luego me puse a girar y creé algunos ovillos de lana\".",
    ["| Shield of Arrav"] = "| Escudo de Arrav",
    ["| \"...so that's how I helped return the Shield of Arrav."] = "| \"... así es como ayudé a devolver el Escudo de Arrav\".",
    ["| \"...so, what Rashiliyia wanted all along was to be reunited with her son in the afterlife."] = "| \"... entonces, lo que Rashiliyia siempre quiso fue reunirse con su hijo en el más allá\".",
    ["| \"...and that was how the Stone of Jas was destroyed and Sliske met his end."] = "| \"...y así fue como la Piedra de Jas fue destruida y Sliske encontró su fin\".",
    ["| \"As a Guardian I must remain on the side on balance, however I am not sad that Sliske is dead."] = "| \"Como guardián, debo permanecer al margen, sin embargo, no estoy triste de que Sliske esté muerto\".",
    ["| The Slug Menace"] = "| La amenaza de las babosas",
    ["| \"...when I told Sir Tiffy that I had accidentally freed the Mother Mallum, he promoted me to the rank of Proselyte within the Temple Knights."] = "| \"... cuando le dije a Sir Tiffy que había liberado accidentalmente a la Madre Mallum, él me ascendió al rango de Prosélito dentro de los Caballeros del Templo\".",
    ["| \"That was a strange response to such an unfortunate event. But the motives of the Temple Knights have always been incomprehensibly unbalanced."] = "| \"Esa fue una respuesta extraña a un acontecimiento tan desafortunado. Pero los motivos de los Caballeros del Templo siempre han estado incomprensiblemente desequilibrados\".",
    ["| Smoking Kills"] = "| Fumar mata",
    ["| \"...who would have thought there were so many monsters down the well in Pollnivneach?"] = "| \"... ¿quién hubiera pensado que había tantos monstruos en el pozo de Pollnivneach?",
    ["| \"You will find that monsters can hide in the most surprising of places. Indeed, those with friendly faces can be the closest things to a monster. Be most careful in your desert adventures."] = "| \"Descubrirás que los monstruos pueden esconderse en los lugares más sorprendentes. De hecho, aquellos con caras amigables pueden ser lo más parecido a un monstruo. Ten mucho cuidado en tus aventuras en el desierto\".",
    ["| Some Like it Cold"] = "| A algunos les gusta el frío",
    ["| \"...and then the egg hatched and a baby penguin came out. You should have seen the look on Larry's face."] = "| \"...y luego el huevo eclosionó y salió un pingüino bebé. Deberías haber visto la expresión en el rostro de Larry\".",
    ["| \"Larry's path was never an easy one, but this will complicate matters."] = "| \"El camino de Larry nunca fue fácil, pero esto complicará las cosas.",
    ["| Song from the Depths"] = "| Canción desde las profundidades",
    ["| \"...so the souls of the sleeping people were returned but Remora, the Siren, was killed by the Queen Black Dragon during our escape."] = "| \"... entonces las almas de las personas dormidas fueron devueltas, pero Remora, la Sirena, fue asesinada por la Reina Dragón Negro durante nuestro escape\".",
    ["| \"Well, at least her death will prevent the Queen from growing stronger stealing other people's souls."] = "| \"Bueno, al menos su muerte evitará que la Reina se haga más fuerte y robe las almas de otras personas\".",
    ["| A Soul's Bane"] = "| La pesadilla de un alma",
    ["| \"...so I defeated all of the monsters in Tolna's subconscious and he escaped from the rift."] = "| \"... así que derroté a todos los monstruos en el subconsciente de Tolna y él escapó de la grieta\".",
    ["| \"The most fearsome monsters are to be found in the darkness of our own minds."] = "| \"Los monstruos más temibles se encuentran en la oscuridad de nuestras propias mentes.",
    ["| Soul Searching"] = "| Búsqueda del alma",
    ["| \"I worked with Icthlarin to gain access to the Sanctum of Rebirth; a strange temple in the Underworld."] = "| \"Trabajé con Icthlarin para obtener acceso al Santuario del Renacimiento; un templo extraño en el inframundo\".",
    ["| Spirit of Summer"] = "| Spirit de Verano",
    ["| \"...I trapped the Spirit Beast and the family could talk again, but they said I had only made it more powerful."] = "| \"...Atrapé a la Bestia Spirit y la familia pudo volver a hablar, pero dijeron que solo la había hecho más poderosa\".",
    ["| \"I have heard of that Spirit Beast. You did very well to even survive your encounter with it."] = "| \"He oído hablar de esa Bestia Spirit. Lo hiciste muy bien incluso para sobrevivir a tu encuentro con ella\".",
    ["| The Spirit of War"] = "| El Spirit de War",
    ["| \"I tested myself against Hermod, the Spirit of War (and Rasial's phantom bodyguard). Despite winning, Rasial just regenerated Hermod. I have much left to learn."] = "| \"Me puse a prueba contra Hermod, the Spirit of War (y el guardaespaldas fantasma de Rasial). A pesar de ganar, Rasial acaba de regenerar a Hermod. Me queda mucho por aprender\".",
    ["| Spirits of the Elid"] = "| Espíritus de los Elid",
    ["| \"...so it turned out that the people of Nardah were dying of thirst because the spirits of the Elid had cursed them for turning away from their goddess."] = "| \"... entonces resultó que la gente de Nardah se estaba muriendo de sed porque los espíritus de los Elid los habían maldecido por alejarse de su diosa\".",
    ["| \"It is a terrible thing for people to turn away from their religion. I think the spirits taught the town a lesson."] = "| \"Es terrible que la gente se aparte de su religión. Creo que los espíritus le dieron una lección a la ciudad\".",
    ["| Spiritual Enlightenment (miniquest)"] = "| Iluminación espiritual (minimisión)",
    ["| \"I climbed the path to enlightenment on the island of Aminishi."] = "| \"Subí el camino hacia la iluminación en la isla de Aminishi\".",
    ["| Stellar Born"] = "| Nacido estelar",
    ["| \"I worked with some astromancers to help a star sprite get back to their home planet, and discovered what was draining their powers."] = "| \"Trabajé con algunos astromantes para ayudar a un star sprite a regresar a su planeta de origen y descubrí qué estaba agotando sus poderes\".",
    ["| Stolen Hearts"] = "| Corazones robados",
    ["| \"...but Ozan and I were caught trying to steal the diamond, and while we were trying to convice the emir to trade it for his son, his own heart gave out!"] = "| \"...pero Ozan y yo fuimos atrapados tratando de robar el diamante, y mientras intentábamos convencer al emir de que lo cambiara por su hijo, ¡su propio corazón se rindió!",
    ["| \"Life is full of little ironies, but do not presume such coincidences are without deliberate cause."] = "| \"La vida está llena de pequeñas ironías, pero no asumas que tales coincidencias no tienen una causa deliberada.",
    ["| Succession"] = "| Sucesión",
    ["| \"I teamed up with Adrasteia for one last adventure before her coronation. Together we tracked Bilrach deep into the Wilderness and ended his scheme."] = "| \"Me asocié con Adrasteia para una última aventura antes de su coronación. Juntos rastreamos a Bilrach hasta lo más profundo del Wilderness y terminamos su plan\".",
    ["| Summer's End"] = "| El fin del verano",
    ["| \"...and after I defeated the Spirit Beast, Summer and her family were finally able to die."] = "| \"...y después de que derroté a la Bestia Spirit, Summer y su familia finalmente pudieron morir\".",
    ["| \"The balance of life and death have been restored. It is good."] = "| \"Se ha restablecido el equilibrio entre la vida y la muerte. Es bueno\".",
    ["| Swan Song"] = "| Canción del cisne",
    ["| \"...so the Wise Old Man said it was time for him to retire, and he left the colony and went home. He taught me a lot, but he wouldn't let me have his hat!"] = "| \"... entonces el Wise Old Man dijo que era hora de que se retirara, dejó la colonia y se fue a casa. ¡Me enseñó mucho, pero no me dejó tener su sombrero!",
    ["A hat is just a hat, Player."] = "Un sombrero es sólo un sombrero, Player.",
    ["To which you reply: \"Grrr!"] = "A lo que respondes: \"¡Grrr!",
    ["| Swept Away"] = "| barrido",
    ["| \"...And that was how I helped the witches prepare their goulash."] = "| \"...Y así fue como ayudé a las brujas a preparar su gulash.",
    ["| Tai Bwo Wannai Trio"] = "| Trío Tai Bwo Wannai",
    ["| \"...so, that was how I helped the people of Tai Bwo Wannai return."] = "| \"... así fue como ayudé a la gente de Tai Bwo Wannai a regresar\".",
    ["| A Tail of Two Cats"] = "| Una cola de dos gatos",
    ["| \"...now Bob and Neite are very happy together!"] = "| \"...¡ahora Bob y Neite están muy felices juntos!",
    ["| \"Bob the cat? I have heard of that strange creature, but have never been able to fathom him. It is no small achievement for you to be able to."] = "| \"¿Bob el gato? He oído hablar de esa extraña criatura, pero nunca he podido comprenderlo. No es un logro pequeño para ti poder hacerlo\".",
    ["| Tales of the God Wars (miniquest)"] = "| Cuentos de las Guerras de Dios (minimisión)",
    ["| \"I discovered tales of the rivalries between the faction generals within the Heart of Gielinor."] = "| \"Descubrí historias de las rivalidades entre los generales de facciones dentro del Corazón de Gielinor\".",
    ["| The Tale of the Muspah"] = "| El cuento del Muspah",
    ["| \"...And so, with Jhallan hibernating again, I had managed to get a trophy for Erjolf."] = "| \"...Y así, con Jhallan hibernando nuevamente, logré conseguir un trofeo para Erjolf\".",
    ["| \"I must ponder whether your actions have interfered with balance or preserved it. Perhaps there is too little information to decide yet."] = "| \"Debo reflexionar si tus acciones han interferido con el equilibrio o lo han preservado. Quizás todavía haya muy poca información para decidir\".",
    ["| Tales of Nomad (miniquest)"] = "| Cuentos de Nomad (minimisión)",
    ["| \"I experienced the stories of Nomad's genesis by exploring cryptic and static scenes from his past."] = "| \"Experimenté las historias de la génesis de Nomad explorando escenas crípticas y estáticas de su pasado\".",
    ["| The Temple at Senntisten"] = "| El Temple at Senntisten",
    ["| \"...And with the communication portal restored, Azzanadra could talk to Zaros again."] = "| \"...Y con el portal de comunicación restaurado, Azzanadra pudo hablar con Zaros nuevamente.",
    ["Finally the order shifts towards balance again. You know, of course, that Zamorak is merely a pretender-god. For a mortal to assume such power is really not good for balance."] = "Finalmente, el orden cambia nuevamente hacia el equilibrio. Sabes, por supuesto, que Zamorak es simplemente un dios pretendiente. Que un mortal asuma tal poder realmente no es bueno para el equilibrio\".",
    ["To which Juna replies \"Guthix gained his power through honest means. He was unaware of what his actions would achieve. Zamorak, however, had unbalanced intentions that cannot be respected."] = "A lo que Juna responde: \"Guthix obtuvo su poder por medios honestos. No sabía lo que lograrían con sus acciones. Zamorak, sin embargo, tenía intenciones desequilibradas que no pueden ser respetadas\".",
    ["| Temple of Ikov (Helping Lucien)"] = "| Templo de Ikov (Ayudando a Lucien)",
    ["| \"...Lucien said that the Staff of Armadyl I gave him had made him more powerful."] = "| \"...Lucien dijo que el Staff o Armadyl que le di lo había hecho más poderoso\".",
    ["| Temple of Ikov (Against Lucien)"] = "| Templo de Ikov (contra Lucien)",
    ["| \"I refused to give Lucien the Staff of Armadyl and had to fight him."] = "| \"Me negué a darle a Lucien el Staff de Armadyl y tuve que pelear con él\".",
    ["| That Old Black Magic"] = "| Ese viejo negro Magic",
    ["| \"I helped to reunite the City of Um's jazz band."] = "| \"Ayudé a reunir la banda de jazz de City of Um\".",
    ["| Thok It To 'Em (saga)"] = "| Thok a ellos (saga)",
    ["| \"I listened to the first saga of Thok, the Daemonheim skillcape owner (but not wearer). He told a tall tale, of charging through a dungeon filled with huge beasts, all in the name of family, love and a fondness for killing creatures in surprisingly novel ways."] = "| \"Escuché la primera saga de Thok, el propietario (pero no el usuario) de Daemonheim skillcape. Contó una gran historia sobre cómo atravesar una mazmorra llena de enormes bestias, todo en nombre de la familia, el amor y la afición por matar criaturas de formas sorprendentemente novedosas\".",
    ["| \"I listened to the second saga of Thok, the Master of Dungeoneering, as he attempted to defeat his brother in a battle of brawn."] = "| \"Escuché la segunda saga de Thok, el maestro de Dungeoneering, mientras intentaba derrotar a su hermano en una batalla de fuerza\".",
    ["| Throne of Miscellania"] = "| Trono de Miscellania",
    ["| \"...So that was how I became King/Queen of Miscellania!<ref name=\"gender\">If a player switches their gender after the quest, the player will say their current gender instead of the one used to marry in the quest, despite the fact that the NPC the player marries to recognises that the player is a different gender.</ref>"] = "| \"...¡Así fue como me convertí en Rey/Reina de Miscellania! <ref name=\"gender\">Si un jugador cambia de género después de la misión, el player dirá su género actual en lugar del que solía casarse en la misión, a pesar de que el NPC con el que se casa el player reconoce que el player es de un género diferente.</ref>",
    ["| Three's Company (saga)"] = "| Compañía de tres (saga)",
    ["| \"I listened to Skaldrun's saga of Sir Owen, Ariane and Ozan's mission into Daemonheim in search of a criminal who had escaped their clutches."] = "| \"Escuché la saga de Skaldrun sobre la misión de Sir Owen, Ariane y Ozan en Daemonheim en busca de un criminal que había escapado de sus garras\".",
    ["| TokTz-Ket-Dill"] = "| TokTz-Ket-Eneldo",
    ["| \"...and that's how I defeated the TokTz-Ket-Dill and helped to write a Tzhaar play."] = "| \"...y así es como derroté al TokTz-Ket-Dill y ayudé a escribir una obra de Tzhaar\".",
    ["| \"I wish I could have seen your play, Player. I am always glad to hear your stories."] = "| \"Ojalá hubiera podido ver tu obra, Player. Siempre me alegra escuchar tus historias\".",
    ["| Tomes of the Warlock"] = "| Tomos del brujo",
    ["| \"I tracked down a series of books written by Orcus, a necromancer from the 2nd Age. From them, I learned of some ancient necromancy secrets."] = "| \"Rastreé una serie de libros escritos por Orcus, un nigromante de la Segunda Edad. A partir de ellos, aprendí algunos secretos antiguos de la nigromancia\".",
    ["| Tortle Combat (miniquest)"] = "| Combate Tortle (minimisión)",
    ["| \"I helped some tortles set up a dojo in Varrock Sewers."] = "| \"Ayudé a algunas tortugas a montar un dojo en Varrock Sewers\".",
    ["| The Tourist Trap"] = "| La trampa para turistas",
    ["| \"...Ana wasn't too happy to be cooped up in that barrel! But at least I got her out of the mining camp."] = "| \"... ¡Ana no estaba muy feliz de estar encerrada en ese barril! Pero al menos la saqué del campamento minero\".",
    ["| Tower of Life"] = "| Torre de la vida",
    ["| \"...So, it turned out that the alchemists had created a Homunculus - a mixture of logic and magic."] = "| \"...Entonces, resultó que los alquimistas habían creado un Homúnculo - una mezcla de lógica y magia.",
    ["| \"Ah, that is good. New forms of life should always be created according to a balance between different principles."] = "| \"Ah, eso es bueno. Siempre deben crearse nuevas formas de vida de acuerdo con un equilibrio entre diferentes principios\".",
    ["| Tree Gnome Village"] = "| Árbol Gnome Pueblo",
    ["| \"..And King Bolren thanked me for defeating the warlord and returning the orbs to the gnome people."] = "| \"...Y King Bolren me agradeció por derrotar al señor de la guerra y devolver los orbes al pueblo gnomo\".",
    ["| Tribal Totem"] = "| Tótem tribal",
    ["| \"...I returned the totem and the Rantuki tribe rewarded me for my help."] = "| \"...Devolví el tótem y la tribu Rantuki me recompensó por mi ayuda.",
    ["| Troll Romance"] = "| Romance trol",
    ["| \"...so Ug and Aga lived happily ever after."] = "| \"...así que Ug y Aga vivieron felices para siempre.",
    ["| Troll Stronghold"] = "| Fortaleza troll",
    ["| \"...and, after I rescued Godric, Dunstan gave me two magic lamps as a reward!"] = "| \"...y, después de rescatar a Godric, ¡Dunstan me dio dos lámparas mágicas como recompensa!",
    ["| Tuai Leit's Own (miniquest)"] = "| El propio Tuai Leit (minimisión)",
    ["| \"I explored the island of Tuai Leit in search of a cure for Ekahi."] = "| \"Exploré la isla de Tuai Leit en busca de una cura para Ekahi\".",
    ["| Twilight of the Gods"] = "| Crepúsculo de los dioses",
    ["| \"I prepared to re-establish the Edicts, in order to stop Zamorak from taking over Gielinor."] = "| \"Me preparé para restablecer los Edictos para evitar que Zamorak se hiciera cargo de Gielinor\".",
    ["| \"...I don't know who put all those traps in the underground pass!"] = "| \"... ¡No sé quién puso todas esas trampas en el underground pass!",
    ["| Unwelcome Guests"] = "| Invitados no deseados",
    ["| \"I found the source of undead attacking Fort Forinthry and helped the Raptor setup a defensive front."] = "| \"Encontré la fuente de los no-muertos que atacaban a Fort Forinthry y ayudé a the Raptor a establecer un frente defensivo\".",
    ["| \"...And once the vampyre was dead, the people of Draynor no longer lived in fear."] = "| \"...Y una vez que el vampyre estuvo muerto, la gente de Draynor ya no vivió con miedo\".",
    ["| Vengeance (saga)"] = "| Venganza (saga)",
    ["| \"I listened to Skaldrun's saga of a vengeful, poisoned forgotten warrior."] = "| \"Escuché la saga de Skaldrun sobre un guerrero olvidado, vengativo y envenenado\".",
    ["| Vessel of the Harbinger"] = "| Vasija del Heraldo",
    ["| \"I worked with a former student of Rasial's, Necrovarus of Port Phasmatys, and learned more about necromantic vessels."] = "| \"Trabajé con un antiguo alumno de Rasial, Necrovarus de Port Phasmatys, y aprendí más sobre las naves nigrománticas\".",
    ["| Violet is Blue"] = "| Violet es azul",
    ["| \"...and that was how I managed to escort Violet across the Land of Snow to the festival."] = "| \"...y así fue como logré escoltar a Violet a través del País de la Nieve hasta el festival\".",
    ["| \"What an uplifting tale! A shame you don't bring me more like these."] = "| \"¡Qué historia tan edificante! Es una pena que no me traigas más como estas\".",
    ["| Violet is Blue Too"] = "| Violet también es azul",
    ["| \"With the help of Violet, we found the missing snow imp and helped save Yeti town by getting new Christmas decorations and managed to decorate the town in time for Christmas day."] = "| \"Con la ayuda de Violet, encontramos al diablillo de nieve perdido y ayudamos a salvar la ciudad de Yeti consiguiendo nuevas decoraciones navideñas y logramos decorar la ciudad a tiempo para el día de Navidad\".",
    ["| Visions of Havenhythe"] = "| Visiones de Havenhythe",
    ["| \"I received a vision calling me to the ancient and beautiful land of Havenhythe, and helped the villagers of Wendlewick construct a lodestone."] = "| \"Recibí una visión que me llamaba a la antigua y hermosa tierra de Havenhythe y ayudé a los aldeanos de Wendlewick a construir un lodestone\".",
    ["| A Void Dance"] = "| Una danza del vacío",
    ["| \"...and on finally tracking down the missing Void Leech, I dealt with it appropriately."] = "| \"...y cuando finalmente localicé a Void Leech desaparecido, lo solucioné apropiadamente\".",
    ["| \"Your decisions and choices are a matter for your own conscience."] = "| \"Tus decisiones y elecciones son un asunto de tu propia conciencia.",
    ["| The Void Stares Back"] = "| El vacío te devuelve la mirada",
    ["| \"...so I defeated the Pest Queen, but lost a good friend."] = "| \"... así que derroté a la Reina Pest, pero perdí a un buen amigo\".",
    ["| \"The knights have not stood united for a very long time."] = "| \"Los caballeros no han estado unidos desde hace mucho tiempo.",
    ["| Wanted!"] = "| ¡Buscado!",
    ["| \"...and, after I finally managed to track him down, let me tell you, that Solus Dellagar was almost as powerful as he was insane!"] = "| \"...y, después de que finalmente logré localizarlo, ¡déjame decirte que Solus Dellagar era casi tan poderoso como loco!",
    ["| \"Yes, it seems he sacrificed his sanity for power. Power often comes with a cost, and the highest cost is often the one you do not immediately see."] = "| \"Sí, parece que sacrificó su cordura por el poder. El poder a menudo tiene un costo, y el costo más alto suele ser el que no se ve de inmediato\".",
    ["| Wandering Ga'al (miniquest)"] = "| Ga'al errante (minimisión)",
    ["| \"I found a Ga'al explorer who disappeared thanks to a very specific set of circumstances. Whomever conceived of them must surely possess a heart of gall."] = "| \"Encontré un explorador de Ga'al que desapareció gracias a una serie de circunstancias muy específicas. Quienquiera que los haya concebido seguramente debe poseer un corazón de descaro.",
    ["| Watchtower"] = "| Atalaya",
    ["| \"...and with the shield generator working, the ogres could never threaten Yanille again."] = "| \"...y con el generador de escudo funcionando, los ogros nunca más podrían amenazar a Yanille\".",
    ["| Waterfall Quest"] = "| Búsqueda de la cascada",
    ["| \"...And that was how I retrieved the Chalice of Eternity from the waterfall."] = "| \"...Y así fue como recuperé el Cáliz de la Eternidad de la cascada.",
    ["| What Lies Below"] = "| Lo que hay debajo",
    ["| \"...but after I defeated King Roald, Rat was able to remove Surok's mind control spell from him."] = "| \"...pero después de que derroté a King Roald, Rat pudo quitarle el hechizo de control mental de Surok\".",
    ["| \"I see the servants of Zamorak still play their part in balancing the world between good and evil."] = "| \"Veo que los servidores de Zamorak todavía desempeñan su papel en el equilibrio del mundo entre el bien y el mal\".",
    ["| What's Mine is Yours"] = "| Lo que es mío es tuyo",
    ["| \"...and that was how I convinced Doric to go back into business."] = "| \"...y así fue como convencí a Doric para que volviera al negocio.",
    ["| \"An uplifting story; I wish you the best in your future ventures."] = "| \"Una historia edificante; te deseo lo mejor en tus futuros proyectos\".",
    ["| While Guthix Sleeps"] = "| Mientras Guthix duerme",
    ["| \"...But Lucien took the Stone of Jas and teleported away!"] = "| \"... ¡Pero Lucien tomó la Piedra de Jas y se teletransportó!",
    ["| \"You should know better than to interfere. Without your involvement, the stone would still rest where my master had put it. But good may yet come of this. We shall see."] = "| \"Deberías saber que no debes interferir. Sin tu participación, la piedra aún permanecería donde mi maestro la había puesto. Pero aún puede salir algo bueno de esto. Ya veremos\".",
    ["| Witch's House"] = "| Casa de la bruja",
    ["| \"...All that trouble just to get a ball out of someone's garden!"] = "| \"... ¡Todos esos problemas sólo para sacar una pelota del jardín de alguien!",
    ["| \"It is often hard to know how long a task will take when we begin it."] = "| \"A menudo es difícil saber cuánto tiempo llevará una tarea cuando la iniciamos\".",
    ["| Witch's Potion (Removed)"] = "| Poción de bruja (eliminada)",
    ["| \"...And once I got her all the ingredients, Hetty's potion increased my magical power!"] = "| \"...Y una vez que le conseguí todos los ingredientes, ¡la poción de Hetty aumentó mi poder mágico!",
    ["| \"I see you are on your way to becoming strong in the magical arts."] = "| \"Veo que estás en camino de volverte fuerte en las artes mágicas\".",
    ["| Witch's Potion (miniquest)"] = "| Poción de bruja (minimisión)",
    ["| \"I've got the makings of a top-class witch! I created a witch's brew with a little help from Hetty."] = "| \"¡Tengo los ingredientes de una bruja de primera clase! Creé un brebaje de bruja con un poco de ayuda de Hetty\".",
    ["| \"...And that's what happened within the light."] = "| \"...Y eso es lo que pasó within the light.",
    ["| \"It must have taken great power to contain such an area within light itself. Intriguing."] = "| \"Debe haber sido necesario un gran poder para contener tal área dentro de la propia luz. Intrigante.",
    ["| Wiz Kid"] = "| niño mago",
    ["| \"I mentored an aspiring young wizard, Ben, in the ways of the runes."] = "| \"Fui mentor de un joven aspirante a mago, Ben, en los caminos de las runas\".",
    ["| Wolf Whistle"] = "| Silbato de lobo",
    ["| \"...And that was how I managed to stop the trolls from making druid soup."] = "| \"...Y así fue como logré evitar que los trolls hicieran sopa de druida.",
    ["| Wolf Whistle (historical) (Removed)"] = "| Wolf Whistle (histórico) (eliminado)",
    ["| \"...And that was how I learned the secrets of summoning."] = "| \"...Y así fue como aprendí los secretos de la invocación.",
    ["| The World Wakes"] = "| El mundo despierta",
    ["|...But it was too late. Sliske had struck the killing blow. Before Guthix died, he showed me what the world will be like if the gods return, and gave me power to defend against them."] = "|...Pero ya era demasiado tarde. Sliske había dado el golpe mortal. Antes de que Guthix muriera, me mostró cómo será el mundo si los dioses regresan y me dio poder para defenderme de ellos.",
    ["| \"These events have paved the way for a new age. Guthix's death removed the edicts from this world, allowing the gods to return. You must remember what he told you, Player."] = "| \"Estos eventos han allanado el camino para una nueva era. La muerte de Guthix eliminó los edictos de este mundo, permitiendo que los dioses regresen. Debes recordar lo que te dijo, Player\".",
    ["| You Are It"] = "| tu lo eres",
    ["| \"...and that was how I overcame the curse of the wishbringer and restored Uri."] = "| \"...y así fue como superé la maldición del cumplidor de deseos y restauré Uri.",
    ["| \"Charos's trinkets appear to have more power than we had previously suspected."] = "| \"Las baratijas de Charos parecen tener más poder de lo que habíamos sospechado anteriormente\".",
    ["| Zogre Flesh Eaters"] = "| Devoradores de carne de Zogre",
    ["| \"...Those Zogres were disgusting! But I learned how to fight them with brutal arrows and disease balm."] = "| \"... ¡Esos Zogres eran asquerosos! Pero aprendí a luchar contra ellos con flechas brutales y bálsamos contra enfermedades\".",
    ["| \"Zombie Ogres!? Some of the foulest creatures of Zamorak. In the great wars, the zogre armies would repel the forces of Saradomin with their stench alone."] = "| \"¿¡Ogros zombis!? Algunas de las criaturas más repugnantes de Zamorak. En las grandes guerras, los ejércitos de zogre repelerían a las fuerzas de Saradomin sólo con su hedor.",
    ["Hello, what are you doing here?"] = "Hola, ¿qué haces aquí?",
    ["Celebrating the anniversary, but also mourning all that we have lost."] = "Celebrando el aniversario, pero también lamentando todo lo que hemos perdido.",
    ["This past ten years has been filled with trying times and sad stories."] = "Estos últimos diez años han estado llenos de tiempos difíciles e historias tristes.",
    ["It has felt to me like the world was thrown out of balance, ever since..."] = "Me ha parecido como si el mundo estuviera fuera de equilibrio, desde entonces...",
    ["You don't have to say. I've felt it too. I think we all have."] = "No es necesario que lo digas. Yo también lo he sentido. Creo que todos lo hemos hecho.",
    ["It was the return of the gods - that started right here with the Battle of Lumbridge, which caused that crater right above where my nest is."] = "Fue el regreso de los dioses, que comenzó aquí mismo con la Batalla de Lumbridge, que causó ese cráter justo encima de donde está mi nido.",
    ["People have been fighting among themselves ever since, split into factions, and their hearts overtaken by greed."] = "La gente ha estado peleando entre sí desde entonces, dividida en facciones y sus corazones invadidos por la codicia.",
    ["The Tears of Guthix have been weeping heavily ever since, and I with them..."] = "Las Lágrimas de Guthix han estado llorando copiosamente desde entonces, y yo con ellas...",
    ["But one cannot remain lost in grief forever, and it is finally starting to feel as if the mood is shifting."] = "Pero uno no puede permanecer perdido en el dolor para siempre, y finalmente comienza a sentir como si el estado de ánimo estuviera cambiando.",
    ["Very true."] = "Muy cierto.",
    ["That is why I came to visit - both to honour the past, but also to look to the future, and what better time to reinvent oneself than an anniversary? Change is coming."] = "Por eso vine de visita: para honrar el pasado, pero también para mirar hacia el futuro, y ¿qué mejor momento para reinventarse que un aniversario? Se acerca el cambio.",
    ["What changes?"] = "¿Qué cambia?",
    ["Did you not see the crater has gone? It has not just healed, it has been rejuvenated!"] = "¿No viste que el cráter desapareció? ¡No sólo ha sanado, sino que ha rejuvenecido!",
    ["It is not just the crater either. I have heard many stories of positive change across our world."] = "Tampoco es sólo el cráter. He escuchado muchas historias de cambios positivos en nuestro mundo.",
    ["And even here, you can see disparate people rejoining hands - old friendships are renewed."] = "E incluso aquí puedes ver a personas dispares volver a unirse: viejas amistades se renuevan.",
    ["Their joy, too, is palpable. It no longer feels that everyone is in it for themselves. Greed is giving way to generosity."] = "Su alegría también es palpable. Ya no se siente que cada uno está en esto por sí mismo. La codicia está dando paso a la generosidad.",
    ["True, there are many wounds to heal, and many friendships to be rekindled, but it truly feels like hope is returning to Gielinor once again, and balance with it."] = "Es cierto, hay muchas heridas que sanar y muchas amistades que reavivar, pero realmente parece que la esperanza está regresando a Gielinor una vez más y el equilibrio con ella.",
    ["You know, I think you're on to something. Here's to the future!"] = "Sabes, creo que has descubierto algo. ¡Aquí está el futuro!",
    ["You have found raven #365, but you need to spot them in order, starting with Terry."] = "Has encontrado el cuervo n.° 365, pero debes ubicarlos en orden, comenzando con Terry.",
    ["Hello friend. You're a long way from civilisation!"] = "Hola amigo. ¡Estás muy lejos de la civilización!",
    ["How do I get into the Kharazi Jungle?"] = "¿Cómo llego a la jungla Kharazi?",
    ["Well, I've not managed it yet but I heard that someone managed to find a way in. But they only just managed to escape the jungle with their lives."] = "Bueno, aún no lo he logrado, pero escuché que alguien logró encontrar una manera de entrar. Pero apenas lograron escapar de la jungla con vida.",
    ["Apparently he was on a mission to map the area. How foolish is that?"] = "Aparentemente tenía la misión de mapear el área. ¿Qué tan tonto es eso?",
    ["Well, in fact I plan to map that area myself."] = "Bueno, de hecho planeo mapear esa área yo mismo.",
    ["--The forester looks very interested-- <br>Oh, well, that sounds quite good actually... <br>Sorry if I sounded rude before, it just didn't seem like a good idea to me."] = "--El guardabosques parece muy interesado-- <br>Oh, bueno, eso suena bastante bien en realidad... <br>Perdón si soné grosero antes, simplemente no me pareció una buena idea.",
    ["I guess I just wouldn't want to do it myself. But a map of that area would certainly be a big task. And it would certainly be very useful... -- The forester looks very thoughtful --"] = "Supongo que no me gustaría hacerlo yo mismo. Pero un mapa de esa zona sería ciertamente una gran tarea. Y sin duda sería muy útil... -- El guardabosques se ve muy pensativo --",
    ["Hey, if you manage to complete it, be sure to let me take a look! Well, best of luck with it, I'm sure you're going to need it."] = "Oye, si logras completarlo, ¡déjame echarle un vistazo! Bueno, mucha suerte con esto, estoy seguro de que lo necesitarás.",
    ["Do you have any other tips about the Kharazi Jungle?"] = "¿Tienes algún otro consejo sobre la jungla Kharazi?",
    ["Not really, but I would say be careful, it's a dangerous place. And good luck."] = "En realidad no, pero diría que ten cuidado, es un lugar peligroso. Y buena suerte.",
    ["Have you seen any natives in the jungle?"] = "¿Has visto algún nativo en la jungla?",
    ["Ok thanks."] = "Bueno, gracias.",
    ["Are you calling me foolish?"] = "¿Me estás llamando tonto?",
    ["No, of course not... Sorry, I have to be on my way..."] = "No, claro que no... Lo siento, tengo que seguir mi camino...",
    ["So someone managed to get into the Kharazi Jungle?"] = "¿Alguien logró entrar en la jungla Kharazi?",
    ["So someone managed to get into the Jungle?"] = "¿Entonces alguien logró entrar a la jungla?",
    ["Yes, he said he was from some place... near the Sorcerer's Tower. Mentioned something about a legend? It meant nothing to me though."] = "Sí, dijo que era de algún lugar... cerca de la Torre del Hechicero. ¿Mencionó algo sobre una leyenda? Aunque no significó nada para mí.",
    ["How do I get into the jungle?"] = "¿Cómo entro a la jungla?",
    ["You're welcome! See you around..."] = "¡De nada! Nos vemos por ahí...",
    ["Can I get another bullroarer{{Sic please?}}"] = "¿Puedo conseguir otro bullroarer{{Sic please?}}?",
    ["Can I get another bullroarer{{Sic}} please?"] = "¿Puedo conseguir otro bullroarer{{Sic}}, por favor?",
    ["Hmmm, what we have here is an opportunity for trade! I'm a bit peckish so why not get me a tasty cooked oomlie wrap and we'll have a deal."] = "Mmmm, ¡lo que tenemos aquí es una oportunidad para comerciar! Tengo un poco de hambre, así que ¿por qué no me traes un delicioso wrap oomlie cocido y hacemos un trato?",
    ["I have one here!"] = "¡Tengo uno aquí!",
    ["Great! Hand it over then!"] = "¡Genial! ¡Dámelo entonces!",
    ["[You trade the cooked Oomlie bird for the bullroarer{{Sic].}}"] = "[Cambias el pájaro Oomlie cocido por el rugido{{Sic].}}",
    ["How can I get one of those?"] = "¿Cómo puedo conseguir uno de esos?",
    ["Oomlie birds are natives of the Kharazi Jungle but they won't be taken without a fight! Once that issue is resolved just cook the bird in a palm leaf over a fire. I'll leave it to your own imagination as to how you get the palm leaf!"] = "Los pájaros Oomlie son nativos de la jungla Kharazi, ¡pero no serán capturados sin luchar! Una vez que se resuelva el problema, simplemente cocine el ave en una hoja de palma al fuego. ¡Dejaré a tu imaginación cómo conseguir la hoja de palma!",
    ["Won't you take something else in return?"] = "¿No aceptarás algo más a cambio?",
    ["Well I doubt that you have anything else which is worth anything to me and Oomlie bird wraps are pretty tasty. I'd have to say sorry but no, that's my final offer."] = "Bueno, dudo que tengas algo más que valga la pena para mí y los wraps de aves de Oomlie son bastante sabrosos. Tendría que pedir perdón pero no, esa es mi oferta final.",
    ["Ok, I'll have a think about it."] = "Ok, lo pensaré.",
    ["Ok! You know where I am if you need me."] = "¡Vale! Sabes dónde estoy si me necesitas.",
    ["I'm a forester, and I specialise in exotic woods. I've not managed to penetrate the Kharazi Jungle very far but I have found some interesting tree specimens."] = "Soy forestal y me especializo en maderas exóticas. No he logrado penetrar muy lejos en la selva de Kharazi, pero he encontrado algunos ejemplares de árboles interesantes.",
    ["If you do happen to get into the Kharazi Jungle, do come and let me know. I'd love to be able to safely navigate my own way in and out."] = "Si por casualidad te adentras en la jungla Kharazi, ven y avísame. Me encantaría poder entrar y salir de forma segura.",
    ["I'm a jungle forester. Names mean little in this part of the world."] = "Soy un jungle forester. Los nombres significan poco en esta parte del mundo.",
    ["Well, I've heard some funny sounds and I think I've seen a native... but I'm not sure. They generally don't like to be seen I guess."] = "Bueno, he escuchado algunos sonidos graciosos y creo que he visto a un nativo... pero no estoy seguro. Supongo que generalmente no les gusta que los vean.",
    ["But I found an item that you might be interested in. You swing it above your head and it makes a strange sound, it seems to attract their attention."] = "Pero encontré un artículo que podría interesarte. Lo mueves sobre tu cabeza y hace un sonido extraño, parece atraer su atención.",
    ["Can I have the item please?"] = "¿Me pueden dar el artículo, por favor?",
    ["Well, I wish I could give it to you. However, I have grown fond of it. And it may help me in case I get lost in the jungle."] = "Bueno, desearía poder dártelo. Sin embargo, le he cogido cariño. Y puede que me ayude en caso de que me pierda en la jungla.",
    ["Will you trade something for it?"] = "¿Cambiarías algo por ello?",
    ["Well, if you have something interesting, let me have a look at it and I'll offer you something in return. OK, I have to go now, but it's been nice talking with you."] = "Bueno, si tienes algo interesante, déjame echarle un vistazo y te ofreceré algo a cambio. Vale, tengo que irme ahora, pero ha sido un placer hablar contigo.",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["I've done all the Hard Tasks in the Karamja set."] = "He realizado todas las tareas difíciles del conjunto Karamja.",
    ["Hmm, indeed. I suppose you'll be wanting a reward!"] = "Hmm, efectivamente. ¡Supongo que querrás una recompensa!",
    ["How can I enchant your Karamja gloves with the power of the forest if you don't have them with you? Bring me the Karamja gloves earned from completing the Medium Tasks."] = "¿Cómo puedo encantar tus guantes Karamja con el poder del bosque si no los tienes contigo? Tráeme los guantes Karamja que se obtienen al completar las tareas medianas.",
    ["The forester takes the Karamja gloves and seems to go into a trance. You hear a rustle in the forest; the gloves seem to shimmer and then turn a darker shade of green."] = "El guardabosques toma los guantes Karamja y parece entrar en trance. Se oye un susurro en el bosque; los guantes parecen brillar y luego adquieren un tono verde más oscuro.",
    ["The blessing that I have placed on these Karamja gloves is a symbol of the exhaustive exploration of the island that you have performed. As well as the benefits of the previous pair, you can take yourself to a place below Shilo"] = "La bendición que he puesto en estos guantes Karamja es un símbolo de la exploración exhaustiva de la isla que habéis realizado. Además de los beneficios del par anterior, puedes ir a un lugar debajo de Shilo.",
    ["Village at any time and enter Brimhaven Dungeon for free. Oh, there's a little added extra for all your hard work, too."] = "Village en cualquier momento y entra gratis a Brimhaven Dungeon. Oh, también hay un pequeño extra por todo tu arduo trabajo.",
    ["Wow, thanks!"] = "¡Vaya, gracias!",
    ["If you lose them, come back to me to reclaim them."] = "Si los pierdes, vuelve conmigo para reclamarlos.",
    ["Ahh...I remember you - didn’t I bless your Karamja gloves?"] = "Ahh... Te recuerdo, ¿no bendije tus guantes Karamja?",
    ["Yes, but I lost them."] = "Sí, pero los perdí.",
    ["Thought as much. Here, have another pair."] = "Lo mismo pensé. Toma, toma otro par.",
    ["[Jungle forester hands you another pair of gloves.]"] = "[Jungle forester te entrega otro par de guantes.]",
    ["Choose an option:{{anchor"] = "Elige una opción:{{anchor",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Tasks in the Karamja set, you are presented with a pair of gloves."] = "Para completar las tareas del conjunto Karamja, se te entregará un par de guantes.",
    ["Completing each difficulty level of the set will allow your gloves to be improved."] = "Completar cada nivel de dificultad del conjunto permitirá mejorar tus guantes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Karamja set's Tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Karamja son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["To claim your Karamja set rewards, speak to Jackie the Fruit in Brimhaven's Agility Arena, Kaleb Paramaya in Shilo Village inn, or myself."] = "Para reclamar las recompensas del conjunto Karamja, habla con Jackie the Fruit en el Agility Arena de Brimhaven, con Kaleb Paramaya en la posada Shilo Village o conmigo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Karamja gloves 1"] = "guantes Karamja 1",
    ["Karamja gloves 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Guantes Karamja 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["[You're handed another Karamja gloves 1.]"] = "[Te entregan otros guantes Karamja 1.]",
    ["Karamja gloves 2"] = "guantes Karamja 2",
    ["Karamja gloves 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Guantes Karamja 2? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Karamja gloves 2.]"] = "[Te entregan otros guantes Karamja 2.]",
    ["Karamja gloves 3"] = "Guantes Karamja 3",
    ["Karamja gloves 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Guantes Karamja 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Karamja gloves 3.]"] = "[Te entregan otros guantes Karamja 3.]",
    ["Karamja gloves 4"] = "Guantes Karamja 4",
    ["Karamja gloves 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Guantes Karamja 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Karamja gloves 4.]"] = "[Te entregan otros guantes Karamja 4.]",
    ["*To access all of this dialogue the player must have:*"] = "*Para acceder a todo este diálogo, el player debe tener:*",
    [":*File:Ring of charos (a).png A Ring of Charos (a)"] = ":*Archivo:Ring of charos (a).png A Ring of Charos (a)",
    [":*File:H.A.M. logo.png Any one or combination of items from the H.A.M. robes set."] = ":*Archivo:H.A.M. logo.png Cualquiera o combinación de artículos del H.A.M. conjunto de batas.",
    ["*Some dialogue options require that certain pieces of equipment be equipped or unequipped.*"] = "*Algunas opciones de diálogo requieren que ciertos equipos estén equipados o desequipados.*",
    ["Hello, what's your job?"] = "Hola, cual es tu trabajo?",
    ["One of upmost importance."] = "Uno de suma importancia.",
    ["Which is?"] = "¿Cuál es?",
    ["**Dialogue Branches**"] = "**Ramas de Diálogo**",
    [":A. Ring of charos (a) on or off, H.A.M. robes off"] = ":A. Ring of charos (a) encendido o apagado, H.A.M. batas fuera",
    ["::A-2. Ring of charos (a) on, H.A.M. robes off"] = "::A-2. Ring of charos (a) en adelante, H.A.M. batas fuera",
    [":::A-2a. Do not use Charm"] = ":::A-2a. No uses encanto",
    [":::A-2b. Use Charm"] = ":::A-2b. Usar encanto",
    ["::::*A-2b becomes B-2*"] = "::::*A-2b se convierte en B-2*",
    ["::A-3. Ring of charos (a) off, H.A.M. robes off"] = "::A-3. Ring of charos (a) apagado, H.A.M. batas fuera",
    [":B. Ring of charos (a) on or off, H.A.M. robes on"] = ":B. Ring of charos (a) encendido o apagado, H.A.M. batas puestas",
    ["::B-2. H.A.M. Dialogue"] = "::B-2. JAMÓN. Diálogo",
    [":::b-1. H.A.M.?"] = ":::b-1. JAMÓN.?",
    [":::b-2. Why are you here?"] = ":::b-2. ¿Por qué estás aquí?",
    ["::::b-2a. Support his cause"] = "::::b-2a. Apoya su causa",
    ["::::b-2b. Disagree with him"] = "::::b-2b. No estoy de acuerdo con el",
    [":::b-3. What have you done?"] = ":::b-3. ¿Qué has hecho?",
    [":::b-4. Finishing up"] = ":::b-4. terminando",
    ["A. **Junior Cadet Bertol**: <span id=\"RingXHAMN\">It's so incredibly top-secret that I'd have to kill you if you found out.</span>"] = "A. **Junior Cadet Bertol**: <span id=\"RingXHAMN\">Es tan increíblemente secreto que tendría que matarte si te enteraras.</span>",
    [":Ring of charos (a) on, H.A.M. robes off"] = ":Ring of charos (a) en adelante, H.A.M. batas fuera",
    [":Ring of charos (a) off, H.A.M. robes off"] = ":Ring of charos (a) apagado, H.A.M. batas fuera",
    ["<span id=\"RingYHAMN\">A-2. **Use Ring of charos (a)?**</span>"] = "<span id=\"RingYHAMN\">A-2. **¿Usar Ring of charos (a)?**</span>",
    [":**Select an Option**"] = ":**Seleccione una opción**",
    ["::A-2a. 1. Best I not prod further, then."] = "::A-2a. 1. Entonces, será mejor que no insista más.",
    ["::A-2b. 2. I can keep a secret. (Charm.)"] = "::A-2b. 2. Puedo guardar un secreto. (Encanto.)",
    [":<span id=\"RingD\">**1. Best I not prod further, then.**</span>"] = ":<span id=\"RingD\">**1. Entonces, será mejor que no insista más.**</span>",
    ["::**Player**: Best I not prod further, then."] = "::**Player**: Entonces, será mejor que no insista más.",
    [":::*Dialogue ends.*"] = ":::*El diálogo termina.*",
    [":<span id=\"RingU\">**2. I can keep a secret. (Charm.)**</span>"] = ":<span id=\"RingU\">**2. Puedo guardar un secreto. (Encanto.)**</span>",
    ["::**Player**: I can keep a secret."] = "::**Player**: Puedo guardar un secreto.",
    ["::**Junior Cadet Bertol**: Very well. I'm a member of H.A.M."] = "::**Junior Cadet Bertol**: Muy bien. Soy miembro de H.A.M.",
    [":::*Skip to H.A.M. Dialogue*"] = ":::*Pasar a H.A.M. Diálogo*",
    ["<span id=\"RingNHAMN\">A-3. **With neither Ring of charos (a) nor H.A.M. robes**</span>"] = "<span id=\"RingNHAMN\">A-3. **Sin Ring of charos (a) ni H.A.M. batas**</span>",
    [":**Player**: I can keep a secret."] = ":**Player**: Puedo guardar un secreto.",
    [":**Junior Cadet Bertol**: The knowledge alone would fry your little brain."] = ":**Junior Cadet Bertol**: El conocimiento por sí solo freiría tu pequeño cerebro.",
    [":**Player**: I doubt it."] = ":**Player**: Lo dudo.",
    [":**Junior Cadet Bertol**: It so would!"] = ":**Junior Cadet Bertol**: ¡Así sería!",
    [":**Player**: Wouldn't."] = ":**Player**: No lo haría.",
    [":**Junior Cadet Bertol**: Would."] = ":**Junior Cadet Bertol**: Lo haría.",
    [":**Player**: Wouldn't times ten!"] = ":**Player**: ¡No sería multiplicado por diez!",
    [":**Junior Cadet Bertol**: Would times infinity!"] = ":**Junior Cadet Bertol**: ¡Se multiplicaría por el infinito!",
    [":**Player**: Prove it."] = ":**Player**: Pruébalo.",
    [":**Junior Cadet Bertol**: Okay, I'm under cover as...ah you almost had me, there."] = ":**Junior Cadet Bertol**: Está bien, estoy encubierto porque... ah, casi me tienes ahí.",
    [":**Player**: Ah, so close!"] = ":**Player**: ¡Ah, qué cerca!",
    ["::*Dialogue ends.*"] = "::*El diálogo termina.*",
    ["<span id=\"RingXHAMY\">B. **With any H.A.M. robe item worn, with or without Ring of charos (a)**</span>"] = "<span id=\"RingXHAMY\">B. **Con cualquier H.A.M. artículo de bata usado, con o sin Ring of charos (a)**</span>",
    [":**Junior Cadet Bertol**: Well, I see from your clothes that you're a member of H.A.M. I am too."] = ":**Junior Cadet Bertol**: Bueno, veo por tu ropa que eres miembro de H.A.M. Yo también lo soy.",
    ["::*To H.A.M. Dialogue*"] = "::*A H.A.M. Diálogo*",
    ["<span id=\"B2\">B-2. **H.A.M. Dialogue**</span>"] = "<span id=\"B2\">B-2. **JAMÓN. Diálogo**</span>",
    ["::b-1. 1. What's H.A.M.?"] = "::b-1. 1. ¿Qué es HAM?",
    ["::b-2. 2. What's H.A.M. got to do with this command centre?"] = "::b-2. 2. ¿Qué es H.A.M.? ¿Tiene que ver con este centro de mando?",
    [":::b-2a. 1. I wish you good luck."] = ":::b-2a. 1. Te deseo buena suerte.",
    [":::b-2b. 2. How awful."] = ":::b-2b. 2. Qué horrible.",
    ["::b-3. 3. What have you done while undercover?"] = "::b-3. 3. ¿Qué has hecho mientras estabas encubierto?",
    ["::b-4. 4. I've heard enough."] = "::b-4. 4. Ya he oído suficiente.",
    [":<span id=\"b1\">**1. What's H.A.M.?**"] = ":<span id=\"b1\">**1. ¿Qué es H.A.M.?**",
    ["::**Player**: What's H.A.M.?"] = "::**Player**: ¿Qué es H.A.M.?",
    ["::**Junior Cadet Bertol**: It stands for 'Humans Against Monsters': a group keen on enforcing that humans are all that belongs on RuneScape."] = "::**Junior Cadet Bertol**: Significa 'Humanos contra monstruos': un grupo interesado en hacer cumplir que los humanos son lo único que pertenece a RuneScape.",
    [":::*Back to H.A.M. Dialogue*"] = ":::*Volver a H.A.M. Diálogo*",
    [":<span id=\"b2\">**2. What's H.A.M. got to do with this command centre?**"] = ":<span id=\"b2\">**2. ¿Qué es H.A.M.? ¿Tiene algo que ver con este centro de mando?**",
    ["::**Player**: What's H.A.M. got to do with this command centre?"] = "::**Player**: ¿Qué es H.A.M.? ¿Tiene que ver con este centro de mando?",
    ["::**Junior Cadet Bertol**: Open your eyes! It's crawling with all manner of disgusting creatures. At least they've got one thing right - humans are officers rather than grunts."] = "::**Junior Cadet Bertol**: ¡Abre los ojos! Está plagado de todo tipo de criaturas repugnantes. Al menos tienen algo en claro: los humanos son oficiales y no gruñidos.",
    ["::**Player**: But what can H.A.M. do about it?"] = "::**Player**: ¿Pero qué puede hacer H.A.M. hacer al respecto?",
    ["::**Junior Cadet Bertol**: My friend, I'm on a mission to stop it all - by any means necessary."] = "::**Junior Cadet Bertol**: Amigo mío, tengo la misión de detenerlo todo, por cualquier medio necesario.",
    [":::**Select an Option**"] = ":::**Seleccione una opción**",
    ["::::<span id=\"b2a\">1. I wish you good luck.</span>"] = "::::<span id=\"b2a\">1. Te deseo buena suerte.</span>",
    [":::::**Player**: I wish you good luck."] = ":::::**Player**: Te deseo buena suerte.",
    [":::::**Junior Cadet Bertol**: Thanks. I can assure you that I'll need no luck with the ingenuity of my plans."] = ":::::**Junior Cadet Bertol**: Gracias. Puedo asegurarte que no necesitaré suerte con el ingenio de mis planes.",
    ["::::::*Back to H.A.M. Dialogue*"] = "::::::*Volver a H.A.M. Diálogo*",
    ["::::<span id=\"b2b\">2. How awful.</span>"] = "::::<span id=\"b2b\">2. Que horrible.</span>",
    [":::::**Player**: How awful."] = ":::::**Player**: Qué horrible.",
    [":::::**Junior Cadet Bertol**: There's nothing awful about my mission."] = ":::::**Junior Cadet Bertol**: No hay nada terrible en mi misión.",
    [":::::**Player**: I disagree. Give me one reason why I shouldn't head to an officer and tell them of your secret agenda."] = ":::::**Player**: No estoy de acuerdo. Dame una razón por la que no debería dirigirme a un oficial y contarle tu agenda secreta.",
    [":::::**Junior Cadet Bertol**: Do as you wish. He'll never believe some stranger over a cadet."] = ":::::**Junior Cadet Bertol**: Haz lo que desees. Nunca creerá en un extraño antes que en un cadete.",
    [":::::**Player**: You mean junior cadet."] = ":::::**Player**: Te refieres al cadete junior.",
    [":::::**Junior Cadet Bertol**: How observant of you."] = ":::::**Junior Cadet Bertol**: Qué observador de tu parte.",
    [":<span id=\"b3\">**3. What have you done while undercover?**"] = ":<span id=\"b3\">**3. ¿Qué has hecho mientras estabas encubierto?**",
    ["::**Player**: What have you done while undercover?"] = "::**Player**: ¿Qué has hecho mientras estabas encubierto?",
    ["::**Junior Cadet Bertol**: Plenty! Spreading rumours, sabotaging special units; recently, I've hit upon mixing up the battle orders so commanders end up travelling to the wrong destinations! He he."] = "::**Junior Cadet Bertol**: ¡Mucho! Difundir rumores, sabotear unidades especiales; ¡Recientemente, he llegado a mezclar las órdenes de batalla para que los comandantes terminen viajando a los destinos equivocados! Él, él.",
    ["::**Player**: Cunning."] = "::**Player**: Astuto.",
    [":<span id=\"b4\">**4. I've heard enough.**"] = ":<span id=\"b4\">**4. Ya he oído suficiente.**",
    ["::**Player**: I've heard enough."] = "::**Player**: Ya he oído suficiente.",
    ["::**Junior Cadet Bertol**: Fine by me."] = "::**Junior Cadet Bertol**: Por mí está bien.",
    ["Hello. What do you do here?"] = "Hola. ¿Qué haces aquí?",
    ["Me? I'm the best junior cadet you'll ever find! Cream of the crop!"] = "¿Yo? ¡Soy el mejor cadete junior que jamás encontrarás! ¡Crema de la cosecha!",
    ["Prove it."] = "Pruébalo.",
    ["I don't need to. It's as sure as eggs."] = "No es necesario. Es tan seguro como los huevos.",
    ["Arrogant much?"] = "¿Muy arrogante?",
    ["Annoying much?"] = "¿Te molesta mucho?",
    ["Time-wasting much?"] = "¿Perdiste mucho el tiempo?",
    ["Duh! Much?"] = "¡Claro! ¿Mucho?",
    ["Hi. You look quite important. What do you do here?"] = "Hola. Pareces bastante importante. ¿Qué haces aquí?",
    ["Shhh, they're watching!"] = "¡Shhh, están mirando!",
    ["What? Who?"] = "¿Qué? ¿OMS?",
    ["There are secret agents everywhere. Trust no-one!"] = "Hay agentes secretos por todas partes. ¡No confíes en nadie!",
    ["Why, what's the matter?"] = "¿Por qué? ¿Cuál es el problema?",
    ["Such a conspiracy like you wouldn't imagine. I believe this place is the source, as I shall soon find out."] = "Una conspiración como no te la imaginas. Creo que este lugar es la fuente, como pronto descubriré.",
    ["I've said too much. Please - go on your way."] = "He dicho demasiado. Por favor, sigue tu camino.",
    ["Hi. It looks like you're planning a complex battle?"] = "Hola. ¿Parece que estás planeando una batalla compleja?",
    ["We talking tactics. Trying to make tactic that beat any opponent."] = "Estamos hablando de tácticas. Intentando hacer una táctica que venza a cualquier oponente.",
    ["That sounds somewhat impossible."] = "Eso suena algo imposible.",
    ["Nothing impossible. Nothing at all."] = "Nada imposible. Nada en absoluto.",
    ["So, what's the tactic?"] = "Entonces, ¿cuál es la táctica?",
    ["I can tell, but remember it a work in progress."] = "Lo sé, pero recuerda que es un trabajo en progreso.",
    ["Of course, I understand."] = "Por supuesto que lo entiendo.",
    ["Okay. The plan start with running at them."] = "Está bien. El plan comienza corriendo hacia ellos.",
    ["Running at them?"] = "¿Corriendo hacia ellos?",
    ["Yes, and shout 'Die, die!' at top of our voices. Then, when the enemy least expects, we do what they least expect."] = "Sí, y grita '¡Muere, muere!' a la altura de nuestras voces. Luego, cuando el enemigo menos lo espera, hacemos lo que menos espera.",
    ["And that is?"] = "¿Y eso es?",
    ["Attack them!"] = "¡Attack ellos!",
    ["Hmmm, that sounds rather basic and predictable, but good luck."] = "Hmmm, eso suena bastante básico y predecible, pero buena suerte.",
    ["Oh, such a crisis here at A.R.M.S.!"] = "¡Oh, qué crisis aquí en A.R.M.S.!",
    ["Can I help?"] = "¿Puedo ayudar?",
    ["Really? Rebellious mercenaries have made away with a cache of A.R.M.S.'s battle supplies, and all the other commanders are fighting a far-away battle. I've been left to 'hold the fort', but, being just one man, I don't think I can retrieve the stolen supplies."] = "¿En serio? Los mercenarios rebeldes se han llevado un alijo de suministros de batalla de A.R.M.S. y todos los demás comandantes están librando una batalla lejana. Me han dejado \"mantener el fuerte\", pero, siendo solo un hombre, no creo que pueda recuperar los suministros robados.",
    ["Don't worry, we'll sort this out."] = "No te preocupes, solucionaremos esto.",
    ["Great, let's go! There's no time to lose."] = "Genial, ¡vamos! No hay tiempo que perder.",
    ["*(Mobilising Armies Tutorial begins)*"] = "*(Comienza el tutorial sobre movilización de ejércitos)*",
    ["What's A.R.M.S.?"] = "¿Qué es A.R.M.S.?",
    ["The Army Recruitment and Mobilisation Society. We're here to make sure all war heroes and warriors can earn a living through honourable combat."] = "Sociedad de Reclutamiento y Movilización del Ejército. Estamos aquí para asegurarnos de que todos los héroes y guerreros de guerra puedan ganarse la vida mediante un combate honorable.",
    ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
    ["You're back! I still need your help with the battle."] = "¡Has vuelto! Todavía necesito tu ayuda con la batalla.",
    ["Okay, let's do this."] = "Bien, hagamos esto.",
    ["*(Mobilising Armies Tutorial continues)*"] = "*(El tutorial sobre movilización de ejércitos continúa)*",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Oh no, what am I to do?"] = "Oh no, ¿qué debo hacer?",
    ["So, can I continue with the officer training?"] = "Entonces, ¿puedo continuar con la capacitación de oficiales?",
    ["*(Officer training continues)*"] = "*(Continúa el entrenamiento de oficiales)*",
    ["Sorry, wrong person."] = "Lo siento, la persona equivocada.",
    ["Oh, okay."] = "Oh, está bien.",
    ["How might I help you?"] = "¿En qué puedo ayudarte?",
    ["Extra training."] = "Entrenamiento adicional.",
